// 中国王朝二元悖论可视化 — 交互逻辑
// State
let currentIndex = 0;

// DOM
const navEl = document.getElementById('nav');
const contentEl = document.getElementById('content');
const modalOverlay = document.getElementById('modal-overlay');
const modalCloseBtn = document.getElementById('modal-close');
const mNum = document.getElementById('m-num');
const mTitle = document.getElementById('m-title');
const mPoleA = document.getElementById('m-pole-a');
const mPoleB = document.getElementById('m-pole-b');
const mBody = document.getElementById('m-body');
const mTag = document.getElementById('m-tag');

// ============ 渲染侧边栏 ============
function renderNav() {
  // Group by era for visual hierarchy
  let lastEra = '';
  const html = DYNASTIES.map((d, i) => {
    let eraHeader = '';
    if (d.era !== lastEra) {
      eraHeader = `<div class="nav-era">${escapeHtml(d.era)}</div>`;
      lastEra = d.era;
    }
    const num = String(i + 1).padStart(2, '0');
    return eraHeader + `
      <div class="nav-item ${i === currentIndex ? 'active' : ''}" data-index="${i}">
        <div class="nav-num">${num}</div>
        <div class="nav-name">${escapeHtml(d.name)}</div>
        <div class="nav-period">${escapeHtml(d.period)}</div>
      </div>
    `;
  }).join('');
  navEl.innerHTML = html;

  // Attach click handlers
  navEl.querySelectorAll('.nav-item').forEach(item => {
    item.addEventListener('click', () => {
      const idx = parseInt(item.dataset.index, 10);
      selectDynasty(idx);
    });
  });
}

// ============ 渲染主内容 ============
function renderContent(index) {
  const d = DYNASTIES[index];
  const num = String(index + 1).padStart(2, '0');

  // Tensions grid
  const tensionsHtml = d.tensions.map((t, ti) => {
    const tNum = String(ti + 1).padStart(2, '0');
    return `
      <div class="tension-card" data-tindex="${ti}">
        <div class="tc-num">
          <span class="tc-num-label">张力</span>
          <span>${tNum}</span>
        </div>
        <div class="tc-poles">
          <div class="tc-pole a">${escapeHtml(t.pole_a)}</div>
          <div class="tc-vs">↔</div>
          <div class="tc-pole b">${escapeHtml(t.pole_b)}</div>
        </div>
        <div class="tc-summary">${escapeHtml(t.summary)}</div>
        <div class="tc-expand">展开 →</div>
      </div>
    `;
  }).join('');

  // Prev / Next controls
  const prev = index > 0 ? DYNASTIES[index - 1] : null;
  const next = index < DYNASTIES.length - 1 ? DYNASTIES[index + 1] : null;
  const controlsHtml = `
    <div class="dynasty-controls">
      ${prev ? `
        <div class="dc-btn" data-target="${index - 1}">
          <div class="dc-btn-label">← 前朝</div>
          <div class="dc-btn-name">${escapeHtml(prev.name)}</div>
        </div>
      ` : '<div></div>'}
      ${next ? `
        <div class="dc-btn dc-btn-next" data-target="${index + 1}">
          <div class="dc-btn-label">后朝 →</div>
          <div class="dc-btn-name">${escapeHtml(next.name)}</div>
        </div>
      ` : '<div></div>'}
    </div>
  `;

  contentEl.innerHTML = `
    <section class="dynasty-hero">
      <div class="dynasty-marker">
        <span class="dynasty-num-large">${num}</span>
        <span class="dynasty-period-large">${escapeHtml(d.period)}</span>
      </div>
      <h1 class="dynasty-name-large">${escapeHtml(d.name)}</h1>
      <div class="dynasty-tagline">${escapeHtml(d.title)}</div>
      <div class="dynasty-tagline" style="margin-top:8px;font-size:14px;opacity:0.7;font-style:italic;">${escapeHtml(d.tagline)}</div>
    </section>

    <section class="mother-paradox">
      <div class="mp-label">
        <div class="mp-label-en">Mother Paradox · 母悖论</div>
        <div class="mp-label-cn">所有张力的总根源</div>
      </div>
      <div class="mp-stage">
        <div class="mp-pole mp-pole-a">
          <div class="mp-pole-marker">A</div>
          <div class="mp-pole-text">${escapeHtml(d.mother_paradox.pole_a)}</div>
        </div>
        <div class="mp-tension">↔</div>
        <div class="mp-pole mp-pole-b">
          <div class="mp-pole-marker">B</div>
          <div class="mp-pole-text">${escapeHtml(d.mother_paradox.pole_b)}</div>
        </div>
      </div>
      <div class="mp-description">${escapeHtml(d.mother_paradox.description)}</div>
    </section>

    <section class="tensions-section">
      <div class="section-heading">
        <div class="section-heading-cn">具体张力</div>
        <div class="section-heading-en">Specific Tensions — Variations of the Mother Paradox</div>
        <div class="section-heading-line"></div>
        <div class="section-heading-count">${d.tensions.length} 张力</div>
      </div>
      <div class="tensions-grid">
        ${tensionsHtml}
      </div>
    </section>

    <section class="meta-conclusion">
      <div class="mc-title">元结论 · Meta-Conclusion</div>
      <div class="mc-text">${escapeHtml(d.meta_conclusion)}</div>
    </section>

    ${controlsHtml}
  `;

  // Tension card clicks
  contentEl.querySelectorAll('.tension-card').forEach(card => {
    card.addEventListener('click', () => {
      const ti = parseInt(card.dataset.tindex, 10);
      openModal(index, ti);
    });
  });

  // Prev/Next buttons
  contentEl.querySelectorAll('.dc-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      const target = parseInt(btn.dataset.target, 10);
      if (!isNaN(target)) selectDynasty(target);
    });
  });

  // Scroll to top of content
  window.scrollTo({ top: 0, behavior: 'smooth' });
}

// ============ 切换王朝 ============
function selectDynasty(index) {
  if (index < 0 || index >= DYNASTIES.length) return;
  currentIndex = index;
  // Update nav active state
  navEl.querySelectorAll('.nav-item').forEach(item => {
    item.classList.toggle('active', parseInt(item.dataset.index, 10) === index);
  });
  renderContent(index);
}

// ============ 模态框 ============
function openModal(dynastyIdx, tensionIdx) {
  const d = DYNASTIES[dynastyIdx];
  const t = d.tensions[tensionIdx];
  const tNum = String(tensionIdx + 1).padStart(2, '0');

  mNum.textContent = `张力 ${tNum} · ${d.name}`;
  mTitle.textContent = `${t.pole_a}  ↔  ${t.pole_b}`;
  mPoleA.textContent = t.pole_a;
  mPoleB.textContent = t.pole_b;

  // Body paragraphs
  mBody.innerHTML = t.body.map(p => `<p>${escapeHtml(p)}</p>`).join('');

  // Tag
  mTag.textContent = t.summary;

  modalOverlay.classList.add('open');
  document.body.style.overflow = 'hidden';
}

function closeModal() {
  modalOverlay.classList.remove('open');
  document.body.style.overflow = '';
}

modalCloseBtn.addEventListener('click', closeModal);
modalOverlay.addEventListener('click', (e) => {
  if (e.target === modalOverlay) closeModal();
});
document.addEventListener('keydown', (e) => {
  if (e.key === 'Escape' && modalOverlay.classList.contains('open')) {
    closeModal();
  }
  // Arrow keys for dynasty navigation (when modal is closed)
  if (!modalOverlay.classList.contains('open')) {
    if (e.key === 'ArrowLeft' && currentIndex > 0) {
      selectDynasty(currentIndex - 1);
    } else if (e.key === 'ArrowRight' && currentIndex < DYNASTIES.length - 1) {
      selectDynasty(currentIndex + 1);
    }
  }
});

// ============ 工具 ============
function escapeHtml(str) {
  if (str == null) return '';
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

// ============ 初始渲染 ============
renderNav();
renderContent(currentIndex);

