// 中国王朝二元悖论数据库
// Each dynasty: { id, name, period, era, title, mother_paradox: {pole_a, pole_b, description}, tensions: [...], meta_conclusion }

const DYNASTIES = [
  // ============ 1. 夏朝 ============
  {
    id: "xia",
    name: "夏朝",
    period: "约前2070—前1600",
    era: "上古",
    title: "原初张力：中国第一个王朝的动力学分析",
    tagline: "从「天下为公」到「家天下」——制度悖论的初次写入",
    mother_paradox: {
      pole_a: "合法性的建构",
      pole_b: "合法性的自我消解",
      description: "大禹的政治权威来源于治水功绩——典型的绩效合法性。但绩效合法性具内在不稳定性：它要求权力的每一次传递都经过重新的绩效验证，而验证过程本身就是对现有权力结构的系统性否定。禹传位伯益、启击败伯益建立世袭，不是个人道德的失败，而是绩效合法性在遭遇足够强大的物质利益结构时必然发生的制度性崩溃。世袭制在解决这个问题的同时，制造了更深的悖论：它将合法性从绩效转移到血统，而血统不能保证绩效。夏朝是第一个将这个悖论制度化的政权，也是第一个被这个悖论摧毁的政权。"
    },
    tensions: [
      {
        pole_a: "治水权威",
        pole_b: "权威的政治异化",
        summary: "治水的成功越彻底，对治水权威的日常依赖就越低——洪水被驯服，恐惧记忆消退，治水功绩的政治动员力随之衰减。",
        body: [
          "大禹治水所建立的权威，有其深刻的历史合理性：黄河流域的农业文明依赖于对洪水的系统性控制，这是超越任何单一部落能力的集体行动问题。治水权威的关键政治副产品，是中国最早的大规模劳动力动员机制——指挥体系、物资调配、强制执行力——这套机制在治水完成之后并未消失，成为王权强制能力的基础设施。",
          "但治水权威包含着内在的政治逻辑陷阱：治水越成功，对其权威的日常性依赖就越低。当洪水被驯服，人们对洪水的恐惧记忆逐渐消退，治水功绩的政治动员力也随之衰减。",
          "太康失国（夏朝第三代君主）是这个张力最直接的案例：太康沉湎游猎、疏于政事，东夷后羿乘机夺权。表面是个人荒政，深层却是治水权威异化之后王权合法性真空的暴露。少康中兴的成功则揭示了另一面：当外部统治者无法提供大禹家族所能提供的意识形态凝聚力，夏朝的政治复辟就获得了情感和文化基础。少康复国不仅是军事胜利，更是历史记忆的政治调动。"
        ]
      },
      {
        pole_a: "部落联盟的弹性结构",
        pole_b: "中央王权的集中冲动",
        summary: "联盟太弱，无法真正整合内部；又太强，无法让各方国感到足够自主——「恰好足够激怒所有人，但又不足以真正控制任何人」。",
        body: [
          "夏朝并非具有清晰官僚体系的中央集权国家，而是以夏后氏为核心、以姻亲和朝贡关系为纽带的松散政治联盟。各方国保有相当程度的内部自治权，对夏王的义务主要体现在朝贡、军事支持和仪式性臣服上。",
          "联盟结构包含一个无法消解的内在矛盾：联盟的有效性依赖于中心权威的相对强大，而中心权威的强大本身会激起边缘成员的离心冲动。当夏王弱势，各方国趋向独立；当夏王强势，强化徭役和贡赋，又会激起方国抵制。",
          "商汤灭夏的成功在政治维度上有一个常被忽视的事实：商汤能够动员大量原本臣服于夏的方国支持反叛，说明夏桀晚期已经将联盟关系系统性地破坏——他在要求联盟成员义务的同时，无法为他们提供应有的保护和利益，联盟的经济合理性已经消失。"
        ]
      },
      {
        pole_a: "农业扩张的物质需求",
        pole_b: "黄河流域的生态承载极限",
        summary: "大禹治水所建立的水利体系是针对特定历史条件设计的——随着上游垦殖推进，其有效性逐渐下降，需要持续更新。",
        body: [
          "大禹治水之后，黄河中下游大量洪泛平原得以开垦，这为夏朝初期的人口增长和农业扩张提供了物质基础。农业扩张是王权财政基础的扩大，也是政治影响力的地理延伸。",
          "但黄河流域的农业扩张本身携带着长期的生态代价：大规模垦殖减少地表植被覆盖，上游水土流失加剧，黄河泥沙淤积量逐渐增大，洪水治理的难度持续上升。夏朝后期诸王的注意力越来越集中于政治斗争和军事防御，水利维护体系的投入相应减少。",
          "夏桀末年的社会动荡，不能仅仅归因于桀的暴政，还必须考虑到夏朝四百余年农业扩张所积累的生态压力已经开始系统性释放——任何政治体制在遭遇这种多重叠加的压力时，都会面临严峻的制度性考验。"
        ]
      },
      {
        pole_a: "仪式权威的精神统合",
        pole_b: "世俗权力的物质基础",
