  const mp = s.mother_paradox;
  if (!mp) {
    nowshowingEl.innerHTML = `
      <div class="ns-cat">${escapeHtml(s.category)}</div>
      <div class="ns-poles">${escapeHtml(s.name)}</div>
    `;
