  }
  nowshowingEl.innerHTML = `
    <div class="ns-cat">${escapeHtml(s.category)} · 母悖论</div>
    <div class="ns-poles">
      <span class="pa">${escapeHtml(mp.pole_a)}</span>
      <span class="vs">↔</span>
      <span class="pb">${escapeHtml(mp.pole_b)}</span>
    </div>
