// ===== 搜索词分组台 · 应用逻辑 =====
(function () {
  'use strict';

  const L1_COLORS = {
    '核心词': '#3F7E6B', '限定词': '#C8893B', '品牌词': '#BC4B33',
    '扩展词': '#7E8A6A', '未归类': '#B3A589'
  };
  const L1_DESC = {
    '核心词': '画板/手写板本体', '限定词': '受众·属性·特点·场景·主题',
    '品牌词': '自有与竞品/IP', '扩展词': '配件与相邻产品', '未归类': '待人工复核'
  };

  // —— DOM —— 
  const $ = id => document.getElementById(id);
  const dropzone = $('dropzone'), fileInput = $('file-input');
  const configCard = $('config-card'), resultCard = $('result-card');
  const fileNameEl = $('file-name'), fileMetaEl = $('file-meta');
  const sheetSelect = $('sheet-select'), kwSelect = $('kw-select'), adsDetected = $('ads-detected');
  const siteInput = $('site-input'), categoryInput = $('category-input'), mergeAccessory = $('merge-accessory');
  const runBtn = $('run-btn');
  const overlay = $('overlay'), overlayText = $('overlay-text');
  const filterInput = $('filter-input'), tableHost = $('table-host'), previewNote = $('preview-note');
  const downloadBtn = $('download-btn'), resetBtn = $('reset-btn');

  // —— 状态 —— 
  let workbook = null;
  let headerRow = [], dataRows = [];
  let adsCols = {};            // {clicks,spend,roas,orders} -> 列索引 或 -1
  let result = null;           // {long, wide, sum, stats, hasAds, headerLong, headerWide, headerSum, dict}
  let activeTab = 'sum';

  const PREVIEW_LIMIT = 200;

  // —— 工具 —— 
  function num(v) {
    if (v == null || v === '') return 0;
    const n = parseFloat(String(v).replace(/,/g, '').replace(/[^0-9.\-]/g, ''));
    return isNaN(n) ? 0 : n;
  }
  function round2(x) { return Math.round((x + Number.EPSILON) * 100) / 100; }
  function round1(x) { return Math.round((x + Number.EPSILON) * 10) / 10; }
  function fmtInt(x) { return Number(x).toLocaleString('en-US'); }
  const reduceMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  function showOverlay(msg) { overlayText.textContent = msg || '处理中…'; overlay.hidden = false; }
  function hideOverlay() { overlay.hidden = true; }

  // —— 列名自动识别 —— 
  function pickKwCol(header) {
    const norm = header.map(h => String(h == null ? '' : h).trim());
    let i = norm.findIndex(h => h === '用户搜索词');
    if (i >= 0) return i;
    i = norm.findIndex(h => /搜索词|search\s*term|customer\s*search/i.test(h));
    if (i >= 0) return i;
    i = norm.findIndex(h => /关键词|keyword|query|term/i.test(h));
    return i; // 可能 -1
  }
  function detectAds(header) {
    const norm = header.map(h => String(h == null ? '' : h).trim());
    const find = (re) => norm.findIndex(h => re.test(h));
    return {
      clicks: find(/^点击$|clicks?/i),
      spend: find(/花费|spend|cost/i),
      roas: find(/roas/i),
      orders: find(/订单|orders?/i),
    };
  }

  // —— 读取文件 —— 
  function handleFiles(files) {
    const file = files && files[0];
    if (!file) return;
    if (!/\.(xlsx|xls|csv)$/i.test(file.name)) {
      flashDrop('请选择 .xlsx、.xls 或 .csv 文件'); return;
    }
    showOverlay('正在读取表格…');
    const reader = new FileReader();
    reader.onload = e => {
      try {
        const data = new Uint8Array(e.target.result);
        workbook = XLSX.read(data, { type: 'array' });
        fileNameEl.textContent = file.name;
        populateSheets();
        configCard.hidden = false;
        resultCard.hidden = true;
        result = null;
        configCard.scrollIntoView({ behavior: reduceMotion ? 'auto' : 'smooth', block: 'start' });
      } catch (err) {
        flashDrop('无法解析该文件，请确认它是有效的 Excel/CSV');
        console.error(err);
      } finally { hideOverlay(); }
    };
    reader.onerror = () => { hideOverlay(); flashDrop('读取文件失败，请重试'); };
    reader.readAsArrayBuffer(file);
  }

  function flashDrop(msg) {
    dropzone.classList.add('error');
    $('drop-hint').textContent = msg;
    setTimeout(() => { dropzone.classList.remove('error'); $('drop-hint').textContent = defaultHint; }, 2600);
  }
  const defaultHint = '拖拽 Excel 到此处，或点击选择文件';

  function populateSheets() {
    sheetSelect.innerHTML = '';
    workbook.SheetNames.forEach(name => {
      const ws = workbook.Sheets[name];
      const ref = ws['!ref'] || '';
      const opt = document.createElement('option');
      opt.value = name; opt.textContent = name + (ref ? '  （' + ref + '）' : '');
      sheetSelect.appendChild(opt);
    });
    // 默认选第一个非空 sheet
    let chosen = workbook.SheetNames.find(n => workbook.Sheets[n]['!ref']) || workbook.SheetNames[0];
    sheetSelect.value = chosen;
    loadSheet(chosen);
  }

  function loadSheet(name) {
    const ws = workbook.Sheets[name];
    const rows = XLSX.utils.sheet_to_json(ws, { header: 1, raw: true, defval: null, blankrows: false });
    if (!rows.length) { headerRow = []; dataRows = []; }
    else { headerRow = rows[0].map(c => c == null ? '' : c); dataRows = rows.slice(1); }

    // 列下拉
    kwSelect.innerHTML = '';
    headerRow.forEach((h, i) => {
      const opt = document.createElement('option');
      opt.value = i;
      opt.textContent = (String(h).trim() || '（空列名）') + '  · 第' + (i + 1) + '列';
      kwSelect.appendChild(opt);
    });
    const kwIdx = pickKwCol(headerRow);
    if (kwIdx >= 0) kwSelect.value = kwIdx;

    adsCols = detectAds(headerRow);
    renderAdsDetected();

    fileMetaEl.textContent = '数据行 ' + fmtInt(dataRows.length) + ' · 字段 ' + headerRow.length + ' 个';
  }

  function renderAdsDetected() {
    const labels = { clicks: '点击', spend: '花费', roas: 'ROAS', orders: '广告订单' };
    const found = Object.keys(labels).filter(k => adsCols[k] >= 0);
    if (!found.length) {
      adsDetected.innerHTML = '<span class="ads-none">未检测到广告表现列（点击 / 花费 / ROAS / 订单）——将仅统计出现次数并分组。</span>';
      return;
    }
    adsDetected.innerHTML = '已识别广告表现列：' +
      found.map(k => '<span class="chip">' + labels[k] + ' → ' + (String(headerRow[adsCols[k]]).trim() || ('第' + (adsCols[k] + 1) + '列')) + '</span>').join('');
  }

  // —— 关联产品并入配件（可逆开关）—— 
  function applyMerge(triples, merge) {
    if (!merge) return triples;
    const seen = new Set(), out = [];
    for (const tp of triples) {
      let [l1, l2, l3] = tp;
      if (l1 === '扩展词' && l2 === '关联产品') l2 = '配件';
      const k = l1 + '|' + l2 + '|' + l3;
      if (!seen.has(k)) { seen.add(k); out.push([l1, l2, l3]); }
    }
    return out;
  }

  // —— 分组主流程 —— 
  function runGrouping() {
    const kwIdx = parseInt(kwSelect.value, 10);
    if (isNaN(kwIdx)) { flashDrop('请先选择"用户搜索词"所在列'); return; }
    showOverlay('正在分组 ' + fmtInt(dataRows.length) + ' 行…');
    // 让遮罩先渲染
    setTimeout(() => {
      try { compute(kwIdx); renderResult(); }
      catch (err) { console.error(err); alert('分组过程中出错：' + err.message); }
      finally { hideOverlay(); }
    }, 30);
  }

  function compute(kwIdx) {
    const merge = mergeAccessory.checked;
    const hasAds = adsCols.clicks >= 0 || adsCols.spend >= 0 || adsCols.roas >= 0 || adsCols.orders >= 0;
    const ci = adsCols.clicks, si = adsCols.spend, ri = adsCols.roas, oi = adsCols.orders;

    // 聚合
    const map = new Map();
    for (const row of dataRows) {
      if (!row) continue;
      const raw = row[kwIdx];
      if (raw == null) continue;
      const kw = String(raw).trim().toLowerCase();
      if (!kw) continue;
      let o = map.get(kw);
      if (!o) { o = { count: 0, clicks: 0, spend: 0, sales: 0, orders: 0 }; map.set(kw, o); }
      o.count++;
      if (hasAds) {
        const sp = si >= 0 ? num(row[si]) : 0;
        const roas = ri >= 0 ? num(row[ri]) : 0;
        o.clicks += ci >= 0 ? num(row[ci]) : 0;
        o.spend += sp;
        o.sales += sp * roas;
        o.orders += oi >= 0 ? num(row[oi]) : 0;
      }
    }

    const terms = Array.from(map.keys());
    const tt = terms.length;
    let to = 0; for (const t of terms) to += map.get(t).count;

    // 分类（缓存 + 合并开关）
    const clsMap = new Map();
    for (const t of terms) clsMap.set(t, applyMerge(classify(t), merge));

    const site = (siteInput.value || '').trim();
    const category = (categoryInput.value || '').trim();

    // 长表
    const longHeader = ['站点', '类目', '一级分类', '二级分类', '三级分类', '用户搜索词', '出现次数', '备注'];
    const long = [];
    for (const t of terms) {
      const cnt = map.get(t).count;
      for (const [l1, l2, l3] of clsMap.get(t)) {
        const note = l1 === '未归类' ? '未匹配，建议人工复核' : '';
        long.push([site, category, l1, l2, l3, t, cnt, note]);
      }
    }
    const ord = x => (window.L1_ORDER && window.L1_ORDER[x] != null) ? window.L1_ORDER[x] : 8;
    long.sort((a, b) =>
      (ord(a[2]) - ord(b[2])) || cmp(a[3], b[3]) || cmp(a[4], b[4]) || (b[6] - a[6]) || cmp(a[5], b[5]));

    // 每词总览
    const wideHeader = ['用户搜索词', '出现次数', '分类数', '一级分类(汇总)', '全部分类(完整路径)'];
    if (hasAds) wideHeader.push('总点击', '总花费', '销售额', 'ACoS%', '广告订单');
    const wide = [];
    for (const t of terms) {
      const o = map.get(t), tr = clsMap.get(t);
      const l1set = Array.from(new Set(tr.map(x => x[0]))).sort((a, b) => ord(a) - ord(b)).join('、');
      const path = tr.map(x => x.filter(Boolean).join('/')).join(' ; ');
      const rowArr = [t, o.count, tr.length, l1set, path];
      if (hasAds) {
        const acos = o.sales > 0 ? round1(o.spend / o.sales * 100) : '';
        rowArr.push(Math.round(o.clicks), round2(o.spend), round2(o.sales), acos, Math.round(o.orders));
      }
      wide.push(rowArr);
    }
    wide.sort((a, b) => (b[1] - a[1]) || cmp(a[0], b[0]));

    // 汇总透视
    const agg = new Map(); // key -> {l1,l2,l3,n,occ}
    for (const t of terms) {
      const cnt = map.get(t).count;
      for (const [l1, l2, l3] of clsMap.get(t)) {
        const k = l1 + '|' + l2 + '|' + l3;
        let a = agg.get(k);
        if (!a) { a = { l1, l2, l3, n: 0, occ: 0 }; agg.set(k, a); }
        a.n++; a.occ += cnt;
      }
    }
    const sumHeader = ['一级分类', '二级分类', '三级分类', '唯一词数', '占唯一词%', '覆盖广告行数', '覆盖广告行%'];
    const sum = Array.from(agg.values()).map(a =>
      [a.l1, a.l2, a.l3, a.n, round1(a.n / tt * 100), a.occ, round1(a.occ / to * 100)]);
    sum.sort((a, b) => (ord(a[0]) - ord(b[0])) || (b[3] - a[3]));

    // 统计 + 一级分布（按唯一词去重计）
    const perL1 = {};
    let multi = 0;
    for (const t of terms) {
      const tr = clsMap.get(t);
      if (tr.length > 1) multi++;
      const ls = new Set(tr.map(x => x[0]));
      ls.forEach(l => perL1[l] = (perL1[l] || 0) + 1);
    }
    const unclassified = perL1['未归类'] || 0;
    const stats = {
      tt, to, multi, unclassified,
      classifiedPct: round1((tt - unclassified) / tt * 100),
      unclassifiedPct: round1(unclassified / tt * 100),
      perL1
    };

    // 字典说明
    const dict = buildDict(stats, merge);

    result = { long, wide, sum, stats, hasAds, longHeader, wideHeader, sumHeader, dict };
  }

  function buildDict(stats, merge) {
    const rows = [
      ['儿童画板（LCD 手写板）· 搜索词分组规则说明', '', ''],
      ['一、分类框架', '', ''],
      ['', '', '一级 / 二级分类沿用 LED Strip Lights「分组规则」的固定骨架；三级分类按本类目自主细化。'],
      ['', '', '一条搜索词可同时命中多个分类（多选分组）：在「分类明细(长表)」中表现为多行；在「每词分类总览」中合并为一行、用分号分隔完整路径。'],
      ['一级分类', '二级分类', '三级分类（本类目细化）'],
      ['核心词', '强相关', '画板/手写板本体词：writing/drawing/doodle/sketch + tablet·pad·board，lcd/led/magnetic/magic slate，含 boogie board / magna doodle / etch a sketch 等通用化品牌词'],
      ['限定词', '产品受众', '人群-儿童/幼儿/婴幼儿/青少年/学龄前·成人；性别-男孩/女孩；年龄段（X year old / ages 2-4 / months 等）'],
      ['限定词', '产品属性', '尺寸（10 inch / 8.5 / large / mini）；颜色（pink/blue/colorful/rainbow 等）'],
      ['限定词', '产品特点', '可擦写·磁性·发光·便携·无尘无墨·安全无毒·充电电池·附笔·教育益智·安静·电子智能·防水·价格诉求'],
      ['限定词', '使用场景', '出行/旅行（travel·airplane·car ride）·学校课堂·居家室内·户外'],
      ['限定词', '产品主题', '节日场合·生日·礼物·促销热点（prime day/deals/clearance）·造型风格（unicorn/dinosaur 等）'],
      ['限定词', '产品系列', '系列/型号名（本类目极少，按需补充）'],
      ['品牌词', '自有品牌', 'KOKODI'],
      ['品牌词', '竞品品牌', '① 直接竞品/同类制造商（TEKFUN、Bravokids、Boogie Board、Crayola、Melissa & Doug、VTech、Fisher-Price…）；② 相邻玩具/IP 引流品牌（LEGO、Barbie、Disney、Bluey、Paw Patrol、Peppa Pig…）。三级=品牌名'],
      ['扩展词', '配件', '手写笔/替换笔·屏幕保护·收纳套·充电线·模板等耗材配件'],
      ['扩展词', merge ? '（关联产品已并入配件）' : '关联产品 ★', merge
        ? '本次导出已将「关联产品」并入「配件」（严格遵循固定二级）。'
        : '本类目自定义新增（LED 规则原仅有「配件」）：涂色/美术用品（蜡笔·涂色书·画笔）、相邻绘画用品（水画垫·画架·白板）、相邻玩具/品类（娃娃·相机·积木·拼图…）、泛玩具/游戏、安静/忙碌玩具'],
      ['二、关键判定说明', '', ''],
      ['', '', '★「扩展词/关联产品」为自定义二级。如需严格遵循固定二级，可勾选页面上的"并入配件"开关——已用 ★ 标注便于一键调整。'],
      ['', '', '拼写纠偏：okd = old（如 "3 year okd boy" 归入年龄段）；tous = toys（归入泛玩具）。'],
      ['', '', 'color/coloring 区分：colorful/colored/具体颜色→颜色属性；coloring book→关联美术用品；coloring pad/board→核心词。'],
      ['', '', '数字消歧：邻接 inch/" →尺寸；邻接 year/old/yr/month/age/+ →年龄段；二者皆无的裸数字不强行归类。'],
      ['', '', '已识别西班牙语词（pizarra/tableta/niños/juguetes/regalos/años 等）并并入对应分类。'],
      ['', '', '促销/热点词（prime day、lightning deals、clearance）多为泛流量，转化通常偏弱，可重点作为否定词候选。'],
      ['三、覆盖情况', '', ''],
      ['', '', '唯一搜索词 ' + fmtInt(stats.tt) + ' 个，对应广告报表行 ' + fmtInt(stats.to) + ' 行；已分类 ' + stats.classifiedPct + '%（按词），未归类 ' + stats.unclassifiedPct + '%（多为 ASIN 编号/账户系统词/生僻拼写，已在长表备注标记"建议人工复核"）。'],
    ];
    return rows;
  }

  // —— 渲染结果 —— 
  function renderResult() {
    resultCard.hidden = false;
    const s = result.stats;
    $('stat-uniq').textContent = fmtInt(s.tt);
    $('stat-classified').textContent = s.classifiedPct + '%';
    $('stat-unclassified').textContent = s.unclassifiedPct + '%';
    $('stat-multi').textContent = fmtInt(s.multi);
    renderSpectrum(s);
    activeTab = 'sum';
    setActiveTabButton();
    filterInput.value = '';
    renderTable();
    resultCard.scrollIntoView({ behavior: reduceMotion ? 'auto' : 'smooth', block: 'start' });
  }

  function renderSpectrum(s) {
    const order = ['核心词', '限定词', '品牌词', '扩展词', '未归类'];
    const present = order.filter(l => s.perL1[l]);
    const total = present.reduce((a, l) => a + s.perL1[l], 0) || 1;
    const bar = $('spectrum-bar');
    bar.innerHTML = '';
    const legend = $('spectrum-legend');
    legend.innerHTML = '';
    present.forEach(l => {
      const pct = s.perL1[l] / total * 100;
      const seg = document.createElement('div');
      seg.className = 'seg';
      seg.style.background = L1_COLORS[l];
      seg.style.width = reduceMotion ? pct + '%' : '0%';
      seg.title = l + ' · ' + fmtInt(s.perL1[l]) + ' 词';
      if (pct > 7) seg.textContent = l;
      bar.appendChild(seg);
      if (!reduceMotion) requestAnimationFrame(() => requestAnimationFrame(() => { seg.style.width = pct + '%'; }));

      const li = document.createElement('div');
      li.className = 'legend-item';
      li.innerHTML = '<span class="dot" style="background:' + L1_COLORS[l] + '"></span>' +
        '<span class="lg-name">' + l + '</span>' +
        '<span class="lg-desc">' + (L1_DESC[l] || '') + '</span>' +
        '<span class="lg-num">' + fmtInt(s.perL1[l]) + ' 词 · ' + round1(s.perL1[l] / s.tt * 100) + '%</span>';
      legend.appendChild(li);
    });
  }

  // —— 预览表格 —— 
  function currentTable() {
    if (activeTab === 'sum') return { header: result.sumHeader, rows: result.sum, l1col: 0 };
    if (activeTab === 'wide') return { header: result.wideHeader, rows: result.wide, l1col: -1 };
    return { header: result.longHeader, rows: result.long, l1col: 2 };
  }

  function renderTable() {
    const { header, rows, l1col } = currentTable();
    const q = (filterInput.value || '').trim().toLowerCase();
    let filtered = rows;
    if (q) filtered = rows.filter(r => r.some(c => String(c).toLowerCase().includes(q)));
    const shown = filtered.slice(0, PREVIEW_LIMIT);

    let html = '<table class="grid"><thead><tr>';
    header.forEach(h => html += '<th>' + esc(h) + '</th>');
    html += '</tr></thead><tbody>';
    for (const r of shown) {
      const l1 = l1col >= 0 ? r[l1col] : null;
      const accent = l1 && L1_COLORS[l1] ? ' style="box-shadow: inset 3px 0 0 ' + L1_COLORS[l1] + '"' : '';
      html += '<tr' + accent + '>';
      r.forEach((c, i) => {
        const cls = (typeof c === 'number') ? ' class="num"' : '';
        html += '<td' + cls + '>' + esc(c) + '</td>';
      });
      html += '</tr>';
    }
    html += '</tbody></table>';
    tableHost.innerHTML = html;

    const total = filtered.length;
    previewNote.textContent = total > PREVIEW_LIMIT
      ? '共 ' + fmtInt(total) + ' 行，预览前 ' + PREVIEW_LIMIT + ' 行 · 完整数据请下载 Excel'
      : '共 ' + fmtInt(total) + ' 行';
  }

  function esc(v) {
    if (v == null) return '';
    return String(v).replace(/[&<>]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));
  }

  function setActiveTabButton() {
    ['sum', 'wide', 'long'].forEach(t => {
      const b = $('tab-' + t);
      if (b) b.classList.toggle('active', t === activeTab);
    });
  }

  // —— 导出 Excel —— 
  function download() {
    if (!result) return;
    showOverlay('正在生成 Excel…');
    setTimeout(() => {
      try {
        const wb = XLSX.utils.book_new();
        const colW = arr => ({ '!cols': arr.map(w => ({ wch: w })) });

        const wsLong = XLSX.utils.aoa_to_sheet([result.longHeader, ...result.long]);
        Object.assign(wsLong, colW([12, 26, 10, 12, 18, 42, 9, 20]));
        wsLong['!freeze'] = { xSplit: 0, ySplit: 1 };
        XLSX.utils.book_append_sheet(wb, wsLong, '分类明细(长表)');

        const wsWide = XLSX.utils.aoa_to_sheet([result.wideHeader, ...result.wide]);
        Object.assign(wsWide, colW(result.hasAds ? [40, 9, 7, 16, 50, 8, 10, 10, 8, 9] : [40, 9, 7, 16, 50]));
        wsWide['!freeze'] = { xSplit: 0, ySplit: 1 };
        XLSX.utils.book_append_sheet(wb, wsWide, '每词分类总览');

        const wsSum = XLSX.utils.aoa_to_sheet([result.sumHeader, ...result.sum]);
        Object.assign(wsSum, colW([10, 16, 24, 10, 11, 14, 12]));
        wsSum['!freeze'] = { xSplit: 0, ySplit: 1 };
        XLSX.utils.book_append_sheet(wb, wsSum, '分类汇总');

        const wsDict = XLSX.utils.aoa_to_sheet(result.dict);
        Object.assign(wsDict, colW([20, 20, 78]));
        XLSX.utils.book_append_sheet(wb, wsDict, '分类字典说明');

        const cat = (categoryInput.value || '搜索词').trim().replace(/[\\\/:\*\?\[\]]/g, '');
        const stamp = new Date().toISOString().slice(0, 10);
        XLSX.writeFile(wb, (cat || '搜索词') + '_分类_' + stamp + '.xlsx');
      } catch (err) { console.error(err); alert('导出失败：' + err.message); }
      finally { hideOverlay(); }
    }, 30);
  }

  function reset() {
    workbook = null; result = null; headerRow = []; dataRows = [];
    fileInput.value = '';
    configCard.hidden = true; resultCard.hidden = true;
    window.scrollTo({ top: 0, behavior: reduceMotion ? 'auto' : 'smooth' });
  }

  // —— 事件绑定 —— 
  dropzone.addEventListener('click', () => fileInput.click());
  dropzone.addEventListener('keydown', e => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); fileInput.click(); } });
  fileInput.addEventListener('change', e => handleFiles(e.target.files));
  ['dragenter', 'dragover'].forEach(ev => dropzone.addEventListener(ev, e => { e.preventDefault(); dropzone.classList.add('over'); }));
  ['dragleave', 'drop'].forEach(ev => dropzone.addEventListener(ev, e => { e.preventDefault(); dropzone.classList.remove('over'); }));
  dropzone.addEventListener('drop', e => { if (e.dataTransfer && e.dataTransfer.files) handleFiles(e.dataTransfer.files); });

  sheetSelect.addEventListener('change', e => loadSheet(e.target.value));
  runBtn.addEventListener('click', runGrouping);
  downloadBtn.addEventListener('click', download);
  resetBtn.addEventListener('click', reset);
  filterInput.addEventListener('input', () => { if (result) renderTable(); });
  ['sum', 'wide', 'long'].forEach(t => {
    const b = $('tab-' + t);
    if (b) b.addEventListener('click', () => { activeTab = t; setActiveTabButton(); renderTable(); });
  });

  // 折叠面板
  document.querySelectorAll('[data-toggle]').forEach(btn => {
    btn.addEventListener('click', () => {
      const target = $(btn.getAttribute('data-toggle'));
      if (!target) return;
      const open = target.hidden;
      target.hidden = !open;
      btn.classList.toggle('open', open);
    });
  });

  $('drop-hint').textContent = defaultHint;
})();

