// ===== 儿童画板搜索词分类器 · JS 版（移植自 classifier.py，逻辑 1:1）=====
// 词边界正则匹配，支持多词短语；空格容忍 \s+，连字符容忍 [-\s]*

function buildP(...words) {
  const pats = words.map(w => {
    w = w.trim();
    let out = '';
    for (const ch of w) {
      if (ch === ' ') out += '\\s+';
      else if (ch === '-') out += '[-\\s]*';
      else if ('.*+?^${}()|[]\\&~#'.includes(ch)) out += '\\' + ch;
      else out += ch;
    }
    return '(?<![a-z])' + out + '(?![a-z])';
  });
  return new RegExp(pats.join('|'), 'i');
}

// 核心相关 token
const RE_DRAW = /(?<![a-z])(?:draw|drawing|write|writing|doodle|doodling|sketch|sketching|scribble|scribbling|tracing|colou?ring|dibujar|dibujo)(?![a-z])/i;
const RE_SURF = /(?<![a-z])(?:tablet|tablets|tableta|tabletas|pad|pads|board|boards|slate|screen|notepad|note\s*pad|pizarra|pizarras)(?![a-z])/i;
const RE_LCDLED = /(?<![a-z])(?:lcd|led)(?![a-z])/i;
const RE_MAGNETIC = /(?<![a-z])(?:magnetic|magnetica|magn[e\u00e9]tica|magnet)(?![a-z])/i;
const RE_MAGIC = /(?<![a-z])(?:magic|m[a\u00e1]gica)(?![a-z])/i;

const RE_CORE_PHRASE = buildP(
 'writing tablet','writing tablets','drawing tablet','drawing tablets','writing pad','drawing pad','drawing pads',
 'writing board','drawing board','drawing boards','doodle board','doodle boards','doodle pad','doodle pads',
 'sketch pad','sketch board','sketch tablet','sketchpad','scribble board','scribble pad','scribble screen',
 'magic slate','magic pad','magic board','writing slate','drawing slate','coloring pad','coloring board','coloring tablet',
 'lcd tablet','led tablet','lcd writing','led writing','lcd drawing','led drawing','lcd screen','writing screen',
 'magna doodle','magnadoodle','etch a sketch','etch-a-sketch','etch sketch','boogie board','boogieboard','boogie boards',
 'magic boards','magic slates','handwriting tablet','rewritable tablet','write and wipe','write & wipe',
 'art pad','art pads','sketch pals','doodle pals','glow board','glow pad','light up board','light board','light pad',
 'slate','slates','doodler','doodlers','aqua drawing','aqua pad',
 'kids tablet','kids tablets','tablet for kids','tablets for kids','tablet for toddlers','toddler tablet','tablet for toddler',
 'tablet para dibujar','tableta de dibujo','tableta para dibujar','pizarra magica','pizarra magnetica',
 'pizarra led','pizarra de dibujo','tablet de dibujo','pizarra para dibujar');

const RE_BPTS = /(?<![a-z])(?:board|pad|tablet|doodle|slate)(?![a-z])/i;
const RE_BPTSSDD = /(?<![a-z])(?:board|pad|tablet|slate|screen|drawing|doodle)(?![a-z])/i;
const RE_DOODLE = /(?<![a-z])doodle(?![a-z])/i;
const RE_DOODLE_CTX = /(?<![a-z])(?:glow|board|pad|tablet|magic|magnetic|lcd|led)(?![a-z])/i;

function isCore(term) {
  if (RE_CORE_PHRASE.test(term)) return true;
  const hasSurf = RE_SURF.test(term);
  if (RE_DRAW.test(term) && hasSurf) return true;
  if (RE_LCDLED.test(term) && (hasSurf || RE_DRAW.test(term))) return true;
  if (RE_MAGNETIC.test(term) && (RE_DRAW.test(term) || RE_BPTS.test(term))) return true;
  if (RE_MAGIC.test(term) && RE_BPTSSDD.test(term)) return true;
  if (RE_DOODLE.test(term) && RE_DOODLE_CTX.test(term)) return true;
  return false;
}

// ===== 规则表：[正则, 一级, 二级, 三级] =====
