const XLSX = require('./node_modules/xlsx');
const { classify, L1_ORDER } = require('./classifier.js');

const wb = XLSX.readFile('/mnt/user-data/uploads/词源.xlsx');
const ws = wb.Sheets['Sheet1'];
const rows = XLSX.utils.sheet_to_json(ws, { header: 1, raw: true, defval: null, blankrows: false });
const header = rows[0].map(c => c == null ? '' : c);
const dataRows = rows.slice(1);
console.log('表头:', header);

// detectAds（与 app.js 同）
const norm = header.map(h => String(h == null ? '' : h).trim());
const find = re => norm.findIndex(h => re.test(h));
const ads = {
  clicks: find(/^点击$|clicks?/i),
  spend: find(/花费|spend|cost/i),
  roas: find(/roas/i),
  orders: find(/订单|orders?/i),
};
console.log('广告列索引:', ads, '→',
  ['clicks','spend','roas','orders'].map(k => k+'='+(ads[k]>=0?header[ads[k]]:'(无)')).join(', '));

const kwIdx = norm.indexOf('用户搜索词');
console.log('搜索词列索引:', kwIdx, header[kwIdx]);

function num(v){ if(v==null||v==='')return 0; const n=parseFloat(String(v).replace(/,/g,'').replace(/[^0-9.\-]/g,'')); return isNaN(n)?0:n; }
const merge = false; // 默认保留关联产品

const hasAds = ads.clicks>=0||ads.spend>=0||ads.roas>=0||ads.orders>=0;
const map = new Map();
for (const row of dataRows){
  if(!row) continue;
  const raw = row[kwIdx]; if(raw==null) continue;
  const kw = String(raw).trim().toLowerCase(); if(!kw) continue;
  let o = map.get(kw); if(!o){o={count:0,clicks:0,spend:0,sales:0,orders:0};map.set(kw,o);}
  o.count++;
  if(hasAds){
    const sp = ads.spend>=0?num(row[ads.spend]):0;
    const roas = ads.roas>=0?num(row[ads.roas]):0;
    o.clicks += ads.clicks>=0?num(row[ads.clicks]):0;
    o.spend += sp; o.sales += sp*roas;
    o.orders += ads.orders>=0?num(row[ads.orders]):0;
  }
}
const terms = Array.from(map.keys());
const tt = terms.length;
let to=0; for(const t of terms) to+=map.get(t).count;

function applyMerge(tr){ if(!merge) return tr; const seen=new Set(),out=[]; for(let[l1,l2,l3]of tr){ if(l1==='扩展词'&&l2==='关联产品')l2='配件'; const k=l1+'|'+l2+'|'+l3; if(!seen.has(k)){seen.add(k);out.push([l1,l2,l3]);}} return out; }
const clsMap = new Map();
for(const t of terms) clsMap.set(t, applyMerge(classify(t)));

// 长表行数
let longCount=0; for(const t of terms) longCount += clsMap.get(t).length;

// 汇总组合数
const agg=new Map();
for(const t of terms){ const cnt=map.get(t).count; for(const[l1,l2,l3]of clsMap.get(t)){ const k=l1+'|'+l2+'|'+l3; let a=agg.get(k); if(!a){a={l1,l2,l3,n:0,occ:0};agg.set(k,a);} a.n++; a.occ+=cnt; } }

// 统计
const perL1={}; let multi=0;
for(const t of terms){ const tr=clsMap.get(t); if(tr.length>1)multi++; new Set(tr.map(x=>x[0])).forEach(l=>perL1[l]=(perL1[l]||0)+1); }
const unclassified = perL1['未归类']||0;

console.log('\n===== 核对（merge=false，与第一阶段同口径）=====');
console.log('唯一搜索词      :', tt, '（第一阶段 20,212）');
console.log('广告报表行(sum) :', to);
console.log('长表行数        :', longCount, '（第一阶段 47,538）');
console.log('汇总组合数      :', agg.size, '（第一阶段 106）');
console.log('命中多类的词    :', multi);
console.log('未归类词数      :', unclassified, '→ 已分类', (((tt-unclassified)/tt*100).toFixed(1))+'%', '（第一阶段 97.3%）');
console.log('一级分布 perL1  :', perL1);
console.log('广告聚合合计    : 点击', Math.round([...map.values()].reduce((a,o)=>a+o.clicks,0)),
  '| 花费', ([...map.values()].reduce((a,o)=>a+o.spend,0)).toFixed(2),
  '| 销售额', ([...map.values()].reduce((a,o)=>a+o.sales,0)).toFixed(2));

