const XLSX = require('./node_modules/xlsx');
const { classify, L1_ORDER } = require('./classifier.js');
const wb0 = XLSX.readFile('/mnt/user-data/uploads/词源.xlsx');
const rows = XLSX.utils.sheet_to_json(wb0.Sheets['Sheet1'], { header:1, raw:true, defval:null, blankrows:false });
const header = rows[0].map(c=>c==null?'':c); const dataRows = rows.slice(1);
const kwIdx = header.map(h=>String(h).trim()).indexOf('用户搜索词');
const ads = { clicks:10, spend:11, roas:13, orders:14 };
function num(v){ if(v==null||v==='')return 0; const n=parseFloat(String(v).replace(/,/g,'').replace(/[^0-9.\-]/g,'')); return isNaN(n)?0:n; }
function round2(x){return Math.round((x+Number.EPSILON)*100)/100;} function round1(x){return Math.round((x+Number.EPSILON)*10)/10;}
function cmp(a,b){return a<b?-1:a>b?1:0;}
const ord = x => (L1_ORDER[x]!=null)?L1_ORDER[x]:8;

const map=new Map();
for(const row of dataRows){ if(!row)continue; const raw=row[kwIdx]; if(raw==null)continue; const kw=String(raw).trim().toLowerCase(); if(!kw)continue;
  let o=map.get(kw); if(!o){o={count:0,clicks:0,spend:0,sales:0,orders:0};map.set(kw,o);} o.count++;
  const sp=num(row[ads.spend]),roas=num(row[ads.roas]); o.clicks+=num(row[ads.clicks]); o.spend+=sp; o.sales+=sp*roas; o.orders+=num(row[ads.orders]); }
const terms=[...map.keys()], tt=terms.length; let to=0; for(const t of terms)to+=map.get(t).count;
const clsMap=new Map(); for(const t of terms) clsMap.set(t, classify(t)); // merge=false

const longHeader=['站点','类目','一级分类','二级分类','三级分类','用户搜索词','出现次数','备注'];
const long=[]; for(const t of terms){ const cnt=map.get(t).count; for(const[l1,l2,l3]of clsMap.get(t)){ long.push(['','儿童画板',l1,l2,l3,t,cnt, l1==='未归类'?'未匹配，建议人工复核':'']); } }
long.sort((a,b)=>(ord(a[2])-ord(b[2]))||cmp(a[3],b[3])||cmp(a[4],b[4])||(b[6]-a[6])||cmp(a[5],b[5]));

const wideHeader=['用户搜索词','出现次数','分类数','一级分类(汇总)','全部分类(完整路径)','总点击','总花费','销售额','ACoS%','广告订单'];
const wide=[]; for(const t of terms){ const o=map.get(t),tr=clsMap.get(t);
  const l1set=[...new Set(tr.map(x=>x[0]))].sort((a,b)=>ord(a)-ord(b)).join('、');
  const path=tr.map(x=>x.filter(Boolean).join('/')).join(' ; ');
  const acos=o.sales>0?round1(o.spend/o.sales*100):'';
  wide.push([t,o.count,tr.length,l1set,path,Math.round(o.clicks),round2(o.spend),round2(o.sales),acos,Math.round(o.orders)]); }
wide.sort((a,b)=>(b[1]-a[1])||cmp(a[0],b[0]));

const agg=new Map(); for(const t of terms){ const cnt=map.get(t).count; for(const[l1,l2,l3]of clsMap.get(t)){ const k=l1+'|'+l2+'|'+l3; let a=agg.get(k); if(!a){a={l1,l2,l3,n:0,occ:0};agg.set(k,a);} a.n++; a.occ+=cnt; } }
const sumHeader=['一级分类','二级分类','三级分类','唯一词数','占唯一词%','覆盖广告行数','覆盖广告行%'];
const sum=[...agg.values()].map(a=>[a.l1,a.l2,a.l3,a.n,round1(a.n/tt*100),a.occ,round1(a.occ/to*100)]);
sum.sort((a,b)=>(ord(a[0])-ord(b[0]))||(b[3]-a[3]));
const dict=[['说明','',''],['唯一词',''+tt,'']];

const wb=XLSX.utils.book_new();
const add=(name,h,r)=>{const ws=XLSX.utils.aoa_to_sheet([h,...r]); XLSX.utils.book_append_sheet(wb,ws,name);};
add('分类明细(长表)',longHeader,long); add('每词分类总览',wideHeader,wide); add('分类汇总',sumHeader,sum);
const wsd=XLSX.utils.aoa_to_sheet(dict); XLSX.utils.book_append_sheet(wb,wsd,'分类字典说明');
XLSX.writeFile(wb,'/tmp/out.xlsx');

// 读回校验
const rb=XLSX.readFile('/tmp/out.xlsx');
console.log('导出 sheet:', rb.SheetNames);
for(const n of rb.SheetNames){ const ref=rb.Sheets[n]['!ref']; console.log('  ', n, '→', ref); }
const fs=require('fs'); console.log('文件字节:', fs.statSync('/tmp/out.xlsx').size);
// 抽样核对：明细首行、含特殊字符的词是否为文本
const back=XLSX.utils.sheet_to_json(rb.Sheets['分类明细(长表)'],{header:1});
console.log('长表数据行(不含表头):', back.length-1, '应为', long.length);
const offenders = back.filter(r=>/^[=\-+@]/.test(String(r[5])));
console.log('以 = - + @ 开头的搜索词样本(应原样为文本):', offenders.slice(0,3).map(r=>r[5]));

