// =====================================================================
// 层叠的中国 v2 — 应用逻辑
// 章节式导览引擎：一章 = 一个对比。
// 地图分四层：省底色 → 市级文化拼图 → 省界墨线(置顶) → 标注。
// 市级边界来自 DataV.GeoAtlas（27 省并行加载，多源备援），
// 失败时优雅降级为省级着色。
// =====================================================================

(function () {
  "use strict";

  const A = window.ATLAS_DATA;
  const W = 1000, H = 780;

  // ============================ 工具 ============================

  // 行政名 → 简称（去掉 市/盟/地区/各类自治州 等后缀）
  const ETHNIC = "(回族|满族|蒙古族?|维吾尔族?|哈萨克族?|藏族|彝族|壮族|苗族|侗族|白族|傣族|土家族|布依族|朝鲜族|哈尼族|傈僳族|景颇族|柯尔克孜族?|锡伯族?|羌族|黎族|畲族|仡佬族|各族)";
  const reEthnic = new RegExp(ETHNIC + "+(自治州|自治县|自治旗|自治区)$");
  const reSuffix = /(自治州|自治区|特别行政区|地区|林区|市|盟|省)$/;
  function shortName(n) {
    if (!n) return "";
    return n.replace(reEthnic, "").replace(reSuffix, "");
  }

  // 市级 → 方言区
  function classifyDialect(provShort, prefShort) {
    const table = A.PREF_DIALECT[provShort] || {};
    let v = table[prefShort];
    if (v === undefined) v = table._default;
    if (v === undefined) v = A.PROV_FALLBACK[provShort] || "nonhanmain";
    return Array.isArray(v) ? { g: v[0], note: v[1] } : { g: v, note: null };
  }

  // 市级 → 文化圈
  function classifyCulture(provShort, prefShort) {
    const table = A.PREF_CULTURE[provShort] || A.PREF_CULTURE["_default_"];
    let v = table[prefShort];
    if (v === undefined) v = table._default;
    if (v === undefined) v = "han";
    return Array.isArray(v) ? { g: v[0], note: v[1] } : { g: v, note: null };
  }

  // ============================ 投影与画布 ============================
  const projection = d3.geoMercator();
  const path = d3.geoPath().projection(projection);

  // 先用大陆框定投影（避免南海诸岛把全图压小）
  const MAINLAND = { type: "Feature", geometry: { type: "Polygon",
    coordinates: [[[73,17.8],[135.6,17.8],[135.6,53.8],[73,53.8],[73,17.8]]] } };
  // 注意绕向：d3 要求外环球面逆时针；若面积超过半球则反转（v1 的教训）
  if (d3.geoArea(MAINLAND) > 2 * Math.PI)
    MAINLAND.geometry.coordinates[0].reverse();
  projection.fitExtent([[14, 14], [W - 14, H - 14]], MAINLAND);

  const svg = d3.select("#china-map")
    .attr("viewBox", `0 0 ${W} ${H}`)
    .attr("preserveAspectRatio", "xMidYMid meet");

  const gRoot   = svg.append("g").attr("class", "viewport");
  const gProv   = gRoot.append("g");                       // 省底色
  const gPref   = gRoot.append("g");                       // 市级拼图
  const gTerr   = gRoot.append("g").style("display","none"); // 自然分区
  const gRange  = gRoot.append("g").style("display","none"); // 山脉
  const gProvTop= gRoot.append("g");                       // 省界墨线(置顶)
  const gLabel  = gRoot.append("g");                       // 区域大字标
  const gPoint  = gRoot.append("g");                       // 县级故事点

  const tooltip = d3.select("#tooltip");

  // ============================ 状态 ============================
  let provFeatures = [];     // 省级 features（含港澳台、南海）
  let prefFeatures = [];     // 市级 features（带 __prov / __short / __dia / __cul）
  let degraded = false;      // 市级数据彻底失败 → 省级降级
  let sceneIdx = 0;
  let subKey = {};           // 每章的子选项记忆 { fracture:'江苏', enclaves:'hakka' }

  // ============================ 数据加载 ============================
  const DATAV = "https://geo.datav.aliyun.com/areas_v3/bound/";
  const GH1 = "https://cdn.jsdelivr.net/gh/longwosion/geojson-map-china@master/";
  const GH2 = "https://raw.githubusercontent.com/longwosion/geojson-map-china/master/";

  async function tryFetch(urls) {
    for (const u of urls) {
      try {
        const r = await fetch(u, { mode: "cors" });
        if (r.ok) return await r.json();
      } catch (e) { /* 下一个源 */ }
    }
    return null;
  }

  // 需要抓取市级子级的 27 个省区（直辖市/特区直接用省级面）
  const PROVS = [
    ["130000","13","河北"],["140000","14","山西"],["150000","15","内蒙古"],
    ["210000","21","辽宁"],["220000","22","吉林"],["230000","23","黑龙江"],
    ["320000","32","江苏"],["330000","33","浙江"],["340000","34","安徽"],
    ["350000","35","福建"],["360000","36","江西"],["370000","37","山东"],
    ["410000","41","河南"],["420000","42","湖北"],["430000","43","湖南"],
    ["440000","44","广东"],["450000","45","广西"],["460000","46","海南"],
    ["510000","51","四川"],["520000","52","贵州"],["530000","53","云南"],
    ["540000","54","西藏"],["610000","61","陕西"],["620000","62","甘肃"],
    ["630000","63","青海"],["640000","64","宁夏"],["650000","65","新疆"]
  ];
  const DIRECT = ["北京","天津","上海","重庆","台湾","香港","澳门"];

  async function loadBase() {
    const data = await tryFetch([
      DATAV + "100000_full.json",
      GH1 + "china.json",
      GH2 + "china.json"
    ]);
    if (!data || !data.features) throw new Error("省级底图加载失败");
    provFeatures = data.features.filter(f => f.properties && f.properties.name);
    return provFeatures;
  }

  async function loadPrefs(onProgress) {
    let done = 0;
    const jobs = PROVS.map(async ([adcode, code2, name]) => {
      const data = await tryFetch([
        `${DATAV}${adcode}_full.json`,
        `${GH1}geometryProvince/${code2}.json`,
        `${GH2}geometryProvince/${code2}.json`
      ]);
      if (data && data.features) {
        data.features.forEach(f => {
          const nm = f.properties && f.properties.name;
          if (!nm) return;
          f.__prov = name;
          f.__short = shortName(nm);
          f.__full = nm;
          prefFeatures.push(f);
        });
      }
      done++; onProgress(done, PROVS.length);
    });
    await Promise.all(jobs);

    // 直辖市/特区：用省级面充当"一个市"
    DIRECT.forEach(name => {
      const f = provFeatures.find(p => shortName(p.properties.name) === name);
      if (f) {
        const clone = { type: "Feature", geometry: f.geometry,
          properties: f.properties, __prov: name, __short: name,
          __full: f.properties.name };
        prefFeatures.push(clone);
      }
    });

    // 某省市级数据缺失 → 用省级面补洞
    const loaded = new Set(prefFeatures.map(f => f.__prov));
    PROVS.forEach(([,,name]) => {
      if (!loaded.has(name)) {
        const f = provFeatures.find(p => shortName(p.properties.name) === name);
        if (f) prefFeatures.push({ type:"Feature", geometry:f.geometry,
          properties:f.properties, __prov:name, __short:name, __full:f.properties.name });
      }
    });

    degraded = prefFeatures.length <= DIRECT.length + 5;

    // 预归类
    prefFeatures.forEach(f => {
      f.__dia = classifyDialect(f.__prov, f.__short);
      f.__cul = classifyCulture(f.__prov, f.__short);
    });
  }

  // ============================ 渲染：静态层 ============================
  function renderStatic() {
    // 省底色
    gProv.selectAll("path").data(provFeatures).enter().append("path")
      .attr("class", "prov-base").attr("d", path);

    // 市级拼图
    gPref.selectAll("path").data(prefFeatures).enter().append("path")
      .attr("class", "pref")
      .attr("d", path)
      .attr("vector-effect", "non-scaling-stroke")
      .on("mousemove", function (ev, f) {
        const s = scene();
        let line2 = "";
        if (s.mode === "culture") {
          const cg = A.CULTURE_GROUPS[f.__cul.g];
          line2 = cg ? cg.name : "";
        } else {
          const dg = A.DIALECT_GROUPS[f.__dia.g];
          line2 = dg ? dg.name : "";
        }
        tooltip.style("opacity", 1)
          .style("left", (ev.pageX + 14) + "px")
          .style("top",  (ev.pageY - 10) + "px")
          .html(`<b>${f.__full}</b><span>${line2}</span>`);
      })
      .on("mouseleave", () => tooltip.style("opacity", 0))
      .on("click", (ev, f) => showDetail(f));

    // 省界墨线（置顶，叠在拼图之上 —— 错位由此可读）
    gProvTop.selectAll("path").data(provFeatures).enter().append("path")
      .attr("class", "prov-line").attr("d", path)
      .attr("vector-effect", "non-scaling-stroke");

    // 自然分区（屏幕坐标平滑闭合曲线，无球面绕向问题）
    const line = d3.line().curve(d3.curveCatmullRomClosed.alpha(0.6));
    A.TERRAIN_REGIONS.forEach(t => {
      const pts = t.ring.map(c => projection(c));
      gTerr.append("path")
        .attr("d", line(pts))
        .attr("class", "terr")
        .style("fill", t.color).style("stroke", t.color)
        .on("click", () => showTerrainDetail(t))
        .on("mousemove", ev => {
          tooltip.style("opacity",1)
            .style("left",(ev.pageX+14)+"px").style("top",(ev.pageY-10)+"px")
            .html(`<b>${t.name}</b><span>${t.type}</span>`);
        })
        .on("mouseleave", () => tooltip.style("opacity",0));
      const c = projection(centroid(t.ring));
      gTerr.append("text").attr("class","terr-label")
        .attr("x", c[0]).attr("y", c[1]).text(t.name);
    });

    // 山脉
    const rline = d3.line().curve(d3.curveCatmullRom.alpha(0.7));
    A.MOUNTAIN_RANGES.forEach(m => {
      const pts = m.path.map(c => projection(c));
      gRange.append("path").attr("d", rline(pts)).attr("class","range")
        .attr("vector-effect","non-scaling-stroke")
        .on("click", () => showRangeDetail(m));
      const mid = pts[Math.floor(pts.length/2)];
      gRange.append("text").attr("class","range-label")
        .attr("x", mid[0]+6).attr("y", mid[1]-4).text(m.name)
        .on("click", () => showRangeDetail(m));
    });

    // 县级故事点
    A.POINTS.forEach(p => {
      const [x,y] = projection([p.lng, p.lat]);
      const g = gPoint.append("g").attr("class","pt")
        .attr("transform",`translate(${x},${y})`)
        .style("display","none")
        .on("click",()=>showPointDetail(p));
      g.append("circle").attr("r",4);
      g.append("circle").attr("r",8).attr("class","pt-halo");
      g.append("text").attr("x",10).attr("y",4).text(p.name);
    });
  }

  function centroid(ring){let sx=0,sy=0;ring.forEach(([x,y])=>{sx+=x;sy+=y});return [sx/ring.length,sy/ring.length];}

  // 区域大字标（方言/文化两套）
  const DIA_LABELS = [
    ["东北官话",[125.6,46.2],"dongbei"],["冀鲁",[116.2,37.5],"jilu"],
    ["胶辽",[121.7,37.1],"jiaoliao"],["中原官话",[113.4,34.1],"zhongyuan"],
    ["兰银",[100.2,38.8],"lanyin"],["江淮",[118.6,32.7],"jianghuai"],
    ["西南官话",[104.6,29.2],"southwest"],["晋语",[111.9,37.9],"jin"],
    ["吴语",[120.1,30.1],"wu"],["徽",[118.2,29.9],"hui"],
    ["赣语",[115.6,28.1],"gan"],["湘语",[111.9,27.4],"xiang"],
    ["闽",[118.4,26],"minnan"],["粤语",[112.4,22.8],"yue"],
    ["客家",[115.7,25],"hakka"],["北京",[116.2,40.4],"beijing"]
  ];
  const CUL_LABELS = [
    ["卫藏",[87.8,30.6],"weizang"],["安多",[98.6,35.2],"amdo"],
    ["康",[99.8,31.2],"kham"],["维吾尔",[80.8,39.2],"uyghur"],
    ["哈萨克",[82.6,46.2],"kazakh"],["蒙古",[113.5,44.6],"mongol"],
    ["回",[106,37.2],"hui"],["朝鲜",[129.2,43.2],"korean"],
    ["彝",[102.4,27.6],"yi"],["苗瑶",[109.2,28.4],"miaoyao"],
    ["壮侗",[107.2,23.6],"zhuangdong"],["滇西",[99.6,26.2],"swethnic"]
  ];
  function renderLabels(list) {
    gLabel.selectAll("*").remove();
    list.forEach(([t, c, g]) => {
      const [x,y] = projection(c);
      gLabel.append("text").attr("class","area-label")
        .attr("x",x).attr("y",y).attr("data-g",g).text(t);
    });
  }

  // ============================ 视角 ============================
  function zoomToPx(b, pad = 0.10, dur = 950) {
    const dx = b[1][0]-b[0][0], dy = b[1][1]-b[0][1];
    const k = Math.max(1, Math.min(10, (1-pad)/Math.max(dx/W, dy/H)));
    const cx = (b[0][0]+b[1][0])/2, cy = (b[0][1]+b[1][1])/2;
    gRoot.transition().duration(dur).ease(d3.easeCubicInOut)
      .attr("transform", `translate(${W/2-k*cx},${H/2-k*cy}) scale(${k})`);
  }
  function zoomNational(dur=950){ gRoot.transition().duration(dur).ease(d3.easeCubicInOut).attr("transform","translate(0,0) scale(1)"); }
  function zoomGeoBBox(bb, pad){ // bb=[[lng0,lat0],[lng1,lat1]]
    const corners=[projection([bb[0][0],bb[0][1]]),projection([bb[0][0],bb[1][1]]),
                   projection([bb[1][0],bb[0][1]]),projection([bb[1][0],bb[1][1]])];
    const xs=corners.map(c=>c[0]), ys=corners.map(c=>c[1]);
    zoomToPx([[Math.min(...xs),Math.min(...ys)],[Math.max(...xs),Math.max(...ys)]], pad);
  }
  function zoomProvince(name){
    const f = provFeatures.find(p => shortName(p.properties.name) === name);
    if (f) zoomToPx(path.bounds(f), 0.16);
  }

  // ============================ 场景引擎 ============================
  const scene = () => A.SCENES[sceneIdx];

  function colorOf(f, s, sub) {
    const dia = A.DIALECT_GROUPS[f.__dia.g], cul = A.CULTURE_GROUPS[f.__cul.g];
    switch (s.mode) {
      case "dialect":     return { fill: dia.color, op: 0.92 };
      case "dialect-dim": return { fill: dia.color, op: 0.35 };
      case "culture":     return { fill: cul.color, op: f.__cul.g==="han" ? 0.5 : 0.92 };
      case "fracture": {
        if (f.__prov === sub.key) return { fill: dia.color, op: 0.95 };
        return { fill: "#e6dabb", op: 0.22 };
      }
      case "enclave": {
        const inProv = sub.provs.includes(f.__prov);
        const hit = sub.groups.includes(f.__dia.g);
        if (hit && inProv) return { fill: dia.color, op: 0.95 };
        if (hit)           return { fill: dia.color, op: 0.6 };
        if (inProv)        return { fill: dia.color, op: 0.22 };
        return { fill: "#e6dabb", op: 0.12 };
      }
      default: return { fill: "#e6dabb", op: 0 };
    }
  }

  function applyScene(idx, instant) {
    sceneIdx = Math.max(0, Math.min(A.SCENES.length - 1, idx));
    const s = scene();
    const sub = currentSub(s);

    // —— 地图 ——
    const showPref = ["dialect","dialect-dim","culture","fracture","enclave"].includes(s.mode);
    gPref.style("display", showPref ? null : "none");
    gTerr.style("display", s.mode === "terrain" ? null : "none");
    gRange.style("display", s.mode === "terrain" ? null : "none");

    if (showPref) {
      const t = instant ? gPref.selectAll(".pref") :
        gPref.selectAll(".pref").transition().duration(650);
      t.style("fill", f => colorOf(f, s, sub).fill)
       .style("fill-opacity", f => colorOf(f, s, sub).op);
    }

    // 省界粗细
    gProvTop.selectAll(".prov-line")
      .classed("strong", ["dialect","culture","terrain","enclave"].includes(s.mode))
      .classed("focus", function(f){ return s.mode==="fracture" && shortName(f.properties.name)===sub.key; });

    // 大字标
    if (s.mode === "dialect") renderLabels(DIA_LABELS);
    else if (s.mode === "culture") renderLabels(CUL_LABELS);
    else gLabel.selectAll("*").remove();

    // 故事点
    gPoint.selectAll(".pt").style("display", "none");
    const ptShow = {
      enclaves: { hakka:["石壁"], huizhou:["婺源","绩溪"], xiangnan:["全州"], chaoshan:[] },
      fracture: { "江苏":["启东·海门"] }
    };
    const wanted = (ptShow[s.id] && ptShow[s.id][sub && sub.key]) || [];
    gPoint.selectAll(".pt").filter(function(){ 
      const t = d3.select(this).select("text").text();
      return wanted.includes(t);
    }).style("display", null);

    // —— 视角 ——
    if (s.zoom === "national") zoomNational();
    else if (s.zoom === "west") zoomGeoBBox([[73.5,21],[112,50]], 0.06);
    else if (s.zoom === "province") zoomProvince(sub.key);
    else if (s.zoom === "bbox") zoomGeoBBox(sub.bbox, 0.08);

    // —— 面板 / 导航 ——
    renderNav();
    renderPanel(s, sub);
  }

  function currentSub(s) {
    if (!s.sub) return null;
    const k = subKey[s.id] || s.sub[0].key;
    return s.sub.find(x => x.key === k) || s.sub[0];
  }

  // ============================ 导航条 ============================
  function renderNav() {
    const nav = d3.select("#chapter-nav").selectAll(".ch")
      .data(A.SCENES, d => d.id);
    const enter = nav.enter().append("button").attr("class","ch")
      .on("click", (e,d) => applyScene(A.SCENES.indexOf(d)));
    enter.append("span").attr("class","ch-num").text(d => d.num);
    enter.append("span").attr("class","ch-title").text(d => d.title);
    nav.merge(enter).classed("active", (d,i) => i === sceneIdx);
  }
  d3.select("#nav-prev").on("click", () => applyScene(sceneIdx - 1));
  d3.select("#nav-next").on("click", () => applyScene(sceneIdx + 1));
  document.addEventListener("keydown", e => {
    if (e.key === "ArrowRight") applyScene(sceneIdx + 1);
    if (e.key === "ArrowLeft")  applyScene(sceneIdx - 1);
  });

  // ============================ 右侧面板 ============================
  const panel = d3.select("#panel");

  function renderPanel(s, sub) {
    let html = `
      <div class="p-num">${s.num} 章</div>
      <h3 class="p-title">${s.title}</h3>
      <p class="p-lede">${s.lede}</p>`;

    if (s.sub) {
      html += `<div class="p-subs">` + s.sub.map(x =>
        `<button class="p-sub ${sub.key===x.key?'on':''}" data-k="${x.key}">${x.label}</button>`
      ).join("") + `</div>`;
      if (sub.text) html += `<p class="p-subtext">${sub.text}</p>`;
    }

    html += legendHTML(s, sub);
    html += `<div class="p-hint">${s.hint || ""}</div>`;
    html += `<div id="detail" class="p-detail"><div class="p-detail-empty">点击地图上的任一市州查看详情。</div></div>`;
    html += `<a class="p-essay-link" href="#essay-${s.id}">↓ 详读本章</a>`;
    if (degraded) html += `<div class="p-warn">⚠ 市级边界数据未能加载，当前以省级精度降级显示。</div>`;

    panel.html(html);

    panel.selectAll(".p-sub").on("click", function () {
      subKey[s.id] = this.dataset.k;
      applyScene(sceneIdx);
    });

    // 图例 hover → 点亮单一群组
    panel.selectAll(".lg-item").on("mouseenter", function () {
      const g = this.dataset.g;
      gPref.selectAll(".pref").style("opacity", f => {
        const key = (s.mode === "culture") ? f.__cul.g : f.__dia.g;
        return key === g ? 1 : 0.10;
      });
      gLabel.selectAll(".area-label").style("opacity", function(){ return this.dataset.g===g?1:0.12; });
    }).on("mouseleave", () => {
      gPref.selectAll(".pref").style("opacity", null);
      gLabel.selectAll(".area-label").style("opacity", null);
    });
  }

  function legendHTML(s, sub) {
    let groups = null, src = null;
    if (s.mode === "dialect" || s.mode === "dialect-dim") { src = A.DIALECT_GROUPS; groups = countGroups(f => f.__dia.g); }
    else if (s.mode === "culture") { src = A.CULTURE_GROUPS; groups = countGroups(f => f.__cul.g); }
    else if (s.mode === "fracture" && sub) { src = A.DIALECT_GROUPS; groups = countGroups(f => f.__dia.g, f => f.__prov === sub.key); }
    else if (s.mode === "enclave" && sub) { src = A.DIALECT_GROUPS; groups = sub.groups.map(g => [g, 0]); }
    if (!groups || !groups.length) return "";
    return `<div class="p-legend">` + groups.map(([g, n]) => {
      const def = src[g]; if (!def) return "";
      const cnt = n ? `<i>${n}</i>` : "";
      return `<div class="lg-item" data-g="${g}"><span class="lg-dot" style="background:${def.color}"></span>${def.name}${cnt}</div>`;
    }).join("") + `</div>`;
  }

  function countGroups(keyFn, filterFn) {
    const m = new Map();
    prefFeatures.forEach(f => {
      if (filterFn && !filterFn(f)) return;
      const k = keyFn(f);
      m.set(k, (m.get(k) || 0) + 1);
    });
    return [...m.entries()].sort((a, b) => b[1] - a[1]);
  }

  // ============================ 详情卡 ============================
  function detailBox() { return d3.select("#detail"); }

  function showDetail(f) {
    const s = scene();
    const isCul = s.mode === "culture";
    const cls = isCul ? f.__cul : f.__dia;
    const def = isCul ? A.CULTURE_GROUPS[cls.g] : A.DIALECT_GROUPS[cls.g];
    const other = isCul ? A.DIALECT_GROUPS[f.__dia.g] : A.CULTURE_GROUPS[f.__cul.g];
    let html = `
      <div class="d-name">${f.__full}<em>${f.__prov}</em></div>
      <div class="d-chip" style="--c:${def.color}">${def.name}</div>`;
    if (cls.note) html += `<p class="d-note">${cls.note}</p>`;
    if (!isCul && f.__cul.g !== "han")
      html += `<p class="d-extra">文化圈：${A.CULTURE_GROUPS[f.__cul.g].name}</p>`;
    if (isCul && other)
      html += `<p class="d-extra">汉语方言：${other.name}</p>`;
    detailBox().html(html);
  }

  function showTerrainDetail(t) {
    detailBox().html(`
      <div class="d-name">${t.name}<em>${t.type}</em></div>
      <p class="d-note">${t.note}</p>`);
  }
  function showRangeDetail(m) {
    detailBox().html(`
      <div class="d-name">${m.name}<em>山脉</em></div>
      <p class="d-note">${m.note}</p>`);
  }
  function showPointDetail(p) {
    detailBox().html(`
      <div class="d-name">${p.name}<em>县级故事</em></div>
      <p class="d-note">${p.note}</p>`);
  }

  // ============================ 启动 ============================
  const loading = d3.select("#map-loading");
  const badge = d3.select("#detail-badge");

  loadBase().then(() => {
    renderStatic.provOnly = true;
    // 先画省级，让用户立刻看到地图
    gProv.selectAll("path").data(provFeatures).enter().append("path")
      .attr("class", "prov-base").attr("d", path);
    gProvTop.selectAll("path").data(provFeatures).enter().append("path")
      .attr("class", "prov-line").attr("d", path)
      .attr("vector-effect", "non-scaling-stroke");
    loading.classed("hide", true);
    setTimeout(() => loading.style("display", "none"), 450);

    badge.style("display", null);
    return loadPrefs((d, total) => badge.text(`市级细化 ${d}/${total}`));
  }).then(() => {
    badge.text("✓ 市级精度").transition().delay(1400).duration(600).style("opacity", 0).remove();

    // 市级与其余图层（省界线重画到拼图之上）
    gProv.selectAll("*").remove();
    gProvTop.selectAll("*").remove();
    renderStatic();
    applyScene(0, true);
  }).catch(err => {
    console.warn(err);
    loading.html(`<div class="load-err">⚠ 地图数据未能从任何远程源加载。<br>
      <span>请确认网络可访问 geo.datav.aliyun.com 或 jsdelivr，<br>或将 GeoJSON 文件随站点自托管（见 README）。</span></div>`);
  });

})();

