// =====================================================================
// 层叠的中国 v2 — 数据文件
// 核心改变：文化区不再手绘色块，而是把全国 ~330 个地级行政单位
// 逐一归类到方言区 / 文化圈，用真实行政边界着色。
// 分类依据《中国语言地图集》(第2版) 的大区划分，过渡地带从主，
// 争议处在 note 中说明。本图为文化示意，非学术精确边界。
// =====================================================================

// ---------------------------------------------------------------------
// 一、方言大区定义（颜色取传统矿物颜料色系）
// ---------------------------------------------------------------------
const DIALECT_GROUPS = {
  // —— 官话八区：同一暖色家族的八个梯度 ——
  dongbei:   { name: "东北官话",  family: "官话", color: "#d8b078" },
  beijing:   { name: "北京官话",  family: "官话", color: "#c89455" },
  jilu:      { name: "冀鲁官话",  family: "官话", color: "#b8854d" },
  jiaoliao:  { name: "胶辽官话",  family: "官话", color: "#e3c augmenter" }, // placeholder will fix
  zhongyuan: { name: "中原官话",  family: "官话", color: "#a96f3c" },
  lanyin:    { name: "兰银官话",  family: "官话", color: "#e2cb9a" },
  jianghuai: { name: "江淮官话",  family: "官话", color: "#8f6b42" },
  southwest: { name: "西南官话",  family: "官话", color: "#c7a168" },
  // —— 非官话汉语：强对比色 ——
  jin:       { name: "晋语",      family: "晋语", color: "#988a28" },
  wu:        { name: "吴语",      family: "吴语", color: "#46699f" },
  hui:       { name: "徽语",      family: "徽语", color: "#6b4e7c" },
  gan:       { name: "赣语",      family: "赣语", color: "#7d8f4a" },
  xiang:     { name: "湘语",      family: "湘语", color: "#c2661f" },
  minnan:    { name: "闽语·闽南", family: "闽语", color: "#b03a2e" },
  mindong:   { name: "闽语·闽东", family: "闽语", color: "#c75b4e" },
  minbei:    { name: "闽语·闽北", family: "闽语", color: "#8d2e24" },
  minzhong:  { name: "闽语·闽中", family: "闽语", color: "#d98273" },
  puxian:    { name: "闽语·莆仙", family: "闽语", color: "#cf6f5f" },
  qionglei:  { name: "闽语·琼雷", family: "闽语", color: "#e8a98c" },
  yue:       { name: "粤语",      family: "粤语", color: "#803a8e" },
  hakka:     { name: "客家话",    family: "客家", color: "#1f8a70" },
  tuhua:     { name: "湘南土话·平话", family: "土话", color: "#9a6a52" },
  // —— 非汉语为主的区域（方言图中以中性底色呈现）——
  nonhanmain:{ name: "非汉语为主", family: "—",  color: "#ddd5bf" }
};

files.content:
/* =====================================================================
   层叠的中国 v2 — 样式
   设计语汇：古籍舆图。宣纸底、墨线、朱砂印；章节条仿线装书书签。
   ===================================================================== */

:root {
  --paper:      #f3e9cf;
  --paper-deep: #ece1c4;
  --paper-dim:  #e6dabb;
  --ink:        #1f1a14;
  --ink-85:     rgba(31, 26, 20, .85);
  --ink-70:     rgba(31, 26, 20, .70);
  --ink-55:     rgba(31, 26, 20, .55);
  --ink-40:     rgba(31, 26, 20, .40);
  --ink-20:     rgba(31, 26, 20, .20);
  --seal:       #b03a2e;
  --seal-soft:  rgba(176, 58, 46, .08);
  --thread:     #8a7a5a;
  --serif-cn:   "Noto Serif SC", "Songti SC", serif;
  --display-cn: "ZCOOL XiaoWei", "Noto Serif SC", serif;
  --latin:      "EB Garamond", Georgia, serif;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: var(--serif-cn);
  color: var(--ink);
  background-color: var(--paper);
  background-image:
    radial-gradient(1100px 500px at 8% -4%, rgba(138, 122, 90, .10), transparent 60%),
    radial-gradient(900px 460px at 104% 0%, rgba(138, 122, 90, .08), transparent 55%);
  line-height: 1.7;
}

button { font-family: inherit; }

button:focus-visible, a:focus-visible {
  outline: 2px solid var(--seal);
  outline-offset: 2px;
}

/* ============================ 页眉 ============================ */
.site-head { padding: 26px 20px 14px; }
.head-inner {
  max-width: 1280px; margin: 0 auto;
  display: flex; align-items: center; gap: 18px;
}
.seal {
  width: 54px; height: 54px; flex: none;
  background: var(--seal); color: var(--paper);
  font-family: var(--display-cn); font-size: 28px;
  display: flex; align-items: center; justify-content: center;
  border-radius: 7px; transform: rotate(-3deg);
  box-shadow: inset 0 0 0 2px rgba(243, 233, 207, .35), 2px 3px 0 rgba(31, 26, 20, .18);
}
.head-text h1 {
  font-family: var(--display-cn); font-weight: 400;
  font-size: 30px; letter-spacing: 7px; line-height: 1.2;
}
.head-sub { font-size: 13px; color: var(--ink-55); letter-spacing: 2.5px; margin-top: 3px; }
.head-note {
  margin-left: auto; font-size: 12px; color: var(--ink-40);
  border: 1px dashed var(--thread); padding: 5px 11px; letter-spacing: 1.5px;
  white-space: nowrap;
}

/* ============================ 章节条（线装书书签） ============================ */
.chapters {
  max-width: 1280px; margin: 10px auto 0; padding: 0 20px;
  display: flex; align-items: flex-start; gap: 10px;
  position: relative;
}
.chapters::before {            /* 装订线：横向针脚 */
  content: ""; position: absolute; left: 20px; right: 20px; top: 0;
  height: 3px;
  background: repeating-linear-gradient(90deg,
    var(--thread) 0 14px, transparent 14px 22px);
  opacity: .55;
}
#chapter-nav {
  display: flex; gap: 7px; overflow-x: auto; padding: 0 2px 6px;
  scrollbar-width: thin; scrollbar-color: var(--ink-20) transparent;
  flex: 1;
}
.ch {
  flex: none; cursor: pointer;
  display: flex; flex-direction: column; align-items: center; gap: 2px;
  padding: 9px 15px 11px;
  background: linear-gradient(var(--paper), var(--paper-deep));
  border: 1px solid var(--ink-20); border-top: none;
  border-radius: 0 0 7px 7px;
