.nav-arrow {
  flex: none; width: 36px; height: 36px; margin-top: 4px;
  border-radius: 50%; border: 1px solid var(--thread);
  background: var(--paper); color: var(--ink-70);
  font-size: 20px; line-height: 1; cursor: pointer;
  transition: border-color .2s, color .2s;
}
.nav-arrow:hover { border-color: var(--seal); color: var(--seal); }

