#panel {
  position: sticky; top: 14px;
  background: var(--paper);
  border: 1px solid var(--ink-20);
  padding: 20px 20px 22px;
  max-height: calc(100vh - 28px); overflow-y: auto;
  scrollbar-width: thin; scrollbar-color: var(--ink-20) transparent;
}
.p-num {
  display: inline-block; font-family: var(--display-cn); font-size: 13px;
  color: var(--seal); border: 1.5px solid var(--seal);
  padding: 3px 9px; letter-spacing: 3px; border-radius: 3px;
}
.p-title {
  font-family: var(--display-cn); font-weight: 400;
  font-size: 26px; letter-spacing: 3px; margin: 12px 0 10px;
}
.p-lede { font-size: 13.8px; line-height: 1.95; color: var(--ink-85); }

.p-subs { display: flex; flex-wrap: wrap; gap: 7px; margin-top: 14px; }
.p-sub {
  font-size: 12.5px; padding: 5px 12px; cursor: pointer;
  background: var(--paper-deep); color: var(--ink-70);
  border: 1px solid var(--ink-20); border-radius: 99px;
  transition: all .18s;
}
.p-sub:hover { border-color: var(--thread); color: var(--ink); }
.p-sub.on { background: var(--seal); border-color: var(--seal); color: var(--paper); }
.p-subtext {
  margin-top: 12px; font-size: 12.8px; line-height: 1.9; color: var(--ink-70);
  border-left: 3px solid var(--seal); padding-left: 11px;
}

.p-legend {
  display: flex; flex-wrap: wrap; gap: 3px 10px; margin-top: 16px;
  padding-top: 14px; border-top: 1px dashed var(--thread);
}
.lg-item {
  display: inline-flex; align-items: center; gap: 6px;
  font-size: 12.3px; color: var(--ink-85);
  padding: 2.5px 7px; border-radius: 3px; cursor: default;
  transition: background .15s;
}
.lg-item:hover { background: var(--paper-deep); }
.lg-dot {
  width: 11px; height: 11px; flex: none;
  border: 1px solid var(--ink-20);
}
.lg-item i { font-family: var(--latin); font-style: italic; font-size: 11px; color: var(--ink-40); }

.p-hint { margin-top: 14px; font-size: 12px; color: var(--ink-55); line-height: 1.8; }
.p-hint::before { content: "※ "; color: var(--seal); }

.p-detail {
  margin-top: 16px; padding-top: 14px;
  border-top: 1px dashed var(--thread); min-height: 88px;
}
.p-detail-empty { font-size: 12.5px; color: var(--ink-40); line-height: 1.8; }
.d-name {
  font-family: var(--display-cn); font-size: 19px; letter-spacing: 1px;
  display: flex; align-items: baseline; gap: 9px;
}
.d-name em { font-style: normal; font-family: var(--serif-cn); font-size: 12px; color: var(--ink-55); }
.d-chip {
  display: inline-flex; align-items: center; gap: 7px;
  margin-top: 9px; font-size: 13px; font-weight: 600;
}
.d-chip::before {
  content: ""; width: 13px; height: 13px;
  background: var(--c); border: 1px solid var(--ink-20);
}
.d-note  { margin-top: 9px; font-size: 13px; line-height: 1.85; color: var(--ink-85); }
.d-extra { margin-top: 7px; font-size: 12px; color: var(--ink-55); }

.p-essay-link {
  display: inline-block; margin-top: 16px; font-size: 13px;
  color: var(--seal); text-decoration: none;
  border-bottom: 1px dashed var(--seal); padding-bottom: 1px;
}
.p-essay-link:hover { border-bottom-style: solid; }

.p-warn {
  margin-top: 14px; padding: 9px 11px;
  background: var(--seal-soft); border-left: 3px solid var(--seal);
  font-size: 12px; line-height: 1.7; color: var(--ink-70);
}

/* ============================ 提示浮签 ============================ */
#tooltip {
  position: fixed; z-index: 60; pointer-events: none;
  background: #2a2118; color: #f0e8d2;
  padding: 7px 11px; border-radius: 4px;
  font-size: 12.5px; line-height: 1.5; max-width: 230px;
  opacity: 0; transition: opacity .15s;
  box-shadow: 0 3px 14px rgba(31, 26, 20, .35);
}
#tooltip b { display: block; font-family: var(--display-cn); font-weight: 400; font-size: 13.5px; letter-spacing: 1px; }
#tooltip span { opacity: .78; font-size: 11.5px; }

/* ============================ 长文 ============================ */
.essay {
  margin-top: 56px;
  background: var(--paper-deep);
  border-top: 1px solid rgba(31, 26, 20, .35);
  box-shadow: inset 0 1px 0 rgba(243, 233, 207, .7), inset 0 5px 0 -4px var(--ink-20);
}
.essay-inner { max-width: 760px; margin: 0 auto; padding: 58px 24px 72px; }
.essay h2 {
  font-family: var(--display-cn); font-weight: 400;
  font-size: 24px; letter-spacing: 2.5px;
  display: flex; align-items: center; gap: 13px;
  margin: 54px 0 18px; scroll-margin-top: 24px;
}
.essay h2:first-child { margin-top: 0; }
.essay .num {
  flex: none; width: 34px; height: 34px;
  border: 1.5px solid var(--seal); color: var(--seal);
  font-size: 15px; display: flex; align-items: center; justify-content: center;
  border-radius: 4px; transform: rotate(-2deg);
}
.essay h3 { font-size: 16.5px; font-weight: 600; margin: 28px 0 9px; letter-spacing: 1px; }
.essay p { font-size: 15px; line-height: 2.05; color: var(--ink-85); margin: 12px 0; }
.essay em { font-style: normal; color: var(--seal); }
.essay strong { font-weight: 600; }
.feature-list { list-style: none; margin: 14px 0; }
.feature-list li {
  font-size: 14.5px; line-height: 1.95; color: var(--ink-85);
  margin: 11px 0; padding-left: 22px; position: relative;
}
.feature-list li::before {
  content: "—"; position: absolute; left: 0; color: var(--seal);
}
.pullquote {
  font-family: var(--display-cn); font-size: 17.5px; line-height: 1.95;
  letter-spacing: 1.5px; color: var(--ink-85);
  background: var(--seal-soft); border-left: 3px solid var(--seal);
  padding: 16px 20px; margin: 28px 0;
}
.essay-caveat {
  margin-top: 48px; padding-top: 18px;
  border-top: 1px dashed var(--thread);
  font-size: 12px !important; color: var(--ink-55) !important; line-height: 1.9 !important;
}

/* ============================ 页脚 ============================ */
.site-foot { text-align: center; padding: 30px 20px 38px; font-size: 12.5px; color: var(--ink-55); }
.foot-dim { margin-top: 6px; font-size: 11px; color: var(--ink-40); }

/* ============================ 响应式 ============================ */
@media (max-width: 1080px) {
  .stage { grid-template-columns: 1fr; }
  #panel { position: static; max-height: none; }
}
@media (max-width: 640px) {
  .site-head { padding: 18px 14px 10px; }
  .head-inner { gap: 12px; }
  .seal { width: 44px; height: 44px; font-size: 22px; }
  .head-text h1 { font-size: 23px; letter-spacing: 4px; }
  .head-sub { font-size: 11.5px; letter-spacing: 1.5px; }
  .head-note { display: none; }
  .chapters { padding: 0 12px; }
  .chapters::before { left: 12px; right: 12px; }
  .ch { padding: 7px 11px 9px; }
  .ch-title { font-size: 10.5px; }
  .stage { padding: 0 12px; margin-top: 12px; }
  #panel { padding: 16px 15px 18px; }
  .p-title { font-size: 22px; }
  .essay-inner { padding: 42px 18px 56px; }
  .essay h2 { font-size: 20.5px; }
}

/* ============================ 动效偏好 ============================ */
@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *, *::before, *::after {
    animation-duration: .01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: .01ms !important;
  }
}

