.head-sub { font-size: 13px; color: var(--ink-55); letter-spacing: 2.5px; margin-top: 3px; }
.head-note {
  margin-left: auto; font-size: 12px; color: var(--ink-40);
  border: 1px dashed var(--thread); padding: 5px 11px; letter-spacing: 1.5px;
  white-space: nowrap;
}

