// 层叠的中国 — 应用逻辑
// 使用 D3 v7 渲染 SVG 地图，多 CDN 备援加载行政省 GeoJSON
// =====================================================================

(function () {
  "use strict";

  const SVG_NS = "http://www.w3.org/2000/svg";
  const W = 1000;
  const H = 760;

  // China-centered Mercator
  const projection = d3.geoMercator()
    .center([105, 36])
    .scale(720)
    .translate([W / 2, H / 2]);

  const pathGen = d3.geoPath().projection(projection);

  // ---- 多 CDN 备援源 ----
  const GEOJSON_SOURCES = [
    "https://geo.datav.aliyun.com/areas_v3/bound/100000_full.json",
    "https://cdn.jsdelivr.net/gh/longwosion/geojson-map-china@master/china.json",
    "https://raw.githubusercontent.com/longwosion/geojson-map-china/master/china.json",
    "./china-provinces.json"   // 用户自托管的本地备份
  ];

  async function loadProvinces() {
    for (const url of GEOJSON_SOURCES) {
      try {
        const res = await fetch(url, { mode: "cors" });
        if (!res.ok) continue;
        const data = await res.json();
        // 各源字段略不同，统一为 FeatureCollection
        if (data.type === "FeatureCollection") return data;
        if (data.features) return { type: "FeatureCollection", features: data.features };
      } catch (e) {
        // 试下一个
      }
    }
    throw new Error("无法加载省级 GeoJSON：所有 CDN 均失败。请将 china.json 与 index.html 放在一起。");
  }

  // ========================== 主初始化 ==========================
  const svg = d3.select("#china-map")
    .attr("viewBox", `0 0 ${W} ${H}`)
    .attr("preserveAspectRatio", "xMidYMid meet");

  // 渲染层级（自下而上）
  const gOcean       = svg.append("g").attr("class", "g-ocean");
  const gProvinces   = svg.append("g").attr("class", "g-provinces");
  const gTerrain     = svg.append("g").attr("class", "g-terrain");
  const gDialects    = svg.append("g").attr("class", "g-dialects");
  const gNonHan      = svg.append("g").attr("class", "g-nonHan");
  const gEnclaves    = svg.append("g").attr("class", "g-enclaves");
  const gFaultLines  = svg.append("g").attr("class", "g-faultLines");
  const gLabels      = svg.append("g").attr("class", "g-labels");
  const gAnnotations = svg.append("g").attr("class", "g-annotations");

  // 默认显示哪些层
  const state = {
    provinces: true,
    dialects: true,
    terrain: false,
    nonHan: false,
    enclaves: true,
    faultLines: false,
    annotations: true
  };

  // ========================== 工具函数 ==========================
  function polygonToFeature(coords) {
    // coords 是 [[lng, lat], ...] 形式
    return {
      type: "Feature",
      geometry: { type: "Polygon", coordinates: [coords] }
    };
  }

  function getCenter(coords) {
    let sx = 0, sy = 0;
    coords.forEach(([x, y]) => { sx += x; sy += y; });
    return [sx / coords.length, sy / coords.length];
  }

  // ========================== 信息面板 ==========================
  const infoPanel = document.getElementById("info-panel");

  function showInfo(html) {
    infoPanel.innerHTML = html;
  }

  function defaultInfo() {
    showInfo(`
      <h3>探索说明</h3>
      <span class="info-tag">How to read</span>
      <p>这张地图把<strong>行政省</strong>、<strong>汉语方言区</strong>、<strong>自然地形</strong>、<strong>非汉文化区</strong>与<strong>跨省文化飞地</strong>叠在同一张底图上。</p>
      <p>请使用左侧的图层开关切换显示。鼠标悬停或点击任一色块、地名标记，此处会显示详细注释。</p>
      <hr/>
      <p style="font-size:.85rem;color:var(--ink-light);font-style:italic;">「省界与文化几乎处处错位 —— 这不是疏忽，是设计。元代以来中央集权的核心技术之一。」</p>
    `);
  }
  defaultInfo();

  // ========================== 渲染：行政省 ==========================
  function renderProvinces(featureCollection) {
    gProvinces.selectAll("path").remove();
    if (!state.provinces) return;

    gProvinces.selectAll("path")
      .data(featureCollection.features)
      .enter()
      .append("path")
      .attr("class", "province-path")
      .attr("d", pathGen)
      .attr("data-name", d => d.properties.name || "")
      .on("mouseenter", function (e, d) {
        d3.select(this).style("fill", "#dcc999");
      })
      .on("mouseleave", function () {
        d3.select(this).style("fill", null);
      })
      .on("click", function (e, d) {
        const name = d.properties.name || "未知";
        const fault = DATA.faultLines.find(f => f.province === name);
        let html = `
          <h3>${name}</h3>
          <span class="info-tag">Administrative Province</span>
          <p>当前点选的是行政省。多数省级单位的边界设计遵循「<em>犬牙交错</em>」原则，刻意打破自然地形与文化连续性。</p>
        `;
        if (fault) {
          html += `<hr/><p><strong>省内文化断层：</strong>${fault.note}</p>`;
        }
        showInfo(html);
      });
  }

  // ========================== 渲染：方言层 ==========================
  function renderDialects() {
    gDialects.selectAll("*").remove();
    gLabels.selectAll(".dialect-label").remove();
    if (!state.dialects) return;

    DATA.dialects.forEach(d => {
      const polys = d.polygons || [d.polygon];
      polys.forEach((poly, idx) => {
        const feature = polygonToFeature(poly);
        gDialects.append("path")
          .attr("d", pathGen(feature))
          .attr("class", "layer-polygon dialect")
          .attr("fill", d.color)
          .attr("stroke", d.color)
          .on("mouseenter", function () {
            d3.select(this).attr("fill-opacity", 0.7);
          })
          .on("mouseleave", function () {
            d3.select(this).attr("fill-opacity", null);
          })
          .on("click", () => {
            showInfo(`
              <h3>${d.name}</h3>
              <span class="info-tag">${d.family} · Han Dialect</span>
              <p>${d.note}</p>
              <hr/>
              <p style="font-size:.85rem;color:var(--ink-light);">汉语方言区与行政省几乎处处错位 —— 中央集权对地方文化-地理-政治三位一体单元的防御机制。</p>
            `);
          });

        if (idx === 0) {
          const c = getCenter(poly);
          const [x, y] = projection(c);
          if (x && y && !isNaN(x) && !isNaN(y)) {
            gLabels.append("text")
              .attr("class", "layer-label dialect-label")
              .attr("x", x).attr("y", y)
              .text(d.name);
          }
        }
      });
    });
  }

  // ========================== 渲染：地形层 ==========================
  function renderTerrain() {
    gTerrain.selectAll("*").remove();
    gLabels.selectAll(".terrain-label").remove();
    if (!state.terrain) return;

    DATA.terrain.forEach(t => {
      const feature = polygonToFeature(t.polygon);
      gTerrain.append("path")
        .attr("d", pathGen(feature))
        .attr("class", "layer-polygon terrain")
        .attr("fill", t.color)
        .attr("stroke", t.color)
        .on("click", () => {
          showInfo(`
            <h3>${t.name}</h3>
            <span class="info-tag">${t.type} · Natural region</span>
            <p>${t.note}</p>
            <hr/>
            <p style="font-size:.85rem;color:var(--ink-light);font-style:italic;">真正让中央忌惮的并非文化共同体，而是「地形完整 + 文化同质 + 资源自足」的单元 —— 四川盆地、关中盆地、岭南、大藏区。</p>
          `);
        });

      const c = getCenter(t.polygon);
      const [x, y] = projection(c);
      if (!isNaN(x) && !isNaN(y)) {
        gLabels.append("text")
          .attr("class", "layer-label terrain-label")
          .attr("x", x).attr("y", y)
          .text(t.name)
          .style("font-style", "italic");
      }
    });
  }

  // ========================== 渲染：非汉文化区 ==========================
  function renderNonHan() {
    gNonHan.selectAll("*").remove();
    gLabels.selectAll(".nonhan-label").remove();
    if (!state.nonHan) return;

    DATA.nonHan.forEach(n => {
      const feature = polygonToFeature(n.polygon);
      gNonHan.append("path")
        .attr("d", pathGen(feature))
        .attr("class", "layer-polygon nonHan")
        .attr("fill", n.color)
        .attr("stroke", n.color)
        .on("click", () => {
          let subHTML = "";
          if (n.sub) {
            subHTML = "<ul class='sub-list'>" + n.sub.map(s => `<li>${s}</li>`).join("") + "</ul>";
          }
          showInfo(`
            <h3>${n.name}</h3>
            <span class="info-tag">${n.ethnic} · Non-Han region</span>
            <p>${n.note}</p>
            ${subHTML}
          `);
        });

      const c = getCenter(n.polygon);
      const [x, y] = projection(c);
      if (!isNaN(x) && !isNaN(y)) {
        gLabels.append("text")
          .attr("class", "layer-label nonhan-label")
          .attr("x", x).attr("y", y)
          .text(n.name.split(" ")[0]);
      }
    });
  }

  // ========================== 渲染：跨省飞地 ==========================
  function renderEnclaves() {
    gEnclaves.selectAll("*").remove();
    gLabels.selectAll(".enclave-label").remove();
    if (!state.enclaves) return;

    DATA.enclaves.forEach(e => {
      const feature = polygonToFeature(e.polygon);
      gEnclaves.append("path")
        .attr("d", pathGen(feature))
        .attr("class", "layer-polygon enclave")
        .attr("fill", e.color)
        .attr("stroke", e.color)
        .on("click", () => {
          showInfo(`
            <h3>${e.name}</h3>
            <span class="info-tag">Cross-province enclave</span>
            <p>${e.note}</p>
            <hr/>
            <p style="font-size:.85rem;color:var(--ink-light);">这类「三角洲式」文化飞地，其文化重心与各自省会的疏离感远大于彼此。</p>
          `);
        });

      const c = getCenter(e.polygon);
      const [x, y] = projection(c);
      if (!isNaN(x) && !isNaN(y)) {
        gLabels.append("text")
          .attr("class", "layer-label enclave-label")
          .attr("x", x).attr("y", y - 4)
          .text(e.name)
          .style("fill", e.color)
          .style("font-weight", "700");
      }
    });
  }

  // ========================== 渲染：省内断层线 ==========================
  function renderFaultLines() {
    gFaultLines.selectAll("*").remove();
    if (!state.faultLines) return;

    DATA.faultLines.forEach(f => {
      f.lines.forEach(line => {
        const lineFeature = {
          type: "Feature",
          geometry: { type: "LineString", coordinates: line.path }
        };
        gFaultLines.append("path")
          .attr("d", pathGen(lineFeature))
          .attr("class", "fault-line")
          .on("mouseenter", function () {
            d3.select(this).style("stroke-width", 2.5);
          })
          .on("mouseleave", function () {
            d3.select(this).style("stroke-width", null);
          })
          .on("click", () => {
            showInfo(`
              <h3>${f.province}：${line.name}</h3>
              <span class="info-tag">Intra-province fault line</span>
              <p>${f.note}</p>
            `);
          });
      });
    });
  }

  // ========================== 渲染：地名注脚 ==========================
  function renderAnnotations() {
    gAnnotations.selectAll("*").remove();
    if (!state.annotations) return;

    DATA.annotations.forEach(a => {
      const [x, y] = projection([a.lng, a.lat]);
      if (isNaN(x) || isNaN(y)) return;

      const g = gAnnotations.append("g")
        .attr("class", "annotation-marker")
        .attr("transform", `translate(${x}, ${y})`)
        .on("click", () => {
          showInfo(`
            <h3>${a.name}</h3>
            <span class="info-tag">${a.type}</span>
            <p>${a.note}</p>
          `);
        });

      g.append("circle").attr("r", 3.6);
      g.append("text").attr("dx", 6).attr("dy", 3).text(a.name);
    });
  }

  // ========================== 总渲染 ==========================
  let provinceData = null;

  function renderAll() {
    if (provinceData) renderProvinces(provinceData);
    renderTerrain();
    renderDialects();
    renderNonHan();
    renderEnclaves();
    renderFaultLines();
    renderAnnotations();
  }

  // ========================== 图层切换 ==========================
  document.querySelectorAll(".layer-toggle input").forEach(input => {
    input.addEventListener("change", () => {
      const key = input.dataset.layer;
      state[key] = input.checked;
      renderAll();
    });
  });

  // 「全部关闭/打开」快捷
  const allOn  = document.getElementById("layer-all-on");
  const allOff = document.getElementById("layer-all-off");
  if (allOn) allOn.addEventListener("click", (e) => {
    e.preventDefault();
    document.querySelectorAll(".layer-toggle input").forEach(i => {
      i.checked = true; state[i.dataset.layer] = true;
    });
    renderAll();
  });
  if (allOff) allOff.addEventListener("click", (e) => {
    e.preventDefault();
    document.querySelectorAll(".layer-toggle input").forEach(i => {
      if (i.dataset.layer !== "provinces") { i.checked = false; state[i.dataset.layer] = false; }
    });
    renderAll();
  });

  // ========================== 启动 ==========================
  const loadingEl = document.getElementById("map-loading");
  loadProvinces()
    .then(data => {
      provinceData = data;
      renderAll();
      loadingEl.classList.add("hide");
      setTimeout(() => loadingEl.style.display = "none", 500);
    })
    .catch(err => {
      console.warn(err);
      // 即便省级 GeoJSON 加载失败，文化层仍可呈现
      provinceData = { type: "FeatureCollection", features: [] };
      renderAll();
      loadingEl.innerHTML = `
        <div style="max-width:380px; font-size:.95rem; font-family:'Noto Serif SC';">
          ⚠ 行政省底图未能从远程 CDN 加载。<br/>
          <span style="font-size:.8rem; color:var(--ink-light);">
            文化层、地形层、断层线仍可正常显示。<br/>
            如需省级边界，请将 china.json 与本页放在同一目录。
          </span>
        </div>`;
      setTimeout(() => loadingEl.classList.add("hide"), 4000);
    });

})();

