versions.new:
function polygonToFeature(coords) {
  // coords 是 [[lng, lat], ...] 形式
  // D3 d3.geoPath 假定 GeoJSON 多边形外环为逆时针（CCW，RFC 7946）。
  // 我们手工绘制时往往为顺时针，因此统一翻转，保证 D3 不会把它视为「整个地球减去一个洞」。
  const ring = ensureCCW(coords);
  return {
    type: "Feature",
    geometry: { type: "Polygon", coordinates: [ring] }
  };
}

// 用叉积之和（鞋带公式）判断方向；若顺时针则反转
function ensureCCW(ring) {
  let sum = 0;
  for (let i = 0; i < ring.length - 1; i++) {
    const [x1, y1] = ring[i];
    const [x2, y2] = ring[i + 1];
    sum += (x2 - x1) * (y2 + y1);
  }
  // sum > 0 → 顺时针（屏幕坐标），需要反转
  return sum > 0 ? ring.slice().reverse() : ring;
}

