versions.new:
function polygonToFeature(coords) {
  // D3 期望 GeoJSON 外环以「球面 CCW」绕行，等价于：
  //   投影后 d3.geoArea < 2π（即面积 < 半球）才会被识别为「小区域」。
  // 我们手绘的多边形若被解释为顺时针，d3.geoArea 会接近 4π。
  // 用 d3.geoArea 检测并必要时反转，比 2D 鞋带公式更鲁棒。
  let feat = {
    type: "Feature",
    geometry: { type: "Polygon", coordinates: [coords] }
  };
  if (d3.geoArea(feat) > 2 * Math.PI) {
    feat.geometry.coordinates[0] = coords.slice().reverse();
  }
  return feat;
}

files.content:
/* =====================================================================
   层叠的中国 — 样式表
   美学：古籍地图 / 学院派 / 文人案头
   配色：宣纸米色 + 朱砂印章红 + 矿物颜料
   ===================================================================== */

@import url("https://fonts.googleapis.com/css2?family=ZCOOL+XiaoWei&family=Noto+Serif+SC:wght@300;400;500;600;700&family=Ma+Shan+Zheng&family=EB+Garamond:ital,wght@0,400;0,600;1,400&display=swap");

:root {
  /* 宣纸基底 */
  --paper:       #f3e9cf;
  --paper-warm:  #ede0bb;
  --paper-light: #faf3df;
  --land-base:   #e8dab8;
  --land-edge:   #c4b48a;
  --ocean:       #d9d2b4;

  /* 墨 */
  --ink:         #1f1a14;
  --ink-soft:    #4a3f30;
  --ink-light:   #7a6b56;
  --hairline:    #b8a786;

  /* 印章朱砂 */
  --seal:        #b03a2e;
  --seal-dark:   #842318;
  --seal-glow:   rgba(176,58,46,.15);

  /* 矿物颜料 */
  --pigment-gold:   #b8860b;
  --pigment-jade:   #4a7c59;
  --pigment-azure:  #2c4f7c;
  --pigment-ochre:  #a05a35;
  --pigment-violet: #6b4e7c;

  --shadow-soft:  0 1px 2px rgba(31,26,20,.08), 0 4px 16px rgba(31,26,20,.06);
  --shadow-deep:  0 2px 4px rgba(31,26,20,.12), 0 12px 32px rgba(31,26,20,.10);
}

* { box-sizing: border-box; margin: 0; padding: 0; }

html, body {
  background: var(--paper);
  color: var(--ink);
  font-family: "Noto Serif SC", "EB Garamond", "Songti SC", Georgia, serif;
  font-weight: 400;
  line-height: 1.65;
  overflow-x: hidden;
}

/* 宣纸纹理（程序化噪点） */
body::before {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 1;
  opacity: .55;
  background-image:
    radial-gradient(circle at 13% 27%, rgba(120,90,40,.07) 0, transparent 60%),
    radial-gradient(circle at 80% 70%, rgba(140,100,30,.06) 0, transparent 55%),
    radial-gradient(circle at 50% 50%, rgba(80,50,20,.03) 0, transparent 80%),
    url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='200' height='200'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='0.85' numOctaves='3' stitchTiles='stitch'/><feColorMatrix values='0 0 0 0 0.2  0 0 0 0 0.15  0 0 0 0 0.08  0 0 0 0.08 0'/></filter><rect width='100%25' height='100%25' filter='url(%23n)'/></svg>");
  mix-blend-mode: multiply;
}

/* ========================== 页眉 ========================== */
header.atlas-head {
  position: relative;
  padding: 4rem 3rem 2rem;
  border-bottom: 1px solid var(--hairline);
  background: linear-gradient(to bottom, var(--paper-light) 0%, var(--paper) 100%);
  z-index: 2;
}

.atlas-head .lead {
  font-family: "EB Garamond", serif;
  font-style: italic;
  color: var(--ink-light);
  letter-spacing: .08em;
  font-size: .82rem;
  margin-bottom: .8rem;
}

.atlas-head h1 {
  font-family: "ZCOOL XiaoWei", "Noto Serif SC", serif;
  font-size: clamp(2.2rem, 5vw, 4.2rem);
  font-weight: 400;
  letter-spacing: .12em;
  color: var(--ink);
  line-height: 1.1;
  margin-bottom: .6rem;
}

.atlas-head h1 .ornament {
  color: var(--seal);
  font-family: "Ma Shan Zheng", cursive;
  margin: 0 .35em;
  font-size: .9em;
}

.atlas-head .subtitle {
  font-family: "Noto Serif SC", serif;
  font-weight: 300;
  color: var(--ink-soft);
  font-size: 1.05rem;
  max-width: 60ch;
  margin-top: .8rem;
}

/* 印章装饰 */
.seal {
  position: absolute;
  top: 3.2rem;
  right: 3rem;
  width: 72px;
  height: 72px;
  border: 2.5px solid var(--seal);
  background: var(--seal);
  color: var(--paper-light);
  font-family: "Ma Shan Zheng", "ZCOOL XiaoWei", serif;
  font-size: 1.05rem;
  font-weight: 700;
  letter-spacing: .15em;
  display: grid;
  place-items: center;
  text-align: center;
  line-height: 1.05;
  border-radius: 4px;
  transform: rotate(-3deg);
  box-shadow: 0 2px 6px rgba(132,35,24,.25);
  padding: 8px;
  writing-mode: vertical-rl;
}

/* ========================== 主区域 ========================== */
main.atlas-main {
  position: relative;
  z-index: 2;
  display: grid;
  grid-template-columns: 280px 1fr 340px;
  gap: 0;
  min-height: calc(100vh - 200px);
  border-bottom: 1px solid var(--hairline);
}

/* ====== 左侧：图层控制 ====== */
.layer-panel {
  padding: 2rem 1.6rem;
  border-right: 1px solid var(--hairline);
  background: var(--paper-light);
}

.layer-panel h2 {
  font-family: "ZCOOL XiaoWei", serif;
  font-size: 1rem;
  letter-spacing: .35em;
  color: var(--ink-soft);
  border-bottom: 1px solid var(--hairline);
  padding-bottom: .7rem;
  margin-bottom: 1.3rem;
}

.layer-panel .group {
  margin-bottom: 1.5rem;
}

.layer-panel .group-title {
  font-family: "EB Garamond", serif;
  font-style: italic;
  font-size: .78rem;
  text-transform: uppercase;
  letter-spacing: .14em;
  color: var(--ink-light);
  margin-bottom: .5rem;
}

.layer-toggle {
  display: flex;
  align-items: center;
  gap: .65rem;
  padding: .55rem .5rem;
  border-radius: 3px;
  cursor: pointer;
  transition: background .2s ease;
  font-size: .95rem;
  color: var(--ink);
  user-select: none;
}

.layer-toggle:hover {
  background: var(--seal-glow);
}

.layer-toggle input { display: none; }

.layer-toggle .checkbox {
  width: 14px;
  height: 14px;
  border: 1.5px solid var(--ink-soft);
  border-radius: 1.5px;
  flex-shrink: 0;
  position: relative;
  transition: all .15s ease;
}

.layer-toggle input:checked + .checkbox {
  background: var(--ink);
  border-color: var(--ink);
}

.layer-toggle input:checked + .checkbox::after {
  content: "";
  position: absolute;
  inset: 2px;
  background: var(--seal);
  border-radius: 1px;
}

.layer-toggle .swatch {
  width: 14px;
  height: 14px;
  border-radius: 50%;
  flex-shrink: 0;
  opacity: .8;
}

.layer-toggle .name { flex: 1; }

.legend-mini {
  margin-top: .7rem;
  padding-left: 1.7rem;
  font-size: .82rem;
  color: var(--ink-soft);
}
.legend-mini .item {
  display: flex; align-items: center; gap: .5rem;
  padding: .2rem 0;
}
.legend-mini .dot {
  width: 10px; height: 10px; border-radius: 50%; opacity: .8;
}

/* ====== 中部：地图 ====== */
.map-stage {
  position: relative;
  background:
    radial-gradient(ellipse at center, var(--paper-light) 0%, var(--paper) 70%, var(--paper-warm) 100%);
  overflow: hidden;
  border-left: 1px solid var(--hairline);
  border-right: 1px solid var(--hairline);
}

#china-map {
  width: 100%;
  height: 100%;
  min-height: 700px;
  display: block;
}

.map-frame-corner {
  position: absolute;
  width: 36px;
  height: 36px;
  border: 1.5px solid var(--ink-soft);
  pointer-events: none;
  opacity: .5;
}
.map-frame-corner.tl { top: 16px; left: 16px; border-right: none; border-bottom: none; }
.map-frame-corner.tr { top: 16px; right: 16px; border-left: none; border-bottom: none; }
.map-frame-corner.bl { bottom: 16px; left: 16px; border-right: none; border-top: none; }
.map-frame-corner.br { bottom: 16px; right: 16px; border-left: none; border-top: none; }

.map-loading {
  position: absolute;
  inset: 0;
  display: grid; place-items: center;
  color: var(--ink-soft);
  font-family: "ZCOOL XiaoWei", serif;
  font-size: 1.2rem;
  letter-spacing: .3em;
  text-align: center;
  background: var(--paper-light);
  z-index: 5;
  transition: opacity .4s ease;
}
.map-loading.hide { opacity: 0; pointer-events: none; }
.map-loading .pulse {
  width: 32px; height: 32px;
  border: 2px solid var(--hairline);
  border-top-color: var(--seal);
  border-radius: 50%;
  margin: 0 auto 1.2rem;
  animation: spin 1.1s linear infinite;
}
@keyframes spin { to { transform: rotate(360deg); } }

.compass {
  position: absolute;
  bottom: 28px;
  right: 28px;
  width: 64px;
  height: 64px;
  pointer-events: none;
  opacity: .65;
}

.scale-bar {
  position: absolute;
  bottom: 28px;
  left: 28px;
  display: flex;
  align-items: center;
  gap: .6rem;
  font-family: "EB Garamond", serif;
  font-size: .75rem;
  color: var(--ink-soft);
  letter-spacing: .1em;
}
.scale-bar .bar {
  height: 4px;
  width: 80px;
  background: linear-gradient(to right, var(--ink) 50%, transparent 50%);
  border: 1px solid var(--ink);
  background-size: 16px 4px;
}

/* ====== 右侧：信息面板 ====== */
.info-panel {
  padding: 2rem 1.8rem;
  background: var(--paper-light);
  border-left: 1px solid var(--hairline);
  overflow-y: auto;
  max-height: calc(100vh - 200px);
}

.info-panel .placeholder {
  color: var(--ink-light);
  font-style: italic;
  font-size: .95rem;
  border-left: 2px solid var(--seal);
  padding-left: 1rem;
  margin-top: 1rem;
}

.info-panel h3 {
  font-family: "ZCOOL XiaoWei", serif;
  font-size: 1.5rem;
  letter-spacing: .08em;
  color: var(--ink);
  margin-bottom: .4rem;
}

.info-panel .info-tag {
  display: inline-block;
  font-family: "EB Garamond", serif;
  font-style: italic;
  font-size: .75rem;
  letter-spacing: .15em;
  color: var(--seal);
  text-transform: uppercase;
  margin-bottom: 1rem;
  border-bottom: 1px solid var(--seal);
  padding-bottom: 2px;
}

.info-panel p {
  font-size: .95rem;
  color: var(--ink-soft);
  margin-bottom: .8rem;
}

.info-panel .sub-list {
  margin-top: .6rem;
  padding-left: 1rem;
  border-left: 2px dashed var(--hairline);
}

.info-panel .sub-list li {
  list-style: none;
  position: relative;
  padding: .3rem 0 .3rem .9rem;
  font-size: .88rem;
  color: var(--ink-soft);
}

.info-panel .sub-list li::before {
  content: "";
  position: absolute;
  left: 0; top: .9rem;
  width: 6px; height: 1px;
  background: var(--seal);
}

.info-panel hr {
  border: none;
  border-top: 1px dashed var(--hairline);
  margin: 1.5rem 0;
}

/* ========================== 地图 SVG 样式 ========================== */
.province-path {
  fill: var(--land-base);
  stroke: var(--ink-soft);
  stroke-width: .55;
  stroke-linejoin: round;
  transition: fill .25s ease;
  cursor: pointer;
}

.province-path:hover {
  fill: #e0cf9c;
}

.province-path.dimmed {
  fill: var(--land-base);
}

.layer-polygon {
  stroke-width: .8;
  stroke-linejoin: round;
  pointer-events: all;
  cursor: pointer;
  transition: opacity .3s ease, fill-opacity .3s ease;
}

.layer-polygon.dialect { fill-opacity: .42; }
.layer-polygon.terrain { fill-opacity: .35; }
.layer-polygon.nonHan  { fill-opacity: .42; stroke-dasharray: 0; }
.layer-polygon.enclave { fill-opacity: .55; stroke-width: 1.4; stroke-dasharray: 4 2; }

.layer-polygon:hover {
  fill-opacity: .68 !important;
}

.fault-line {
  fill: none;
  stroke: var(--seal);
  stroke-width: 1.2;
  stroke-dasharray: 5 3;
  opacity: .75;
}

.annotation-marker circle {
  fill: var(--seal);
  stroke: var(--paper-light);
  stroke-width: 1.5;
  transition: r .2s ease;
  cursor: pointer;
}
.annotation-marker:hover circle { fill: var(--seal-dark); }

.annotation-marker text {
  font-family: "ZCOOL XiaoWei", serif;
  font-size: 11px;
  fill: var(--ink);
  letter-spacing: .05em;
  text-anchor: start;
  pointer-events: none;
  text-shadow:
    -1px -1px 0 var(--paper-light),
    1px -1px 0 var(--paper-light),
    -1px 1px 0 var(--paper-light),
    1px 1px 0 var(--paper-light),
    0 0 3px var(--paper-light);
}

.layer-label {
  font-family: "ZCOOL XiaoWei", serif;
  font-size: 13px;
  fill: var(--ink);
  pointer-events: none;
  letter-spacing: .15em;
  text-anchor: middle;
  font-weight: 600;
  paint-order: stroke;
  stroke: var(--paper-light);
  stroke-width: 3px;
  stroke-linejoin: round;
}

/* ========================== 叙事 ========================== */
section.essay {
  position: relative;
  z-index: 2;
  padding: 5rem 2rem;
  background: var(--paper-light);
  border-top: 2px solid var(--ink);
}

.essay-inner {
  max-width: 780px;
  margin: 0 auto;
}

.essay h2 {
  font-family: "ZCOOL XiaoWei", serif;
  font-size: 2.4rem;
  font-weight: 400;
  letter-spacing: .12em;
  color: var(--ink);
  margin: 3.5rem 0 1rem;
  position: relative;
  padding-bottom: .6rem;
}

.essay h2:first-child { margin-top: 0; }

.essay h2::after {
  content: "";
  position: absolute;
  bottom: 0; left: 0;
  width: 60px;
  height: 3px;
  background: var(--seal);
}

.essay h2 .num {
  font-family: "EB Garamond", serif;
  font-style: italic;
  font-size: .55em;
  color: var(--seal);
  letter-spacing: .08em;
  margin-right: .8rem;
  vertical-align: top;
  display: inline-block;
  transform: translateY(.4em);
}

.essay h3 {
  font-family: "ZCOOL XiaoWei", serif;
  font-size: 1.25rem;
  letter-spacing: .1em;
  margin: 2rem 0 .8rem;
  color: var(--ink-soft);
}

.essay p {
  font-family: "Noto Serif SC", serif;
  font-size: 1.02rem;
  color: var(--ink);
  margin-bottom: 1.1rem;
  line-height: 1.85;
  text-align: justify;
}

.essay strong {
  font-weight: 700;
  color: var(--seal-dark);
}

.essay em {
  font-style: italic;
  color: var(--ink-soft);
}

.essay .pullquote {
  border-left: 3px solid var(--seal);
  padding: 1rem 1.4rem;
  margin: 1.6rem 0;
  font-family: "ZCOOL XiaoWei", serif;
  font-size: 1.15rem;
  letter-spacing: .04em;
  color: var(--ink);
  background: var(--paper);
}

.essay ul.feature-list {
  list-style: none;
  margin: 1rem 0 1.5rem;
  padding: 0;
}

.essay ul.feature-list li {
  position: relative;
  padding: .55rem 0 .55rem 1.6rem;
  font-size: .98rem;
  color: var(--ink);
  border-bottom: 1px dotted var(--hairline);
}

.essay ul.feature-list li::before {
  content: "◆";
  position: absolute;
  left: 0; top: .65rem;
  color: var(--seal);
  font-size: .7rem;
}

footer.atlas-foot {
  position: relative;
  z-index: 2;
  padding: 2.5rem 2rem;
  text-align: center;
  background: var(--paper-warm);
  border-top: 1px solid var(--hairline);
  color: var(--ink-light);
  font-family: "EB Garamond", serif;
  font-size: .85rem;
  font-style: italic;
  letter-spacing: .1em;
  line-height: 1.8;
}

footer.atlas-foot .cn {
  font-family: "Noto Serif SC", serif;
  font-style: normal;
  letter-spacing: .15em;
  display: block;
  margin-bottom: .4rem;
  color: var(--ink-soft);
}

/* 响应式 */
@media (max-width: 1100px) {
  main.atlas-main {
    grid-template-columns: 1fr;
  }
  .layer-panel, .info-panel {
    border-left: none; border-right: none;
    border-bottom: 1px solid var(--hairline);
    max-height: none;
  }
  .map-stage {
    border: none;
    border-bottom: 1px solid var(--hairline);
  }
  #china-map { min-height: 500px; }
  .seal { width: 56px; height: 56px; top: 2rem; right: 2rem; font-size: .85rem; }
}

@media (max-width: 700px) {
  header.atlas-head { padding: 2.5rem 1.4rem 1.5rem; }
  .seal { display: none; }
  .layer-panel, .info-panel { padding: 1.4rem 1.2rem; }
  section.essay { padding: 3rem 1.4rem; }
  .essay h2 { font-size: 1.8rem; }
}

