  font-family: "EB Garamond", serif;
  font-style: italic;
  color: var(--ink-light);
  letter-spacing: .08em;
  font-size: .82rem;
  margin-bottom: .8rem;
}

.atlas-head h1 {
  font-family: "ZCOOL XiaoWei", "Noto Serif SC", serif;
  font-size: clamp(2.2rem, 5vw, 4.2rem);
  font-weight: 400;
  letter-spacing: .12em;
  color: var(--ink);
  line-height: 1.1;
  margin-bottom: .6rem;
}

.atlas-head h1 .ornament {
  color: var(--seal);
  font-family: "Ma Shan Zheng", cursive;
  margin: 0 .35em;
  font-size: .9em;
}

.atlas-head .subtitle {
  font-family: "Noto Serif SC", serif;
  font-weight: 300;
  color: var(--ink-soft);
  font-size: 1.05rem;
  max-width: 60ch;
  margin-top: .8rem;
}

/* 印章装饰 */
