  padding: 2rem 1.8rem;
  background: var(--paper-light);
  border-left: 1px solid var(--hairline);
  overflow-y: auto;
  max-height: calc(100vh - 200px);
}

.info-panel .placeholder {
  color: var(--ink-light);
  font-style: italic;
  font-size: .95rem;
  border-left: 2px solid var(--seal);
  padding-left: 1rem;
  margin-top: 1rem;
}

.info-panel h3 {
  font-family: "ZCOOL XiaoWei", serif;
  font-size: 1.5rem;
  letter-spacing: .08em;
  color: var(--ink);
  margin-bottom: .4rem;
}

.info-panel .info-tag {
  display: inline-block;
  font-family: "EB Garamond", serif;
  font-style: italic;
  font-size: .75rem;
  letter-spacing: .15em;
  color: var(--seal);
  text-transform: uppercase;
  margin-bottom: 1rem;
  border-bottom: 1px solid var(--seal);
  padding-bottom: 2px;
}

.info-panel p {
  font-size: .95rem;
  color: var(--ink-soft);
  margin-bottom: .8rem;
}

.info-panel .sub-list {
  margin-top: .6rem;
  padding-left: 1rem;
  border-left: 2px dashed var(--hairline);
}

.info-panel .sub-list li {
  list-style: none;
  position: relative;
  padding: .3rem 0 .3rem .9rem;
  font-size: .88rem;
  color: var(--ink-soft);
}

.info-panel .sub-list li::before {
  content: "";
  position: absolute;
  left: 0; top: .9rem;
  width: 6px; height: 1px;
  background: var(--seal);
}

.info-panel hr {
  border: none;
  border-top: 1px dashed var(--hairline);
  margin: 1.5rem 0;
}

/* ========================== 地图 SVG 样式 ========================== */
.province-path {
  fill: var(--land-base);
  stroke: var(--ink-soft);
  stroke-width: .55;
  stroke-linejoin: round;
  transition: fill .25s ease;
  cursor: pointer;
}

.province-path:hover {
  fill: #e0cf9c;
}

.province-path.dimmed {
  fill: var(--land-base);
}

.layer-polygon {
  stroke-width: .8;
  stroke-linejoin: round;
  pointer-events: all;
  cursor: pointer;
  transition: opacity .3s ease, fill-opacity .3s ease;
}

.layer-polygon.dialect { fill-opacity: .42; }
.layer-polygon.terrain { fill-opacity: .35; }
.layer-polygon.nonHan  { fill-opacity: .42; stroke-dasharray: 0; }
.layer-polygon.enclave { fill-opacity: .55; stroke-width: 1.4; stroke-dasharray: 4 2; }

.layer-polygon:hover {
  fill-opacity: .68 !important;
}

.fault-line {
  fill: none;
  stroke: var(--seal);
  stroke-width: 1.2;
  stroke-dasharray: 5 3;
  opacity: .75;
}

.annotation-marker circle {
  fill: var(--seal);
  stroke: var(--paper-light);
  stroke-width: 1.5;
  transition: r .2s ease;
  cursor: pointer;
}
.annotation-marker:hover circle { fill: var(--seal-dark); }

.annotation-marker text {
  font-family: "ZCOOL XiaoWei", serif;
  font-size: 11px;
  fill: var(--ink);
  letter-spacing: .05em;
  text-anchor: start;
  pointer-events: none;
  text-shadow:
    -1px -1px 0 var(--paper-light),
    1px -1px 0 var(--paper-light),
    -1px 1px 0 var(--paper-light),
    1px 1px 0 var(--paper-light),
    0 0 3px var(--paper-light);
}

.layer-label {
  font-family: "ZCOOL XiaoWei", serif;
  font-size: 13px;
  fill: var(--ink);
  pointer-events: none;
  letter-spacing: .15em;
  text-anchor: middle;
  font-weight: 600;
  paint-order: stroke;
  stroke: var(--paper-light);
  stroke-width: 3px;
  stroke-linejoin: round;
}

/* ========================== 叙事 ========================== */
section.essay {
  position: relative;
  z-index: 2;
  padding: 5rem 2rem;
  background: var(--paper-light);
  border-top: 2px solid var(--ink);
}

.essay-inner {
  max-width: 780px;
  margin: 0 auto;
}

.essay h2 {
  font-family: "ZCOOL XiaoWei", serif;
  font-size: 2.4rem;
  font-weight: 400;
  letter-spacing: .12em;
  color: var(--ink);
  margin: 3.5rem 0 1rem;
  position: relative;
  padding-bottom: .6rem;
}

.essay h2:first-child { margin-top: 0; }

.essay h2::after {
  content: "";
  position: absolute;
  bottom: 0; left: 0;
  width: 60px;
  height: 3px;
  background: var(--seal);
}

.essay h2 .num {
  font-family: "EB Garamond", serif;
  font-style: italic;
  font-size: .55em;
  color: var(--seal);
  letter-spacing: .08em;
  margin-right: .8rem;
  vertical-align: top;
  display: inline-block;
  transform: translateY(.4em);
}

.essay h3 {
  font-family: "ZCOOL XiaoWei", serif;
  font-size: 1.25rem;
  letter-spacing: .1em;
  margin: 2rem 0 .8rem;
  color: var(--ink-soft);
}

.essay p {
  font-family: "Noto Serif SC", serif;
  font-size: 1.02rem;
  color: var(--ink);
  margin-bottom: 1.1rem;
  line-height: 1.85;
  text-align: justify;
}

.essay strong {
  font-weight: 700;
  color: var(--seal-dark);
}

.essay em {
  font-style: italic;
  color: var(--ink-soft);
}

.essay .pullquote {
  border-left: 3px solid var(--seal);
  padding: 1rem 1.4rem;
  margin: 1.6rem 0;
  font-family: "ZCOOL XiaoWei", serif;
  font-size: 1.15rem;
  letter-spacing: .04em;
  color: var(--ink);
  background: var(--paper);
}

.essay ul.feature-list {
  list-style: none;
  margin: 1rem 0 1.5rem;
  padding: 0;
}

.essay ul.feature-list li {
  position: relative;
  padding: .55rem 0 .55rem 1.6rem;
  font-size: .98rem;
  color: var(--ink);
  border-bottom: 1px dotted var(--hairline);
}

.essay ul.feature-list li::before {
  content: "◆";
  position: absolute;
  left: 0; top: .65rem;
  color: var(--seal);
  font-size: .7rem;
}

footer.atlas-foot {
  position: relative;
  z-index: 2;
  padding: 2.5rem 2rem;
  text-align: center;
  background: var(--paper-warm);
  border-top: 1px solid var(--hairline);
  color: var(--ink-light);
  font-family: "EB Garamond", serif;
  font-size: .85rem;
  font-style: italic;
  letter-spacing: .1em;
  line-height: 1.8;
}

footer.atlas-foot .cn {
  font-family: "Noto Serif SC", serif;
  font-style: normal;
  letter-spacing: .15em;
  display: block;
  margin-bottom: .4rem;
  color: var(--ink-soft);
}

/* 响应式 */
@media (max-width: 1100px) {
  main.atlas-main {
    grid-template-columns: 1fr;
  }
  .layer-panel, .info-panel {
    border-left: none; border-right: none;
    border-bottom: 1px solid var(--hairline);
    max-height: none;
  }
  .map-stage {
    border: none;
    border-bottom: 1px solid var(--hairline);
  }
  #china-map { min-height: 500px; }
  .seal { width: 56px; height: 56px; top: 2rem; right: 2rem; font-size: .85rem; }
}

@media (max-width: 700px) {
  header.atlas-head { padding: 2.5rem 1.4rem 1.5rem; }
  .seal { display: none; }
  .layer-panel, .info-panel { padding: 1.4rem 1.2rem; }
  section.essay { padding: 3rem 1.4rem; }
  .essay h2 { font-size: 1.8rem; }
}

