// v3 冒烟测试：jsdom + 伪造 GeoJSON，走通滚动叙事全链路
const fs = require("fs");
const { JSDOM } = require("jsdom");

const html = fs.readFileSync("index.html", "utf-8")
  .replace(/<script src="https:[^"]+"><\/script>/g, "")
  .replace(/<script src="data\.js"><\/script>/g, "")
  .replace(/<script src="app\.js"><\/script>/g, "");

const dom = new JSDOM(html, { pretendToBeVisual: true, url: "https://example.org/" });
const { window } = dom;
global.window = window; global.document = window.document;
global.navigator = window.navigator;
global.requestAnimationFrame = window.requestAnimationFrame;
global.innerHeight = 800;

const d3 = require("d3");
// jsdom 无 SVG transform.baseVal：过渡降级为同步（真实浏览器无碍）
d3.selection.prototype.transition = function () {
  const sel = this;
  sel.duration = () => sel; sel.ease = () => sel; sel.delay = () => sel;
  return sel;
};

const sq = (x, y, s = 2) => ({ type: "Polygon",
  coordinates: [[[x,y],[x+s,y],[x+s,y+s],[x,y+s],[x,y]]] });
const provFC = { type: "FeatureCollection", features: [
  { type:"Feature", properties:{ name:"江苏省" }, geometry: sq(118, 32, 3) },
  { type:"Feature", properties:{ name:"河南省" }, geometry: sq(112, 33, 3) },
  { type:"Feature", properties:{ name:"广东省" }, geometry: sq(112, 22, 3) },
  { type:"Feature", properties:{ name:"西藏自治区" }, geometry: sq(85, 30, 6) },
  { type:"Feature", properties:{ name:"北京市" }, geometry: sq(116, 40, 1) }
]};
const prefData = {
  "320000": { type:"FeatureCollection", features: [
    { type:"Feature", properties:{ name:"苏州市" }, geometry: sq(120, 31, 1) },
    { type:"Feature", properties:{ name:"徐州市" }, geometry: sq(117, 34, 1) } ]},
  "410000": { type:"FeatureCollection", features: [
    { type:"Feature", properties:{ name:"郑州市" }, geometry: sq(113, 34.5, 1) },
    { type:"Feature", properties:{ name:"安阳市" }, geometry: sq(114, 35.8, 1) } ]},
  "440000": { type:"FeatureCollection", features: [
    { type:"Feature", properties:{ name:"梅州市" }, geometry: sq(115.8, 24, 1) } ]},
  "540000": { type:"FeatureCollection", features: [
    { type:"Feature", properties:{ name:"昌都市" }, geometry: sq(97, 31, 1) },
    { type:"Feature", properties:{ name:"拉萨市" }, geometry: sq(91, 29.5, 1) } ]}
};
const fetchMock = url => {
  if (url.includes("100000_full")) return Promise.resolve({ ok:true, json:()=>Promise.resolve(provFC) });
  const m = url.match(/(\d{6})_full/);
  if (m && prefData[m[1]]) return Promise.resolve({ ok:true, json:()=>Promise.resolve(prefData[m[1]]) });
  return Promise.reject(new Error("offline"));
};
global.fetch = fetchMock; window.fetch = fetchMock;

new Function("window","document","d3","fetch", fs.readFileSync("data.js","utf-8"))(window, window.document, d3, fetchMock);
new Function("window","document","d3","fetch", fs.readFileSync("app.js","utf-8"))(window, window.document, d3, fetchMock);

const sleep = ms => new Promise(r => setTimeout(r, ms));
const toRgb = h => { const n = parseInt(h.slice(1),16); return `rgb(${(n>>16)&255}, ${(n>>8)&255}, ${n&255})`; };
const eq = (got, hex) => got === hex || got === toRgb(hex);

(async () => {
  await sleep(350);
  const fail = [];
  const AT = window.__atlas;
  const A = window.ATLAS_DATA;
  const $$ = s => window.document.querySelectorAll(s);

  // 1. 22 步已生成，末步含探索按钮
  const steps = $$("#steps .step");
  if (steps.length !== AT.STEPS.length) fail.push(`步骤 ${steps.length} ≠ ${AT.STEPS.length}`);
  if (!window.document.getElementById("to-explore")) fail.push("末步缺探索按钮");

  const prefOf = (view, name) => {
    let el = null;
    view.svg.selectAll ? null : null;
    window.document.querySelectorAll("#" + (view === AT.story ? "story-map" : "explore-map") + " .pref")
      .forEach(p => { const d = d3.select(p).datum(); if (d && d.__short === name) el = p; });
    return el;
  };

  // 2. 第 3 步（苏州+徐州两城）
  AT.applyStep(3, true); await sleep(30);
  const sz = prefOf(AT.story, "苏州"), xz = prefOf(AT.story, "徐州"), zz = prefOf(AT.story, "郑州");
  if (!sz || !xz || !zz) fail.push("找不到市级单元");
  else {
    if (!eq(sz.style.fill, A.DIALECT_GROUPS.wu.color)) fail.push(`S3 苏州 ${sz.style.fill}`);
    if (!eq(xz.style.fill, A.DIALECT_GROUPS.zhongyuan.color)) fail.push(`S3 徐州 ${xz.style.fill}`);
    if (!eq(zz.style.fill, "#ece1c4")) fail.push(`S3 郑州应为底色，得 ${zz.style.fill}`);
  }
  const cityLabels = [...$$("#story-map .city-label")].map(t => t.textContent);
  if (!(cityLabels.includes("苏州") && cityLabels.includes("徐州"))) fail.push("S3 城市标注缺失");

  // 3. 第 4 步（中原官话全亮，keepProv 江苏）
  AT.applyStep(4, true); await sleep(30);
  if (!eq(zz.style.fill, A.DIALECT_GROUPS.zhongyuan.color)) fail.push(`S4 郑州 ${zz.style.fill}`);
  const ay = prefOf(AT.story, "安阳");
  if (!eq(ay.style.fill, "#e6dabb")) fail.push(`S4 安阳(晋语)应淡出，得 ${ay.style.fill}`);
  if (!eq(sz.style.fill, A.DIALECT_GROUPS.wu.color)) fail.push("S4 苏州应保留省内色(keepProv)");

  // 4. 第 13 步（藏区三分文化模式）
  AT.applyStep(13, true); await sleep(30);
  const cd = prefOf(AT.story, "昌都"), ls = prefOf(AT.story, "拉萨");
  if (!eq(cd.style.fill, A.CULTURE_GROUPS.kham.color)) fail.push(`S13 昌都 ${cd.style.fill}`);
  if (!eq(ls.style.fill, A.CULTURE_GROUPS.weizang.color)) fail.push(`S13 拉萨 ${ls.style.fill}`);
  if (!eq(sz.style.fill, "#ece1c4")) fail.push(`S13 苏州应为汉地淡色`);

  // 5. 第 12 步（徽州）故事点显示
  AT.applyStep(12, true); await sleep(30);
  const shown = [...$$("#story-map .pt")].filter(p => p.style.display !== "none").map(p => p.getAttribute("data-name"));
  if (!(shown.includes("婺源") && shown.includes("绩溪") && shown.length === 2)) fail.push(`S12 故事点 ${shown}`);

  // 6. 第 19 步（山川形便）：地形层 ghost 可见
  AT.applyStep(19, true); await sleep(30);
  const terrG = window.document.querySelector("#story-map .ghost");
  if (!terrG || terrG.style.display === "none") fail.push("S19 地形层未显示");
  const terrPaths = $$("#story-map .terr");
  if (terrPaths.length !== A.TERRAIN_REGIONS.length) fail.push(`地形区 ${terrPaths.length} ≠ ${A.TERRAIN_REGIONS.length}`);

  // 7. 探索视图：默认方言着色 + 图例 + 切换文化
  AT.renderExplore(); await sleep(30);
  const szE = prefOf(AT.explore, "苏州");
  if (!eq(szE.style.fill, A.DIALECT_GROUPS.wu.color)) fail.push(`探索 苏州 ${szE.style.fill}`);
  if (!$$("#ex-legend .lg-item").length) fail.push("探索图例为空");
  AT.setMode("culture"); await sleep(30);
  const cdE = prefOf(AT.explore, "昌都");
  if (!eq(cdE.style.fill, A.CULTURE_GROUPS.kham.color)) fail.push(`探索文化 昌都 ${cdE.style.fill}`);

  // 8. 图例点亮：wu 高亮时苏州 opacity 1，昌都 0.08
  AT.setMode("dialect"); await sleep(30);
  AT.explore.highlight("wu", "dialect");
  if (szE.style.opacity !== "1") fail.push(`高亮 苏州 opacity ${szE.style.opacity}`);
  if (cdE.style.opacity !== "0.08") fail.push(`高亮 昌都 opacity ${cdE.style.opacity}`);
  AT.explore.highlight(null);

  if (fail.length) { console.error("✗ 冒烟失败:"); fail.forEach(f => console.error("  -", f)); process.exit(1); }
  console.log("=== v3 冒烟全部通过：22 步生成、单城/群组/文化/地形各步着色、故事点、探索切换与图例点亮 ===");
  process.exit(0);
})().catch(e => { console.error("✗ 异常:", e); process.exit(1); });

