  if (!eq(cd.style.fill, A.CULTURE_GROUPS.kham.color)) fail.push(`S13 昌都 ${cd.style.fill}`);
  if (!eq(ls.style.fill, A.CULTURE_GROUPS.weizang.color)) fail.push(`S13 拉萨 ${ls.style.fill}`);
  if (!eq(sz.style.fill, "#ece1c4")) fail.push(`S13 苏州应为汉地淡色`);

  // 5. 第 12 步（徽州）故事点显示
  AT.applyStep(12, true); await sleep(30);
  const shown = [...$$("#story-map .pt")].filter(p => p.style.display !== "none").map(p => p.getAttribute("data-name"));
  if (!(shown.includes("婺源") && shown.includes("绩溪") && shown.length === 2)) fail.push(`S12 故事点 ${shown}`);

  // 6. 第 19 步（山川形便）：地形层 ghost 可见
  AT.applyStep(19, true); await sleep(30);
  const terrG = window.document.querySelector("#story-map .ghost");
  if (!terrG || terrG.style.display === "none") fail.push("S19 地形层未显示");
  const terrPaths = $$("#story-map .terr");
  if (terrPaths.length !== A.TERRAIN_REGIONS.length) fail.push(`地形区 ${terrPaths.length} ≠ ${A.TERRAIN_REGIONS.length}`);

  // 7. 探索视图：默认方言着色 + 图例 + 切换文化
  AT.renderExplore(); await sleep(30);
  const szE = prefOf(AT.explore, "苏州");
  if (!eq(szE.style.fill, A.DIALECT_GROUPS.wu.color)) fail.push(`探索 苏州 ${szE.style.fill}`);
  if (!$$("#ex-legend .lg-item").length) fail.push("探索图例为空");
  AT.setMode("culture"); await sleep(30);
  const cdE = prefOf(AT.explore, "昌都");
  if (!eq(cdE.style.fill, A.CULTURE_GROUPS.kham.color)) fail.push(`探索文化 昌都 ${cdE.style.fill}`);

  // 8. 图例点亮：wu 高亮时苏州 opacity 1，昌都 0.08
  AT.setMode("dialect"); await sleep(30);
  AT.explore.highlight("wu", "dialect");
  if (szE.style.opacity !== "1") fail.push(`高亮 苏州 opacity ${szE.style.opacity}`);
  if (cdE.style.opacity !== "0.08") fail.push(`高亮 昌都 opacity ${cdE.style.opacity}`);
  AT.explore.highlight(null);

  if (fail.length) { console.error("✗ 冒烟失败:"); fail.forEach(f => console.error("  -", f)); process.exit(1); }
  console.log("=== v3 冒烟全部通过：22 步生成、单城/群组/文化/地形各步着色、故事点、探索切换与图例点亮 ===");
  process.exit(0);
})().catch(e => { console.error("✗ 异常:", e); process.exit(1); });

