// 地形层视觉校验：投影 13 个自然区 + 10 条山脉，叠 5° 经纬网 + 已知城市锚点
const fs = require("fs");
const d3geo = require("d3-geo");
const d3shape = require("d3-shape");

const code = fs.readFileSync("data.js", "utf-8");
const A = (new Function("var window={};" + code + ";return window.ATLAS_DATA;"))();

const W = 1000, H = 780;
const MAINLAND = { type: "Feature", geometry: { type: "Polygon",
  coordinates: [[[73,17.8],[135.6,17.8],[135.6,53.8],[73,53.8],[73,17.8]]] } };
if (d3geo.geoArea(MAINLAND) > 2 * Math.PI) MAINLAND.geometry.coordinates[0].reverse();

const projection = d3geo.geoMercator().fitExtent([[14,14],[W-14,H-14]], MAINLAND);

const CITIES = [
  ["北京",116.40,39.90],["上海",121.47,31.23],["广州",113.26,23.13],
  ["成都",104.07,30.67],["西安",108.94,34.34],["兰州",103.83,36.06],
  ["乌鲁木齐",87.62,43.83],["拉萨",91.11,29.65],["哈尔滨",126.53,45.80],
  ["武汉",114.30,30.60],["昆明",102.83,24.88],["呼和浩特",111.75,40.84],
  ["福州",119.30,26.08],["南宁",108.37,22.82],["太原",112.55,37.87]
];

let svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}" viewBox="0 0 ${W} ${H}">
<rect width="${W}" height="${H}" fill="#f3e9cf"/>`;

// 经纬网
for (let lng = 75; lng <= 135; lng += 5) {
  const a = projection([lng, 18]), b = projection([lng, 54]);
  svg += `<line x1="${a[0]}" y1="${a[1]}" x2="${b[0]}" y2="${b[1]}" stroke="#c9bb98" stroke-width="0.5"/>
<text x="${a[0]+2}" y="${H-6}" font-size="9" fill="#8a7a5a">${lng}°</text>`;
}
for (let lat = 20; lat <= 52; lat += 5) {
  let pts = [];
  for (let lng = 73; lng <= 135.6; lng += 2) pts.push(projection([lng, lat]));
  svg += `<polyline points="${pts.map(p=>p.join(",")).join(" ")}" fill="none" stroke="#c9bb98" stroke-width="0.5"/>
<text x="4" y="${projection([73,lat])[1]-2}" font-size="9" fill="#8a7a5a">${lat}°</text>`;
}

// 自然区（Catmull-Rom 闭合曲线）
const line = d3shape.line().curve(d3shape.curveCatmullRomClosed.alpha(0.6));
A.TERRAIN_REGIONS.forEach(t => {
  const pts = t.ring.map(c => projection(c));
  svg += `<path d="${line(pts)}" fill="${t.color}" fill-opacity="0.5" stroke="${t.color}" stroke-width="1.5"/>`;
  const cx = pts.reduce((s,p)=>s+p[0],0)/pts.length, cy = pts.reduce((s,p)=>s+p[1],0)/pts.length;
  svg += `<text x="${cx}" y="${cy}" font-size="15" text-anchor="middle" fill="#1f1a14" font-weight="bold">${t.name}</text>`;
});

// 山脉
const rline = d3shape.line().curve(d3shape.curveCatmullRom.alpha(0.7));
A.MOUNTAIN_RANGES.forEach(m => {
  const pts = m.path.map(c => projection(c));
  svg += `<path d="${rline(pts)}" fill="none" stroke="#2a2118" stroke-width="2" stroke-dasharray="7,4"/>`;
  const mid = pts[Math.floor(pts.length/2)];
  svg += `<text x="${mid[0]+6}" y="${mid[1]-4}" font-size="12" fill="#2a2118">▲${m.name}</text>`;
});

// 城市锚点
CITIES.forEach(([n, lng, lat]) => {
  const [x,y] = projection([lng,lat]);
  svg += `<circle cx="${x}" cy="${y}" r="3.5" fill="#b03a2e"/>
<text x="${x+6}" y="${y+4}" font-size="11" fill="#b03a2e" font-weight="bold">${n}</text>`;
});

svg += `</svg>`;
fs.writeFileSync("preview-terrain.svg", svg);
console.log("✓ preview-terrain.svg written");

