// 启动冒烟测试：jsdom + 伪造 GeoJSON，验证应用真实跑通
const fs = require("fs");
const { JSDOM } = require("jsdom");

const html = fs.readFileSync("index.html", "utf-8")
  .replace(/<script src="https:[^"]+"><\/script>/g, "")
  .replace(/<script src="data\.js"><\/script>/g, "")
  .replace(/<script src="app\.js"><\/script>/g, "");

const dom = new JSDOM(html, { pretendToBeVisual: true, url: "https://example.org/" });
const { window } = dom;
global.window = window;
global.document = window.document;
global.navigator = window.navigator;
global.requestAnimationFrame = window.requestAnimationFrame;

const d3 = require("d3");

// jsdom 不实现 SVG transform.baseVal（d3 过渡插值依赖它，真实浏览器无碍）。
// 测试中把过渡降级为同步应用，行为断言不变。
d3.selection.prototype.transition = function () {
  const sel = this;
  sel.duration = () => sel;
  sel.ease = () => sel;
  sel.delay = () => sel;
  return sel;
};

// —— 伪造 GeoJSON ——
const sq = (x, y, s = 2) => ({ type: "Polygon",
  coordinates: [[[x,y],[x+s,y],[x+s,y+s],[x,y+s],[x,y]]] });
const provFC = { type: "FeatureCollection", features: [
  { type:"Feature", properties:{ name:"江苏省", adcode:"320000" }, geometry: sq(118, 32, 3) },
  { type:"Feature", properties:{ name:"广东省", adcode:"440000" }, geometry: sq(112, 22, 3) },
  { type:"Feature", properties:{ name:"福建省", adcode:"350000" }, geometry: sq(117, 25, 3) },
  { type:"Feature", properties:{ name:"西藏自治区", adcode:"540000" }, geometry: sq(85, 30, 6) },
  { type:"Feature", properties:{ name:"北京市", adcode:"110000" }, geometry: sq(116, 40, 1) },
  { type:"Feature", properties:{ name:"台湾省", adcode:"710000" }, geometry: sq(120.5, 23, 1.5) }
]};
const prefData = {
  "320000": { type:"FeatureCollection", features: [
    { type:"Feature", properties:{ name:"苏州市" }, geometry: sq(120, 31, 1) },
    { type:"Feature", properties:{ name:"徐州市" }, geometry: sq(117, 34, 1) },
    { type:"Feature", properties:{ name:"南京市" }, geometry: sq(118.5, 31.8, 1) }
  ]},
  "440000": { type:"FeatureCollection", features: [
    { type:"Feature", properties:{ name:"梅州市" }, geometry: sq(115.8, 24, 1) },
    { type:"Feature", properties:{ name:"湛江市" }, geometry: sq(110, 21, 1) }
  ]},
  "540000": { type:"FeatureCollection", features: [
    { type:"Feature", properties:{ name:"昌都市" }, geometry: sq(97, 31, 1) },
    { type:"Feature", properties:{ name:"那曲市" }, geometry: sq(92, 31.5, 1) }
  ]}
};

let fetchCount = 0;
const fetchMock = url => {
  fetchCount++;
  if (url.includes("100000_full")) return Promise.resolve({ ok: true, json: () => Promise.resolve(provFC) });
  const m = url.match(/(\d{6})_full/);
  if (m && prefData[m[1]]) return Promise.resolve({ ok: true, json: () => Promise.resolve(prefData[m[1]]) });
  return Promise.reject(new Error("offline: " + url));
};
global.fetch = fetchMock;
window.fetch = fetchMock;

// —— 执行 data.js + app.js ——
const dataCode = fs.readFileSync("data.js", "utf-8");
const appCode = fs.readFileSync("app.js", "utf-8");
new Function("window", "document", "d3", "fetch", dataCode)(window, window.document, d3, fetchMock);
new Function("window", "document", "d3", "fetch", appCode)(window, window.document, d3, fetchMock);

// —— 异步断言 ——
const sleep = ms => new Promise(r => setTimeout(r, ms));
(async () => {
  await sleep(300); // 等加载链完成

  const fail = [];
  const $$ = s => window.document.querySelectorAll(s);

  // 1. 章节条
  const tabs = $$("#chapter-nav .ch");
  if (tabs.length !== 7) fail.push(`章节签数量 ${tabs.length} ≠ 7`);
  if (!tabs[0] || !tabs[0].classList.contains("active")) fail.push("首章未激活");

  // 2. 面板内容（序章）
  const panel = window.document.getElementById("panel").innerHTML;
  if (!panel.includes("一张底图")) fail.push("面板未渲染序章");

  // 3. 市级拼图与省界线
  const prefs = $$(".pref");
  if (prefs.length < 8) fail.push(`市级路径仅 ${prefs.length}（应含苏粤藏市级 + 直辖/兜底省面）`);
  const provLines = $$(".prov-line");
  if (provLines.length !== provFC.features.length) fail.push(`省界线 ${provLines.length} ≠ ${provFC.features.length}`);

  // 4. 切到「壹 · 方言」并验证着色
  tabs[1].dispatchEvent(new window.Event("click", { bubbles: true }));
  await sleep(900); // 等 650ms 填色过渡

  const findPref = name => [...$$(".pref")].find(p => {
    const d = d3.select(p).datum(); return d && d.__short === name;
  });
  const expectFill = (name, hex) => {
    const el = findPref(name);
    if (!el) { fail.push(`找不到市级单元 ${name}`); return; }
    const f = el.style.fill;
    // jsdom 可能给 rgb() 形式，统一比较
    const toRgb = h => { const n = parseInt(h.slice(1), 16);
      return `rgb(${(n>>16)&255}, ${(n>>8)&255}, ${n&255})`; };
    if (f !== hex && f !== toRgb(hex)) fail.push(`${name} 填色 ${f} ≠ ${hex}`);
  };
  const G = window.ATLAS_DATA.DIALECT_GROUPS;
  expectFill("苏州", G.wu.color);
  expectFill("徐州", G.zhongyuan.color);
  expectFill("梅州", G.hakka.color);
  expectFill("湛江", G.qionglei.color);
  expectFill("台湾", G.minnan.color);

  // 5. 图例存在且包含吴语
  const panel2 = window.document.getElementById("panel").innerHTML;
  if (!panel2.includes("lg-item")) fail.push("方言章无图例");
  if (!panel2.includes("吴语")) fail.push("图例缺少吴语");

  // 6. 点击徐州 → 详情卡含中原官话注释
  const xz = findPref("徐州");
  xz.dispatchEvent(new window.Event("click", { bubbles: true }));
  await sleep(50);
  const detail = window.document.getElementById("detail").innerHTML;
  if (!detail.includes("中原官话")) fail.push("徐州详情卡未显示中原官话");
  if (!detail.includes("互通")) fail.push("徐州详情卡未带注释");

  // 7. 切到「肆 · 非汉」验证文化着色（昌都=康）
  tabs[4].dispatchEvent(new window.Event("click", { bubbles: true }));
  await sleep(900);
  const cd = findPref("昌都");
  const C = window.ATLAS_DATA.CULTURE_GROUPS;
  const cdFill = cd.style.fill;
  const toRgb = h => { const n = parseInt(h.slice(1), 16);
    return `rgb(${(n>>16)&255}, ${(n>>8)&255}, ${n&255})`; };
  if (cdFill !== C.kham.color && cdFill !== toRgb(C.kham.color)) fail.push(`昌都文化填色 ${cdFill} ≠ 康 ${C.kham.color}`);

  console.log(`fetch 调用 ${fetchCount} 次（27 省 + 底图，含备援重试）`);
  if (fail.length) { console.error("✗ 冒烟测试失败:"); fail.forEach(f => console.error("  -", f)); process.exit(1); }
  console.log("=== 冒烟测试全部通过：启动、七章导航、市级着色、详情卡、文化圈着色 ===");
  process.exit(0);
})().catch(e => { console.error("✗ 异常:", e); process.exit(1); });

