// 测试：名称归一化 + 分类覆盖率
const fs = require("fs");
const code = fs.readFileSync("data.js", "utf-8");
const A = (new Function("var window={};" + code + ";return window.ATLAS_DATA;"))();

// —— 与 app.js 保持一致的归一化与分类逻辑 ——
const ETHNIC = "(回族|满族|蒙古族?|维吾尔族?|哈萨克族?|藏族|彝族|壮族|苗族|侗族|白族|傣族|土家族|布依族|朝鲜族|哈尼族|傈僳族|景颇族|柯尔克孜族?|锡伯族?|羌族|黎族|畲族|仡佬族|各族)";
const reEthnic = new RegExp(ETHNIC + "+(自治州|自治县|自治旗|自治区)$");
const reSuffix = /(自治州|自治区|特别行政区|地区|林区|市|盟|省)$/;
const shortName = n => n.replace(reEthnic, "").replace(reSuffix, "");

function classifyDialect(prov, pref) {
  const t = A.PREF_DIALECT[prov] || {};
  let v = t[pref] !== undefined ? t[pref] : t._default;
  if (v === undefined) v = A.PROV_FALLBACK[prov] || "nonhanmain";
  return Array.isArray(v) ? v[0] : v;
}
function classifyCulture(prov, pref) {
  const t = A.PREF_CULTURE[prov] || A.PREF_CULTURE["_default_"];
  let v = t[pref] !== undefined ? t[pref] : t._default;
  if (v === undefined) v = "han";
  return Array.isArray(v) ? v[0] : v;
}

// —— 样本：各省官方全称（含棘手的自治州/地区/盟/林区） ——
const SAMPLES = {
  "河北": ["石家庄市","唐山市","邯郸市","张家口市","承德市","邢台市","衡水市"],
  "山西": ["太原市","大同市","临汾市","运城市","吕梁市"],
  "内蒙古": ["呼和浩特市","包头市","赤峰市","呼伦贝尔市","兴安盟","锡林郭勒盟","阿拉善盟","鄂尔多斯市","巴彦淖尔市"],
  "辽宁": ["沈阳市","大连市","丹东市","营口市","朝阳市"],
  "吉林": ["长春市","延边朝鲜族自治州"],
  "黑龙江": ["哈尔滨市","齐齐哈尔市","大兴安岭地区","绥化市"],
  "江苏": ["南京市","苏州市","徐州市","南通市","连云港市","镇江市","宿迁市"],
  "浙江": ["杭州市","温州市","丽水市"],
  "安徽": ["合肥市","阜阳市","黄山市","宣城市","安庆市","蚌埠市"],
  "福建": ["福州市","厦门市","莆田市","三明市","南平市","龙岩市","宁德市"],
  "江西": ["南昌市","九江市","上饶市","赣州市","景德镇市","萍乡市"],
  "山东": ["济南市","青岛市","烟台市","潍坊市","济宁市","临沂市","菏泽市","威海市"],
  "河南": ["郑州市","安阳市","新乡市","焦作市","信阳市","济源市","濮阳市"],
  "湖北": ["武汉市","黄冈市","孝感市","咸宁市","恩施土家族苗族自治州","仙桃市","神农架林区","十堰市"],
  "湖南": ["长沙市","岳阳市","常德市","永州市","郴州市","湘西土家族苗族自治州","张家界市","邵阳市"],
  "广东": ["广州市","深圳市","汕头市","梅州市","惠州市","湛江市","潮州市","韶关市","茂名市","汕尾市"],
  "广西": ["南宁市","柳州市","桂林市","梧州市","百色市","河池市","崇左市","贺州市","防城港市"],
  "海南": ["海口市","三亚市","儋州市","五指山市","琼海市","乐东黎族自治县","陵水黎族自治县","昌江黎族自治县"],
  "四川": ["成都市","攀枝花市","凉山彝族自治州","甘孜藏族自治州","阿坝藏族羌族自治州","绵阳市"],
  "贵州": ["贵阳市","黔东南苗族侗族自治州","黔南布依族苗族自治州","黔西南布依族苗族自治州","毕节市","铜仁市"],
  "云南": ["昆明市","大理白族自治州","西双版纳傣族自治州","迪庆藏族自治州","怒江傈僳族自治州","德宏傣族景颇族自治州","红河哈尼族彝族自治州","文山壮族苗族自治州","楚雄彝族自治州","丽江市","普洱市","临沧市"],
  "西藏": ["拉萨市","日喀则市","昌都市","林芝市","山南市","那曲市","阿里地区"],
  "陕西": ["西安市","延安市","榆林市","汉中市","安康市","商洛市"],
  "甘肃": ["兰州市","嘉峪关市","天水市","武威市","临夏回族自治州","甘南藏族自治州","陇南市","酒泉市"],
  "青海": ["西宁市","海东市","海北藏族自治州","黄南藏族自治州","海南藏族自治州","果洛藏族自治州","玉树藏族自治州","海西蒙古族藏族自治州"],
  "宁夏": ["银川市","固原市","中卫市"],
  "新疆": ["乌鲁木齐市","克拉玛依市","吐鲁番市","哈密市","昌吉回族自治州","博尔塔拉蒙古自治州","巴音郭楞蒙古自治州","阿克苏地区","克孜勒苏柯尔克孜自治州","喀什地区","和田地区","伊犁哈萨克自治州","塔城地区","阿勒泰地区","石河子市","阿拉尔市","图木舒克市","五家渠市"],
  "北京": ["北京市"], "天津": ["天津市"], "上海": ["上海市"], "重庆": ["重庆市"],
  "台湾": ["台湾省"], "香港": ["香港特别行政区"], "澳门": ["澳门特别行政区"]
};

let total = 0, badDia = [], badCul = [], shortFails = [];
for (const [prov, names] of Object.entries(SAMPLES)) {
  for (const full of names) {
    total++;
    const s = shortName(full);
    // 归一化失败 = 为空，或仍以真正的行政后缀结尾（"苏州"的"州"是名字本体，不算）
    if (!s || /(自治州|自治县|自治区|地区|林区|特别行政区)$/.test(s) || /[市盟省]$/.test(s)) {
      shortFails.push(`${full} → "${s}"`);
    }
    const d = classifyDialect(prov, s);
    const c = classifyCulture(prov, s);
    if (!A.DIALECT_GROUPS[d]) badDia.push(`${prov}/${full}(${s}) → ${d}`);
    if (!A.CULTURE_GROUPS[c]) badCul.push(`${prov}/${full}(${s}) → ${c}`);
  }
}

// 每省兜底测试：未知名称必须有合法默认
for (const prov of Object.keys(A.PREF_DIALECT)) {
  const d = classifyDialect(prov, "某某");
  const c = classifyCulture(prov, "某某");
  if (!A.DIALECT_GROUPS[d]) badDia.push(`${prov}/某某 → ${d}`);
  if (!A.CULTURE_GROUPS[c]) badCul.push(`${prov}/某某 → ${c}`);
}

// 抽查关键归类是否符合预期
const EXPECT = [
  ["江苏","徐州","zhongyuan"], ["江苏","苏州","wu"], ["陕西","汉中","southwest"],
  ["陕西","榆林","jin"], ["河南","安阳","jin"], ["广东","梅州","hakka"],
  ["广东","湛江","qionglei"], ["广东","潮州","minnan"], ["福建","龙岩","hakka"],
  ["山西","运城","zhongyuan"], ["内蒙古","呼和浩特","jin"], ["内蒙古","赤峰","dongbei"],
  ["湖北","咸宁","gan"], ["湖北","黄冈","jianghuai"], ["湖南","永州","tuhua"],
  ["青海","西宁","zhongyuan"], ["新疆","喀什","nonhanmain"], ["新疆","乌鲁木齐","lanyin"]
];
const EXPECT_CUL = [
  ["西藏","拉萨","weizang"], ["西藏","昌都","kham"], ["西藏","那曲","amdo"],
  ["青海","玉树","kham"], ["青海","海西","mongol"], ["四川","甘孜","kham"],
  ["四川","阿坝","amdo"], ["甘肃","甘南","amdo"], ["云南","迪庆","kham"],
  ["吉林","延边","korean"], ["四川","凉山","yi"], ["贵州","黔东南","miaoyao"],
  ["新疆","伊犁","kazakh"], ["新疆","巴音郭楞","mongol"], ["宁夏","银川","hui"]
];
let wrong = [];
EXPECT.forEach(([p, n, want]) => { const got = classifyDialect(p, n); if (got !== want) wrong.push(`方言 ${p}/${n}: 期望 ${want} 实得 ${got}`); });
EXPECT_CUL.forEach(([p, n, want]) => { const got = classifyCulture(p, n); if (got !== want) wrong.push(`文化 ${p}/${n}: 期望 ${want} 实得 ${got}`); });

console.log(`样本总数: ${total}`);
console.log(`归一化失败: ${shortFails.length}`, shortFails.slice(0, 8));
console.log(`方言归类无效: ${badDia.length}`, badDia.slice(0, 8));
console.log(`文化归类无效: ${badCul.length}`, badCul.slice(0, 8));
console.log(`关键预期不符: ${wrong.length}`, wrong);
process.exit(shortFails.length || badDia.length || badCul.length || wrong.length ? 1 : 0);

