// Render preview to verify polygons project correctly within China's bounds
const fs = require('fs');
const d3 = require('d3');

const dataCode = fs.readFileSync('data.js', 'utf-8');
const DATA = (new Function('var window = {}; ' + dataCode + '; return window.DATA;'))();

const W = 1000, H = 760;
const projection = d3.geoMercator().center([105, 36]).scale(720).translate([W/2, H/2]);
const pathGen = d3.geoPath().projection(projection);

function polyToFeat(coords) {
  let feat = { type: "Feature", geometry: { type: "Polygon", coordinates: [coords] } };
  if (d3.geoArea(feat) > 2 * Math.PI) {
    feat.geometry.coordinates[0] = coords.slice().reverse();
  }
  return feat;
}

let svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${W} ${H}" style="background:#f3e9cf">`;
svg += `<rect x="0" y="0" width="${W}" height="${H}" fill="#f3e9cf"/>`;

DATA.terrain.forEach(t => {
  const p = pathGen(polyToFeat(t.polygon));
  svg += `<path d="${p}" fill="${t.color}" fill-opacity="0.3" stroke="${t.color}" stroke-width="0.5"/>`;
});

DATA.dialects.forEach(d => {
  const polys = d.polygons || [d.polygon];
  polys.forEach(poly => {
    const p = pathGen(polyToFeat(poly));
    svg += `<path d="${p}" fill="${d.color}" fill-opacity="0.42" stroke="${d.color}" stroke-width="0.6"/>`;
  });
});

DATA.nonHan.forEach(n => {
  const p = pathGen(polyToFeat(n.polygon));
  svg += `<path d="${p}" fill="${n.color}" fill-opacity="0.4" stroke="${n.color}" stroke-width="1" stroke-dasharray="3 2"/>`;
});

DATA.enclaves.forEach(e => {
  const p = pathGen(polyToFeat(e.polygon));
  svg += `<path d="${p}" fill="${e.color}" fill-opacity="0.55" stroke="${e.color}" stroke-width="1.4"/>`;
});

function centroid(coords) {
  let sx = 0, sy = 0;
  coords.forEach(([x, y]) => { sx += x; sy += y; });
  return [sx / coords.length, sy / coords.length];
}

DATA.terrain.forEach(t => {
  const [x, y] = projection(centroid(t.polygon));
  svg += `<text x="${x}" y="${y}" font-size="12" font-family="serif" fill="#1f1a14" text-anchor="middle" font-style="italic" stroke="#f3e9cf" stroke-width="2.5" paint-order="stroke">${t.name}</text>`;
});

DATA.annotations.forEach(a => {
  const [x, y] = projection([a.lng, a.lat]);
  svg += `<circle cx="${x}" cy="${y}" r="3" fill="#b03a2e" stroke="#fff" stroke-width="0.8"/>`;
  svg += `<text x="${x + 5}" y="${y + 3}" font-size="9" font-family="serif" fill="#1f1a14" stroke="#f3e9cf" stroke-width="2" paint-order="stroke">${a.name}</text>`;
});

svg += `</svg>`;
fs.writeFileSync('preview.svg', svg);
console.log('SVG written, size:', svg.length);

