const pptxgen = require("pptxgenjs");

// ---- Chow brand palette ----
const PARCH = "F3EAD3";   // parchment bg
const INK   = "2B2117";   // ink text
const TEAL  = "3F7E6B";   // teal
const TERRA = "BC4B33";   // terracotta
const CARD  = "FDFBF5";   // warm white card
const MUTED = "8A7B66";   // muted caption
const TINT_T = "E7EFEA";  // teal tint band
const TINT_R = "F4E3DA";  // terracotta tint row

const F = "Noto Serif SC";
const makeShadow = () => ({ type: "outer", color: "000000", blur: 7, offset: 2, angle: 45, opacity: 0.14 });

let p = new pptxgen();
p.layout = "LAYOUT_WIDE"; // 13.33 x 7.5
p.author = "Chow";
p.title = "燕东微 2025年报深度拆解与同业对比";

// ============================ SLIDE 1 ============================
let s1 = p.addSlide();
s1.background = { color: PARCH };

s1.addText("燕东微（688172）2025年报深度拆解：一张「在建工程」财报", {
  x: 0.5, y: 0.28, w: 12.33, h: 0.52, margin: 0,
  fontFace: F, fontSize: 26, bold: true, color: INK, align: "left"
});
s1.addText("结论先行：18.33亿营收对应274亿净经营资产与约650亿市值——利润表记录的是28nm产线的建设成本，而非既有业务的经营成果；亏损是资本开支周期的必然，真正的问题只在于市场为这份期权支付的价格。", {
  x: 0.5, y: 0.84, w: 12.33, h: 0.56, margin: 0,
  fontFace: F, fontSize: 11.5, italic: true, color: TERRA, align: "left", valign: "top"
});

// ---- 4 stat cards ----
const cardY = 1.52, cardH = 1.08, cardW = 2.90, gap = 0.243;
const cards = [
  { label: "营业收入（快报）", num: "18.33亿", numColor: TEAL,  sub: "同比 +7.56%｜连续第二年低个位数波动" },
  { label: "归母净利润", num: "-3.92亿", numColor: TERRA, sub: "同比 -119.99%｜上市后连亏两年" },
  { label: "扣非归母净利（预告）", num: "-8.8~-11亿", numColor: TERRA, sub: "缺口约5~7亿由非经常损益回填" },
  { label: "2026Q1 归母净利", num: "-2.59亿", numColor: TERRA, sub: "单季亏损 ≈ 2025全年的 66%，失速加深" },
];
cards.forEach((c, i) => {
  const x = 0.5 + i * (cardW + gap);
  s1.addShape(p.shapes.ROUNDED_RECTANGLE, { x, y: cardY, w: cardW, h: cardH, rectRadius: 0.06, fill: { color: CARD }, line: { type: "none" }, shadow: makeShadow() });
  s1.addText(c.label, { x: x + 0.16, y: cardY + 0.10, w: cardW - 0.32, h: 0.24, margin: 0, fontFace: F, fontSize: 9.5, color: MUTED, bold: true });
  s1.addText(c.num,   { x: x + 0.16, y: cardY + 0.32, w: cardW - 0.32, h: 0.44, margin: 0, fontFace: F, fontSize: 25, bold: true, color: c.numColor });
  s1.addText(c.sub,   { x: x + 0.16, y: cardY + 0.78, w: cardW - 0.32, h: 0.26, margin: 0, fontFace: F, fontSize: 8.5, color: MUTED });
});

// ---- left: chart ----
s1.addText("归母净利润轨迹（亿元）：从5.5亿盈利到亏损失速", {
  x: 0.5, y: 2.85, w: 5.35, h: 0.3, margin: 0, fontFace: F, fontSize: 13, bold: true, color: INK
});
s1.addChart(p.charts.BAR, [
  { name: "盈利期", labels: ["2021", "2022", "2023", "2024", "2025", "26Q1"], values: [5.50, 4.62, 4.52, null, null, null] },
  { name: "亏损期", labels: ["2021", "2022", "2023", "2024", "2025", "26Q1"], values: [null, null, null, -1.78, -3.92, -2.59] },
], {
  x: 0.4, y: 3.18, w: 5.5, h: 2.72,
  barDir: "col", barGrouping: "stacked",
  chartColors: [TEAL, TERRA],
  chartArea: { fill: { color: PARCH } },
  plotArea: { fill: { color: PARCH } },
  catAxisLabelColor: MUTED, catAxisLabelFontSize: 10, catAxisLabelFontFace: F,
  valAxisLabelColor: MUTED, valAxisLabelFontSize: 9, valAxisLabelFontFace: F,
  valAxisMinVal: -5, valAxisMaxVal: 6.5,
