], { x: 0.72, y: 6.28, w: 11.9, h: 0.76, margin: 0, fontFace: F, valign: "top" });

s1.addText("数据来源：公司2025年度业绩快报/业绩预告（2026.01–02）、2025年三季报、2026年一季报、向特定对象发行股票募集说明书；整理时点 2026-07。", {
  x: 0.5, y: 7.14, w: 12.33, h: 0.24, margin: 0, fontFace: F, fontSize: 8, color: MUTED
});

// ============================ SLIDE 2 ============================
let s2 = p.addSlide();
s2.background = { color: PARCH };

s2.addText("同业坐标与前景推演：市场定价的是战略期权，不是现金流", {
  x: 0.5, y: 0.28, w: 12.33, h: 0.52, margin: 0,
  fontFace: F, fontSize: 26, bold: true, color: INK
});
s2.addText("与功率IDM双雄正面对比没有胜算——体量差6~9倍、盈利为负、研发强度异常。多头逻辑只能建立在「特种IC垄断＋国产装备28nm产线＋京东方需求内循环」的政治经济学坐标上；空头逻辑是35倍PS与2027–29年折旧洪峰。", {
  x: 0.5, y: 0.84, w: 12.33, h: 0.56, margin: 0,
  fontFace: F, fontSize: 11.5, italic: true, color: TERRA, valign: "top"
});

// ---- left: comparison table ----
s2.addText("2025年报同业对比（亿元）", { x: 0.5, y: 1.52, w: 6.6, h: 0.3, margin: 0, fontFace: F, fontSize: 13, bold: true, color: INK });

const th = (t) => ({ text: t, options: { fill: { color: TEAL }, color: "FFFFFF", bold: true, fontSize: 10, align: "center", valign: "middle", fontFace: F } });
const td = (t, o = {}) => ({ text: t, options: Object.assign({ fontSize: 9.5, color: INK, align: "center", valign: "middle", fontFace: F, fill: { color: CARD } }, o) });
const tdL = (t, o = {}) => td(t, Object.assign({ align: "left" }, o));

const hiFill = { fill: { color: TINT_R } };
s2.addTable([
  [th("公司"), th("营收"), th("同比"), th("归母净利"), th("研发/营收"), th("一句话定位")],
  [td("燕东微", Object.assign({ bold: true }, hiFill)), td("18.33", hiFill), td("+7.6%", hiFill), td("-3.92", Object.assign({ color: TERRA, bold: true }, hiFill)), td("≈52%†", hiFill), tdL("特种IC＋国产装备12吋，建设期", hiFill)],
  [td("华润微", { bold: true }), td("110.54"), td("+9.2%"), td("6.61"), td("10.6%"), tdL("功率IDM龙头，国内MOSFET第一")],
  [td("士兰微", { bold: true }), td("130.52"), td("+16.3%"), td("3.99"), td("9.0%"), tdL("IGBT/SiC放量，全球功率第六")],
  [td("华虹公司", { bold: true }), td("172.91"), td("+20.2%"), td("3.77"), td("—"), tdL("特色工艺代工，华虹制造爬坡期")],
], {
  x: 0.5, y: 1.86, w: 6.6, colW: [0.92, 0.88, 0.78, 0.98, 0.94, 2.10],
  rowH: [0.34, 0.42, 0.42, 0.42, 0.42],
  border: { pt: 0.75, color: "DCD2BD" },
});
s2.addText("† 燕东微为2025前三季度口径（6.10亿/11.67亿）；华润微归母同比-13.4%、扣非-26.8%，士兰微归母同比+81.3%，华虹归母同比-1.0%。", {
  x: 0.5, y: 3.95, w: 6.6, h: 0.42, margin: 0, fontFace: F, fontSize: 8, color: MUTED
});

// ---- left: two conclusion cards ----
const cc = [
  { t: "体量与盈利：不在同一战场", b: "华润微、士兰微营收为燕东微的6~7倍且全部盈利。三家可比公司的共同经验是12吋爬坡期折旧吞噬利润：华润微两条12吋线与联营亏损拖累归母-13.4%，华虹制造爬坡令其H1归母骤降72%——这正是燕东微2027年后的镜像预演。", c: TEAL },
  { t: "估值错位：PS≈35x vs 同业4~7x", b: "约650亿市值 ÷ 18.3亿营收≈35倍PS，而三家同业均在个位数。市场支付的不是现有业务，而是北电集成达产年83.4亿收入的贴现，以及「北京必须拥有一条28nm去美化产线」的政治承诺。", c: TERRA },
];
let ccy = 4.42;
cc.forEach((k) => {
  s2.addShape(p.shapes.ROUNDED_RECTANGLE, { x: 0.5, y: ccy, w: 6.6, h: 1.24, rectRadius: 0.06, fill: { color: CARD }, line: { type: "none" }, shadow: makeShadow() });
  s2.addText([
    { text: k.t, options: { bold: true, fontSize: 11, color: k.c, breakLine: true } },
    { text: k.b, options: { fontSize: 9.5, color: INK } },
  ], { x: 0.68, y: ccy + 0.08, w: 6.26, h: 1.10, margin: 0, fontFace: F, valign: "top", paraSpaceAfter: 2 });
  ccy += 1.36;
});

// ---- right: three pillars ----
const R2X = 7.42, R2W = 5.41;
s2.addText("竞争力：三根真实的支柱", { x: R2X, y: 1.52, w: R2W, h: 0.3, margin: 0, fontFace: F, fontSize: 13, bold: true, color: INK });
const pillars = [
  { t: "特种IC——利润压舱石", b: "特种集成电路及器件面向特种应用，垄断属性、高毛利；董事长张劲松兼任北京电控党委书记，订单与资源的国资通道明确。" },
  { t: "北电集成——去美化产线的稀缺性", b: "330亿、28–55nm特色工艺、规划5万片/月，以国产装备为主（北方华创深度绑定）；2025Q4设备已搬入，2026H2量产——制裁情景下的战略保险。" },
  { t: "芯屏生态——需求内循环", b: "京东方显示驱动IC需求牵引，产能消化有集团内兜底；北京电控以现金40.2亿全额认购定增（17.86元/股），真金白银站台。" },
];
let py = 1.86;
pillars.forEach((blk, i) => {
  s2.addShape(p.shapes.OVAL, { x: R2X, y: py + 0.02, w: 0.30, h: 0.30, fill: { color: TEAL }, line: { type: "none" } });
  s2.addText(String(i + 1), { x: R2X, y: py + 0.02, w: 0.30, h: 0.30, margin: 0, fontFace: F, fontSize: 12, bold: true, color: "FFFFFF", align: "center", valign: "middle" });
  s2.addText([
    { text: blk.t, options: { bold: true, fontSize: 10.5, color: INK, breakLine: true } },
    { text: blk.b, options: { fontSize: 9.5, color: INK } },
  ], { x: R2X + 0.44, y: py - 0.02, w: R2W - 0.44, h: 0.86, margin: 0, fontFace: F, valign: "top", paraSpaceAfter: 2 });
  py += 0.90;
});

// ---- right: outlook & risks ----
s2.addText("前景推演与风险", { x: R2X, y: 4.62, w: R2W, h: 0.3, margin: 0, fontFace: F, fontSize: 13, bold: true, color: INK });
s2.addShape(p.shapes.ROUNDED_RECTANGLE, { x: R2X, y: 4.96, w: R2W, h: 2.06, rectRadius: 0.06, fill: { color: TINT_T }, line: { type: "none" } });
s2.addText([
  { text: "时间表：2026H2量产 → 2030满产 → 2031达产年收入预计83.4亿。但项目自测算2027–2038年平均税后利润仅6.6亿/年，对330亿投资回报率约2%——财务上这是一个不指望股东回报的项目。", options: { fontSize: 9.5, color: INK, breakLine: true } },
  { text: "风险序列：①折旧洪峰2027–29，量产即亏损放大；②成熟制程全球性过剩＋显示驱动IC价格竞争；③股东行为已给信号——2025年多方套现后，亦庄国投再拟减持≤1%（2026.6–9月）。", options: { fontSize: 9.5, color: INK, breakLine: true } },
  { text: "操作含义：非基本面标的，是政策贝塔＋事件驱动（量产/验证/订单公告）的交易性标的。", options: { fontSize: 9.5, bold: true, color: TERRA } },
], { x: R2X + 0.16, y: 5.06, w: R2W - 0.32, h: 1.88, margin: 0, fontFace: F, valign: "top", paraSpaceAfter: 4 });

s2.addText("数据来源：各公司2025年年度报告/业绩快报、燕东微定增募集说明书与项目公告、公开新闻整理；估值为约数，随行情波动。仅为信息整理，不构成投资建议。", {
  x: 0.5, y: 7.14, w: 12.33, h: 0.24, margin: 0, fontFace: F, fontSize: 8, color: MUTED
});

p.writeFile({ fileName: "/home/claude/燕东微2025年报深度拆解与同业对比.pptx" }).then(() => console.log("done"));

