const h2 = (text) => new Paragraph({
  heading: HeadingLevel.HEADING_2,
  children: [new TextRun({ text, font: HEI, size: 27, bold: true })],
});

const title = (text) => new Paragraph({
  alignment: AlignmentType.CENTER,
  spacing: { after: 120 },
  children: [new TextRun({ text, font: HEI, size: 44, bold: true })],
});

const subtitle = (text) => new Paragraph({
  alignment: AlignmentType.CENTER,
  spacing: { after: 360 },
  children: [new TextRun({ text, font: SONG, size: 21, color: "595959" })],
});

const children = [
  title("在不可消解的张力中安居"),
  subtitle("——个体与社会关系之出路的一份论纲"),

  h1("导言"),
  pRich([
    { t: "“个体如何与社会相处”被反复设问，而最常见的答法，是为二者寻一个最终的和解公式——以善良意志约束权力意志，以公共意志统摄个体意志，宣告“个体自由不侵害公共利益、社会秩序不压抑合理人性”。本纲的根本主张与此相反：" },
    { t: "个体与社会之间不存在可被理论一举抚平的裂口；真正的出路不是一个和解的命题，而是一种在不可消解的张力中持续安居的实践。", b: true },
  ]),
  p("下文先在元问题层面重设问题，再以分析厘清被混为一谈的层次，继而陈明价值多元这一实质立场，在恰当之处动用悬置，最后把问题从理论移交给实践，给出正面的出路。所用之“综合”，自始至终只取局部的、可错的、可修订的编织之义，绝不取黑格尔式“扬弃”那种自我了结的形而上学和解——本纲拒绝为融贯而融贯。"),

  h1("一、重设问题：一个伪装成难题的画面错置（元问题层面）"),
  p("把“个体与社会”设想成两个先行存在、再求拼合的实体，这是一幅误导性的图画。维特根斯坦提醒我们：许多哲学难题并非有待解答的问题，而是有待解散的混乱——它们扎根于一幅错置的图画。此处的错置在于：个体从来不是先有一个完足的内核、然后才被抛入社会；人的语言、自我意识、乃至“我是谁”的回答，本就在与他人的相互承认中生成。但与此同时，每一个体又是不可替换的单数——他的处境、抉择与死亡，无人能够代领。"),
  p("于是真正的事态不是“两个东西要相加”，而是一个内在于人之境况的张力：人既彻底地是社会的，又不可化约地是单数的。看清这一点，“求一个把二者合一的公式”这个要求本身就失去了根据。这是一步元层面的解散，还不是实质主张：它只清场，不立论。"),

  h1("二、分析的清理：把被混为一谈的层次分开（分析层面）"),
  p("附件之失，大半源于跨层级的混同。分析的职责，是先把它们一一剥开。"),
  h2("（一）三个问题不可混用"),
  p("“个体与社会实际上如何关联”（描述）、“二者应当如何”（规范）、“身处其中的我该如何活”（生存），是三个不同的问题，各有各的判准。附件把对实在的描述、对应然的规定与对生活的劝勉揉成一团，以致每一步都显得比它实际拥有的根据更稳。"),
  h2("（二）关键词项各有歧义，须分疏"),
  p("“自由”至少有三义：免于干涉的消极自由、自我主导的积极自由、不受任意支配的共和自由；三者会彼此冲突（伯林的著名警告）。“社会”亦非一物：它可指结构、可指共同体、可指公共领域、可指国家，混用则论证暗中偷换。先标明在何义上使用，才不致以词的滑动冒充论证的推进。"),
  h2("（三）语言是介质，而非并列项"),
  p("语言不是与社会结构、资本、文化并列的第四种“规定性”，而是其余各项得以被陈述的条件本身。社会结构与资本是因果之力，文化是规范之维，唯语言是这一切被言说的介质。这一分疏有一个直接后果：任何“反思”都发生在语言之内，而非语言之上——它无法跃到构成它的东西外面去俯瞰全局。此点将在第五部分用以拆掉“上帝视角的反思主体”。"),

  h1("三、实质立场：价值多元与不可公度（本体—价值层面）"),
  pRich([
    { t: "清场与分疏之后，方可立论。本纲的实质立场是价值多元论：" },
    { t: "人所珍视的诸善——自主与归属、自由与秩序、本真与团结、效率与公正——是复多的，彼此并非总能同时最大化，有时根本不可公度。", b: true },
    { t: "这不是说尚缺一套更高明的理论去调和它们，而是说，“一切真问题都有唯一正解、且诸正解必然彼此相容”这条自古希腊承袭下来的一元论预设，本身就是错的（伯林称之为西方思想的核心误信）。承认这一点，意味着承认：在两种皆善之物之间作不可两全的选择，以及由此而来的真实损失，是人之境况的常态，而非理论不够圆熟的征兆（汉普希尔论冲突之恒在）。" },
  ]),
  p("须将多元论与相对主义划清。多元论不主张“怎样都行”：可被欲求的诸善落在一个人之为人的共同视域之内，此视域之外者（如以折磨为乐）仍是野蛮，仍可被拒斥。多元论只否认一件事——存在一个能把所有善无损地排成一序、一举实现的总公式。正因如此，要求个体与社会“终归和谐”的那种期待，不只是过高，而是方向错了。"),

  h1("四、悬置的位置：搁置“最终闭合”之要求（认识—元哲学层面）"),
  p("既然一元的和解在原则上不可得，面对那道残余的裂口，理性的回应便是悬置——但要悬置得其所。这里悬置的，不是“对一切下判断”（那是对悬置的滥用），而恰恰是“必须为个体与社会求得一个最终理论闭合”这一要求本身。"),
  p("一个类比有助于看清其结构（仅为类比，非证明）：哥德尔表明，足够丰富的形式系统无法在自身之内证明自身的全部真与一致；塔斯基表明，一种语言的真需要一个元语言来谈论。同理，没有任何一套社会理论能够在其自身之内，把“单数的个体”与“复数的共同体”之间的缝隙彻底缝合——因为作出缝合的那个反思，本身就处在缝隙的一侧。于是，把残余张力悬置、令其敞开，不是认输，而是认清工具的边界。"),
  p("也正是在此，本纲对“综合”划定界限：综合只在局部的、实践的、可修订的意义上被允许——把此时此地的诸善尽力编织得可以过活；它绝不被允许僭称为那种自我了结的形而上学和解。为融贯而强求融贯，恰是要避免的病。"),

  h1("五、出路：把问题从理论移交给实践（实践层面：正面主张）"),
  p("那么出路何在？出路在于：个体与社会的“解”，根本不是一个待证的命题，而是一种生活的样式。哲学在此回到它古老的身份——不是一套学说，而是一种生活方式（哈多）。这一样式有五个相互支撑的面向。"),
  h2("（一）以实践智慧代替公式"),
  p("个体在张力中安身，靠的不是“以善约束权”那样的机械配比，而是亚里士多德意义上的实践智慧：在具体情境中判断何处当坚守、何处可让步、让步到何处仍不构成背叛。德性不是两种意志的力学平衡，而是一种在个案中权衡的能力；它无法被化约为规则，只能在践行中养成。"),
  h2("（二）以争胜的公共领域代替统一的公意"),
  p("卢梭式“普遍意志”许诺把众人之异熔为一个共同意志，其暗面正是“强迫人自由”。更诚实的安排是：不取消冲突，而将冲突制度化为合法的、持续的、非暴力的争胜（墨菲的争胜民主；阿伦特对复多性的肯定）。一个自由社会的标志，不是众声归一，而是异见能够在不被消灭的前提下持续交锋。秩序由此不再是压平差异，而是为差异提供共处的规则。"),
  h2("（三）以厚共同体维系单数者的价值"),
  p("一个人若怀抱与周遭不同的、更高的标准，单凭孤身持守难以久长——一套无人共用的道德语汇，会像私人语言一样慢慢失去重量（维特根斯坦）。出路不是孤独的殉道，而是寻得或缔结一个哪怕极小的、共享同一实践的共同体；德性活在传统与实践之中，而非活在独自的内心（麦金太尔之审慎可取）。这一面向，正是抽象之论与个人处境的接榫处。"),
  h2("（四）诚实承认不可挽回的代价"),
  p("出路绝不许诺一个谁都不受损的双赢。在不可公度的善之间作选，必有真实而无法补偿的损失；一种成熟的活法接纳这一悲剧维度，而非用“终将和谐”将其粉饰（此即希腊悲剧的古老教诲，亦是李安电影一再逼视之物）。能否睁眼直视代价，是真出路与廉价安慰的分界。"),
  h2("（五）处境中的、对话的、可错的自我"),
  p("作此一切的自我，不是一个跃出语言与历史、俯瞰全局的阿基米德式反思主体——那正是被批判的启蒙幻象之回返。反思是真实的，却始终是局部的、由内而发的、可被修订的；自我在与他者的相互承认中持续生成（此乃黑格尔可取的一面：承认，而非和解），而承认是一场没有终点的较量，不是一劳永逸的安顿。"),

  h1("六、一个东方注脚：和而不同"),
  p("这一立场在中国思想里有一个相称的表述：“君子和而不同。”“和”不是“同”——不是把差异熔为一律，而是让不同者各居其位、相互成全。它与价值多元论同调，而与一元的“同”相抗。需诚实补一句：中国传统同时携带“差序格局”式的特殊主义——义务按关系亲疏分等；故“和而不同”若要支撑一个普遍主义的公共领域，尚须直面这一结构性张力，而非绕过它。把资源说足，也把难处说透，才不致以一句古语充当现成的答案。"),

  h1("结语"),
  p("综观全纲：个体与社会之间没有最终的和解公式，这不是悲观，而是清醒。真正的出路，不是走出张力，而是学会在张力中安居得当——以实践智慧周旋于个案，以争胜的公共生活安顿分歧，以厚实的共同体托住单数的坚持，以对代价的正视守住诚实，以可错而对话的自我承接没有终点的承认。这是一种有纪律地拒绝终极和解的活法：它不把矛盾按平，而把矛盾当作一个自由生命的常住条件来对待。本纲亦以同样的诚实承认自身的限度——它给出的不是定论，而是一个可被继续检验、修订与争辩的方向；而能够被继续争辩，本就是它所主张的那种生活的题中之义。"),
];

const doc = new Document({
  creator: "Claude",
  title: "在不可消解的张力中安居——个体与社会关系之出路的一份论纲",
  styles: {
    default: { document: { run: { font: SONG, size: 24 } } },
    paragraphStyles: [
      { id: "Heading1", name: "Heading 1", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { font: HEI, size: 32, bold: true },
        paragraph: { spacing: { before: 300, after: 140 }, outlineLevel: 0 } },
      { id: "Heading2", name: "Heading 2", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { font: HEI, size: 27, bold: true },
        paragraph: { spacing: { before: 200, after: 100 }, outlineLevel: 1 } },
    ],
  },
  sections: [{
    properties: {
      page: {
        size: { width: 11906, height: 16838 },
        margin: { top: 1440, right: 1440, bottom: 1440, left: 1440 },
      },
    },
    footers: {
