const fs = require("fs");
const {
  Document, Packer, Paragraph, TextRun,
  AlignmentType, HeadingLevel, PageNumber, Footer
} = require("docx");

const SONG = { ascii: "Times New Roman", eastAsia: "宋体", hAnsi: "Times New Roman" };
const HEI = { ascii: "Arial", eastAsia: "黑体", hAnsi: "Arial" };

const p = (text) => new Paragraph({
  spacing: { line: 360, lineRule: "auto", after: 80 },
  indent: { firstLine: 480 },
  children: [new TextRun({ text, font: SONG, size: 24 })],
});
const pRich = (segs) => new Paragraph({
  spacing: { line: 360, lineRule: "auto", after: 80 },
  indent: { firstLine: 480 },
  children: segs.map(s => new TextRun({ text: s.t, bold: !!s.b, font: SONG, size: 24 })),
});
const h1 = (text) => new Paragraph({
  heading: HeadingLevel.HEADING_1,
  children: [new TextRun({ text, font: HEI, size: 32, bold: true })],
});
const title = (text) => new Paragraph({
  alignment: AlignmentType.CENTER, spacing: { after: 120 },
  children: [new TextRun({ text, font: HEI, size: 42, bold: true })],
});
const subtitle = (text) => new Paragraph({
  alignment: AlignmentType.CENTER, spacing: { after: 360 },
  children: [new TextRun({ text, font: SONG, size: 21, color: "595959" })],
});

const children = [
  title("不必把它解决，但可以把它过好"),
  subtitle("——个体与社会相处的一条出路"),

  pRich([
    { t: "你要的那条路，先得从一个让人不舒服、但越早接受越好的事实出发：" },
    { t: "个体和社会之间，没有一个能严丝合缝对上的答案。", b: true },
    { t: "你想忠于自己的那部分——活得真、活得有种、不糊弄——和你想被接纳、想有同类、想过安稳日子的那部分，本来就会互相拉扯，有时根本没法两全。谁要是许给你一个“只要怎样怎样、两边就都圆满”的公式，那是在哄你。" },
  ]),
  p("所以出路不是一个想通了就一劳永逸的道理，而是一种活法。它不保证你舒服，但能让你站得住、走得下去。下面是这条路的几块落脚石。"),

  h1("一、别等一个完美的合榫"),
  p("把“我和这个世界对不上”当成一道必须解出来的题，你会一直拧巴。它不是题，是处境——像天气。承认它无解，不是泄气，恰恰是松绑：你不再为“怎么还没找到那个让一切和解的办法”而焦虑，因为根本就没有那个办法。路，是从这里才开始的。"),

  h1("二、守一个小内核，其余的讲分寸"),
  p("你不可能事事都按最高标准、毫不让步地顶着整个环境过——那不是有原则，很多时候只是好面子；而且在一个不太守信的环境里，单方面的死磕，往往只让你白吃亏。真正的功夫是：想清楚哪几条是你碰都不能碰的底线（清单越短越实在），守死它；除此之外，看人看事拿捏分寸——什么时候该坚持、什么时候可以退、退到哪儿还不算背叛自己。分寸感不是规则能教会的，是在一件件具体的事里磨出来的。守住核心，别处灵活，这是个体在这条路上最基本的姿势。"),

  h1("三、找到你的几个人"),
  p("这一条最实在，也最容易被忽略。一个人若怀着跟周围不一样、更高的标准，光靠自己硬扛，是扛不久的——一套没人跟你一起用的标准，时间长了会慢慢失重，连你自己都开始怀疑它到底还算不算数。出路不是孤胆英雄式的死守，而是去找到、或者攒起一小撮跟你这么活的人，哪怕只有三五个。一起认这套东西的人，能让它一直是活的、能落地的。你真正缺的，往往不是更硬的道理，是几个同路人。宗教团体真正管用的地方，从来不在教义对不对，而在于它给人凑齐了一拨一起这么过日子的人。这件事，值得你专门花力气去做。"),

  h1("四、对社会，不求一致，只求余地"),
  p("你不会让整个社会都认同你，也别去想。而且要看清：一个所有人都被捏成同一套价值的社会，不是天堂，是噩梦。一种过得下去的共同生活，给你的从来不是众口一词，而是余地——能不被碾碎地、持续地把不同说出来。所以你对外的力气，别花在“把大家都说服、都掰过来”上，那既办不到、方向也错了；该花在守护那种“可以不一样、还能一起过”的规矩上。秩序的好，不在于把差异压平，而在于给差异留出共处的地方。你跟社会相处的本分，不是改造别人，是和大家一起守住那点让彼此都能喘气的余地。"),

  h1("五、认账：代价是真的"),
  p("得跟你说句实话：在一个比你松、比你随便的环境里，做一个对自己有要求的人，是要付代价的——错过一些机会，活得没那么轻省，有时还得忍受不被理解、合不来。"),
  pRich([
    { t: "一种成熟的活法，是睁着眼把这账认了，而不是两头骗自己。一头别信“只要心善、制度好，最后总会和谐”那种廉价安慰，那是粉饰；另一头也别把自己活成悲情主角，整天泡在“我多高尚、没人懂我”里。代价就摆在那儿——看清它、认了它、付了它，然后接着走。这里有个挺准的分界：" },
    { t: "你这么活着，心里若是稳的、踏实的，那这套东西就是真属于你的；它若老让你憋出一股“我比他们强”的怨气，那你先该怀疑的，是你这套标准本身，而不是这个世界。", b: true },
  ]),

  h1("六、别把自己的标准当成天理"),
  p("对一个标准高的人，最大的陷阱是自以为是——把自己那套价值当成明摆着的真理，把周围人看成看不见这真理的庸众。可你也是从自己这一亩三分地往外看的，你也会错；那些活得更圆融、更通人情世故的人，未必就比你低。把对面那套更松、更讲关系的活法，简单当成“愚昧”，那是你的傲慢，不是事实。你不是圣人对着一群烂人，你只是在用另一套规矩过日子。常拿这把尺子量量自己：我守这些，到底是真讲究，还是在给自己撑场面？"),

  h1("结语：不必把它解决，把它过好"),
