    --color-text-primary: #e8e6e0;
    --color-text-secondary: #a8a6a0;
    --color-text-tertiary: #6f6e68;
    --color-background-primary: #1f1f1d;
    --color-background-secondary: #2a2a27;
    --color-background-page: #1a1a18;
    --color-border-tertiary: rgba(255, 255, 255, 0.10);
    --color-border-secondary: rgba(255, 255, 255, 0.18);
  }
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  background: var(--color-background-page);
  color: var(--color-text-primary);
  font-family: var(--font-sans);
  font-size: 16px;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

a { color: inherit; text-decoration: underline; text-underline-offset: 2px; }
a:hover { opacity: 0.7; }

.container {
  max-width: 760px;
  margin: 0 auto;
  padding: 32px 24px 64px;
}

.page-header {
  margin-bottom: 24px;
  padding-bottom: 16px;
  border-bottom: 0.5px solid var(--color-border-tertiary);
}

.page-header h1 {
  font-size: 22px;
  font-weight: 500;
  margin: 0 0 6px;
  letter-spacing: -0.01em;
}

.page-sub {
  font-size: 14px;
  color: var(--color-text-secondary);
  margin: 0 0 4px;
  line-height: 1.5;
}

.page-meta {
  font-size: 12px;
  color: var(--color-text-tertiary);
  margin: 0;
}

.summary {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 10px;
  margin-bottom: 20px;
}

.summary-card {
  padding: 14px 16px;
  background: var(--color-background-secondary);
  border-radius: var(--border-radius-md);
}

.summary-num {
  font-size: 20px;
  font-weight: 500;
}

.summary-lbl {
  font-size: 13px;
  color: var(--color-text-secondary);
  margin-top: 2px;
}

.tabs {
  display: flex;
  gap: 0;
  border-bottom: 0.5px solid var(--color-border-tertiary);
  margin-bottom: 16px;
  flex-wrap: wrap;
}

.tab {
  padding: 12px 16px;
  cursor: pointer;
  border: none;
  background: transparent;
  color: var(--color-text-secondary);
  font-size: 14px;
  font-family: inherit;
  border-bottom: 2px solid transparent;
  margin-bottom: -1px;
  transition: color 0.15s, border-color 0.15s;
}

.tab:hover { color: var(--color-text-primary); }

.tab.active {
  color: var(--color-text-primary);
  border-bottom-color: var(--color-text-primary);
  font-weight: 500;
}

.panel { display: none; }
.panel.active { display: block; }

.panel h2 {
  font-size: 18px;
  font-weight: 500;
  margin: 18px 0 8px;
}

.panel h3 {
  font-size: 12px;
  font-weight: 500;
  margin: 22px 0 10px;
  color: var(--color-text-secondary);
  letter-spacing: 0.5px;
  text-transform: uppercase;
}

.panel-sub {
  font-size: 14px;
  color: var(--color-text-secondary);
  margin: 0;
  line-height: 1.55;
}

.panel-sub.note { margin-top: 8px; font-size: 13px; }

.chart {
  width: 100%;
  margin: 14px 0 8px;
  display: block;
}

.chart-grid {
  stroke: #7f7f7f;
  stroke-width: 0.5;
  stroke-dasharray: 2 3;
  opacity: 0.3;
}

.chart-axis {
  font-size: 11px;
  fill: var(--color-text-secondary);
}

.chart-anno {
  font-size: 10px;
  fill: var(--color-text-secondary);
}

.chart-patch-label {
  font-size: 12px;
  font-weight: 500;
}

.chart-patch-muted {
  fill: var(--color-text-secondary);
}

.chart-line {
  stroke: var(--color-text-primary);
}

.step-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 8px;
  margin: 8px 0;
}

.step {
  padding: 12px 14px;
  background: var(--color-background-secondary);
  border-left: 3px solid;
  border-radius: 0;
}

.step-cf { border-left-color: #D85A30; }
.step-opt { border-left-color: #1D9E75; }

.step-label {
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.4px;
  text-transform: uppercase;
  margin-bottom: 6px;
}

.step-cf .step-label { color: #D85A30; }
.step-opt .step-label { color: #1D9E75; }

.step-title {
  font-size: 14px;
  font-weight: 500;
  margin-bottom: 4px;
  line-height: 1.4;
}

.step-desc {
  font-size: 13px;
  color: var(--color-text-secondary);
  line-height: 1.55;
}

.sizebar-wrap {
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 6px 0;
}

.sizebar-label {
  width: 96px;
  flex-shrink: 0;
  color: var(--color-text-secondary);
  font-size: 13px;
}

.sizebar {
  height: 30px;
  border-radius: 4px;
  display: flex;
  align-items: center;
  padding: 0 12px;
  color: white;
  font-weight: 500;
  font-size: 13px;
  min-width: 80px;
}

.evidence {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 8px;
}

.evidence > div {
  padding: 12px 14px;
  background: var(--color-background-secondary);
  border-left: 3px solid;
  border-radius: 0;
}

.evidence-cf { border-left-color: #D85A30; }
.evidence-opt { border-left-color: #378ADD; }

.ev-title {
  font-size: 12px;
  color: var(--color-text-secondary);
  margin-bottom: 4px;
}

.ev-body {
  font-size: 13px;
  line-height: 1.55;
}

.ev-strong-cf { color: #D85A30; font-weight: 500; }
.ev-strong-opt { color: #378ADD; font-weight: 500; }
.ev-muted { color: var(--color-text-secondary); }

.pnl {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: 8px;
  margin-top: 8px;
}

.pnl-cell {
  padding: 14px 16px;
  border-radius: var(--border-radius-md);
  background: var(--color-background-secondary);
}

.pnl-amt {
  font-size: 20px;
  font-weight: 500;
}

.pnl-amt.loss { color: #D85A30; }
.pnl-amt.profit { color: #1D9E75; }
.pnl-amt.net { color: var(--color-text-primary); }

.pnl-lbl {
  font-size: 12px;
  color: var(--color-text-secondary);
  margin-top: 2px;
}

.callout {
  margin-top: 18px;
  padding: 14px 16px;
  background: var(--color-background-secondary);
  border-left: 3px solid #BA7517;
  border-radius: 0;
}

.callout-title {
  font-size: 14px;
  font-weight: 500;
  color: #BA7517;
  margin-bottom: 6px;
}

.callout-body {
  font-size: 13px;
  line-height: 1.6;
}

.callout ul {
  margin: 8px 0 0;
  padding-left: 18px;
  font-size: 12px;
  line-height: 1.7;
  color: var(--color-text-secondary);
}

.callout li { margin-bottom: 2px; }

.day-chart {
  margin: 14px 0;
}

.day-row {
  display: grid;
  grid-template-columns: 100px 1fr 110px 140px;
  gap: 10px;
  align-items: center;
  padding: 6px 6px;
  cursor: pointer;
  border-radius: 4px;
  font-size: 12px;
  transition: background 0.1s;
}

.day-row:hover,
.day-row.selected {
  background: var(--color-background-secondary);
