  border-radius: 3px;
  overflow: hidden;
}

.day-bar {
  height: 100%;
  border-radius: 3px;
  transition: filter 0.1s;
}

.day-row:hover .day-bar { filter: brightness(1.1); }

.day-amt {
  text-align: right;
  font-variant-numeric: tabular-nums;
  font-weight: 500;
}

.day-strat {
  font-size: 11px;
  color: var(--color-text-secondary);
}

.legend {
  margin-top: 14px;
  padding: 10px 14px;
  border-radius: var(--border-radius-md);
  background: var(--color-background-secondary);
  display: flex;
  gap: 18px;
  font-size: 12px;
  flex-wrap: wrap;
}

.legend-dot {
  display: inline-block;
  width: 12px;
  height: 12px;
  border-radius: 2px;
  margin-right: 6px;
  vertical-align: middle;
}

.detail {
  margin-top: 14px;
  padding: 14px 16px;
  border-radius: var(--border-radius-md);
  background: var(--color-background-secondary);
}

.detail[hidden] { display: none; }

.detail-title {
  font-size: 14px;
  font-weight: 500;
  margin-bottom: 4px;
}

.detail-meta {
  font-size: 12px;
  color: var(--color-text-secondary);
  margin-bottom: 8px;
}

.detail-body {
  font-size: 13px;
  line-height: 1.6;
}

.page-footer {
  margin-top: 48px;
  padding-top: 16px;
  border-top: 0.5px solid var(--color-border-tertiary);
  font-size: 12px;
  color: var(--color-text-tertiary);
  line-height: 1.6;
