@media (max-width: 640px) {
  .container { padding: 20px 16px 48px; }
  .page-header h1 { font-size: 19px; }
  .panel h2 { font-size: 16px; }
  .day-row {
    grid-template-columns: 88px 1fr 90px;
    gap: 8px;
  }
  .day-strat { display: none; }
  .tabs { font-size: 13px; }
  .tab { padding: 10px 12px; font-size: 13px; }
}

