:root {
  --color-text-primary: #1a1a1a;
  --color-text-secondary: #5f5e5a;
  --color-text-tertiary: #9b9a93;
  --color-background-primary: #ffffff;
  --color-background-secondary: #f5f4ef;
  --color-background-page: #faf9f5;
  --color-border-tertiary: rgba(0, 0, 0, 0.10);
  --color-border-secondary: rgba(0, 0, 0, 0.20);
  --border-radius-md: 8px;
  --border-radius-lg: 12px;
  --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC",
               "Hiragino Sans GB", "Microsoft YaHei", "Noto Sans CJK SC",
               "Source Han Sans CN", sans-serif;
}

@media (prefers-color-scheme: dark) {
  :root {
    --color-text-primary: #e8e6e0;
    --color-text-secondary: #a8a6a0;
    --color-text-tertiary: #6f6e68;
    --color-background-primary: #1f1f1d;
    --color-background-secondary: #2a2a27;
    --color-background-page: #1a1a18;
    --color-border-tertiary: rgba(255, 255, 255, 0.10);
    --color-border-secondary: rgba(255, 255, 255, 0.18);
  }
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  background: var(--color-background-page);
  color: var(--color-text-primary);
  font-family: var(--font-sans);
  font-size: 16px;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

a { color: inherit; text-decoration: underline; text-underline-offset: 2px; }
a:hover { opacity: 0.7; }

.container {
  max-width: 760px;
  margin: 0 auto;
  padding: 32px 24px 64px;
}

.page-header {
  margin-bottom: 24px;
  padding-bottom: 16px;
  border-bottom: 0.5px solid var(--color-border-tertiary);
}

.page-header h1 {
  font-size: 22px;
  font-weight: 500;
  margin: 0 0 6px;
  letter-spacing: -0.01em;
}

.page-sub {
  font-size: 14px;
  color: var(--color-text-secondary);
  margin: 0 0 4px;
  line-height: 1.5;
}

.page-meta {
  font-size: 12px;
  color: var(--color-text-tertiary);
  margin: 0;
}

.summary {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 10px;
  margin-bottom: 20px;
}

.summary-card {
  padding: 14px 16px;
  background: var(--color-background-secondary);
  border-radius: var(--border-radius-md);
}

.summary-num {
  font-size: 20px;
  font-weight: 500;
}

.summary-lbl {
  font-size: 13px;
  color: var(--color-text-secondary);
  margin-top: 2px;
}

.tabs {
  display: flex;
  gap: 0;
  border-bottom: 0.5px solid var(--color-border-tertiary);
  margin-bottom: 16px;
  flex-wrap: wrap;
}

.tab {
  padding: 12px 16px;
  cursor: pointer;
  border: none;
  background: transparent;
  color: var(--color-text-secondary);
  font-size: 14px;
  font-family: inherit;
  border-bottom: 2px solid transparent;
  margin-bottom: -1px;
  transition: color 0.15s, border-color 0.15s;
}

.tab:hover { color: var(--color-text-primary); }

.tab.active {
  color: var(--color-text-primary);
  border-bottom-color: var(--color-text-primary);
  font-weight: 500;
}

.panel { display: none; }
.panel.active { display: block; }

.panel h2 {
  font-size: 18px;
  font-weight: 500;
  margin: 18px 0 8px;
}

.panel h3 {
  font-size: 12px;
  font-weight: 500;
  margin: 22px 0 10px;
  color: var(--color-text-secondary);
  letter-spacing: 0.5px;
  text-transform: uppercase;
}

.panel-sub {
  font-size: 14px;
  color: var(--color-text-secondary);
  margin: 0;
  line-height: 1.55;
}

.panel-sub.note { margin-top: 8px; font-size: 13px; }

.chart {
  width: 100%;
  margin: 14px 0 8px;
  display: block;
}

.chart-grid {
  stroke: #7f7f7f;
  stroke-width: 0.5;
  stroke-dasharray: 2 3;
  opacity: 0.3;
}

.chart-axis {
  font-size: 11px;
  fill: var(--color-text-secondary);
}

.chart-anno {
  font-size: 10px;
  fill: var(--color-text-secondary);
}

.chart-patch-label {
  font-size: 12px;
  font-weight: 500;
}

.chart-patch-muted {
  fill: var(--color-text-secondary);
}

.chart-line {
  stroke: var(--color-text-primary);
}

.step-grid {
