  font-weight: 500;
  letter-spacing: 0.4px;
  text-transform: uppercase;
  margin-bottom: 6px;
}

.step-cf .step-label { color: #D85A30; }
.step-opt .step-label { color: #1D9E75; }

.step-title {
  font-size: 14px;
  font-weight: 500;
