  align-items: center;
  gap: 10px;
  margin: 6px 0;
}

.sizebar-label {
  width: 96px;
  flex-shrink: 0;
  color: var(--color-text-secondary);
  font-size: 13px;
}

.sizebar {
  height: 30px;
  border-radius: 4px;
