  align-items: center;
  padding: 0 12px;
  color: white;
  font-weight: 500;
  font-size: 13px;
  min-width: 80px;
}

.evidence {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 8px;
