  background: var(--color-background-secondary);
  border-left: 3px solid;
  border-radius: 0;
}

.evidence-cf { border-left-color: #D85A30; }
.evidence-opt { border-left-color: #378ADD; }

.ev-title {
  font-size: 12px;
  color: var(--color-text-secondary);
  margin-bottom: 4px;
}

.ev-body {
  font-size: 13px;
  line-height: 1.55;
}

.ev-strong-cf { color: #D85A30; font-weight: 500; }
.ev-strong-opt { color: #378ADD; font-weight: 500; }
.ev-muted { color: var(--color-text-secondary); }

.pnl {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: 8px;
  margin-top: 8px;
}

.pnl-cell {
  padding: 14px 16px;
  border-radius: var(--border-radius-md);
  background: var(--color-background-secondary);
}

.pnl-amt {
  font-size: 20px;
  font-weight: 500;
}

.pnl-amt.loss { color: #D85A30; }
.pnl-amt.profit { color: #1D9E75; }
.pnl-amt.net { color: var(--color-text-primary); }

.pnl-lbl {
  font-size: 12px;
  color: var(--color-text-secondary);
  margin-top: 2px;
}

.callout {
  margin-top: 18px;
  padding: 14px 16px;
  background: var(--color-background-secondary);
  border-left: 3px solid #BA7517;
  border-radius: 0;
}

.callout-title {
  font-size: 14px;
  font-weight: 500;
  color: #BA7517;
  margin-bottom: 6px;
}

.callout-body {
  font-size: 13px;
  line-height: 1.6;
}

.callout ul {
  margin: 8px 0 0;
  padding-left: 18px;
  font-size: 12px;
  line-height: 1.7;
  color: var(--color-text-secondary);
}

.callout li { margin-bottom: 2px; }

.day-chart {
  margin: 14px 0;
