// 考点标记(黄点) — 带防重叠错位
const kpPositions = state.route.kp.map(k => posAtWaypoint(k.at));
// 计算每个标号的偏移(避免重叠): 若与前一个屏幕距离过近,上下错开
const labelOffsets = computeLabelOffsets(kpPositions);
state.route.kp.forEach((k, idx) => {
  const pos = kpPositions[idx];
  const isCur = (idx === state.curStep);
  const r = isCur ? 7 : 4.5;
  ctx.fillStyle = isCur ? '#f5a623' : '#e6b800';
  ctx.beginPath();
  ctx.arc(WX(pos.x), WY(pos.y), r, 0, Math.PI*2);
  ctx.fill();
  if (isCur) {
    ctx.strokeStyle = 'rgba(245,166,35,0.4)';
    ctx.lineWidth = 4;
    ctx.beginPath();
    ctx.arc(WX(pos.x), WY(pos.y), r+4, 0, Math.PI*2);
    ctx.stroke();
  }
  // 序号(带错位)
  const off = labelOffsets[idx];
  const lx = WX(pos.x) + off.dx;
  const ly = WY(pos.y) + off.dy;
  if (off.dx !== 0 || off.dy !== 0) {
    // 错位时画一条细引线
    ctx.strokeStyle = 'rgba(230,184,0,0.5)';
    ctx.lineWidth = 0.8;
    ctx.beginPath();
    ctx.moveTo(WX(pos.x), WY(pos.y));
    ctx.lineTo(lx, ly);
    ctx.stroke();
    // 错位标号画小圆底
    ctx.fillStyle = isCur ? '#f5a623' : '#e6b800';
    ctx.beginPath();
    ctx.arc(lx, ly, isCur?8:6.5, 0, Math.PI*2);
    ctx.fill();
  }
  ctx.fillStyle = '#0f1419';
  ctx.font = `bold ${isCur?10:8.5}px sans-serif`;
  ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
  ctx.fillText((idx+1), lx, ly);
});

// 计算考点标号偏移,避免相邻标号在屏幕上重叠
function computeLabelOffsets(positions){
  const offsets = positions.map(()=>({dx:0, dy:0}));
  const MIN_DIST = 20; // 屏幕像素最小间距
  const screenPos = positions.map(p => ({x: WX(p.x), y: WY(p.y)}));
  for (let i=1; i<screenPos.length; i++){
    for (let j=0; j<i; j++){
      const ax = screenPos[i].x + offsets[i].dx;
      const ay = screenPos[i].y + offsets[i].dy;
      const bx = screenPos[j].x + offsets[j].dx;
      const by = screenPos[j].y + offsets[j].dy;
      const d = Math.hypot(ax-bx, ay-by);
      if (d < MIN_DIST){
        // 判断路段方向:相邻航点决定标号往哪个垂直方向错开
        // 简单策略:若两点水平接近→上下错;若垂直接近→左右错
        const dxRaw = Math.abs(screenPos[i].x - screenPos[j].x);
        const dyRaw = Math.abs(screenPos[i].y - screenPos[j].y);
        if (dxRaw <= dyRaw){
          // 垂直道路:标号左右错开
          offsets[i].dx = (offsets[j].dx >= 0) ? -16 : 16;
        } else {
          // 水平道路:标号上下错开
          offsets[i].dy = (offsets[j].dy <= 0) ? 17 : -17;
        }
      }
    }
  }
  return offsets;
}

