    .tab { padding: 14px 14px; font-size: 0.85rem; }
    h2 { font-size: 1.5rem; }
    .result-value, .status-value { font-size: 1.2rem; }
    .layout { gap: 28px; }
    table.schedule th, table.schedule td { padding: 8px 10px; }
    table.schedule { font-size: 0.78rem; }
