    --ink: #1A1814;
    --ink-soft: #3D362C;
    --muted: #7A6F5F;
    --muted-2: #B3A892;
    --accent: #8B2C2C;
    --accent-hover: #6E2222;
    --accent-soft: #C76B5F;
    --gold: #B89060;
    --border: #DDD3BC;
    --border-strong: #C5B89B;
    --positive: #2F6B3D;
    --negative: #8B2C2C;

