/* 设计系统:parchment / ink / crimson / gold + aegean(路径B)
   与既有项目族(逻辑地图集、悖论地图集、房贷计算器 Web 版)同源 */
page {
  --bg: #F7F3EA;
  --paper: #FFFDF8;
  --ink: #1A1814;
  --ink-2: #5A5244;
  --crimson: #8B2C2C;
  --gold: #B89060;
  --aegean: #2E5E6E;
  --line: #E4DAC4;
  --ok: #3E6B4F;
  --warn: #A8722A;
  --bad: #8B2C2C;

  background: var(--bg);
  color: var(--ink);
