versions.new:
  // ---- 判定 ----
  // 红线逻辑与分析一致:月供必须能由妻子税后收入独立覆盖,
  // 投资收益只能是加分项,不能成为生存现金流的必要项。
  let verdict;
  if (remainA < 0) verdict = 'nocash';
  else if (pmtTotal > wifeYuan) verdict = 'redline';
  else if (surplus >= 3000) verdict = 'comfort';
  else if (surplus >= 0) verdict = 'edge';
  else verdict = 'reliant';

  // ================= 资产负债表视角(基于路径 A 的推荐结构) =================
  const offshore = p.offshore != null ? p.offshore : 0;   // 境外美股(万,RMB 计)
  const equityER = p.equityER != null ? p.equityER : 0;   // 美股预期年化 %
  const riskFree = p.riskFree != null ? p.riskFree : 0;    // 国债/大额存单 %

  // 资产端(万)
  const aHouse = price;            // 核心资产:不动产(长期、缺乏流动性)
  const aCushion = cushionA;       // 无风险资产:安全垫(国债/大额存单)
  const aDomestic = investA;       // 境内可投资金
  const aOffshore = offshore;      // 境外权益(受结汇额度限制)
  const totalAssets = aHouse + aCushion + aDomestic + aOffshore;

  // 负债端(万)= 公积金 + 商贷
  const debtTotal = loanTotal;
  // 权益(净资产)= 资产 − 负债
  const equity = totalAssets - debtTotal;

  // 两个层次的杠杆,刻意区分(避免把"房产层 5 倍"误当成"家庭层")
  const assetLeverage = downA > 0 ? price / downA : Infinity;     // 房产层 LBO 杠杆 = 1/首付比
  const hhLeverage = equity > 0 ? totalAssets / equity : Infinity; // 家庭层杠杆 = 总资产/净资产

  // 加权债务成本(文档所称 WACC,严格说只含债务侧)
  const wacc = debtTotal > 0
    ? (fundLoan * p.fundRate + commLoan * p.commRate) / debtTotal
    : 0;

  // 偿债保障倍数(DSCR)与全口径覆盖倍数
  const dscr = pmtTotal > 0 ? wifeYuan / pmtTotal : Infinity;     // 收入/月供
  const coverage = (pmtTotal + livingYuan) > 0
    ? wifeYuan / (pmtTotal + livingYuan) : Infinity;              // 收入/(月供+生活)

  // 息差分解:锁定息差(可套利)vs 权益风险溢价(非套利、且受结汇限制)
  const lockedCarry = p.rStar - wacc;        // 百分点,境内固收 r* − 加权债务成本
  const equityPremium = equityER - wacc;     // 百分点,美股 E[R] − 加权债务成本(波动/不可锁定)

  // 尾部对冲:把安全垫视作看跌期权
  // 年化"保费" ≈ 安全垫 × (r* − 无风险利率):为换取确定性而放弃的收益
  const putPremium = aCushion * Math.max(0, p.rStar - riskFree) / 100; // 万/年
  const putProtectMonths = cushionMonthsA;   // 可覆盖月数 = 保护"深度"

  // 价格区间判定(沿用既有结论:建议区 / 稳健上限 / 红线)
  let priceZone;
  if (price <= 450) priceZone = 'in';
  else if (price <= 500) priceZone = 'cap';
  else priceZone = 'over';

  return {
    n, downA, deedTax, oneTimeA, loanTotal, fundLoan, commLoan,
    pmtFund, pmtComm, pmtTotal, ratio, surplus,
    remainA, cushionA, investA, cushionMonthsA,
    fundLoanB, downB, oneTimeB, pmtB, remainB, cushionB, investB,
    cushionMonthsB, surplusB,
    pvComm, npvDiff, verdict,
    cushionUnderfunded: remainA >= 0 && remainA < p.cushionT,
    // 资产负债表视角
    aHouse, aCushion, aDomestic, aOffshore, totalAssets,
    debtTotal, equity, assetLeverage, hhLeverage, wacc,
    dscr, coverage, lockedCarry, equityPremium,
    putPremium, putProtectMonths, priceZone,
  };
}

