function monthsBetween(dateStr, refDate) {
  if (!dateStr) return 0;
  const d = new Date(dateStr);
  const r = refDate ? new Date(refDate) : new Date();
  if (isNaN(d) || isNaN(r) || d >= r) return 0;
  return (r.getFullYear() - d.getFullYear()) * 12 + (r.getMonth() - d.getMonth());
}

export default function App() {
  const [selected, setSelected] = useState(null);
  const [propertyDate, setPropertyDate] = useState("");
  const [hukouMoveDate, setHukouMoveDate] = useState("");
  const [rentDate, setRentDate] = useState("");
  const [socialInsuranceMonths, setSocialInsuranceMonths] = useState("");
  const [refDate, setRefDate] = useState("2026-09-01");

  const cat = CATEGORIES.find((c) => c.key === selected);

  const result = useMemo(() => {
    if (!cat) return null;
    let bonus = 0;
    const details = [];
    const rate = 0.05;

    if (cat.bonusType === "property") {
      const m = monthsBetween(propertyDate, refDate);
      bonus = +(m * rate).toFixed(2);
      details.push(`产权证已满 ${m} 个月，加分 ${bonus}`);
    } else if (cat.bonusType === "hukou_move") {
      const m = monthsBetween(hukouMoveDate, refDate);
      bonus = +(m * rate).toFixed(2);
      details.push(`户籍迁入已满 ${m} 个月，加分 ${bonus}`);
    } else if (cat.bonusType === "hukou_and_rent") {
      const m1 = monthsBetween(hukouMoveDate, refDate);
      const b1 = +(m1 * rate).toFixed(2);
      details.push(`户籍迁入已满 ${m1} 个月，加分 ${b1}`);
      const m2 = monthsBetween(rentDate, refDate);
      const b2 = +(m2 * rate).toFixed(2);
      details.push(`租赁备案已满 ${m2} 个月，加分 ${b2}`);
      bonus = +(b1 + b2).toFixed(2);
    } else if (cat.bonusType === "social_insurance") {
      const raw = parseInt(socialInsuranceMonths) || 0;
      const extra = Math.max(0, raw - 12);
      bonus = +(extra * rate).toFixed(2);
      details.push(`社保累计 ${raw} 个月（超出12个月部分 ${extra} 个月），加分 ${bonus}`);
    } else if (cat.bonusType === "rent_and_social") {
      const m1 = monthsBetween(rentDate, refDate);
      const b1 = +(m1 * rate).toFixed(2);
      details.push(`租赁备案已满 ${m1} 个月，加分 ${b1}`);
      const raw = parseInt(socialInsuranceMonths) || 0;
      const extra = Math.max(0, raw - 12);
      const b2 = +(extra * rate).toFixed(2);
      details.push(`社保累计 ${raw} 个月（超出12个月部分 ${extra} 个月），加分 ${b2}`);
      bonus = +(b1 + b2).toFixed(2);
    }

    return { base: cat.base, bonus, total: +(cat.base + bonus).toFixed(2), details };
  }, [cat, propertyDate, hukouMoveDate, rentDate, socialInsuranceMonths, refDate]);

  const needsProperty = cat && (cat.bonusType === "property");
  const needsHukou = cat && ["hukou_move", "hukou_and_rent"].includes(cat.bonusType);
  const needsRent = cat && ["hukou_and_rent", "rent_and_social"].includes(cat.bonusType);
  const needsSocial = cat && ["social_insurance", "rent_and_social"].includes(cat.bonusType);

  return (
    <div style={{ minHeight: "100vh", fontFamily: "'Noto Serif SC', 'Source Han Serif CN', Georgia, serif", background: "linear-gradient(160deg, #fdf6ec 0%, #f5e6c8 50%, #ecdbb4 100%)", color: "#3a2e1e" }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Noto+Serif+SC:wght@400;600;700;900&display=swap');
        * { box-sizing: border-box; margin: 0; padding: 0; }
        .card-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: 12px; }
        .cat-card {
          border: 2px solid #d4c09e; border-radius: 12px; padding: 16px; cursor: pointer;
          background: rgba(255,255,255,0.6); transition: all 0.2s;
        }
        .cat-card:hover { border-color: #b8860b; background: rgba(255,255,255,0.85); transform: translateY(-2px); box-shadow: 0 6px 20px rgba(0,0,0,0.08); }
        .cat-card.active { border-color: #8b6914; background: linear-gradient(135deg, #fff9ec, #fff3d6); box-shadow: 0 4px 16px rgba(139,105,20,0.2); }
        .field { margin-bottom: 16px; }
        .field label { display: block; font-weight: 600; margin-bottom: 6px; font-size: 14px; color: #5a4a2a; }
        .field input { width: 100%; padding: 10px 14px; border: 2px solid #d4c09e; border-radius: 8px; font-size: 15px; font-family: inherit; background: #fffdf7; color: #3a2e1e; outline: none; }
        .field input:focus { border-color: #8b6914; box-shadow: 0 0 0 3px rgba(139,105,20,0.12); }
        .result-box { background: linear-gradient(135deg, #8b6914, #a67c1a); color: #fff; border-radius: 16px; padding: 28px; margin-top: 24px; }
        .score-big { font-size: 56px; font-weight: 900; line-height: 1; }
        .badge { display: inline-block; padding: 3px 10px; border-radius: 20px; font-size: 12px; font-weight: 700; }
      `}</style>

      <div style={{ maxWidth: 800, margin: "0 auto", padding: "32px 16px" }}>
        <div style={{ textAlign: "center", marginBottom: 32 }}>
          <div style={{ fontSize: 13, letterSpacing: 6, color: "#8b6914", fontWeight: 700, marginBottom: 8 }}>深圳市龙岗区</div>
          <h1 style={{ fontSize: 28, fontWeight: 900, color: "#3a2e1e", letterSpacing: 2 }}>义务教育积分计算器</h1>
          <p style={{ fontSize: 13, color: "#8a7a5a", marginTop: 8 }}>选择类型并填写信息，自动计算入学积分</p>
        </div>

        <div style={{ marginBottom: 24 }}>
          <h2 style={{ fontSize: 16, fontWeight: 700, marginBottom: 12, color: "#5a4a2a" }}>① 选择积分类型</h2>
          <div className="card-grid">
            {CATEGORIES.map((c) => (
              <div key={c.key} className={`cat-card ${selected === c.key ? "active" : ""}`} onClick={() => setSelected(c.key)}>
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 6 }}>
