              <div className="field">
                <label>户籍迁入学区日期</label>
                <input type="date" value={hukouMoveDate} onChange={(e) => setHukouMoveDate(e.target.value)} />
              </div>
            )}
            {needsRent && (
              <div className="field">
                <label>租赁凭证备案日期</label>
                <input type="date" value={rentDate} onChange={(e) => setRentDate(e.target.value)} />
              </div>
            )}
            {needsSocial && (
              <div className="field">
                <label>社保累计缴交月数（养老+医疗同时缴交）</label>
                <input type="number" min="0" placeholder="请输入月数" value={socialInsuranceMonths} onChange={(e) => setSocialInsuranceMonths(e.target.value)} />
              </div>
            )}

            {result && (
              <div className="result-box">
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-end", flexWrap: "wrap", gap: 16 }}>
                  <div>
                    <div style={{ fontSize: 13, opacity: 0.8, marginBottom: 4 }}>预估总积分</div>
                    <div className="score-big">{result.total}</div>
                  </div>
                  <div style={{ textAlign: "right" }}>
                    <div style={{ fontSize: 13, opacity: 0.8 }}>基础分 {result.base} + 加分 {result.bonus}</div>
                  </div>
                </div>
                <div style={{ marginTop: 16, borderTop: "1px solid rgba(255,255,255,0.25)", paddingTop: 12 }}>
                  {result.details.map((d, i) => (
                    <div key={i} style={{ fontSize: 13, opacity: 0.9, marginBottom: 4 }}>• {d}</div>
                  ))}
                </div>
              </div>
            )}
          </div>
        )}

        <div style={{ textAlign: "center", marginTop: 32, fontSize: 11, color: "#a09070" }}>
          仅供参考，实际积分以龙岗区教育局官方计算为准
