function monthsBetween(dateStr, refDate) {
  if (!dateStr) return 0;
  const d = new Date(dateStr);
  const r = refDate ? new Date(refDate) : new Date();
  if (isNaN(d) || isNaN(r) || d >= r) return 0;
  return (r.getFullYear() - d.getFullYear()) * 12 + (r.getMonth() - d.getMonth());
}

function ScoreBar({ score, maxScore = 110 }) {
  const pct = Math.min(100, (score / maxScore) * 100);
  return (
    <div style={{ width: "100%", height: 6, background: "rgba(0,0,0,0.08)", borderRadius: 3 }}>
      <div style={{ width: `${pct}%`, height: "100%", borderRadius: 3, background: "linear-gradient(90deg, #b8860b, #d4a017)", transition: "width 0.4s ease" }} />
    </div>
  );
}

function StatusBadge({ myScore, cutoff }) {
  if (!myScore || !cutoff) return null;
  const diff = myScore - cutoff;
  if (diff >= 5) return <span style={{ padding: "2px 8px", borderRadius: 12, fontSize: 11, fontWeight: 700, background: "#d4edda", color: "#155724" }}>很稳 +{diff.toFixed(2)}</span>;
  if (diff >= 0) return <span style={{ padding: "2px 8px", borderRadius: 12, fontSize: 11, fontWeight: 700, background: "#fff3cd", color: "#856404" }}>较稳 +{diff.toFixed(2)}</span>;
  if (diff >= -5) return <span style={{ padding: "2px 8px", borderRadius: 12, fontSize: 11, fontWeight: 700, background: "#ffe0b2", color: "#e65100" }}>有风险 {diff.toFixed(2)}</span>;
  return <span style={{ padding: "2px 8px", borderRadius: 12, fontSize: 11, fontWeight: 700, background: "#f8d7da", color: "#721c24" }}>较难 {diff.toFixed(2)}</span>;
}

