// ---- 幼儿园：查询 ----
setKgArea: function (e) { this.setData({ kgArea: e.currentTarget.dataset.v }); this.kgApply(); },
setKgGrade: function (e) { this.setData({ kgGradeF: e.currentTarget.dataset.v }); this.kgApply(); },
setKgTypeF: function (e) { this.setData({ kgTypeF: e.currentTarget.dataset.v }); this.kgApply(); },
onKgSearch: function (e) { this.setData({ kgSearch: e.detail.value }); this.kgApply(); },
kgFeeTxt: function (k) {
  if (k.type === '公办') {
    const f = GRADE_FEE[k.grade];
    return f ? f + ' 元/月 · 政府定价' : '政府定价（按等级）';
  }
  if (k.fee) return k.fee + ' 元/月 · 备案参考';
  return '以备案公示为准';
},
kgApply: function () {
  const d = this.data;
  const kgSel = this.kgSel;
  const self = this;
  const list = KG.filter(function (k) {
    if (d.kgArea !== '全部' && k.area !== d.kgArea) return false;
    if (d.kgTypeF !== '全部' && k.type !== d.kgTypeF) return false;
    if (d.kgGradeF !== '全部' && k.grade !== d.kgGradeF) return false;
    if (d.kgSearch && k.name.indexOf(d.kgSearch) < 0) return false;
    return true;
  });
  const order = { '省一级': 0, '市一级': 1, '区一级': 2, '规范化': 3 };
  list.sort(function (a, b) {
    const ga = a.grade in order ? order[a.grade] : 9, gb = b.grade in order ? order[b.grade] : 9;
    if (ga !== gb) return ga - gb;
    return a.area < b.area ? -1 : (a.area > b.area ? 1 : 0);
  });
  const rows = list.map(function (k) {
    return {
      key: 'kg|' + k.name,
      name: k.name,
      area: k.area,
      type: k.type,
      gradeTxt: k.grade || '—',
      puhui: k.puhui,
      feeTxt: self.kgFeeTxt(k),
      selected: kgSel.has('kg|' + k.name)
    };
  });
  this.setData({ kgRows: rows, kgCount: rows.length });
},

// ---- 幼儿园：对比 ----
toggleKgSelect: function (e) {
  const k = e.currentTarget.dataset.k;
  if (this.kgSel.has(k)) this.kgSel.delete(k); else this.kgSel.add(k);
  this.setData({ kgSelCount: this.kgSel.size });
  this.kgApply();
},
kgClearAll: function () {
  this.kgSel.clear();
  this.setData({ kgSelCount: 0, showKgCompare: false });
  this.kgApply();
},
openKgCompare: function () {
  if (this.kgSel.size < 2) return;
  const self = this;
  const items = [];
  this.kgSel.forEach(function (key) {
    const name = key.split('|')[1];
    const ref = KG.filter(function (k) { return k.name === name; })[0];
    if (ref) items.push(ref);
  });
  const cols = items.map(function (k, i) {
    return { name: k.name, color: PALETTE[i % PALETTE.length], key: 'kg|' + k.name };
  });
  const rows = [
    { label: '类型', cells: items.map(function (k) { return { txt: k.type }; }) },
    { label: '片区', cells: items.map(function (k) { return { txt: k.area }; }) },
    { label: '办园等级', cells: items.map(function (k) { return { txt: k.grade || '—', na: !k.grade }; }) },
    { label: '普惠性', cells: items.map(function (k) { return { txt: k.type === '公办' ? '（公办）' : (k.puhui ? '普惠' : '非普惠') }; }) },
    { label: '保教费', cells: items.map(function (k) { return { txt: self.kgFeeTxt(k) }; }) }
  ];
  this.setData({ showKgCompare: true, kgCmpCols: cols, kgCmpRows: rows });
},
removeKgCmp: function (e) {
  this.kgSel.delete(e.currentTarget.dataset.k);
  this.setData({ kgSelCount: this.kgSel.size });
  this.kgApply();
  if (this.kgSel.size < 2) this.setData({ showKgCompare: false });
  else this.openKgCompare();
},
closeKgCompare: function () { this.setData({ showKgCompare: false }); },

