.cbar{position:fixed;left:50%;transform:translateX(-50%);bottom:18px;background:#3a2e1e;color:#fff;border-radius:30px;padding:10px 14px 10px 18px;display:flex;align-items:center;gap:12px;box-shadow:0 8px 28px rgba(0,0,0,.28);z-index:50;font-size:14px}
.cbar.hidden{display:none}
.cbar .cnt{font-weight:700}
.cbar .cnt span{color:#f0c14b}
.cbtn{border:none;border-radius:20px;padding:8px 18px;font-family:inherit;font-size:13px;font-weight:700;cursor:pointer;transition:.15s}
.cbtn-go{background:#f0c14b;color:#3a2e1e}
.cbtn-go:disabled{background:#6a5e4e;color:#aa9e8e;cursor:not-allowed}
.cbtn-clear{background:transparent;color:#d8cebe;border:1px solid #6a5e4e}
.overlay{position:fixed;inset:0;background:rgba(40,30,18,.55);z-index:60;display:flex;align-items:flex-start;justify-content:center;padding:24px 12px;overflow-y:auto}
.overlay.hidden{display:none}
.modal{background:#fdf8ef;border-radius:16px;max-width:900px;width:100%;padding:22px;box-shadow:0 20px 60px rgba(0,0,0,.3);margin:auto}
.modal-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:14px}
.modal-head h2{margin:0;font-size:18px}
.xclose{border:none;background:#ece0c8;width:34px;height:34px;border-radius:50%;font-size:18px;cursor:pointer;color:#5a4a2a;line-height:1}
.xclose:hover{background:#ddcfb0}
.chartwrap{background:rgba(255,255,255,.7);border:1px solid #e8dcc4;border-radius:12px;padding:12px;margin-bottom:16px}
.chart-legend{display:flex;flex-wrap:wrap;gap:12px;margin-top:8px;font-size:12px}
.chart-legend span{display:flex;align-items:center;gap:5px;color:#5a4a2a}
.cmp-scroll{overflow-x:auto;border-radius:10px;border:1px solid #e8dcc4}
table.cmp{border-collapse:collapse;width:100%;font-size:13px;min-width:420px}
table.cmp th,table.cmp td{padding:9px 11px;text-align:center;border-bottom:1px solid #efe6d2;white-space:nowrap}
table.cmp thead th{background:#f3ead6;position:sticky;top:0}
table.cmp tbody td:first-child,table.cmp thead th:first-child{text-align:left;background:#f3ead6;position:sticky;left:0;font-weight:700;color:#6a5a3a;z-index:1}
table.cmp .colname{font-weight:700;font-size:13px}
table.cmp .rmv{border:none;background:none;color:#b06;cursor:pointer;font-size:13px;margin-left:4px}
table.cmp td.best{background:#fff4d6;font-weight:900;color:#8b6914;border-radius:4px}
.cdot{display:inline-block;width:10px;height:10px;border-radius:50%;flex-shrink:0}
.cmp-stage{font-size:10px;padding:1px 6px;border-radius:8px;background:#e7eefc;color:#3457a6;margin-left:4px}
</style>
</head>
<body>
<div class="wrap">
  <div class="header">
    <div class="sub">深圳市龙岗区</div>
    <h1>义务教育录取积分线查询系统</h1>
    <p>小一 · 初一历年录取积分 · 片区与竞争度查询</p>
  </div>

  <div class="tabs">
    <button class="tb on" data-tab="primary" onclick="switchTab('primary')">小一录取积分</button>
    <button class="tb" data-tab="middle" onclick="switchTab('middle')">初一录取积分</button>
    <button class="tb" data-tab="doc" onclick="switchTab('doc')">数据说明 / 升学率</button>
  </div>

  <div class="panel">
    <!-- query tabs share one filter UI -->
    <div id="query-section">
      <div class="filters">
        <div class="frow"><span class="flabel">片区</span><span id="area-chips"></span></div>
        <div class="frow"><span class="flabel">竞争度</span><span id="comp-chips"></span></div>
        <div class="frow">
          <span class="flabel">类型</span>
          <select class="inp" id="type-filter" onchange="render()" style="font-size:13px">
            <option value="全部">全部</option><option value="公办">公办</option><option value="民办">民办</option>
          </select>
          <label class="ckrow" onclick="toggle9()"><span class="ckbox" id="ck9"></span>仅九年一贯制</label>
          <input class="inp" id="search" placeholder="搜索学校名称…" oninput="render()" style="font-size:13px;flex:1;min-width:140px">
        </div>
        <div class="frow">
          <span class="flabel">排序</span>
          <select class="inp" id="sort" onchange="render()" style="font-size:13px">
            <option value="score_desc">按最新积分 高→低</option>
            <option value="score_asc">按最新积分 低→高</option>
            <option value="area">按片区</option>
          </select>
        </div>
      </div>

      <div class="note" id="stage-note"></div>

      <div class="legend">
        <span><span class="ld" style="background:#f8d7da"></span>极热门(≥100)</span>
        <span><span class="ld" style="background:#ffe0b2"></span>热门(90-100)</span>
        <span><span class="ld" style="background:#fff3cd"></span>较热(75-90)</span>
        <span><span class="ld" style="background:#d4edda"></span>一般(66-75)</span>
        <span><span class="ld" style="background:#d1ecf1"></span>门槛较低(&lt;66)</span>
      </div>

      <div class="count" id="count"></div>
      <div class="list" id="list"></div>
    </div>

    <!-- doc tab -->
    <div id="doc-section" class="doc hidden">
      <div class="warn">
        <b>关于"升学率 / 四大名校录取率 / 梯队"——重要说明。</b><br>
        广东省与深圳市教育部门明文规定：<b>严禁公布、宣传、炒作中考升学率</b>（《广东省进一步规范普通中小学招生入学工作的指导意见》2026-03-10 施行；《深圳市深化高中阶段学校考试招生制度改革的实施意见》）。因此<b>不存在官方发布的初中"四大率/升学率"数据</b>，网络上流传的相关数字均为非官方估算或机构宣传，无法溯源核实。"梯队"同样是家长与媒体的非官方概念，<b>官方没有任何学校梯队排名</b>。<br>
        基于"信息须来自官方"的要求，本系统<b>不收录这些无官方来源的数据</b>，以免误导。下方"竞争度"指标是直接从官方公示的录取积分线推导得出，可作为衡量学校热度的客观替代参考。
      </div>

      <h3>一、数据范围与"近10年"的现实</h3>
      <p>本系统收录的是<b>各校录取后公示的最低录取积分线</b>：小一为 2022–2025 年，初一为 2021–2025 年（含部分 2025 公示亮点）。更早年份不纳入，原因有三：积分入学规则（基础分、加分项、优享学区等）历年调整，跨年口径并不一致；学区划分与新建学校逐年变化；2020 年及以前缺乏可公开、可统一对比的全区数据。强行拼凑"10 年"反而会牺牲准确性，因此以可靠的近 4–5 届为准。</p>

      <h3>二、数据来源与口径（对应"官方来源"要求）</h3>
      <ul>
        <li><b>录取积分线</b>：原始数据来自各校录取结束后在校内/官网的<b>公示</b>（官方动作），由好师来教育、乐有家研究中心等第三方逐年汇总。官方原始数据可在龙岗区政府网各年度《学位申请指南》及各校公示查询，初一历年分数另有官方 Excel（lg.gov.cn 附件）。</li>
        <li><b>片区 / 招生范围</b>：以官方《龙岗区义务教育阶段小一·初一学位申请指南》为准（lg.gov.cn / sz.gov.cn 每年发布）。</li>
        <li><b>公办锁片区、民办面向全区</b>：源自《龙岗区教育局关于做好当年义务教育阶段新生招生工作的通知》——"民办学校面向全区招生"。</li>
      </ul>

      <h3>三、片区对应关系（锁片区 vs 跨片区）</h3>
      <ul>
        <li><b>公办学校＝锁片区</b>：按官方划定的"学区地段"招生，只面向地段内符合条件的适龄儿童。本系统在每所公办学校上标注其所属<b>街道/片区</b>；精确到小区/道路的招生范围请查当年官方指南（逐校、逐年文字描述）。</li>
        <li><b>民办学校＝面向全区（跨片区）</b>：不锁地段，全区适龄儿童均可报名，按积分高低统一录取；带小学部的民办初中可<b>直升</b>，超计划时同样按积分录取。</li>
      </ul>

      <h3>四、竞争度指标怎么看</h3>
      <p>"竞争度"是从录取积分线<b>直接推导</b>的客观指标，无需任何非官方数据。其逻辑是：龙岗积分以户籍+住房类别给基础分（如学区户籍+商品房≈100、龙岗户籍≈75、深圳其他区租房≈70、非深户租房=60），录取线越高，意味着录到的"边际考生"越靠前、所需的购房/社保/户籍时长越长，竞争越激烈：</p>
      <div class="metric-card"><div class="mt">极热门（≥100 分）</div><div class="md">通常需"学区户籍+商品房"，且购房时长往往达数年甚至 10 年以上才能录取。</div></div>
      <div class="metric-card"><div class="mt">热门（90–100 分）</div><div class="md">需学区户籍或学区购房，门槛较高。</div></div>
      <div class="metric-card"><div class="mt">较热（75–90 分）</div><div class="md">龙岗户籍家庭有机会冲刺，部分需购房或较长居住时长。</div></div>
      <div class="metric-card"><div class="mt">一般（66–75 分）</div><div class="md">深圳其他区户籍租房、或社保较长的非深户家庭多可入读。</div></div>
      <div class="metric-card"><div class="mt">门槛较低（&lt;66 分）</div><div class="md">非深户租房家庭通常即可录取，竞争压力小。</div></div>
      <p>对<b>民办（跨片区）</b>学校，因面向全区招生，其录取线反映的是<b>全区范围</b>的竞争；对<b>公办（锁片区）</b>学校，录取线反映的是<b>该片区内</b>的竞争。两者口径不同，横向比较时需注意。</p>

      <h3>五、学费</h3>
      <ul>
        <li><b>公办（含政府资助学校的公办班）</b>：义务教育阶段免学费（官方政策）。</li>
        <li><b>民办</b>：实行政府指导价、经发改部门备案，逐校逐年不同，区间跨度较大。本系统不臆造具体金额；准确学费请查当年各校《招生简章》或深圳市/龙岗区发改部门公布的备案价。</li>
      </ul>

      <h3>六、官方查询入口</h3>
      <ul>
        <li>龙岗区政府在线（学位申请指南、招生通知、历年初一录取分数附件）：lg.gov.cn</li>
        <li>深圳政府在线 - 龙岗区招生通知：sz.gov.cn</li>
        <li>"龙岗教育"微信公众号（小一/初一报名、学区、录取查询）</li>
        <li>深圳市招生考试办公室（中考相关政策）：szeb.sz.gov.cn</li>
      </ul>
    </div>
  </div>

  <div class="footer">
    录取积分线来自各校公示，经第三方汇总，仅供参考；片区与政策以龙岗区教育局官方发布为准。<br>
    升学率/梯队无官方来源，故不收录。实际录取与积分以当年官方核定为准。
  </div>
</div>

<div class="cbar hidden" id="cbar">
  <span class="cnt">已选 <span id="cbar-n">0</span> 所</span>
  <button class="cbtn cbtn-go" id="cbar-go" onclick="openCompare()">对比</button>
  <button class="cbtn cbtn-clear" onclick="clearAll()">清空</button>
</div>

<div class="overlay hidden" id="overlay" onclick="if(event.target===this)closeCompare()">
  <div class="modal">
    <div class="modal-head"><h2>学校对比</h2><button class="xclose" onclick="closeCompare()">×</button></div>
    <div id="compare-body"></div>
  </div>
</div>

<script>
const DATA = __DATA__;
const STAGE_NOTE = {
  primary: '小一录取积分线（2022–2025）。<b>公办锁片区</b>（按学区地段招生），<b>民办面向全区</b>（跨片区、按积分录取）。竞争度由录取线推导，详见"数据说明"。',
  middle: '初一录取积分线（2021–2025）。带小学部的民办初中可<b>直升</b>；超计划按积分录取。深圳<b>严禁公布升学率</b>，故本表只含可溯源的录取积分线。'
};
const YEARS = { primary:['2022','2023','2024','2025'], middle:['2021','2022','2023','2024','2025'] };

let state = { tab:'primary', area:'全部', comp:'全部', only9:false };
let selected = new Map(); // id "stage|name" -> {stage,name}
const PALETTE = ['#b8860b','#3457a6','#2d6a2d','#a6346a','#0c5460','#9a4a00','#6a3a8a','#c0392b'];

function latestScore(s){
  const ys = YEARS[state.tab];
  for(let i=ys.length-1;i>=0;i--){ if(s.scores[ys[i]]!=null) return s.scores[ys[i]]; }
  return null;
}
function compLevel(v){
  if(v==null) return null;
  if(v>=100) return '极热门';
  if(v>=90)  return '热门';
  if(v>=75)  return '较热';
  if(v>=66)  return '一般';
  return '门槛较低';
}
const COMP_CLASS={'极热门':'b-vhot','热门':'b-hot','较热':'b-warm','一般':'b-mid','门槛较低':'b-low'};
function compBadge(v){
  const lv=compLevel(v);
  if(!lv) return '';
  return '<span class="badge '+COMP_CLASS[lv]+'">'+lv+'</span>';
}
function barHTML(v){ if(v==null) return ''; const p=Math.min(100,(v/110)*100); return '<div class="bar"><div class="bf" style="width:'+p+'%"></div></div>'; }

function areas(){ const set=new Set(DATA[state.tab].map(s=>s.area)); return ['全部',...set]; }

function renderAreaChips(){
  document.getElementById('area-chips').innerHTML = areas().map(a=>
    '<button class="ch '+(state.area===a?'on':'')+'" onclick="setArea(\''+a+'\')">'+a+'</button>'
  ).join('');
}
function setArea(a){ state.area=a; renderAreaChips(); render(); }
function renderCompChips(){
  const levels=['全部','极热门','热门','较热','一般','门槛较低'];
  document.getElementById('comp-chips').innerHTML = levels.map(l=>
    '<button class="ch '+(state.comp===l?'on':'')+'" onclick="setComp(\''+l+'\')">'+l+'</button>'
  ).join('');
}
function setComp(l){ state.comp=l; renderCompChips(); render(); }
function toggle9(){ state.only9=!state.only9; document.getElementById('ck9').className='ckbox'+(state.only9?' on':''); document.getElementById('ck9').innerHTML=state.only9?'✓':''; render(); }

function switchTab(t){
  state.tab=t;
  document.querySelectorAll('.tb').forEach(b=>b.classList.toggle('on',b.dataset.tab===t));
  document.getElementById('query-section').classList.toggle('hidden',t==='doc');
  document.getElementById('doc-section').classList.toggle('hidden',t!=='doc');
  if(t!=='doc'){
    state.area='全部'; state.comp='全部';
    document.getElementById('stage-note').innerHTML = STAGE_NOTE[t];
    renderAreaChips();
    renderCompChips();
    render();
  }
}

function render(){
  if(state.tab==='doc') return;
  const typeF=document.getElementById('type-filter').value;
  const q=document.getElementById('search').value.trim();
  const sort=document.getElementById('sort').value;
  const ys=YEARS[state.tab];

  let list=DATA[state.tab].filter(s=>{
    if(state.area!=='全部'&&s.area!==state.area) return false;
    if(typeF!=='全部'&&s.type!==typeF) return false;
    if(state.only9&&!s.is9) return false;
    if(state.comp!=='全部'&&compLevel(latestScore(s))!==state.comp) return false;
    if(q&&!s.name.includes(q)) return false;
    return true;
  });

  if(sort==='area'){
    list.sort((a,b)=> a.area===b.area ? (latestScore(b)||0)-(latestScore(a)||0) : a.area.localeCompare(b.area,'zh'));
  } else {
    const dir = sort==='score_asc'?1:-1;
    list.sort((a,b)=> dir*(((latestScore(a)||0)-(latestScore(b)||0))));
  }

  document.getElementById('count').textContent='共 '+list.length+' 所学校';
  document.getElementById('list').innerHTML = list.map(s=>{
    const lock = s.type==='公办'
      ? '<span class="tag t-lock">锁片区·'+s.area+'</span>'
      : '<span class="tag t-cross">面向全区</span>';
    const nine = s.is9 ? '<span class="tag t-9">九年一贯</span>' : '';
    const typeTag = s.type==='公办'?'<span class="tag t-pub">公办</span>':'<span class="tag t-pri">民办</span>';
    const lv=latestScore(s);
    const sel = selected.has(state.tab+'|'+s.name);
    const jsName = s.name.replace(/'/g,"\\'");

    const cells = ys.map(y=>{
      const v=s.scores[y];
      return '<div class="yc"><div class="yl">'+y+'</div><div class="yv'+(v==null?' na':'')+'">'+(v!=null?v:'—')+'</div>'+(v!=null?barHTML(v):'')+'</div>';
    }).join('');

    // trend: latest vs previous available
    let trend='';
    const vals=ys.map(y=>s.scores[y]).filter(v=>v!=null);
    if(vals.length>=2){
      const d=vals[vals.length-1]-vals[vals.length-2];
      const cls=d>0?'trend-up':(d<0?'trend-down':'trend-flat');
      trend='<span class="'+cls+'">近一年 '+(d>0?'↑':(d<0?'↓':'→'))+Math.abs(d).toFixed(2)+'</span>';
    }

    return '<div class="sr"><div class="sr-top">'
      +'<label class="selck'+(sel?' on':'')+'" title="加入对比" onclick="toggleSelect(\''+state.tab+'\',\''+jsName+'\')">'+(sel?'✓':'')+'</label>'
      +'<div style="flex:1;min-width:150px"><span class="sr-name">'+s.name+'</span>'+typeTag+nine+'</div>'+compBadge(lv)+'</div>'
      +'<div class="years">'+cells+'</div>'
      +'<div class="sr-foot">'+lock+trend+'</div></div>';
  }).join('');
}

function findSchool(stage,name){ return DATA[stage].find(s=>s.name===name); }
function stageLabel(st){ return st==='primary'?'小一':'初一'; }

function toggleSelect(stage,name){
  const id=stage+'|'+name;
  if(selected.has(id)) selected.delete(id); else selected.set(id,{stage,name});
  render(); updateCompareBar();
}
function clearAll(){ selected.clear(); closeCompare(); render(); updateCompareBar(); }
function updateCompareBar(){
  const n=selected.size;
  const bar=document.getElementById('cbar');
  bar.classList.toggle('hidden', n<1);
  document.getElementById('cbar-n').textContent=n;
  document.getElementById('cbar-go').disabled = n<2;
}

function compYears(items){
  const set=new Set();
  items.forEach(({stage,ref})=> YEARS[stage].forEach(y=>{ if(ref.scores[y]!=null) set.add(y); }));
  return [...set].sort();
}
function compBadgeText(v){
  if(v==null) return '—';
  if(v>=100) return '极热门'; if(v>=90) return '热门'; if(v>=75) return '较热'; if(v>=66) return '一般'; return '门槛较低';
}

function chartSVG(items, years){
  const W=620,H=240,pl=38,pr=14,pt=14,pb=30;
  const iw=W-pl-pr, ih=H-pt-pb;
  let vals=[]; items.forEach(({ref})=>years.forEach(y=>{ if(ref.scores[y]!=null) vals.push(ref.scores[y]); }));
  if(vals.length===0) return '';
  let dmin=Math.min(...vals), dmax=Math.max(...vals);
  let yMin=Math.floor((dmin-2)/5)*5, yMax=Math.ceil((dmax+2)/5)*5;
  if(yMax===yMin) yMax=yMin+5;
  const xN=years.length;
  const xPos=i=> xN===1 ? pl+iw/2 : pl + iw*i/(xN-1);
  const yPos=v=> pt + ih*(1-(v-yMin)/(yMax-yMin));
  let svg='<svg viewBox="0 0 '+W+' '+H+'" width="100%" style="display:block">';
  // y gridlines
  const steps=4;
  for(let k=0;k<=steps;k++){
    const val=yMin+(yMax-yMin)*k/steps; const y=yPos(val);
    svg+='<line x1="'+pl+'" y1="'+y+'" x2="'+(W-pr)+'" y2="'+y+'" stroke="#e6dcc6" stroke-width="1"/>';
    svg+='<text x="'+(pl-6)+'" y="'+(y+3)+'" font-size="10" fill="#a09070" text-anchor="end">'+val.toFixed(0)+'</text>';
  }
  // x labels
  years.forEach((y,i)=>{ svg+='<text x="'+xPos(i)+'" y="'+(H-10)+'" font-size="10" fill="#8a7a5a" text-anchor="middle">'+y+'</text>'; });
  // lines
  items.forEach((it,idx)=>{
    const col=PALETTE[idx%PALETTE.length];
    const pts=[];
    years.forEach((y,i)=>{ const v=it.ref.scores[y]; if(v!=null) pts.push([xPos(i),yPos(v)]); });
    if(pts.length>1){
      let d='M'+pts[0][0]+' '+pts[0][1];
      for(let j=1;j<pts.length;j++) d+=' L'+pts[j][0]+' '+pts[j][1];
      svg+='<path d="'+d+'" fill="none" stroke="'+col+'" stroke-width="2.5" stroke-linejoin="round"/>';
    }
    pts.forEach(p=> svg+='<circle cx="'+p[0]+'" cy="'+p[1]+'" r="3.5" fill="'+col+'"/>');
  });
  svg+='</svg>';
  return svg;
}

function openCompare(){
  if(selected.size<2) return;
  const items=[...selected.values()].map(({stage,name})=>({stage,name,ref:findSchool(stage,name)})).filter(x=>x.ref);
  const years=compYears(items);

  // chart + legend
  let legend='<div class="chart-legend">'+items.map((it,i)=>'<span><span class="cdot" style="background:'+PALETTE[i%PALETTE.length]+'"></span>'+it.ref.name+'</span>').join('')+'</div>';
  let chart='<div class="chartwrap">'+chartSVG(items,years)+legend+'</div>';

  // table
  let head='<tr><th>指标</th>'+items.map((it,i)=>
    '<th><span class="cdot" style="background:'+PALETTE[i%PALETTE.length]+';display:inline-block;margin-right:5px"></span><span class="colname">'+it.ref.name+'</span><span class="cmp-stage">'+stageLabel(it.stage)+'</span><button class="rmv" title="移除" onclick="removeCmp(\''+it.stage+'\',\''+it.name.replace(/'/g,"\\'")+'\')">×</button></th>'
  ).join('')+'</tr>';

  const rows=[];
  rows.push(['类型', items.map(it=>it.ref.type)]);
  rows.push(['片区', items.map(it=>it.ref.area)]);
  rows.push(['招生模式', items.map(it=>it.ref.type==='公办'?'锁片区':'面向全区')]);
  rows.push(['九年一贯', items.map(it=>it.ref.is9?'是':'否')]);
  rows.push(['竞争度(最新)', items.map(it=>compBadgeText(latestOf(it)))]);

  let body=rows.map(([label,vals])=>
    '<tr><td>'+label+'</td>'+vals.map(v=>'<td>'+v+'</td>').join('')+'</tr>'
  ).join('');

  // year rows with best highlight
  body+=years.map(y=>{
    const vs=items.map(it=>it.ref.scores[y]);
    const present=vs.filter(v=>v!=null);
    const best=present.length?Math.max(...present):null;
    return '<tr><td>'+y+' 录取积分</td>'+vs.map(v=>{
      if(v==null) return '<td style="color:#cdc3ad">—</td>';
      return '<td class="'+(v===best?'best':'')+'">'+v+'</td>';
    }).join('')+'</tr>';
  }).join('');

  // trend row
  body+='<tr><td>近一年趋势</td>'+items.map(it=>{
    const ys=YEARS[it.stage].map(y=>it.ref.scores[y]).filter(v=>v!=null);
    if(ys.length<2) return '<td>—</td>';
    const d=ys[ys.length-1]-ys[ys.length-2];
    const c=d>0?'#c0392b':(d<0?'#27ae60':'#999');
    return '<td style="color:'+c+'">'+(d>0?'↑':(d<0?'↓':'→'))+Math.abs(d).toFixed(2)+'</td>';
  }).join('')+'</tr>';

  document.getElementById('compare-body').innerHTML =
    chart + '<div class="cmp-scroll"><table class="cmp"><thead>'+head+'</thead><tbody>'+body+'</tbody></table></div>';
  document.getElementById('overlay').classList.remove('hidden');
}
function latestOf(it){
  const ys=YEARS[it.stage];
  for(let i=ys.length-1;i>=0;i--){ if(it.ref.scores[ys[i]]!=null) return it.ref.scores[ys[i]]; }
  return null;
}
function removeCmp(stage,name){
  selected.delete(stage+'|'+name);
  render(); updateCompareBar();
  if(selected.size<2) closeCompare(); else openCompare();
}
function closeCompare(){ document.getElementById('overlay').classList.add('hidden'); }

// init
document.getElementById('stage-note').innerHTML = STAGE_NOTE['primary'];
renderAreaChips();
renderCompChips();
render();
updateCompareBar();
</script>
</body>
