// ====== 全书内容数据 ======
// 章节顺序（用于上一章/下一章导航）
const order = ['prologue', 'ch1', 'ch2', 'ch3', 'ch4', 'ch5', 'synthesis'];

// 第一章：思想家时间轴
const thinkers = [
  {
    name: '雅各比', year: '1799', tag: '提出概念',
    latin: 'F. H. Jacobi · 1743—1819',
    meta: '1799 · 致费希特的信',
    headline: '首次提出"虚无主义"概念',
    desc: '雅各比批判德国观念论：费希特的"绝对自我"否定了独立于意识的客观实在，使外部世界沦为思维的附属品。这种体系必然导向"虚无"——它否定了任何超越主观意识的真实存在，包括上帝、自然与他者。他同时批判斯宾诺莎的因果决定论：当一切被还原为冰冷的因果链条，真、善、美、爱便失去其超越性根基。',
    quote: '"我将这种观念论斥为虚无主义——它是一切哲学的毁灭者，将万物消解为纯粹思维形式。"'
  },
  {
    name: '叔本华', year: '1819', tag: '意志的虚无',
    latin: 'A. Schopenhauer · 1788—1860',
    meta: '《作为意志和表象的世界》',
    headline: '指出意志的虚无本质',
    desc: '叔本华揭示世界本质上是盲目意志的表象——意志不断追求满足却永无餍足，因此痛苦是生命常态，幸福只是痛苦的暂时缺席。这一悲观主义的存在论，为后续虚无主义思想提供了重要前提。',
    quote: '"人生在欲望与无聊之间摇摆——欲望未满足时痛苦，欲望满足后无聊。"'
  },
  {
    name: '陀思妥耶夫斯基', year: '1880', tag: '一切皆许可',
    latin: 'F. Dostoevsky · 1821—1881',
    meta: '《群魔》·《卡拉马佐夫兄弟》',
    headline: '若上帝不存在，是否一切皆许可？',
    desc: '通过《群魔》中基里洛夫的自杀论辩，揭示虚无主义者将自由意志推向极端后的毁灭性。在《卡拉马佐夫兄弟》中，伊凡的质疑——"若上帝存在，为何容许苦难？"——探讨信仰崩塌后的伦理真空。陀氏由此揭示了理性与信仰的深刻冲突。',
    quote: '"如上帝不存在，那么一切皆许可？" / "无人对苦难负责，这让我不能心安。"'
  },
  {
    name: '尼采', year: '1882', tag: '上帝死了',
    latin: 'F. Nietzsche · 1844—1900',
    meta: '《快乐的科学》',
    headline: '上帝死了 · 重估一切价值',
    desc: '尼采诊断西方文明的根本危机：最高价值的贬黜。柏拉图主义构造"理念世界"，基督教提供"彼岸天国"，当这些信仰崩溃便导致虚无主义。他区分消极虚无主义（绝望、冷漠）与积极虚无主义（重估价值、创造新价值），并以酒神精神、权力意志、超人、永恒轮回作为出路——身体是唯一的尺度。',
    quote: '"如其所是地存在的世界，他断定它不应当存在；对于如其应当是地存在的世界，他断定它并不实存。"'
  },
  {
    name: '韦伯', year: '1917', tag: '祛魅 · 铁笼',
    latin: 'Max Weber · 1864—1920',
    meta: '《学术作为一种志业》',
    headline: '世界的祛魅 · 工具理性的铁笼',
    desc: '韦伯指出现代世界因失去神圣根基，人们不再能依靠统一的宇宙秩序。取而代之的是"诸神之争"——各种不可通约的价值争夺人心。工具理性扩张：以最有效、最经济的方式达成目标，而不追问目标本身的价值。一切被量化，人被嵌入无法逃脱的系统规则，困于"铁笼"之中。',
    quote: '"世界失去了神圣的根基，取而代之的是各种不可通约的诸神在争夺人心。"'
  },
  {
    name: '海德格尔', year: '1927', tag: '存在的遗忘',
    latin: 'M. Heidegger · 1889—1976',
    meta: '《存在与时间》',
    headline: '虚无主义即"存在的遗忘"',
    desc: '海德格尔将西方哲学史看作虚无主义逐步展开的历史——从柏拉图理念论到基督教神学，再到笛卡尔的主体性哲学、启蒙理性，直至尼采的"上帝已死"，都是存在被技术化、工具化、对象化的过程。人类只关注"存在者"，遗忘了"存在"本身。出路在于：诗意地栖居、思的任务与返回开端。',
    quote: '"语言是存在的家。" / "诗意地栖居，重新唤醒人对存在的本真体验。"'
  },
  {
    name: '19-20世纪谱系', year: '20C', tag: '多重面相',
    latin: 'The Modern Genealogy',
    meta: '从马克思到齐泽克',
    headline: '虚无主义的多重面相',
    desc: '马克思：资本逻辑将一切价值还原为交换价值，资本主义即虚无主义。舍勒：价值秩序颠倒。萨特：自由就是虚无。梅洛-庞蒂：身体的遗忘。列维纳斯：同一性暴力、他者的排斥。福柯："人死了"。鲍德里亚：虚拟比真实更真实。泰勒：意义真空。齐泽克：宏大叙事背后的空洞。',
    quote: '根源总结：宇宙的冷漠、家园的丧失、价值秩序颠倒、存在的遗忘、文化异化、自我解构、存在的焦虑。'
  }
];

// 第二章：五种基本类型
const types = [
  { n: '01', name: '认识论虚无主义', latin: 'Epistemological', desc: '质疑人类获取"客观知识"的可能性，认为一切认知（科学、逻辑、理性）都是主观建构或语言游戏。真理是相对于特定个体或群体而存在的——尼采是其典型代表。' },
  { n: '02', name: '道德虚无主义', latin: 'Moral', desc: '否认存在客观的道德价值或善恶标准。道德规范并非源于绝对真理或神圣法则，而是由文化、习俗、权力或个体偏好任意建构。可分为超道德主义、道德主观主义和唯我论。' },
  { n: '03', name: '存在论虚无主义', latin: 'Existential', desc: '聚焦"人生意义的缺失"，认为宇宙本身无目的、无意图，人类存在是偶然的"荒诞"。若传统赋予的意义被证伪，个体陷入无意义感。代表：叔本华、托尔斯泰、加缪。' },
  { n: '04', name: '宇宙论虚无主义', latin: 'Cosmic', desc: '断言宇宙是无意义的，绝对意义上否定任何可理解或可知的结构，或相对意义上否认人所渴求的价值与存在意义。代表：叔本华、尼采、罗素。' },
  { n: '05', name: '政治与历史虚无主义', latin: 'Political & Historical', desc: '否定社会历史或政治价值，否定某一国家/民族的历史叙事，或认为所有政治制度本质上无优劣，仅为权力博弈的工具。常被用于意识形态批判。' }
];

// 第二章：十种当代表现
const manifests = [
  { n: 'i', title: '价值相对主义与道德冷漠', desc: '"什么都行、什么都不信、什么都不在乎"。对公共事务、环境危机、社会正义缺乏参与感和责任感。' },
  { n: 'ii', title: '极端怀疑主义', desc: '从怀疑一切滑向否定一切。为阴谋论、网络暴力、民粹主义、反智倾向、极端行为提供心理土壤。' },
  { n: 'iii', title: '技术与资本的合谋', desc: '人的价值被简化为数据、流量、消费力、生产力。消费主义成为虚无主义的温床，制造虚假需求填补精神空虚。' },
  { n: 'iv', title: '政治与文化虚无', desc: '对国家、民族、进步等宏大叙事持嘲讽态度。社会共识难以形成，公共讨论碎片化，文化沦为娱乐消费品。' },
  { n: 'v', title: '历史虚无主义', desc: '质疑历史客观性，认为历史只是不同叙事之间的竞争，对民族传统、英雄人物的否定或戏谑化。' },
  { n: 'vi', title: '当代犬儒主义', desc: '看透一切的讽刺与冷漠。情感冷漠、疏离、缺乏信任，常以讽刺消解严肃。愤世嫉俗，不相信改变的可能。' },
  { n: 'vii', title: '功利主义与有用崇拜', desc: '"唯金钱论""唯成功论"。当成功成为唯一标准，"意义""幸福""内在价值"被边缘化，人被工具化。' },
  { n: 'viii', title: '文化工业与娱乐至死', desc: '深度思考、严肃艺术被边缘化。沉浸短视频、快餐文化、虚拟社交，看似充实，实则更孤独、焦虑、空虚。' },
  { n: 'ix', title: '关系破裂 · 个体原子化', desc: '社会成为内卷的拼搏战场。失去稳定联结的同时也失去道德口碑，造成社会信任危机。' },
  { n: 'x', title: '生命意义虚无 · 心理危机', desc: '"成就焦虑、意义缺失、自我怀疑"的群体心理——躺平、摆烂、佛系。存在性抑郁加剧。' }
];

// 第三章：四大社会根源
const roots = [
  { icon: 'i', title: '工业革命与资本主义', items: ['劳动异化', '共同体瓦解', '市场逻辑统摄一切', '价值还原为交换价值', '商品拜物教'] },
  { icon: 'ii', title: '政治结构', items: ['代议制的旁观化', '政治冷漠', '民粹主义兴起', '科层化与去政治化', '治理与合法性危机'] },
  { icon: 'iii', title: '城市化与社会变迁', items: ['"无根"状态', '关系商品化', '三座大山：房·教·医', '阶层固化', '权力-资本-技术合谋'] },
  { icon: 'iv', title: '个体生存层面', items: ['消费奴役', '关系工具化', '内卷·996·KPI', '算法与数字垄断', '"末人"文明'] }
];

// 第四章：机制流 / 数据
const mech = [
  { n: 'MECH · 1', title: '意义系统的崩塌' },
  { n: 'MECH · 2', title: '认知扭曲的强化' },
  { n: 'MECH · 3', title: '神经生物学受损' },
  { n: 'MECH · 4', title: '防御机制失效' }
];
const stats = [
  { num: '10', unit: '%', label: '全球成年人精神疾病估算 (WHO)' },
  { num: '6.8', unit: '%', label: '中国精神疾病率 · 柳叶刀-区域健康 2024' },
  { num: '+', unit: '', label: 'PGD 程度与虚无主义信念正相关 (2025)' }
];

// 第五章：三层出路 / 自我演化
const paths = [
  {
    roman: 'I', title: '自我重构', latin: 'Reconstruction of the Self', root: false,
    items: ['放弃绝对真理，拥抱常识与共识', '接纳生命的有限性', '视角性真理观', '回归自然与真实生活', '构建多维社会关系', '承担伦理-政治责任', '尊重肉体，热爱生活']
  },
  {
    roman: 'II', title: '文化改造', latin: 'Cultural Transformation', root: false,
    items: ['突破哲学三角：世界·意识·语言', '从唯我论走向经验世界', '进入伦理-政治生活', '批判符号暴力与逻辑垄断', '升级身心-世界的解释范式', '关系本体论的兴起']
  },
  {
    roman: 'III', title: '社会改造', latin: 'Social Reform · The Root Solution', root: true,
    items: ['政治体制与法律制度的变革', '促进市场经济转型，鼓励高质量创新', '鼓励社区自治，发展民间互助', '改进教育制度', '培育公共理性与对话文化', '形成对资本-技术的制衡机制', '构建多元价值评价体系', '保障基本权利与尊严']
  }
];
const evolution = [
  { step: 'STAGE I', title: '建构', desc: '在传统、宗教、家庭中获得初始的自我' },
  { step: 'STAGE II', title: '膨胀', desc: '启蒙之后，自我替代上帝，成为最后的法官' },
  { step: 'STAGE III', title: '解构', desc: '意识、主体、人均被祛魅，"人死了"' },
  { step: 'STAGE IV', title: '重构', desc: '自我是社会的结果——通过参与社会改造来实现自我' }
];

// 第六章：意义谱系
const lineage = [
  { icon: 'μ', title: '追问命运', era: 'MYTH', desc: 'Me · Maat · Moira 神话中不可捉摸的命运' },
  { icon: 'λ', title: '柏拉图主义', era: 'REASON', desc: '理念、本质、形而上学的世界——以理性把握真实' },
  { icon: '†', title: '基督教精神', era: 'FAITH', desc: '救赎、恩典、彼岸天国、上帝的依托' },
  { icon: 'I', title: '自我的演化', era: 'SELF', desc: '建构→膨胀→解构→重构，自我替代上帝又被解构' },
  { icon: '∞', title: '社会变革', era: 'PRAXIS', desc: '投身世界，热爱生活，参与伦理-政治-文化的改造升级' }
];

// ====== 章节总表 ======
const chapters = {
  prologue: {
    roman: '序', romanLatin: 'PROLOGUE', navTitle: '前言',
    title: '前言', subtitle: '哲学的一体两面',
    layout: 'prologue',
    intro: '哲学就是哲学史，哲学史就是寻找确定性（本源、开端、本质、终极因、真理）与克服虚无主义的历史。寻找确定性与克服虚无主义，是哲学的一体两面。',
    quote: '古代之所以未突出虚无主义问题，因为传统生活、宗教、形而上学占主导地位——大地稳定可靠，血缘绵延不绝，宗教提供终极价值，形而上学保有第一因。而现代人，正是在这一切被祛魅、被怀疑、被解构之后，才直面"无"。',
    pillars: [
      { k: '大地', v: '农耕社会依赖可靠的大地，稳定的社群关系、风俗习惯，神话史诗传统。' },
      { k: '血缘', v: '亲情、宗族、祖先崇拜，是与自然和谐相处的整体性世界解释体系。' },
      { k: '宗教生活', v: '道、梵、佛性、上帝是终极真理，奠定道德基础与社会价值秩序。' },
      { k: '形而上学', v: '终极实在、第一因、本质、理念，可通过抽象思辨逐步逼近。' }
    ]
  },
  ch1: {
    roman: '壹', romanLatin: 'CAPUT I', navTitle: '思想批判',
    title: '虚无主义批判谱系', subtitle: 'A Genealogy of Nihilism · 思想批判',
    layout: 'ch1',
    intro: '虚无主义（Nihilism）源于拉丁语 "nihil"，意为"无"。从怀疑论、相对论一路演进，雅各比首次将其作为概念提出（1799），尼采使其成为哲学核心，海德格尔将之诊断为"存在的遗忘"。点击任一姓名，查看其核心诊断。',
    thinkers: thinkers
  },
  ch2: {
    roman: '贰', romanLatin: 'CAPUT II', navTitle: '类型表现',
    title: '虚无主义的类型与表现', subtitle: 'Typology & Phenomenology · 症状学',
    layout: 'ch2',
    intro: '当代哲学将虚无主义划分为五种基本类型，覆盖认识、道德、存在、宇宙与政治。在此理论分类之外，它在当下生活中以十种具体形态显现。切换标签查看两个层面。',
    types: types,
    manifests: manifests
  },
  ch3: {
    roman: '叁', romanLatin: 'CAPUT III', navTitle: '社会根源',
    title: '虚无主义的社会根源', subtitle: 'Social Critique · 病因学',
    layout: 'ch3',
    intro: '关键转折：虚无主义不是个人想不开，而是由现代社会结构、文化氛围与权力关系共同制造的精神状态。四大根源彼此交织。',
    roots: roots,
    ironcageTitle: '韦伯的铁笼 · 工具理性的胜利',
    ironcageLatin: 'Stahlhartes Gehäuse · The Iron Cage',
    ironcageBody: '人被视作"劳动力""消费者""生产单元"；时间被换算成金钱，生命被衡量为效率。个体的价值不再取决于其作为人的尊严、自由与内在价值，而是其能创造多少经济价值。最终，人被困在韦伯所说的"铁笼"中——一个由理性、科层制、市场逻辑主宰，但缺少意义与自由的牢笼。'
  },
  ch4: {
    roman: '肆', romanLatin: 'CAPUT IV', navTitle: '精神疾病',
    title: '虚无主义与精神疾病', subtitle: 'The Pathology of Meaninglessness · 临床观察',
    layout: 'ch4',
    intro: '虚无主义思维并非中性的哲学姿态——它通过多个机制与抑郁、焦虑、自杀意念发生临床关联。两者还构成恶性循环：虚无加剧症状，症状强化虚无。',
    mech: mech,
    cycle: '虚无主义思维 → 抑郁情绪 → 认知功能受损 → 更深的虚无感',
    stats: stats,
    note: '关键诊断：克服虚无主义不能仅靠个人心理调适或哲学思辨，而必须从改造塑造人的社会环境入手。心理治疗只能自救，社会改造却可以造福亿万人——这一判断直接通往第五章。'
  },
  ch5: {
    roman: '伍', romanLatin: 'CAPUT V', navTitle: '克服出路',
    title: '克服虚无主义的出路', subtitle: 'Three Paths Out · 三层处方',
    layout: 'ch5',
    intro: '虚无主义并非终点，而可能是一次重新发问、重新创造与重新生活的契机。作者提出三层并行的出路：自我重构、文化改造、社会改造。前两者可以自救，唯有社会改造是根本出路。',
    pathsIntro: '虚无主义是一种清醒剂，它逼迫我们反思习以为常的信念。若能正视虚无、不逃避、不沉溺，而以此为契机重建价值，就能在"空无"中寻找"有"，在"怀疑"中建立"信念"，在"解构"之后走向"重构"。',
    paths: paths,
    evolution: evolution
  },
  synthesis: {
    roman: '陆', romanLatin: 'CAPUT VI', navTitle: '总结',
    title: '从命运到社会改造', subtitle: 'A Lineage of Meaning-Making · 视觉化总结',
    layout: 'synthesis',
    intro: '人类寻找意义的五个阶段——从神话中的命运，到柏拉图的理性，到基督教的信仰，到现代自我的演化，最终落在社会变革的实践。',
    lineage: lineage,
    codaQuote: '哲学家们只是用不同的方式解释世界，而问题在于改变世界。',
    codaCite: '— KARL MARX · 第十一条提纲 —',
    codaSub: '"点滴之水，汇聚江海"'
  }
};

function getChapter(id) {
  const key = chapters[id] ? id : 'prologue';
  return Object.assign({ id: key }, chapters[key]);
}

function getNav(id) {
  const i = order.indexOf(id);
  const at = i < 0 ? 0 : i;
  return {
    prev: at > 0 ? { id: order[at - 1], title: chapters[order[at - 1]].navTitle } : null,
    next: at < order.length - 1 ? { id: order[at + 1], title: chapters[order[at + 1]].navTitle } : null
  };
}

// 首页目录（脉络）数据
const toc = order.map(function (id) {
  const c = chapters[id];
  return { id: id, roman: c.roman, romanLatin: c.romanLatin, title: c.navTitle, subtitle: c.subtitle };
});

module.exports = { chapters, order, toc, getChapter, getNav };

