  // ====================================================
  onLoad() {
    const cur = this.data.thinkers.find(t => t.id === this.data.currentThinkerId);
    this.setData({ currentThinker: cur });
    this._navMap = this.data.navItems.map(n => n.id);
  },

  onReady() {
    this._computeSectionTops();
    // 字体/排版可能在首帧后微调，延迟再算一次
    setTimeout(() => this._computeSectionTops(), 600);
  },

  // 计算每个章节的绝对滚动偏移量
  _computeSectionTops() {
    const query = wx.createSelectorQuery();
    query.selectAll('.js-section').boundingClientRect();
    query.selectViewport().scrollOffset();
    query.exec(res => {
      const rects = res[0] || [];
      const scrollTop = (res[1] && res[1].scrollTop) || 0;
      const tops = {};
      rects.forEach(r => {
        if (r.id) tops[r.id] = Math.round(r.top + scrollTop);
      });
      this._sectionTops = tops;
      this.setData({ sectionTops: tops });
    });
  },

  // 滚动时高亮当前章节
  onPageScroll(e) {
    const tops = this._sectionTops;
    if (!tops || !this._navMap) return;
    const y = e.scrollTop + 120;
    let current = this._navMap[0];
    for (const id of this._navMap) {
      if (tops[id] !== undefined && tops[id] <= y) current = id;
    }
    if (current !== this.data.activeNav) {
      this.setData({ activeNav: current, navScrollId: 'nav-' + current });
    }
  },

  // 点击导航 / 节点 / 流程图 → 跳转到对应章节
  jumpTo(e) {
    const target = e.currentTarget.dataset.target;
    if (!target) return;
    this.setData({ navScrollId: 'nav-' + target });
    wx.pageScrollTo({ selector: '#' + target, duration: 420, offsetTop: 0 });
  },

  // 选择思想家
  selectThinker(e) {
    const id = e.currentTarget.dataset.id;
    const cur = this.data.thinkers.find(t => t.id === id);
    if (cur) this.setData({ currentThinkerId: id, currentThinker: cur });
  },

  // 切换类型 / 表现 标签
  switchTab(e) {
    const tab = e.currentTarget.dataset.tab;
    if (tab !== this.data.activeTab) this.setData({ activeTab: tab });
  },

  // 返回顶部
  backToTop() {
    wx.pageScrollTo({ scrollTop: 0, duration: 420 });
  },

  // 分享
  onShareAppMessage() {
    return {
      title: '探索生命的意义与价值 · 从虚无中寻找希望与力量',
      path: '/pages/index/index'
    };
  },
  onShareTimeline() {
    return { title: '探索生命的意义与价值 · 从虚无中寻找希望与力量' };
  }
});

