files.content:
.page {
  width: 100%;
  height: 100vh;
  background: var(--paper);
}

/* ===== Hero ===== */
.hero {
  background: radial-gradient(circle at 50% 36%, #1f1a16 0%, #14110f 60%, #0d0b09 100%);
  padding: 90rpx 56rpx 80rpx;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
}

.hero-figure {
  position: relative;
  width: 360rpx;
  height: 360rpx;
  margin-bottom: 56rpx;
  display: flex;
  align-items: center;
  justify-content: center;
}
.ring {
  position: absolute;
  border-radius: 50%;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
}
.ring-outer {
  width: 360rpx;
  height: 360rpx;
  border: 1rpx dashed rgba(184, 135, 70, 0.4);
}
.ring-gold {
  width: 268rpx;
  height: 268rpx;
  border: 1rpx solid rgba(184, 135, 70, 0.55);
  box-shadow: 0 0 40rpx rgba(184, 135, 70, 0.15);
}
.void-core {
  position: relative;
  width: 200rpx;
  height: 200rpx;
  border-radius: 50%;
  background: radial-gradient(circle at 50% 50%, #050403 0%, #100d0b 70%);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  box-shadow: inset 0 0 50rpx rgba(0, 0, 0, 0.9);
}
.light-center {
  position: absolute;
  width: 70rpx;
  height: 70rpx;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(212, 165, 116, 0.85) 0%, rgba(184, 135, 70, 0.12) 70%, transparent 100%);
  top: 36rpx;
}
.void-label {
  font-size: 40rpx;
  color: var(--gold-bright);
  letter-spacing: 8rpx;
  margin-top: 34rpx;
  text-indent: 8rpx;
}
.void-latin {
  font-size: 18rpx;
  font-style: italic;
  letter-spacing: 4rpx;
  color: rgba(184, 135, 70, 0.6);
  margin-top: 6rpx;
}

.hero-eyebrow {
  font-style: italic;
  letter-spacing: 4rpx;
  color: var(--gold);
  font-size: 24rpx;
  margin-bottom: 28rpx;
}
.hero-title {
  font-size: 76rpx;
  line-height: 1.25;
  color: #f4ede0;
  font-weight: 600;
  letter-spacing: 4rpx;
}
.hero-title .hl { color: var(--gold-bright); }
.hero-sub {
  font-style: italic;
  font-size: 26rpx;
  color: rgba(244, 237, 224, 0.5);
  letter-spacing: 2rpx;
  margin-top: 18rpx;
}
.hero-lede {
  font-size: 28rpx;
  line-height: 1.85;
  color: rgba(244, 237, 224, 0.78);
  margin-top: 40rpx;
  max-width: 600rpx;
}
.hero-lede .em { color: var(--gold-bright); }
.hero-meta {
  margin-top: 46rpx;
  font-size: 24rpx;
  color: rgba(244, 237, 224, 0.55);
  letter-spacing: 2rpx;
}
.hero-meta .dot { margin: 0 16rpx; color: var(--gold); }
.hero-hint {
  margin-top: 48rpx;
  font-size: 22rpx;
  font-style: italic;
  letter-spacing: 3rpx;
  color: rgba(184, 135, 70, 0.7);
}

/* ===== 核心命题 ===== */
.thesis {
  background: var(--paper-warm);
  border-bottom: 1rpx solid var(--line);
  padding: 72rpx 56rpx 64rpx;
  text-align: center;
}
.thesis-mark {
  font-size: 90rpx;
  color: var(--gold);
  line-height: 0.5;
  height: 60rpx;
}
.thesis-body {
  font-size: 38rpx;
  line-height: 1.7;
  color: var(--ink);
  font-weight: 500;
}
.thesis-hl {
  color: var(--crimson);
  border-bottom: 3rpx solid rgba(184, 135, 70, 0.5);
  padding-bottom: 2rpx;
}
.thesis-note {
  font-size: 26rpx;
  line-height: 1.8;
  color: var(--slate);
  margin-top: 32rpx;
  max-width: 600rpx;
  margin-left: auto;
  margin-right: auto;
}

/* ===== 目录头 ===== */
.toc-head {
  padding: 72rpx 56rpx 16rpx;
}
.toc-title {
  font-size: 56rpx;
  color: var(--ink);
  font-weight: 600;
  letter-spacing: 2rpx;
}
.toc-desc {
  font-size: 26rpx;
  color: var(--slate);
  margin-top: 18rpx;
  line-height: 1.7;
}

/* ===== 目录列表 ===== */
.toc-list {
  padding: 32rpx 40rpx 0;
}
.toc-item {
  display: flex;
  align-items: center;
  padding: 36rpx 28rpx;
  background: #fbf6ec;
  border: 1rpx solid var(--line);
  border-radius: 8rpx;
  margin-bottom: 22rpx;
  position: relative;
  overflow: hidden;
}
.toc-item::before {
  content: "";
  position: absolute;
  left: 0; top: 0; bottom: 0;
  width: 6rpx;
  background: var(--gold);
}
.toc-roman {
  width: 120rpx;
  display: flex;
  flex-direction: column;
  align-items: center;
  flex-shrink: 0;
}
.roman-cn {
  font-size: 52rpx;
  color: var(--crimson);
  font-weight: 600;
  line-height: 1;
}
.roman-phase {
  font-size: 16rpx;
  font-style: italic;
  letter-spacing: 2rpx;
  color: var(--gold-deep);
  margin-top: 10rpx;
}
.toc-main {
  flex: 1;
  padding: 0 16rpx;
}
.toc-item-title {
  font-size: 34rpx;
  color: var(--ink);
  font-weight: 600;
  letter-spacing: 1rpx;
}
.toc-item-sub {
  font-size: 24rpx;
  color: var(--slate);
  margin-top: 8rpx;
}
.toc-arrow {
  font-size: 36rpx;
  color: var(--gold);
  flex-shrink: 0;
}

/* ===== 页脚 ===== */
.footer {
  margin-top: 40rpx;
  padding: 80rpx 56rpx 40rpx;
  background: radial-gradient(circle at 50% 0%, #1f1a16 0%, #14110f 100%);
  text-align: center;
}
.footer-line {
  width: 60rpx;
  height: 2rpx;
  background: var(--gold);
  margin: 0 auto 40rpx;
}
.footer-quote {
  font-size: 36rpx;
  color: var(--gold-bright);
  letter-spacing: 4rpx;
  margin-bottom: 28rpx;
}
.footer-cite {
  font-size: 28rpx;
  line-height: 1.8;
  color: rgba(244, 237, 224, 0.8);
  max-width: 580rpx;
  margin: 0 auto;
}
.footer-mark {
  font-size: 22rpx;
  font-style: italic;
  letter-spacing: 2rpx;
  color: rgba(244, 237, 224, 0.45);
  margin-top: 36rpx;
}
.bottom-safe {
  height: env(safe-area-inset-bottom);
  background: #14110f;
}

versions.content:
/* ============ 固定章节导航 ============ */
.topnav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  background: rgba(244, 237, 224, 0.96);
  border-bottom: 1rpx solid var(--line);
}
.topnav-scroll { width: 100%; white-space: nowrap; }
.topnav-inner { display: inline-flex; align-items: center; padding: 22rpx 28rpx; }
.topnav-item {
  display: inline-block;
  font-size: 26rpx;
  letter-spacing: 3rpx;
  color: var(--ink-soft);
  padding: 6rpx 22rpx;
  position: relative;
}
.topnav-item.active { color: var(--gold-deep); font-weight: 600; }
.topnav-item.active::after {
  content: "";
  position: absolute;
  left: 22rpx;
  right: 22rpx;
  bottom: -2rpx;
  height: 2rpx;
  background: var(--gold);
}

.page {
  padding-top: 92rpx;
  position: relative;
  overflow: hidden;
  background-image:
    radial-gradient(circle at 12% 8%, rgba(184, 135, 70, 0.07) 0%, transparent 38%),
    radial-gradient(circle at 88% 92%, rgba(107, 43, 43, 0.05) 0%, transparent 38%);
}

/* ============ HERO ============ */
.hero { padding: 60rpx 48rpx 80rpx; }
.eyebrow {
  font-size: 26rpx;
  color: var(--gold-deep);
  letter-spacing: 4rpx;
  margin-bottom: 28rpx;
}
.hero-title {
  font-weight: 900;
  font-size: 76rpx;
  line-height: 1.12;
  color: var(--ink);
  margin-bottom: 22rpx;
}
.hero-title .accent { color: var(--crimson); font-style: italic; }
.hero-sub {
  font-size: 30rpx;
  color: var(--slate);
  letter-spacing: 2rpx;
  margin-bottom: 50rpx;
}

/* 中央图示 */
.diagram {
  position: relative;
  width: 600rpx;
  height: 600rpx;
  margin: 20rpx auto 40rpx;
}
.ring-outer {
  position: absolute;
  top: 20rpx; left: 20rpx;
  width: 560rpx; height: 560rpx;
  border: 1rpx dashed rgba(184, 135, 70, 0.5);
  border-radius: 50%;
}
.ring-node {
  position: absolute;
  top: 50rpx; left: 50rpx;
  width: 500rpx; height: 500rpx;
  border: 1rpx solid rgba(184, 135, 70, 0.55);
  border-radius: 50%;
}
.void {
  position: absolute;
  top: 180rpx; left: 180rpx;
  width: 240rpx; height: 240rpx;
  border-radius: 50%;
  border: 1rpx solid rgba(184, 135, 70, 0.4);
  background: radial-gradient(circle at 50% 50%, #14110f 0%, #14110f 58%, rgba(20,17,15,0.0) 100%);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  box-shadow: 0 0 60rpx rgba(212, 165, 116, 0.25);
}
.void-cn { color: var(--paper); font-size: 44rpx; font-weight: 600; }
.void-latin { color: var(--gold-bright); font-size: 22rpx; letter-spacing: 4rpx; margin-top: 6rpx; }

.dnode {
  position: absolute;
  width: 96rpx; height: 96rpx;
  border-radius: 50%;
  background: var(--paper);
  border: 2rpx solid var(--gold);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  z-index: 3;
}
.dnode-num { font-size: 22rpx; color: var(--ink); }
.dnode-word { font-size: 20rpx; color: var(--gold-deep); margin-top: 2rpx; }
.dnode-hover { transform: scale(1.08); background: var(--ink); }
.dnode-hover .dnode-num { color: var(--gold-bright); }
.dnode-hover .dnode-word { color: var(--paper-warm); }
.dnode.crimson { background: var(--crimson); border-color: var(--gold-bright); width: 108rpx; height: 108rpx; }
.dnode.crimson .dnode-num { color: var(--gold-bright); }
.dnode.crimson .dnode-word { color: var(--paper); font-weight: 600; }

.n-top    { left: 252rpx; top: 2rpx; }
.n-tr     { left: 469rpx; top: 127rpx; }
.n-br     { left: 469rpx; top: 377rpx; }
.n-bottom { left: 252rpx; top: 502rpx; }
.n-bl     { left: 36rpx;  top: 377rpx; }
.n-tl     { left: 30rpx;  top: 121rpx; }

.hero-lede {
  font-size: 30rpx;
  line-height: 1.85;
  color: var(--ink-soft);
  border-left: 3rpx solid var(--gold);
  padding-left: 28rpx;
  margin: 20rpx 0 44rpx;
}
.hl-crimson { color: var(--crimson); font-weight: 600; }
.hl { color: var(--gold-deep); font-weight: 600; }

.hero-meta { display: flex; flex-wrap: wrap; gap: 36rpx; }
.hm { display: flex; flex-direction: column; }
.hm-k { font-size: 20rpx; letter-spacing: 3rpx; color: var(--slate); }
.hm-v { font-size: 28rpx; font-weight: 500; color: var(--ink); margin-top: 6rpx; }

.scroll-hint {
  margin-top: 56rpx;
  text-align: center;
  font-size: 22rpx;
  letter-spacing: 3rpx;
  color: var(--slate);
}

/* ============ 通用 section 标签 ============ */
.section-label {
  font-size: 24rpx;
  letter-spacing: 6rpx;
  color: var(--gold-deep);
  margin-bottom: 24rpx;
  text-transform: uppercase;
}
.section-label.gold { color: var(--gold-bright); }
.chapter-eyebrow {
  font-size: 24rpx;
  letter-spacing: 6rpx;
  color: var(--gold-deep);
  margin-bottom: 18rpx;
}

/* ============ 前言 ============ */
.thesis {
  background: var(--ink);
  color: var(--paper);
  padding: 90rpx 48rpx;
}
.thesis-h {
  font-weight: 700;
  font-size: 52rpx;
  line-height: 1.35;
  margin-bottom: 44rpx;
}
.break { display: block; height: 0; }
.thesis-quote {
  font-size: 32rpx;
  font-weight: 300;
  line-height: 1.9;
  font-style: italic;
  color: var(--paper-warm);
  border-left: 2rpx solid var(--gold);
  padding-left: 30rpx;
}
.thesis-author {
  margin-top: 32rpx;
  margin-left: 30rpx;
  font-size: 26rpx;
  color: var(--gold-bright);
  letter-spacing: 2rpx;
}

/* ============ 脉络 ============ */
.journey { padding: 90rpx 48rpx; }
.journey-h {
  font-weight: 700;
  font-size: 56rpx;
  line-height: 1.2;
  color: var(--ink);
  margin-bottom: 24rpx;
}
.journey-intro {
  font-size: 28rpx;
  line-height: 1.85;
  color: var(--ink-soft);
  margin-bottom: 50rpx;
}
.flow-list { display: flex; flex-direction: column; gap: 0; }
.flow-card {
  display: flex;
  align-items: center;
  gap: 28rpx;
  padding: 32rpx 8rpx;
  border-bottom: 1rpx solid var(--line);
}
.flow-card-hover { background: var(--paper-warm); }
.flow-num {
  flex-shrink: 0;
  width: 84rpx; height: 84rpx;
  border-radius: 50%;
  border: 1.5rpx solid var(--line-strong);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 34rpx;
  color: var(--ink);
  background: var(--paper);
}
.flow-body { flex: 1; }
.flow-stage { font-size: 20rpx; letter-spacing: 3rpx; color: var(--gold-deep); margin-bottom: 4rpx; }
.flow-title { font-size: 32rpx; font-weight: 600; color: var(--ink); margin-bottom: 2rpx; }
.flow-desc { font-size: 24rpx; color: var(--slate); }
.flow-arrow { font-size: 40rpx; color: var(--gold); flex-shrink: 0; }

/* ============ 章节通用 ============ */
.chapter { padding: 80rpx 48rpx; border-top: 1rpx solid var(--line); position: relative; }
.crumbs {
  font-size: 24rpx;
  color: var(--gold-deep);
  letter-spacing: 2rpx;
  margin-bottom: 30rpx;
}
.chapter-num {
  font-size: 120rpx;
  font-weight: 300;
  color: var(--gold);
  line-height: 1;
  margin-bottom: 8rpx;
}
.cn-label {
  display: block;
  font-size: 22rpx;
  letter-spacing: 5rpx;
  color: var(--gold-deep);
  margin-top: 8rpx;
}
.chapter-h {
  font-weight: 700;
  font-size: 50rpx;
  line-height: 1.25;
  color: var(--ink);
  margin: 18rpx 0 14rpx;
}
.chapter-sub {
  font-size: 28rpx;
  color: var(--gold-deep);
  margin-bottom: 24rpx;
  letter-spacing: 1rpx;
}
.chapter-intro {
  font-size: 28rpx;
  line-height: 1.85;
  color: var(--ink-soft);
  margin-bottom: 40rpx;
}

/* ============ 思想家时间轴 ============ */
.thinker-rail { width: 100%; white-space: nowrap; margin-bottom: 40rpx; }
.thinker-rail-inner {
  display: inline-flex;
  padding: 10rpx 0 20rpx;
  border-bottom: 2rpx solid var(--paper-deep);
}
.thinker {
  display: inline-flex;
  flex-direction: column;
  align-items: center;
  width: 220rpx;
  padding: 8rpx 12rpx;
  white-space: normal;
  text-align: center;
}
.thinker-year { font-size: 24rpx; color: var(--gold-deep); letter-spacing: 1rpx; }
.thinker-dot {
  width: 22rpx; height: 22rpx;
  border-radius: 50%;
  background: var(--paper);
  border: 3rpx solid var(--gold);
  margin: 14rpx 0;
}
.thinker.active .thinker-dot {
  background: var(--ink);
  transform: scale(1.3);
  box-shadow: 0 0 0 10rpx rgba(184, 135, 70, 0.16);
}
.thinker-name { font-size: 28rpx; font-weight: 600; color: var(--ink); margin-bottom: 6rpx; line-height: 1.3; }
.thinker.active .thinker-name { color: var(--crimson); }
.thinker-label { font-size: 22rpx; color: var(--slate); line-height: 1.4; }

.thinker-detail {
  padding: 44rpx 40rpx;
  background: linear-gradient(135deg, rgba(184, 135, 70, 0.06), rgba(244,237,224,0));
  border: 1rpx solid var(--line);
  border-left: 5rpx solid var(--gold);
}
.td-who { padding-bottom: 28rpx; border-bottom: 1rpx solid var(--line); margin-bottom: 28rpx; }
.td-name { font-size: 44rpx; font-weight: 700; color: var(--ink); margin-bottom: 8rpx; }
.td-latin { font-size: 26rpx; color: var(--gold-deep); margin-bottom: 14rpx; }
.td-meta { font-size: 22rpx; color: var(--slate); letter-spacing: 1rpx; }
.td-h { font-size: 22rpx; letter-spacing: 4rpx; color: var(--gold-deep); margin-bottom: 16rpx; }
.td-idea {
  font-size: 36rpx;
  font-weight: 500;
  font-style: italic;
  line-height: 1.5;
  color: var(--ink);
  margin-bottom: 24rpx;
}
.td-desc { font-size: 27rpx; line-height: 1.9; color: var(--ink-soft); }
.td-quote {
  margin-top: 26rpx;
  padding: 22rpx 26rpx;
  background: rgba(20, 17, 15, 0.04);
  border-left: 3rpx solid var(--crimson);
  font-style: italic;
  font-size: 25rpx;
  line-height: 1.75;
  color: var(--ink-soft);
}

/* ============ 标签 / 类型 / 表现 ============ */
.tabs { display: flex; gap: 6rpx; margin-bottom: 36rpx; border-bottom: 1rpx solid var(--line); }
.tab {
  flex: 1;
  text-align: center;
  padding: 24rpx 12rpx;
  font-size: 28rpx;
  color: var(--slate);
  border-bottom: 3rpx solid transparent;
}
.tab.active { color: var(--ink); font-weight: 600; border-bottom-color: var(--gold); }

.types-list { display: flex; flex-direction: column; gap: 24rpx; }
.type-card {
  position: relative;
  padding: 36rpx 34rpx;
  background: var(--paper-warm);
  border: 1rpx solid var(--line);
  border-top: 4rpx solid var(--gold);
  overflow: hidden;
}
.type-card-hover { background: var(--paper-deep); }
.type-num {
  position: absolute;
  top: 18rpx; right: 28rpx;
  font-size: 80rpx;
  color: var(--gold);
  opacity: 0.35;
  line-height: 1;
}
.type-name { font-size: 34rpx; font-weight: 600; color: var(--ink); margin-bottom: 6rpx; padding-right: 90rpx; }
.type-latin { font-size: 25rpx; color: var(--gold-deep); margin-bottom: 18rpx; }
.type-desc { font-size: 27rpx; line-height: 1.8; color: var(--ink-soft); }

.manifest-list {
  display: flex;
  flex-direction: column;
  border-top: 1rpx solid var(--line);
}
.manifest-item {
  display: flex;
  gap: 26rpx;
  padding: 34rpx 8rpx;
  border-bottom: 1rpx solid var(--line);
}
.manifest-num { flex-shrink: 0; width: 60rpx; font-size: 48rpx; color: var(--gold); line-height: 1.1; }
.manifest-name { font-size: 30rpx; font-weight: 600; color: var(--ink); margin-bottom: 8rpx; }
.manifest-desc { font-size: 26rpx; line-height: 1.75; color: var(--ink-soft); }

/* ============ 社会根源 ============ */
.roots-list { display: flex; flex-direction: column; gap: 24rpx; }
.root-card {
  padding: 36rpx 34rpx;
  background: var(--paper-warm);
  border: 1rpx solid var(--line);
}
.root-card-hover { background: var(--ink); }
.root-card-hover .root-name { color: var(--gold-bright); }
.root-card-hover .root-icon { color: var(--gold-bright); }
.root-card-hover .root-li { color: var(--paper-warm); }
.root-icon { font-size: 52rpx; color: var(--gold-deep); line-height: 1; margin-bottom: 16rpx; }
.root-name { font-size: 34rpx; font-weight: 600; color: var(--ink); margin-bottom: 18rpx; }
.root-items { display: flex; flex-direction: column; }
.root-li {
  font-size: 26rpx;
  color: var(--slate);
  line-height: 1.7;
  padding: 8rpx 0;
  border-bottom: 1rpx dashed var(--line);
}
.root-li:last-child { border-bottom: none; }

.iron-cage {
  margin-top: 50rpx;
  padding: 56rpx 44rpx;
  background: var(--ink);
  color: var(--paper);
}
.ic-h { font-size: 40rpx; font-weight: 700; color: var(--paper); margin-bottom: 8rpx; }
.ic-latin { font-size: 26rpx; color: var(--gold-bright); letter-spacing: 2rpx; margin-bottom: 28rpx; }
.ic-p { font-size: 29rpx; line-height: 1.9; color: var(--paper-warm); }
.ic-hl { color: var(--gold-bright); font-weight: 600; }

/* ============ 精神疾病 ============ */
.mech-list { display: flex; flex-direction: column; align-items: stretch; margin-bottom: 36rpx; }
.mech-step {
  position: relative;
  padding: 36rpx 30rpx;
  background: var(--paper-warm);
  border: 1rpx solid var(--line);
  text-align: center;
  margin-bottom: 36rpx;
}
.mech-stage { font-size: 22rpx; color: var(--gold-deep); letter-spacing: 3rpx; margin-bottom: 10rpx; }
.mech-title { font-size: 32rpx; font-weight: 600; color: var(--ink); }
.mech-down {
  position: absolute;
  bottom: -34rpx; left: 50%;
  transform: translateX(-50%);
  width: 44rpx; height: 44rpx;
  border-radius: 50%;
  border: 1rpx solid var(--gold);
  background: var(--paper);
  color: var(--gold);
  font-size: 26rpx;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 2;
}

.cycle {
  padding: 40rpx 40rpx;
  background: rgba(107, 43, 43, 0.06);
  border: 1rpx solid rgba(107, 43, 43, 0.2);
  border-left: 4rpx solid var(--crimson);
}
.cycle-label { font-size: 22rpx; letter-spacing: 3rpx; color: var(--crimson); margin-bottom: 12rpx; }
.cycle-p { font-size: 32rpx; line-height: 1.7; color: var(--ink); }

.stats-list { display: flex; flex-direction: column; gap: 10rpx; margin-top: 50rpx; }
.stat {
  display: flex;
  align-items: baseline;
  gap: 30rpx;
  padding: 30rpx 10rpx;
  border-bottom: 1rpx solid var(--line);
}
.stat-num { font-size: 88rpx; font-weight: 300; color: var(--crimson); line-height: 1; flex-shrink: 0; min-width: 200rpx; }
.stat-unit { font-size: 40rpx; color: var(--gold-deep); }
.stat-label { font-size: 25rpx; color: var(--slate); line-height: 1.6; }

.key-diag {
  margin-top: 50rpx;
  padding: 40rpx;
  background: linear-gradient(135deg, rgba(107,43,43,0.06), rgba(244,237,224,0));
  border-left: 4rpx solid var(--crimson);
  font-size: 28rpx;
  line-height: 1.85;
  color: var(--ink-soft);
}
.kd-strong { color: var(--ink); font-weight: 600; }

/* ============ 出路 ============ */
.paths-quote {
  padding: 40rpx;
  background: linear-gradient(135deg, rgba(74, 92, 58, 0.08), rgba(244,237,224,0));
  border-left: 4rpx solid var(--moss);
  font-size: 32rpx;
  font-style: italic;
  line-height: 1.7;
  color: var(--ink);
  margin-bottom: 40rpx;
}
.paths-list { display: flex; flex-direction: column; gap: 24rpx; }
.path-col {
  position: relative;
  padding: 44rpx 38rpx;
  background: var(--paper);
  border: 1rpx solid var(--line);
}
.path-col.path-dark { background: var(--ink); }
.path-roman { font-size: 44rpx; color: var(--gold); line-height: 1; margin-bottom: 16rpx; }
.path-dark .path-roman { color: var(--gold-bright); }
.path-name { font-size: 38rpx; font-weight: 700; color: var(--ink); margin-bottom: 8rpx; }
.path-dark .path-name { color: var(--paper); }
.path-latin { font-size: 25rpx; color: var(--gold-deep); margin-bottom: 24rpx; }
.path-dark .path-latin { color: var(--gold-bright); }
.path-items { display: flex; flex-direction: column; }
.path-li {
  font-size: 27rpx;
  line-height: 1.65;
  color: var(--ink-soft);
  padding: 14rpx 0;
  border-bottom: 1rpx dashed var(--line);
}
.path-li:last-child { border-bottom: none; }
.path-dark .path-li { color: var(--paper-warm); border-bottom-color: rgba(244, 237, 224, 0.15); }
.root-tag {
  position: absolute;
  top: 0; right: 0;
  padding: 10rpx 22rpx;
  background: var(--crimson);
  color: var(--paper);
  font-size: 22rpx;
  letter-spacing: 2rpx;
}

/* 自我演化 */
.evo-block { margin-top: 60rpx; }
.evo-h { font-size: 38rpx; font-weight: 600; color: var(--ink); margin-bottom: 8rpx; }
.evo-sub { font-size: 26rpx; color: var(--gold-deep); margin-bottom: 30rpx; letter-spacing: 1rpx; }
.evo-list { display: flex; flex-direction: column; gap: 18rpx; }
.evo-stage { padding: 32rpx 34rpx; border: 1rpx solid var(--line); }
.evo-0 { background: rgba(184, 135, 70, 0.1); }
.evo-1 { background: rgba(212, 165, 116, 0.18); }
.evo-2 { background: rgba(107, 43, 43, 0.08); }
.evo-3 { background: rgba(74, 92, 58, 0.12); }
.evo-step { font-size: 22rpx; color: var(--gold-deep); margin-bottom: 8rpx; letter-spacing: 2rpx; }
.evo-name { font-size: 38rpx; font-weight: 600; color: var(--ink); margin-bottom: 10rpx; }
.evo-desc { font-size: 26rpx; color: var(--ink-soft); line-height: 1.6; }

/* ============ 总结 ============ */
.synthesis {
  background: var(--ink);
  color: var(--paper);
  padding: 90rpx 48rpx;
  background-image:
    radial-gradient(circle at 18% 20%, rgba(212, 165, 116, 0.1) 0%, transparent 36%),
    radial-gradient(circle at 82% 80%, rgba(107, 43, 43, 0.08) 0%, transparent 36%);
}
.syn-h { font-weight: 700; font-size: 56rpx; line-height: 1.2; color: var(--paper); margin-bottom: 14rpx; }
.syn-sub { font-size: 30rpx; color: var(--gold-bright); margin-bottom: 50rpx; letter-spacing: 1rpx; }

.lineage-list { display: flex; flex-direction: column; gap: 0; }
.lineage-step {
  display: flex;
  gap: 30rpx;
  align-items: flex-start;
  padding: 32rpx 0;
  border-bottom: 1rpx solid rgba(212, 165, 116, 0.2);
}
.lineage-circle {
  flex-shrink: 0;
  width: 96rpx; height: 96rpx;
  border-radius: 50%;
  border: 1rpx solid var(--gold);
  background: rgba(212, 165, 116, 0.08);
  color: var(--gold-bright);
  font-size: 40rpx;
  display: flex;
  align-items: center;
  justify-content: center;
}
.lineage-body { flex: 1; padding-top: 4rpx; }
.lineage-name { font-size: 34rpx; font-weight: 600; color: var(--paper); margin-bottom: 6rpx; }
.lineage-era { font-size: 22rpx; color: var(--gold-bright); letter-spacing: 3rpx; margin-bottom: 10rpx; }
.lineage-desc { font-size: 25rpx; color: var(--paper-warm); line-height: 1.7; opacity: 0.88; }

.coda {
  margin-top: 60rpx;
  padding: 56rpx 44rpx;
  border: 1rpx solid var(--gold);
  background: rgba(212, 165, 116, 0.04);
  text-align: center;
}
.coda-mark { font-size: 80rpx; color: var(--gold); line-height: 0.6; margin-bottom: 24rpx; }
.coda-quote {
  font-size: 38rpx;
  font-weight: 300;
  font-style: italic;
  line-height: 1.6;
  color: var(--paper);
  margin-bottom: 24rpx;
}
.coda-cite { font-size: 24rpx; color: var(--gold-bright); letter-spacing: 3rpx; }
.coda-tail { margin-top: 30rpx; font-size: 30rpx; font-style: italic; color: var(--paper-warm); }

/* ============ 页脚 ============ */
.footer {
  padding: 60rpx 48rpx 80rpx;
  background: #0a0907;
  color: var(--paper-warm);
  text-align: center;
  font-size: 25rpx;
  letter-spacing: 2rpx;
}
.footer-src { margin-top: 14rpx; color: var(--slate); font-size: 22rpx; line-height: 1.7; }
.footer-top {
  margin-top: 36rpx;
  display: inline-block;
  padding: 16rpx 40rpx;
  border: 1rpx solid var(--gold-deep);
  color: var(--gold-bright);
  font-size: 24rpx;
  letter-spacing: 2rpx;
}

.page {
  width: 100%;
  height: 100vh;
  background: var(--paper);
}

/* ===== Hero ===== */
.hero {
  background: radial-gradient(circle at 50% 36%, #1f1a16 0%, #14110f 60%, #0d0b09 100%);
  padding: 90rpx 56rpx 80rpx;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
}

.hero-figure {
  position: relative;
  width: 360rpx;
  height: 360rpx;
  margin-bottom: 56rpx;
  display: flex;
  align-items: center;
  justify-content: center;
}
.ring {
  position: absolute;
  border-radius: 50%;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
}
.ring-outer {
  width: 360rpx;
  height: 360rpx;
  border: 1rpx dashed rgba(184, 135, 70, 0.4);
}
.ring-gold {
  width: 268rpx;
  height: 268rpx;
  border: 1rpx solid rgba(184, 135, 70, 0.55);
  box-shadow: 0 0 40rpx rgba(184, 135, 70, 0.15);
}
.void-core {
  position: relative;
  width: 200rpx;
  height: 200rpx;
  border-radius: 50%;
  background: radial-gradient(circle at 50% 50%, #050403 0%, #100d0b 70%);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  box-shadow: inset 0 0 50rpx rgba(0, 0, 0, 0.9);
}
.light-center {
  position: absolute;
  width: 70rpx;
  height: 70rpx;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(212, 165, 116, 0.85) 0%, rgba(184, 135, 70, 0.12) 70%, transparent 100%);
  top: 36rpx;
}
.void-label {
  font-size: 40rpx;
  color: var(--gold-bright);
  letter-spacing: 8rpx;
  margin-top: 34rpx;
  text-indent: 8rpx;
}
.void-latin {
  font-size: 18rpx;
  font-style: italic;
  letter-spacing: 4rpx;
  color: rgba(184, 135, 70, 0.6);
  margin-top: 6rpx;
}

.hero-eyebrow {
  font-style: italic;
  letter-spacing: 4rpx;
  color: var(--gold);
  font-size: 24rpx;
  margin-bottom: 28rpx;
}
.hero-title {
  font-size: 76rpx;
  line-height: 1.25;
  color: #f4ede0;
  font-weight: 600;
  letter-spacing: 4rpx;
}
.hero-title .hl { color: var(--gold-bright); }
.hero-sub {
  font-style: italic;
  font-size: 26rpx;
  color: rgba(244, 237, 224, 0.5);
  letter-spacing: 2rpx;
  margin-top: 18rpx;
}
.hero-lede {
  font-size: 28rpx;
  line-height: 1.85;
  color: rgba(244, 237, 224, 0.78);
  margin-top: 40rpx;
  max-width: 600rpx;
}
.hero-lede .em { color: var(--gold-bright); }
.hero-meta {
  margin-top: 46rpx;
  font-size: 24rpx;
  color: rgba(244, 237, 224, 0.55);
  letter-spacing: 2rpx;
}
.hero-meta .dot { margin: 0 16rpx; color: var(--gold); }
.hero-hint {
  margin-top: 48rpx;
  font-size: 22rpx;
  font-style: italic;
  letter-spacing: 3rpx;
  color: rgba(184, 135, 70, 0.7);
}

/* ===== 核心命题 ===== */
.thesis {
  background: var(--paper-warm);
  border-bottom: 1rpx solid var(--line);
  padding: 72rpx 56rpx 64rpx;
  text-align: center;
}
.thesis-mark {
  font-size: 90rpx;
  color: var(--gold);
  line-height: 0.5;
  height: 60rpx;
}
.thesis-body {
  font-size: 38rpx;
  line-height: 1.7;
  color: var(--ink);
  font-weight: 500;
}
.thesis-hl {
  color: var(--crimson);
  border-bottom: 3rpx solid rgba(184, 135, 70, 0.5);
  padding-bottom: 2rpx;
}
.thesis-note {
  font-size: 26rpx;
  line-height: 1.8;
  color: var(--slate);
  margin-top: 32rpx;
  max-width: 600rpx;
  margin-left: auto;
  margin-right: auto;
}

/* ===== 目录头 ===== */
.toc-head {
  padding: 72rpx 56rpx 16rpx;
}
.toc-title {
  font-size: 56rpx;
  color: var(--ink);
  font-weight: 600;
  letter-spacing: 2rpx;
}
.toc-desc {
  font-size: 26rpx;
  color: var(--slate);
  margin-top: 18rpx;
  line-height: 1.7;
}

/* ===== 目录列表 ===== */
.toc-list {
  padding: 32rpx 40rpx 0;
}
.toc-item {
  display: flex;
  align-items: center;
  padding: 36rpx 28rpx;
  background: #fbf6ec;
  border: 1rpx solid var(--line);
  border-radius: 8rpx;
  margin-bottom: 22rpx;
  position: relative;
  overflow: hidden;
}
.toc-item::before {
  content: "";
  position: absolute;
  left: 0; top: 0; bottom: 0;
  width: 6rpx;
  background: var(--gold);
}
.toc-roman {
  width: 120rpx;
  display: flex;
  flex-direction: column;
  align-items: center;
  flex-shrink: 0;
}
.roman-cn {
  font-size: 52rpx;
  color: var(--crimson);
  font-weight: 600;
  line-height: 1;
}
.roman-phase {
  font-size: 16rpx;
  font-style: italic;
  letter-spacing: 2rpx;
  color: var(--gold-deep);
  margin-top: 10rpx;
}
.toc-main {
  flex: 1;
  padding: 0 16rpx;
}
.toc-item-title {
  font-size: 34rpx;
  color: var(--ink);
  font-weight: 600;
  letter-spacing: 1rpx;
}
.toc-item-sub {
  font-size: 24rpx;
  color: var(--slate);
  margin-top: 8rpx;
}
.toc-arrow {
  font-size: 36rpx;
  color: var(--gold);
  flex-shrink: 0;
}

/* ===== 页脚 ===== */
.footer {
  margin-top: 40rpx;
  padding: 80rpx 56rpx 40rpx;
  background: radial-gradient(circle at 50% 0%, #1f1a16 0%, #14110f 100%);
  text-align: center;
}
.footer-line {
  width: 60rpx;
  height: 2rpx;
  background: var(--gold);
  margin: 0 auto 40rpx;
}
.footer-quote {
  font-size: 36rpx;
  color: var(--gold-bright);
  letter-spacing: 4rpx;
  margin-bottom: 28rpx;
}
.footer-cite {
  font-size: 28rpx;
  line-height: 1.8;
  color: rgba(244, 237, 224, 0.8);
  max-width: 580rpx;
  margin: 0 auto;
}
.footer-mark {
  font-size: 22rpx;
  font-style: italic;
  letter-spacing: 2rpx;
  color: rgba(244, 237, 224, 0.45);
  margin-top: 36rpx;
}
.bottom-safe {
  height: env(safe-area-inset-bottom);
  background: #14110f;
}

