/* =========================================================
   人物数据 · figures.js
   ========================================================= */

const FIGURES_DATA = [
  {
    era: "族长时代",
    items: [
      { id: "fg-adam", name: "亚当", role: "人类始祖",
        detail: "希伯来文 'adam 与 'adamah（地）同根——'从地土所造的'。<br><br>亚当是人类原型——按神的形像所造（创 1:27），被赋予治理与照管被造界的责任（'治理这地'1:28）。神带各样动物到他面前任他命名。然后神造夏娃为他的伴侣。<br><br>亚当违命之后，咒诅临到——'<strong>你必汗流满面才得糊口</strong>'（3:19）。被逐出伊甸园。<br><br>在新约中，亚当是<strong>'后来要来之人的预像'</strong>（罗 5:14）——保罗将基督称为'末后的亚当'（林前 15:45），第一个亚当带来罪与死，第二个亚当带来义与生命。"
      },
      { id: "fg-noah", name: "挪亚", role: "洪水中的义人",
        detail: "名字意为'安息'。父亲拉麦说他要'安慰我们'（创 5:29）——预表洪水后的新开始。<br><br>'挪亚是个义人，在当时的世代是个完全人；挪亚与神同行'（6:9）——这是创世记中第二位被记载'与神同行'的人（第一位是以诺）。<br><br>他造方舟、带家人和动物渡过洪水。出方舟后筑坛献祭——这是圣经中第一次提到燔祭。神立挪亚之约：以彩虹为记，应许不再以洪水灭世。<br><br>但挪亚的故事并未止于此。他后来栽了葡萄园，喝醉了赤身露体，引出儿子之间的事件——提醒读者：连最敬虔的人也仍是堕落的。"
      },
      { id: "fg-abraham", name: "亚伯拉罕", role: "信心之父",
        detail: "原名亚伯兰（'尊贵的父'），被神改名为亚伯拉罕（'多国的父'）。<br><br>七十五岁时蒙召离开吾珥到迦南。无后嗣到一百岁才得着应许的儿子以撒。<br><br>关键事件：与罗得分地（让步给侄子）、营救罗得（亚伯拉罕之战）、与麦基洗德相会、献以撒（创 22）。<br><br>'亚伯拉罕信耶和华，耶和华就以此为他的义'（15:6）——这一节被新约引用三次（罗 4、加 3、雅 2），成为<strong>因信称义</strong>的旧约根基。<br><br>三大宗教（犹太教、基督教、伊斯兰教）都奉他为信仰之父——故有'<strong>亚伯拉罕宗教</strong>'之称。"
      },
      { id: "fg-sarah", name: "撒拉", role: "应许之母",
        detail: "原名撒莱，被神改名撒拉（意为'公主'）。亚伯拉罕的妻子，长亚伯拉罕约 10 岁。<br><br>她在生育上长期'不育'——这是创世记中反复出现的母题（撒拉、利百加、拉结都曾不能怀孕）。九十岁时仍蒙应许怀孕，<strong>九十一岁生以撒</strong>（'喜笑'之意——回应她最初听到应许时的暗笑）。<br><br>因急于成全应许，她曾把使女夏甲给亚伯拉罕——生以实玛利。这成为后来不可调和的家族张力。<br><br>她是希伯来书'信心英雄殿'（11:11）中唯一被提名的女性。新约中视她和夏甲为两约的预表（加 4:21–31）。"
      },
      { id: "fg-jacob", name: "雅各", role: "被改造的欺骗者",
        detail: "亚伯拉罕之孙，以撒之子，以扫的双胞胎弟弟。出生时抓住哥哥的脚跟——故得名'雅各'（抓脚跟者，引申为'欺骗者'）。<br><br>他用红汤换长子名分、骗瞎眼的父亲祝福、被舅舅拉班反复欺骗、与拉班勾心斗角——他的人生充满'抓取'。<br><br>关键转折：<strong>雅博渡口</strong>（创 32）——夜里独自一人时与神搏斗到天明。他的大腿被摸了一下就瘸了，但他不肯放手，要神祝福他。神改他名为<strong>'以色列'</strong>（与神较力者）。<br><br>从此他瘸着腿走完人生——既是被改变的标志，也是仍带肉体软弱的提醒。<br><br>他十二个儿子成为以色列十二支派的祖先。"
