/* =========================================================
   人物数据 · figures.js
   ========================================================= */

const FIGURES_DATA = [
  {
    era: "族长时代",
    items: [
      { id: "fg-adam", name: "亚当", role: "人类始祖",
        detail: "希伯来文 'adam 与 'adamah（地）同根——'从地土所造的'。<br><br>亚当是人类原型——按神的形像所造（创 1:27），被赋予治理与照管被造界的责任（'治理这地'1:28）。神带各样动物到他面前任他命名。然后神造夏娃为他的伴侣。<br><br>亚当违命之后，咒诅临到——'<strong>你必汗流满面才得糊口</strong>'（3:19）。被逐出伊甸园。<br><br>在新约中，亚当是<strong>'后来要来之人的预像'</strong>（罗 5:14）——保罗将基督称为'末后的亚当'（林前 15:45），第一个亚当带来罪与死，第二个亚当带来义与生命。"
      },
      { id: "fg-noah", name: "挪亚", role: "洪水中的义人",
        detail: "名字意为'安息'。父亲拉麦说他要'安慰我们'（创 5:29）——预表洪水后的新开始。<br><br>'挪亚是个义人，在当时的世代是个完全人；挪亚与神同行'（6:9）——这是创世记中第二位被记载'与神同行'的人（第一位是以诺）。<br><br>他造方舟、带家人和动物渡过洪水。出方舟后筑坛献祭——这是圣经中第一次提到燔祭。神立挪亚之约：以彩虹为记，应许不再以洪水灭世。<br><br>但挪亚的故事并未止于此。他后来栽了葡萄园，喝醉了赤身露体，引出儿子之间的事件——提醒读者：连最敬虔的人也仍是堕落的。"
      },
      { id: "fg-abraham", name: "亚伯拉罕", role: "信心之父",
        detail: "原名亚伯兰（'尊贵的父'），被神改名为亚伯拉罕（'多国的父'）。<br><br>七十五岁时蒙召离开吾珥到迦南。无后嗣到一百岁才得着应许的儿子以撒。<br><br>关键事件：与罗得分地（让步给侄子）、营救罗得（亚伯拉罕之战）、与麦基洗德相会、献以撒（创 22）。<br><br>'亚伯拉罕信耶和华，耶和华就以此为他的义'（15:6）——这一节被新约引用三次（罗 4、加 3、雅 2），成为<strong>因信称义</strong>的旧约根基。<br><br>三大宗教（犹太教、基督教、伊斯兰教）都奉他为信仰之父——故有'<strong>亚伯拉罕宗教</strong>'之称。"
      },
      { id: "fg-sarah", name: "撒拉", role: "应许之母",
        detail: "原名撒莱，被神改名撒拉（意为'公主'）。亚伯拉罕的妻子，长亚伯拉罕约 10 岁。<br><br>她在生育上长期'不育'——这是创世记中反复出现的母题（撒拉、利百加、拉结都曾不能怀孕）。九十岁时仍蒙应许怀孕，<strong>九十一岁生以撒</strong>（'喜笑'之意——回应她最初听到应许时的暗笑）。<br><br>因急于成全应许，她曾把使女夏甲给亚伯拉罕——生以实玛利。这成为后来不可调和的家族张力。<br><br>她是希伯来书'信心英雄殿'（11:11）中唯一被提名的女性。新约中视她和夏甲为两约的预表（加 4:21–31）。"
      },
      { id: "fg-jacob", name: "雅各", role: "被改造的欺骗者",
        detail: "亚伯拉罕之孙，以撒之子，以扫的双胞胎弟弟。出生时抓住哥哥的脚跟——故得名'雅各'（抓脚跟者，引申为'欺骗者'）。<br><br>他用红汤换长子名分、骗瞎眼的父亲祝福、被舅舅拉班反复欺骗、与拉班勾心斗角——他的人生充满'抓取'。<br><br>关键转折：<strong>雅博渡口</strong>（创 32）——夜里独自一人时与神搏斗到天明。他的大腿被摸了一下就瘸了，但他不肯放手，要神祝福他。神改他名为<strong>'以色列'</strong>（与神较力者）。<br><br>从此他瘸着腿走完人生——既是被改变的标志，也是仍带肉体软弱的提醒。<br><br>他十二个儿子成为以色列十二支派的祖先。"
      },
      { id: "fg-joseph", name: "约瑟", role: "护理的见证",
        detail: "雅各与拉结的长子（雅各最爱之子）。十七岁时被嫉妒的哥哥们卖到埃及。<br><br>在埃及由奴隶到囚犯，再由囚犯到宰相——'<strong>他在我手下亨通</strong>'是创世记 39 章四次出现的主题句。<br><br>他治理埃及度过七年大饥荒，后来与饥荒中来寻粮的哥哥们重逢。处理感情爆发后，他向哥哥们说出圣经最伟大的护理宣言：<br><br>'<strong>从前你们的意思是要害我，但神的意思原是好的，要保全许多人的性命，成就今日的光景。</strong>'（创 50:20）<br><br>他的故事不仅是个人传记，也是<strong>整本圣经'神在恶中作工'神学的早期典范</strong>。"
      }
    ]
  },
  {
    era: "出埃及与征服",
    items: [
      { id: "fg-moses", name: "摩西", role: "立法者与中保",
        detail: "希伯来奴隶出身，被法老女儿收养，在埃及王宫中受最好的教育。四十岁时杀埃及人后逃到米甸旷野作牧人四十年。八十岁时蒙召带百姓出埃及。<br><br>事工四十年——带领百姓出埃及、过红海、立约于西奈、漂流旷野。<br><br>他是<strong>圣经中最独特的人物</strong>之一——'<strong>耶和华与摩西面对面说话，好像人与朋友说话一般</strong>'（出 33:11）。这是其他先知都没有的亲密。<br><br>但他也有极人性的弱点——口才不好（出 4:10）、曾因怒气击打磐石违命（民 20）、不得进迦南。<br><br>申命记结尾的悼词：'<strong>以后以色列中再没有兴起先知像摩西的；他是耶和华面对面所认识的</strong>'（申 34:10）。这一句也为'<strong>那一位</strong>'更大的先知留下盼望——耶稣明确将自己呈现为这位。"
      },
      { id: "fg-aaron", name: "亚伦", role: "首位大祭司",
        detail: "摩西的哥哥，比摩西大三岁。在出埃及叙事中，他作为摩西的'代言人'——因摩西自言'拙口笨舌'。<br><br>但他也有显著的失败：<strong>金牛犊事件</strong>（出 32）——摩西在山上时，亚伦顺从百姓压力造金牛犊。这一事件本应使他丧命，但因摩西代求得免。<br><br>之后亚伦被立为<strong>第一位大祭司</strong>——他和子孙的祭司职任贯穿整个旧约。亚伦的祭司体系在希伯来书中被对比——不完全的、需要不断献祭的；基督则是<strong>完全的、永远的大祭司</strong>，按麦基洗德的等次。<br><br>亚伦死于何珥山（民 20:28），由他的儿子以利亚撒接续大祭司职。"
      },
      { id: "fg-joshua", name: "约书亚", role: "进入应许之地的领袖",
        detail: "原名何细亚（'拯救'），摩西改其名为约书亚（'<strong>耶和华是拯救</strong>'）——与希腊文'耶稣'同义同源。<br><br>从年轻时就跟随摩西——在西奈山陪同摩西、看守会幕、十二探子之一（与迦勒同为持信心立场的两人）。<br><br>摩西死后他被立为以色列领袖，带领百姓<strong>过约旦河、攻取迦南、分配土地</strong>。<br><br>他的告别讲话——'<strong>至于我和我家，我们必定事奉耶和华</strong>'（书 24:15）成为千古名言。<br><br>约书亚在很多方面是耶稣的预表：他们同名同义；约书亚带百姓进入物质的应许之地，耶稣带百姓进入更深的'安息'（来 4 章）。"
      },
      { id: "fg-rahab", name: "喇合", role: "归信的耶利哥妓女",
        detail: "约书亚派的两个探子在耶利哥城中被她窝藏在自己房顶的麻秸下。她的告白令人惊讶：<br><br>'<strong>我知道耶和华已经把这地赐给你们…因为耶和华你们的神，本是上天下地的神</strong>'（书 2:9, 11）。<br><br>她交换条件：当城被攻破时保留她和家人的性命。她用<strong>朱红线绳</strong>从窗户系下——这成为约定的记号。耶利哥城倒塌时她全家得救。<br><br>她不仅得救，还<strong>成为以色列人</strong>——并嫁给犹大支派的撒门，生波阿斯（路得的丈夫）。她是<strong>大卫的高祖母</strong>，进入耶稣的家谱（太 1:5）。<br><br>新约把她列在'信心英雄殿'（来 11:31），雅各也以她为'<strong>信行合一</strong>'的范例（雅 2:25）。一位异邦妓女成为弥赛亚血脉中的母亲——恩典的极致表达。"
      }
    ]
  },
  {
    era: "士师与王国",
    items: [
      { id: "fg-deborah", name: "底波拉", role: "女先知与女士师",
        detail: "在士师时期众多男性领袖中，底波拉作为女先知与女士师领导以色列。她坐在以法莲山地的棕树下，百姓上她那里听判断。<br><br>当迦南王耶宾欺压以色列二十年，底波拉召军长巴拉，命他去打仗。但巴拉说：'你若同我去，我就去；你若不同我去，我就不去。'<br><br>底波拉警告：'<strong>这次你行的路得不着荣耀，因为耶和华要将西西拉交在一个妇人手里</strong>'（士 4:9）。<br><br>那妇人是<strong>雅亿</strong>——基尼人希百的妻子。逃亡的迦南军长西西拉躲入她的帐棚，雅亿用帐棚的橛子钉透他的鬓边。<br><br>士师记 5 章是底波拉之歌——圣经最古老的诗篇之一。"
      },
      { id: "fg-samuel", name: "撒母耳", role: "最后的士师，先知的开创",
        detail: "母亲哈拿不能生育，恳求神赐子，应许要将他归与神。神听了——撒母耳出生（'神所赐的'）。哈拿的尊主颂式祷告（撒上 2 章）启发了后来马利亚的尊主颂。<br><br>撒母耳从小在示罗会幕中事奉。一夜神三次呼叫他，他以为是大祭司以利的声音——以利明白后教他回答：'<strong>请说，仆人敬听</strong>'（撒上 3:9）。<br><br>从此神兴起他作'先知'——这是圣经中第一位职业先知。他是<strong>最后的士师</strong>，<strong>第一位先知传统的开创者</strong>，也是<strong>立王者</strong>——膏立扫罗，又膏立大卫。<br><br>他在以色列从神权制过渡到君主制的关键时刻起到桥梁作用。"
      },
      { id: "fg-david", name: "大卫", role: "合神心意的王",
        detail: "耶西的第八个儿子，少年时是牧羊人。撒母耳被差去伯利恒膏立他时，他正在野外放羊——前七个哥哥都被介绍过却都被神否决。'耶和华不像人看人；人是看外貌，耶和华是看内心'（撒上 16:7）。<br><br>大卫击杀歌利亚，进入扫罗宫廷弹琴；扫罗嫉妒后他逃亡多年；扫罗死后先作犹大王，七年后统一以色列十二支派为王。<br><br>四十年王朝的高点：攻取耶路撒冷、迎回约柜、得着<strong>大卫之约</strong>（撒下 7）；低点：与拔示巴的事件及随后的家庭悲剧。<br><br>他是诗篇中最多产的诗人（73 篇标'大卫的诗'）。新约称耶稣为'<strong>大卫的子孙</strong>'——这是最常用的弥赛亚称号之一。"
      },
      { id: "fg-solomon", name: "所罗门", role: "智慧之王",
        detail: "大卫与拔示巴的儿子，在年长哥哥们的位上被立为王。<br><br>登基后神在梦中向他显现，他求<strong>智慧</strong>——神大悦，赐他空前的智慧、财富、尊荣。<br><br>他建造圣殿（前 966–959 年）、写下三千句箴言和一千零五首诗、回答示巴女王所有难题。<br><br>但他后来娶外邦妻妾众多，因这些妻子的影响而拜偶像。神宣告：在他死后王国必分裂。<br><br>所罗门可能是<strong>《传道书》</strong>的作者——书末写道'<strong>这些事都已听见了，总意就是敬畏神，谨守他的诫命；这是人所当尽的本分</strong>'（传 12:13）。如果是他暮年的反思，这一句更加重——一位曾'万事都尝试'的人最终的结论。"
      },
      { id: "fg-saul", name: "扫罗", role: "以色列第一位王",
        detail: "便雅悯支派人，'比众民高一头'，外貌威武。被神拣选为以色列第一位王——但神同时通过撒母耳警告百姓，立王并非神的本意。<br><br>开始时谦卑（'我家在便雅悯支派中是至小的'撒上 9:21），但很快显出软弱：擅自献祭（撒上 13）、不彻底执行神对亚玛力人的命令（撒上 15）——撒母耳的回应'<strong>听命胜于献祭</strong>'（15:22）成为名言。<br><br>之后扫罗对大卫的嫉妒主导了他的后半生——多次想杀大卫。临终前他在基利波山战败，自刎而死。<br><br>扫罗是圣经中悲剧性的人物——开始得好但走向越来越远。他提醒我们：被神拣选并不保证忠诚到底。"
      }
    ]
  },
  {
    era: "先知",
    items: [
      { id: "fg-elijah", name: "以利亚", role: "提斯比的先知",
        detail: "提斯比人，活动于北国亚哈王时期（前 9 世纪中叶）。突然出现，毫无家世背景介绍。<br><br>关键事迹：宣告三年半旱灾、在基立溪被乌鸦喂养、住寡妇家油面不缺、复活寡妇的儿子、<strong>迦密山对决巴力先知</strong>（王上 18）、在何烈山听见<strong>'微小的声音'</strong>（王上 19）、膏立以利沙、宣告亚哈与耶洗别的审判。<br><br>结局非凡——他没有死，而是<strong>乘旋风、火车火马升天</strong>（王下 2）。<br><br>玛拉基书结尾预言以利亚必再来（玛 4:5）。新约视施洗约翰为这预言的应验（太 11:14）。耶稣登山变像时，摩西与以利亚显现——代表律法与先知。"
      },
      { id: "fg-isaiah", name: "以赛亚", role: "弥赛亚预言的先知",
        detail: "出身耶路撒冷贵族，事工跨越乌西雅、约坦、亚哈斯、希西家四王（前 8 世纪后半）。<br><br>蒙召经历（赛 6 章）非常戏剧化——他在圣殿中见到耶和华坐在高高的宝座上，撒拉弗呼喊'圣哉、圣哉、圣哉'。他喊'我是嘴唇不洁的人'，撒拉弗以红炭洁净他，他回应'<strong>我在这里，请差遣我</strong>'。<br><br>他的事工跨越亚述危机——劝希西家王不要倚靠埃及而要倚靠神。最著名的预言：<strong>童女怀孕生子（7:14）、和平之子（9:6–7）、受苦的仆人（53 章）、新天新地（65 章）</strong>。<br><br>新约引用他超过 60 次。犹太传统说他殉道——在玛拿西王时期被锯成两半。"
      },
      { id: "fg-jeremiah", name: "耶利米", role: "流泪的先知",
        detail: "祭司之家出身，在前 626 年（约 20 岁）蒙召事奉到耶路撒冷陷落（前 586）后——共四十多年。<br><br>蒙召时他抗议：'我是年幼的，不知怎样说。'神回答：'<strong>我未将你造在腹中，我已晓得你；你未出母胎，我已分别你为圣</strong>'（耶 1:5）。<br><br>他奉命传讲将临的审判——结果遭尽逼迫：被鞭打、被关入井底、被诬陷叛国、最后被掳同胞强行带到埃及。<br><br>他的'<strong>哀诉</strong>'（耶利米书有六处先知抱怨自己事奉之苦的段落）使他成为圣经中最具人性深度的先知。'神啊，你欺哄我'（20:7）这种诚实的呼喊几乎令人不安。<br><br>但他传讲的<strong>新约</strong>预言（耶 31:31–34）成为新约神学最重要的旧约根基之一。"
      },
      { id: "fg-ezekiel", name: "以西结", role: "异象的先知",
        detail: "祭司之子，在前 597 年第二批被掳之列。在巴比伦的迦巴鲁河边。<br><br>蒙召经历宏伟（结 1 章）——四活物（人、狮、牛、鹰的脸）、四轮、像水苍玉之上有宝座——'<strong>这是耶和华荣耀的形像</strong>'。<br><br>他大量使用<strong>象征行为</strong>：躺三百九十日（代表以色列罪孽）、剃发分三份（代表三种命运）、不得为亡妻哀哭（代表耶路撒冷将临的厄运）。<br><br>关键异象：<strong>圣殿的荣光离开</strong>（结 10–11 章——神不再住在那殿中）；<strong>枯骨复生</strong>（结 37——以色列必复兴）；<strong>新圣殿</strong>（结 40–48——理想化的未来圣殿，新约中常被解读为属灵教会或末世的预表）。<br><br>'我必将石心从你们的肉体中除掉，赐给你们肉心'（36:26）是新约的预告。"
      },
      { id: "fg-daniel", name: "但以理", role: "在异邦宫廷的圣徒",
        detail: "犹大贵族青年，前 605 年第一批被掳之列。在巴比伦宫廷被训练为公务员。<br><br>从拒绝王的食物（不愿玷污自己）开始，他和三友以洁身自爱赢得神的恩待。<br><br>他在<strong>四个外邦王朝（巴比伦的尼布甲尼撒、伯沙撒；玛代波斯的大利乌、古列）</strong>下都被高升——这本身是神护理的奇迹。<br><br>关键事件：解尼布甲尼撒的金像异梦、解伯沙撒筵席上墙上的字、被扔狮坑因他不肯停止祷告。<br><br>但以理书的后半（7–12 章）是<strong>启示文学</strong>的代表——四兽异象、七十个七的预言。耶稣多次以'<strong>人子</strong>'自称，正是引自但 7:13–14。<br><br>但以理是新约外的圣经人物中最常被新约启示录回响的。"
      }
    ]
  },
  {
    era: "新约",
    items: [
      { id: "fg-mary", name: "马利亚", role: "耶稣之母",
        detail: "拿撒勒的童女，已与约瑟订婚。天使加百列来报喜——她将怀圣灵的孕，生子取名耶稣。<br><br>她最深的回应是顺服中的迷茫：'我没有出嫁，怎么有这事呢？'然后是'<strong>我是主的使女，情愿照你的话成就在我身上</strong>'（路 1:38）。<br><br>她的<strong>'尊主颂'</strong>（路 1:46–55）是新约最美的诗篇之一——'<strong>他用膀臂施展大能；那狂傲的人，正心里妄想就被他赶散了。他叫有权柄的失位，叫卑贱的升高</strong>'。这一首至今在世界各地教会的晚祷中诵唱。<br><br>她在加利利的迦拿促成耶稣的第一个神迹（约 2），却也在儿子事工中常显出被动甚至担忧。她在十字架下站立——耶稣临终把她托付给约翰。她在马可楼与门徒一同祷告，等候圣灵降临。"
      },
      { id: "fg-jbaptist", name: "施洗约翰", role: "弥赛亚的先锋",
        detail: "祭司撒迦利亚与以利沙伯（马利亚的亲戚）所生。出生本身即是神迹——双亲都已年老。<br><br>他在旷野长大，'穿骆驼毛的衣服，腰束皮带，吃的是蝗虫野蜜'——神态仿如以利亚的复现。耶稣明确说：'<strong>他就是那应当来的以利亚</strong>'（太 11:14）。<br><br>他在约旦河边传<strong>悔改的洗礼</strong>，宣告：'<strong>我以后来的，能力比我更大…他要用圣灵与火给你们施洗</strong>'（太 3:11）。<br><br>耶稣来受他的洗——约翰起初不肯，最后顺服。看见耶稣时他说：'<strong>看哪，神的羔羊，除去世人罪孽的</strong>'（约 1:29）。<br><br>他后来因斥责希律安提帕娶兄弟的妻子被关入监，最终被砍头。耶稣评价：'<strong>凡妇人所生的，没有一个兴起来大过施洗约翰的</strong>'（太 11:11）。"
      },
      { id: "fg-jesus", name: "耶稣基督", role: "道成肉身的神子",
        detail: "希伯来名 Yeshua（约书亚），意为'<strong>耶和华是拯救</strong>'。'基督'（Christ）即希伯来文'弥赛亚'（受膏者）的希腊译法。<br><br>生于伯利恒（约公元前 4 年），长于拿撒勒。约 30 岁开始公开事工——三年传道、行神迹、训练门徒。<br><br>他的核心信息：'<strong>日期满了，神的国近了。你们当悔改，信福音</strong>'（可 1:15）。<br><br>他被祭司、长老、文士定罪交给罗马总督彼拉多，在公元 30 年（或 33 年）逾越节钉十字架。<br><br>三日后复活，向门徒多次显现，四十日后升天。<br><br>整本新约对他的身份有多重宣告：<strong>道</strong>（约 1）、<strong>神的儿子</strong>（太 16）、<strong>基督</strong>（太 16）、<strong>人子</strong>（耶稣常自称）、<strong>羔羊</strong>（启示录）、<strong>大祭司</strong>（希伯来书）、<strong>始与终</strong>（启 1）。<br><br>基督教信仰的全部都集中于这一位历史人物——'<strong>道成肉身</strong>'是基督教对'神'之定义的根本特点。"
      },
      { id: "fg-peter", name: "彼得", role: "首领门徒",
        detail: "原名西门，加利利渔夫，与弟弟安得烈一同蒙召。耶稣给他改名'<strong>矶法</strong>'（亚兰文）/'彼得'（希腊文），意为'石头'。<br><br>性格冲动率直——总是第一个回答问题，第一个采取行动，也第一个犯错。<br><br>关键时刻：<strong>该撒利亚腓立比的认信</strong>（'你是基督，是永生神的儿子'，太 16:16）；最后晚餐前否认必三次否认主，几小时后果然在大祭司院子里三次否认；<strong>提比哩亚海边的复职</strong>（约 21——耶稣三次问他'你爱我吗'，对应他的三次否认）。<br><br>五旬节那日他作主要讲员（徒 2）——开启教会时代。后来开放福音给外邦人（哥尼流家，徒 10）。<br><br>传统认为他在罗马尼禄逼迫时殉道——倒钉十字架（自认不配像主一样正钉）。"
      },
      { id: "fg-john", name: "约翰", role: "蒙爱的门徒",
        detail: "西庇太的儿子，雅各的弟弟，加利利渔夫。耶稣给他和哥哥起绰号'<strong>雷子</strong>'（半尼其）——可能因他们激烈的性格（曾建议从天上降火烧撒玛利亚村庄）。<br><br>他是耶稣<strong>核心三人组</strong>之一（彼得、雅各、约翰）——见证登山变像、客西马尼祷告、睚鲁女儿的复活。在最后晚餐时'侧身挨近耶稣的怀里'——后来被称为'耶稣所爱的门徒'。<br><br>他是<strong>唯一在十字架下的男性门徒</strong>——耶稣临终把母亲马利亚托付给他。<br><br>晚年大概住在以弗所，被流放拔摩岛——在那里写下《启示录》。<br><br>他的著作：约翰福音、约翰一二三书、启示录——共五卷新约书卷。从他早期的'雷子'到晚年反复劝勉'<strong>小子们哪，你们要彼此相爱</strong>'——是基督塑造一个人的最深例证。"
      },
      { id: "fg-magdalene", name: "抹大拉的马利亚", role: "复活的首位见证人",
        detail: "出身抹大拉（加利利海边的城）。耶稣曾从她身上赶出七个鬼（路 8:2）——这一描述强烈暗示她从极深的破碎中被救赎。<br><br>她跟随耶稣事奉，可能用自己的财物供给（路 8:3）。<br><br>她在十字架下站立到最后，目睹耶稣的安葬。<br><br>七日的第一日清晨，她到坟墓——发现石头已被挪开，坟墓是空的。她跑去告诉门徒。彼得和约翰来看后回去，但她留在坟外哭泣。<br><br>转身——看见耶稣站着，但以为是园丁，问'<strong>先生，若是你把他移了去，请告诉我，你把他放在哪里，我便去取他</strong>'（约 20:15）。<br><br>耶稣只叫她一声：'<strong>马利亚</strong>。'<br><br>她回头说'<strong>拉波尼</strong>（夫子）'——就认出了。<br><br>耶稣命她去告诉门徒——她因此成为<strong>'使徒中的使徒'</strong>，复活福音的第一位传告者。"
      },
      { id: "fg-paul", name: "保罗", role: "外邦人的使徒",
        detail: "原名扫罗，便雅悯支派人，生于大数（小亚细亚）的犹太家庭，享有罗马公民权。在耶路撒冷拜法利赛人迦玛列为师，是<strong>'按律法说，是法利赛人；论热心，则逼迫教会'</strong>（腓 3:5–6）。<br><br>司提反殉道时他在场。后向大祭司请文书要去大马色搜捕基督徒——途中蒙复活的基督显现而归主（徒 9）。<br><br>三次旅行布道、写下 13 卷新约书信。他的神学主题：<strong>因信称义</strong>、<strong>在基督里</strong>、<strong>新造</strong>、<strong>圣灵的工作</strong>、<strong>教会作为基督的身体</strong>、<strong>万有归一于基督</strong>。<br><br>他自陈所受患难：'<strong>我比他们多受劳苦，多下监牢，受鞭打是过重的，冒死是屡次有的…</strong>'（林后 11:23–28）。<br><br>晚年在罗马第二次坐监后殉道——传统说被斩首（罗马公民权使他免于钉十字架）。"
      }
    ]
  }
];

files.content:
/* =========================================================
   故事数据 · stories.js
   ========================================================= */

const STORIES_DATA = {
  old: {
    label: "旧约的核心叙事",
    items: [
      { id: "st-eden", title: "伊甸园", sub: "无瑕的开始与最初的失落", ref: "创世记 2–3",
        detail: "神在伊甸（'乐园'）中安置受造的人。园中有四条河流（其中两条至今仍存——底格里斯与幼发拉底）。神对人的命令简单：可以吃园中各样树上的果子，惟独'分别善恶树'的果子不可吃。<br><br>蛇引诱夏娃：'你们便如神能知道善恶。'夏娃和亚当吃了——眼睛'明亮'了，但发现自己赤身。神来时他们躲避；面对追问时彼此推卸。<br><br>神宣告咒诅，但其中也藏着应许——女人的后裔要伤蛇的头（3:15）。然后将他们逐出伊甸园，<strong>把守道路的基路伯</strong>把守生命树的路。<br><br>这一叙事的影响极深远：从奥古斯丁的'原罪论'到米尔顿的《失乐园》，到现代心理学对人之分裂的诊断。"
      },
      { id: "st-cain", title: "该隐与亚伯", sub: "罪从一代蔓延至下一代", ref: "创世记 4",
        detail: "亚当夏娃的两个儿子——该隐种地，亚伯牧羊。两人都向神献祭，亚伯的被神悦纳，该隐的不被悦纳。<br><br>神对该隐说话——这是圣经中最早的劝诫之一：'<strong>你若行得好，岂不蒙悦纳？你若行得不好，罪就伏在门前。它必恋慕你，你却要制伏它</strong>'（4:7）。<br><br>但该隐没有听。他把弟弟带到田里杀了。神质问'你兄弟在哪里？'——该隐的回答'我岂是看守我兄弟的吗？'成为人类自私的经典宣告。<br><br>该隐被驱逐，但神仍设立保护他的记号——审判中仍有怜悯。这一短短一章揭示罪的迅速蔓延：从违命到杀人只过了一代。"
      },
      { id: "st-noah", title: "挪亚方舟", sub: "在审判中保留余民", ref: "创世记 6–9",
        detail: "人类繁衍后罪也加增。'<strong>耶和华见人在地上罪恶很大，终日所思想的尽都是恶</strong>'（6:5）。神决定以洪水洁净世界，但拣选挪亚——他在那时代'是个义人，完全人，与神同行'。<br><br>方舟规格：长三百肘（约 137 米）、宽五十肘（23 米）、高三十肘（13.7 米）——三层。挪亚一家八口和各样动物进入。神亲手关上方舟的门。<br><br>洪水持续 40 昼夜，然后水退去 150 天。挪亚放鸽子三次试探——第二次衔回橄榄叶，第三次不再回来——表示陆地已干。<br><br>出方舟后挪亚献祭，神立约——以彩虹为记，应许不再以洪水灭世。这是<strong>圣经中第一次彩虹的出现</strong>，至今每次见到彩虹都唤起这一约的记忆。"
      },
      { id: "st-isaac", title: "献以撒", sub: "信心最深的张力", ref: "创世记 22",
        detail: "亚伯拉罕等候二十五年才得着应许的独子以撒。然后神的命令临到：'<strong>你带着你的儿子，就是你独生的儿子，你所爱的以撒，往摩利亚地去，在我所要指示你的山上，把他献为燔祭</strong>'（22:2）。<br><br>叙述异常沉默。亚伯拉罕没有讨价还价（与他为所多玛求情时形成对比）。他清晨起来，劈柴、备驴，三日的路程。<br><br>到山上，以撒问'<strong>燔祭的羊羔在哪里呢？</strong>'亚伯拉罕回答：'我儿，神必自己预备作燔祭的羊羔。'<br><br>当亚伯拉罕举刀的瞬间，天使呼喊：'不可在这童子身上下手！'树丛中有一只羊代替献祭。<br><br>克尔凯郭尔在《恐惧与战栗》中以此章为核心，论'信仰的骑士'——超越伦理普遍性的'目的论暂悬'。新约则视此为基督代死的预表（罗 8:32）。"
      },
      { id: "st-jacob", title: "雅各的天梯", sub: "天与地的连接点", ref: "创世记 28",
        detail: "雅各刚刚骗去哥哥的祝福，逃离家乡。在一处野地夜宿，<strong>用石头作枕</strong>。<br><br>梦中他见一个梯子立在地上，梯子的头顶着天，神的使者在梯子上上去下来。神立在梯子之上对他说话——重申给亚伯拉罕的应许，并应许必与他同在。<br><br>雅各醒了说：'<strong>这地方何等可畏！这不是别的，乃是神的殿，也是天的门</strong>'（28:17）。他把作枕的石头立起来作柱子，浇油在上面，称那地方为<strong>伯特利</strong>（'神的殿'）。<br><br>这个'天梯'意象在后来反复出现。耶稣在约翰福音 1:51 对拿但业说：'你将要看见天开了，神的使者上去下来在<strong>人子身上</strong>。'——耶稣自己就是天与地的连接点。"
      },
      { id: "st-josephegypt", title: "约瑟在埃及", sub: "护理在苦难中浮现", ref: "创世记 37–50",
        detail: "雅各的爱子约瑟（17 岁）做了两个梦——梦见哥哥们的禾捆向他下拜、梦见日月星辰向他下拜。<br><br>哥哥们恨他，骗父亲说被野兽吞了，把他卖给商队带到<strong>埃及</strong>。波提乏家中尽忠，被女主人诬陷下监；为狱友解梦显出神的恩赐。两年后法老做了关于七年丰荒的梦——召约瑟解，他被立为<strong>埃及的宰相</strong>，时年 30 岁。<br><br>七年丰收后饥荒来临。哥哥们到埃及买粮，不认得已成宰相的弟弟。约瑟逐步试探他们，最终在感情爆发中显明身份：'我是约瑟，你们的兄弟。'<br><br>面对哥哥们的恐惧，约瑟说：'<strong>从前你们的意思是要害我，但神的意思原是好的</strong>'（50:20）——基督教'神的护理'神学的最经典宣告。"
