/* =========================================================
   故事数据 · stories.js
   ========================================================= */

const STORIES_DATA = {
  old: {
    label: "旧约的核心叙事",
    items: [
      { id: "st-eden", title: "伊甸园", sub: "无瑕的开始与最初的失落", ref: "创世记 2–3",
        detail: "神在伊甸（'乐园'）中安置受造的人。园中有四条河流（其中两条至今仍存——底格里斯与幼发拉底）。神对人的命令简单：可以吃园中各样树上的果子，惟独'分别善恶树'的果子不可吃。<br><br>蛇引诱夏娃：'你们便如神能知道善恶。'夏娃和亚当吃了——眼睛'明亮'了，但发现自己赤身。神来时他们躲避；面对追问时彼此推卸。<br><br>神宣告咒诅，但其中也藏着应许——女人的后裔要伤蛇的头（3:15）。然后将他们逐出伊甸园，<strong>把守道路的基路伯</strong>把守生命树的路。<br><br>这一叙事的影响极深远：从奥古斯丁的'原罪论'到米尔顿的《失乐园》，到现代心理学对人之分裂的诊断。"
      },
      { id: "st-cain", title: "该隐与亚伯", sub: "罪从一代蔓延至下一代", ref: "创世记 4",
        detail: "亚当夏娃的两个儿子——该隐种地，亚伯牧羊。两人都向神献祭，亚伯的被神悦纳，该隐的不被悦纳。<br><br>神对该隐说话——这是圣经中最早的劝诫之一：'<strong>你若行得好，岂不蒙悦纳？你若行得不好，罪就伏在门前。它必恋慕你，你却要制伏它</strong>'（4:7）。<br><br>但该隐没有听。他把弟弟带到田里杀了。神质问'你兄弟在哪里？'——该隐的回答'我岂是看守我兄弟的吗？'成为人类自私的经典宣告。<br><br>该隐被驱逐，但神仍设立保护他的记号——审判中仍有怜悯。这一短短一章揭示罪的迅速蔓延：从违命到杀人只过了一代。"
      },
      { id: "st-noah", title: "挪亚方舟", sub: "在审判中保留余民", ref: "创世记 6–9",
        detail: "人类繁衍后罪也加增。'<strong>耶和华见人在地上罪恶很大，终日所思想的尽都是恶</strong>'（6:5）。神决定以洪水洁净世界，但拣选挪亚——他在那时代'是个义人，完全人，与神同行'。<br><br>方舟规格：长三百肘（约 137 米）、宽五十肘（23 米）、高三十肘（13.7 米）——三层。挪亚一家八口和各样动物进入。神亲手关上方舟的门。<br><br>洪水持续 40 昼夜，然后水退去 150 天。挪亚放鸽子三次试探——第二次衔回橄榄叶，第三次不再回来——表示陆地已干。<br><br>出方舟后挪亚献祭，神立约——以彩虹为记，应许不再以洪水灭世。这是<strong>圣经中第一次彩虹的出现</strong>，至今每次见到彩虹都唤起这一约的记忆。"
      },
      { id: "st-isaac", title: "献以撒", sub: "信心最深的张力", ref: "创世记 22",
        detail: "亚伯拉罕等候二十五年才得着应许的独子以撒。然后神的命令临到：'<strong>你带着你的儿子，就是你独生的儿子，你所爱的以撒，往摩利亚地去，在我所要指示你的山上，把他献为燔祭</strong>'（22:2）。<br><br>叙述异常沉默。亚伯拉罕没有讨价还价（与他为所多玛求情时形成对比）。他清晨起来，劈柴、备驴，三日的路程。<br><br>到山上，以撒问'<strong>燔祭的羊羔在哪里呢？</strong>'亚伯拉罕回答：'我儿，神必自己预备作燔祭的羊羔。'<br><br>当亚伯拉罕举刀的瞬间，天使呼喊：'不可在这童子身上下手！'树丛中有一只羊代替献祭。<br><br>克尔凯郭尔在《恐惧与战栗》中以此章为核心，论'信仰的骑士'——超越伦理普遍性的'目的论暂悬'。新约则视此为基督代死的预表（罗 8:32）。"
      },
      { id: "st-jacob", title: "雅各的天梯", sub: "天与地的连接点", ref: "创世记 28",
        detail: "雅各刚刚骗去哥哥的祝福，逃离家乡。在一处野地夜宿，<strong>用石头作枕</strong>。<br><br>梦中他见一个梯子立在地上，梯子的头顶着天，神的使者在梯子上上去下来。神立在梯子之上对他说话——重申给亚伯拉罕的应许，并应许必与他同在。<br><br>雅各醒了说：'<strong>这地方何等可畏！这不是别的，乃是神的殿，也是天的门</strong>'（28:17）。他把作枕的石头立起来作柱子，浇油在上面，称那地方为<strong>伯特利</strong>（'神的殿'）。<br><br>这个'天梯'意象在后来反复出现。耶稣在约翰福音 1:51 对拿但业说：'你将要看见天开了，神的使者上去下来在<strong>人子身上</strong>。'——耶稣自己就是天与地的连接点。"
      },
      { id: "st-josephegypt", title: "约瑟在埃及", sub: "护理在苦难中浮现", ref: "创世记 37–50",
        detail: "雅各的爱子约瑟（17 岁）做了两个梦——梦见哥哥们的禾捆向他下拜、梦见日月星辰向他下拜。<br><br>哥哥们恨他，骗父亲说被野兽吞了，把他卖给商队带到<strong>埃及</strong>。波提乏家中尽忠，被女主人诬陷下监；为狱友解梦显出神的恩赐。两年后法老做了关于七年丰荒的梦——召约瑟解，他被立为<strong>埃及的宰相</strong>，时年 30 岁。<br><br>七年丰收后饥荒来临。哥哥们到埃及买粮，不认得已成宰相的弟弟。约瑟逐步试探他们，最终在感情爆发中显明身份：'我是约瑟，你们的兄弟。'<br><br>面对哥哥们的恐惧，约瑟说：'<strong>从前你们的意思是要害我，但神的意思原是好的</strong>'（50:20）——基督教'神的护理'神学的最经典宣告。"
      },
      { id: "st-bush", title: "燃烧的荆棘", sub: "'我是自有永有的'", ref: "出埃及记 3",
        detail: "摩西从埃及王宫逃到米甸已四十年，作为牧羊人。一日他领羊群到何烈山，看见<strong>一处荆棘被火烧着却没有烧毁</strong>——他凑近看。<br><br>神从荆棘中呼叫：'摩西，摩西！…不要近前来，当把你脚上的鞋脱下来，因为你所站之地是圣地。'<br><br>神宣告：'我是你父亲的神'——并差他下去拯救以色列出埃及。<br><br>摩西问：他们若问'你父祖的神叫什么名字'，我要怎样回答？<br><br>神说：'<strong>我是自有永有的（'EHYEH ASHER 'EHYEH）。…你要对以色列人这样说：'那自有的（YHWH）打发我到你们这里来'</strong>'（3:14–15）。<br><br>这是<strong>YHWH</strong>（耶和华）这圣名的揭示——可译为'我是那我所是'或'我必是那我必是'。神不仅存在，而是自存的根源。后世神学和哲学（包括托马斯·阿奎那的'存在自身'神学）都从此节生发。"
      },
      { id: "st-redsea", title: "过红海", sub: "救赎的原型事件", ref: "出埃及记 14",
        detail: "十灾后法老让以色列出去，但又反悔，带战车六百辆追赶。以色列人到达<strong>红海</strong>边，前有水后有兵，惊慌呼叫。<br><br>摩西说：'<strong>不要惧怕！只管站住！看耶和华今天向你们所要施行的救恩</strong>'（14:13）。<br><br>夜里耶和华使大东风刮起，把海水分开。以色列人在干地上行走过海，水左右作墙垣。埃及军队追入海中，水回流将他们淹没。<br><br>米利暗（摩西的姐姐）领众妇女击鼓跳舞唱凯歌：'<strong>耶和华啊，神中谁能像你？</strong>'（出 15:11）<br><br>这成为旧约救赎的<strong>原型事件</strong>——后来诗篇、先知书反复回到这一时刻。新约则将其神学化：基督徒的洗礼对应过红海（林前 10:1–2），基督作为更深的'摩西'带领新出埃及。"
      },
      { id: "st-david", title: "大卫与歌利亚", sub: "弱小战胜强暴的范型", ref: "撒母耳记上 17",
        detail: "非利士人侵入以色列，他们的勇士<strong>歌利亚</strong>（约 3 米高）每日叫阵——四十天没有人敢应战。<br><br>少年牧童大卫给前线的哥哥送饭，听见歌利亚辱骂神。他自告奋勇出战。扫罗给他穿铠甲，他穿不惯就脱了。<br><br>大卫只带<strong>牧人的杖、五块光滑石子、机弦</strong>。歌利亚见他是个少年，不屑一顾。<br><br>大卫的回答振聋发聩：'<strong>你来攻击我，是靠着刀枪和铜戟；我来攻击你，是靠着万军之耶和华的名</strong>'（17:45）。<br><br>他迎面奔向歌利亚，从囊中取石、机弦一甩——石子击中歌利亚的额头，歌利亚仆倒。大卫拔出歌利亚自己的刀割下他的头。<br><br>这一故事成为'<strong>弱小者战胜强暴</strong>'的永恒典范——西方文化中无数处境用'David vs Goliath'来比喻。"
      },
      { id: "st-solomon", title: "所罗门的智慧", sub: "两妇争子的审判", ref: "列王纪上 3",
        detail: "所罗门继位后，神在梦中向他显现：'你愿我赐你什么？'<br><br>所罗门没有求长寿、富贵、敌人之命，而是求'<strong>智慧可以判断你的民，能辨别是非</strong>'（王上 3:9）。神大悦，应许赐他空前的智慧——并加添他没有求的财富与尊荣。<br><br>不久之后，两个妓女来争抢一婴孩——双方都说是自己的儿子，对方夜里把死婴换了她的活婴。所罗门下令：'拿刀来！把活孩子劈成两半，一半给这个，一半给那个。'<br><br>真母亲心如刀绞——'求我主，把活孩子给那妇人吧，万不可杀他！'另一个说：'这孩子也不归我，也不归你，把他劈了吧！'<br><br>所罗门立刻判定：把孩子给前者——'她就是他的母亲。'<br><br>这一判决传遍以色列，百姓敬畏这王，因看出'<strong>神的智慧在他里面</strong>'。"
      },
      { id: "st-elijah", title: "迦密山对决", sub: "真神与假神的较量", ref: "列王纪上 18",
        detail: "亚哈王和耶洗别在北国推行巴力崇拜。以利亚向王宣告：'我若不祷告，这些年必不降露不下雨。'三年半后回来——召集巴力的 450 位先知到迦密山对决。<br><br>规则：双方各预备一只公牛放在柴上，但不点火。哪位神降下火来烧尽祭物，哪位就是真神。<br><br>巴力先知从早到中午呼求'巴力啊，求你应允我们！'又呼号又用刀枪自刺血流满身——毫无回应。以利亚讥讽：'<strong>大声求告吧！…他或默想、或走到一边、或行路、或睡觉，你们当叫醒他</strong>'（18:27）。<br><br>到了晚祭时分，以利亚修筑耶和华的坛，浇水浇透三遍（共十二桶）。然后短短祷告：<br><br>'耶和华啊，求你应允我！应允我！使这民知道你耶和华是神。'<br><br>耶和华降下火来，<strong>烧尽祭物、木柴、石头、尘土，连沟里的水也烧干了</strong>。"
      },
      { id: "st-daniel", title: "但以理在狮坑", sub: "在异乡的忠贞", ref: "但以理书 6",
        detail: "但以理在波斯王大利乌朝中位高权重。同僚嫉妒，想找把柄不得——他们看出'必须从他神的律法中找题目'，遂设阴谋。<br><br>他们怂恿王下诏：三十日内，谁向除王以外的神祈求，必扔在狮子坑中。诏书一颁就不可更改。<br><br>但以理知道后，<strong>仍照素常一日三次开窗朝耶路撒冷祷告</strong>。被告发。王心中愁烦想救他——但律法不可改。<br><br>但以理被扔下狮坑，王封住坑口。王整夜禁食，不能入睡。次日清晨急忙到狮坑，哀声呼问：'你所事奉的神能救你吗？'<br><br>但以理回答：'<strong>我的神差遣使者封住狮子的口，叫狮子不伤我</strong>'（6:22）。<br><br>但以理被拉出来——身上毫无伤损，'<strong>因为信靠他的神</strong>'。"
      },
      { id: "st-jonah", title: "约拿与大鱼", sub: "神慈爱及于仇敌", ref: "约拿书",
        detail: "神命约拿去亚述首都<strong>尼尼微</strong>——以色列的最大仇敌——传警告。约拿不愿，逃向相反方向，乘船去他施。<br><br>海上起大风暴。水手抽签——签落在约拿身上。约拿承认：'<strong>我是希伯来人，我敬畏耶和华——那创造沧海旱地之天上的神</strong>'（1:9）。他自请被抛入海。海立刻平静。<br><br>耶和华<strong>预备一条大鱼</strong>吞了约拿。约拿在鱼腹中三日三夜祷告。鱼把他吐在岸上。<br><br>第二次蒙召时，约拿勉强去了——只宣告短短一句'再四十日，尼尼微必倾覆'。结果<strong>整城从王到牲畜都披麻悔改</strong>。神就免去灾祸。<br><br>约拿大怒：'我知道你是有恩典、有怜悯的神，所以我才逃。'神最后用一棵植物的兴衰教训他——你为一棵蓖麻树发愁，'<strong>何况这尼尼微大城，其中不能分辨左手右手的有十二万多人</strong>'？<br><br>耶稣以约拿三日在鱼腹为自己受死复活的预表（太 12:39–40）。"
      }
    ]
  },
  new: {
    label: "新约的核心叙事",
    items: [
      { id: "st-nativity", title: "基督降生", sub: "马槽中的王", ref: "路加福音 1–2，马太福音 1–2",
        detail: "<strong>路加</strong>的笔触：天使加百列向尚未出嫁的童女<strong>马利亚</strong>报喜——她要怀一子，给他起名耶稣，'<strong>他要为大，称为至高者的儿子</strong>'。马利亚问'我没有出嫁，怎么有这事呢？'天使回答圣灵要临到你。马利亚说：'<strong>我是主的使女，情愿照你的话成就在我身上</strong>。'<br><br>因罗马的户口登记，已订婚的约瑟带怀孕的马利亚回到祖籍伯利恒。客店没地方，孩子生在<strong>马槽</strong>里。<br><br>夜间野外的牧羊人忽然天使显现：'<strong>我报给你们大喜的信息，是关乎万民的</strong>'——天兵一同赞美。<br><br><strong>马太</strong>的笔触不同：东方博士（magi）跟随星辰来朝，但希律王听闻后心里不安，下令屠杀伯利恒所有两岁以下男婴。约瑟得天使指示，带圣家逃往埃及。<br><br>两本福音书都强调：这位婴孩是<strong>'要应验主借先知所说的话'</strong>——以马内利、和平之子、伯利恒的君王。"
      },
      { id: "st-sermon", title: "登山宝训", sub: "天国的伦理宪章", ref: "马太福音 5–7",
        detail: "耶稣事工早期，见许多人就上了山，门徒环绕。他开始教导，<strong>《登山宝训》</strong>——共三章，是耶稣最长的连续讲论。<br><br>开篇是'<strong>八福</strong>'：虚心的人、哀恸的人、温柔的人、饥渴慕义的人、怜恤人的、清心的、使人和睦的、为义受逼迫的——一一指为'有福了'。这彻底翻转了人世对'幸福'的标准。<br><br>接着耶稣论：盐与光、律法的真意、'六个反题'（'你们听见有话说…只是我告诉你们…'——杀人/愤怒、奸淫/动淫念、起誓、报复、爱仇敌等）、施舍祷告禁食的真心、不能事奉两个主、不要忧虑、不要论断、求就给你们、窄门、好树坏树、根基（'<strong>聪明人把房子盖在磐石上</strong>'）。<br><br>'<strong>主祷文</strong>'位于本讲论中央（6:9–13）。<br><br>结尾众人'希奇他的教训，因为他教训他们正像有权柄的人，不像他们的文士'（7:28–29）。这一篇章被无数后世人——从托尔斯泰到甘地——视为人类伦理的最高表述。"
      },
      { id: "st-feeding", title: "五饼二鱼", sub: "出现在四福音的神迹", ref: "马太 14、马可 6、路加 9、约翰 6",
        detail: "<strong>这是耶稣的神迹中唯一被四本福音书都记载的</strong>——可见其重要性。<br><br>耶稣听见施洗约翰的死讯，独自退到旷野。但群众跟随他来——耶稣怜悯他们，整日教导。日落时门徒说：'天已晚了，请散开众人，让他们自己买吃的。'<br><br>耶稣说：'你们给他们吃吧。'门徒答：我们这里只有<strong>五个饼、两条鱼</strong>。<br><br>耶稣令众人坐在草地上（约 5000 男人，加上妇女孩子可能 1.5 万人）。他<strong>拿起、祝谢、擘开、递给</strong>门徒——这一组动作是后来圣餐的原型。<br><br>众人都吃饱了，剩下零碎收拾起来装满<strong>十二个篮子</strong>。<br><br>约翰福音特别记载这神迹后耶稣的'<strong>生命之粮</strong>'讲论（约 6 章）——'我就是生命的粮…吃这粮的就必永远活着。'物质的吃饱指向更深的灵粮。"
      },
      { id: "st-lazarus", title: "拉撒路复活", sub: "复活与生命的预表", ref: "约翰福音 11",
        detail: "马大、马利亚的弟弟<strong>拉撒路</strong>病重。她们差人告诉耶稣：'你所爱的人病了。'但耶稣故意延迟两日才动身。<br><br>到达伯大尼时，拉撒路<strong>已经在坟墓里四天</strong>。马大出来迎接——'主啊，你若早在这里，我兄弟必不死。'耶稣对她说：<br><br>'<strong>复活在我，生命也在我；信我的人虽然死了，也必复活。凡活着信我的人，必永远不死。你信这话吗？</strong>'（11:25–26）<br><br>耶稣到坟墓前——这是约翰福音最深的一刻：'<strong>耶稣哭了</strong>'（11:35，圣经最短的一节）。神子在面对死亡的真实痛苦中流泪。<br><br>耶稣命人挪开坟石——马大说'已经臭了'。耶稣大声呼叫：'<strong>拉撒路，出来！</strong>'<br><br>那死人手脚裹着布，脸上包着手巾，就出来了。耶稣说：'解开，叫他走！'<br><br>这神迹直接引发祭司决定要杀耶稣——也成为他自己复活的预告。"
      },
      { id: "st-supper", title: "最后晚餐", sub: "新约的设立", ref: "马太 26、马可 14、路加 22、约翰 13",
        detail: "受难前的<strong>逾越节</strong>，耶稣与十二门徒共进晚餐。约翰福音特别记载耶稣<strong>洗门徒的脚</strong>——主的姿态翻转——给彼得带来强烈的张力。<br><br>用餐中耶稣说：'你们中间有一个要卖我了。'门徒一一问'主，是我吗？'犹大也问，耶稣回答'你说的是'，犹大就出去了。<br><br>然后耶稣<strong>设立圣餐</strong>：<br><br>他<strong>拿起饼来，祝谢了，擘开，递给门徒</strong>说：'<strong>这是我的身体，为你们舍的；你们应当如此行，为的是记念我。</strong>'<br><br>饭后又拿起杯来，说：'<strong>这杯是用我的血所立的新约，是为你们流出来的。</strong>'<br><br>这是<strong>耶利米书 31:31 '新约'</strong>预言的应验时刻——基督的死立约，以他的血代替西奈山的牛羊之血。圣餐至今每周在全球教会中持续进行。<br><br>晚餐后他们到客西马尼园。"
      },
      { id: "st-gethsemane", title: "客西马尼园", sub: "'不要照我的意思'", ref: "马太 26、马可 14、路加 22",
        detail: "客西马尼（'榨橄榄油'之意）是橄榄山下的一处园子。耶稣常去那里。受难前夜，他带门徒到那里——彼得、雅各、约翰跟随更近。<br><br>'<strong>我心里甚是忧伤，几乎要死</strong>'，他对他们说，'你们在这里等候，和我一同警醒。'<br><br>他稍往前走，<strong>俯伏在地</strong>祷告：<br><br>'<strong>我父啊，倘若可行，求你叫这杯离开我。然而，不要照我的意思，只要照你的意思。</strong>'（太 26:39）<br><br>路加记载：'他的汗珠如大血点，滴在地上'（路 22:44）——这是医生路加观察到的<strong>血汗症</strong>，极度精神压力下的生理反应。<br><br>三次回来都见门徒睡着了——'<strong>你们与我一同警醒，竟不能片时吗？</strong>'<br><br>第三次祷告完，犹大带兵丁来到。犹大用亲嘴的暗号识别耶稣。耶稣不抵抗，束手就擒。彼得当时拔刀砍了大祭司仆人的耳朵，耶稣摸着那耳朵医好他——临难前最后的怜悯。"
      },
      { id: "st-cross", title: "十字架与复活", sub: "救赎的完成", ref: "四福音书",
        detail: "经过夜审（大祭司家）和晨审（公会）后，耶稣被交给罗马总督<strong>彼拉多</strong>。彼拉多查不出他什么罪，但群众喊'钉他十字架！'彼拉多洗手表示无辜，把耶稣鞭打、嘲弄、戴荆棘冠、披紫袍、然后交给士兵钉十字架。<br><br>地点是<strong>各各他</strong>（'髑髅地'）。从早晨九时（'巳初'）钉到下午三时（'申初'）。期间七句话被记下，称为'<strong>十架七言</strong>'：<br><br>① '父啊，赦免他们…'<br>② '今日你要同我在乐园里了'（对悔改的强盗）<br>③ '母亲，看你的儿子'（托付马利亚给约翰）<br>④ '<strong>我的神，我的神，为什么离弃我？</strong>'（引诗篇 22:1）<br>⑤ '我渴了'<br>⑥ '<strong>成了！</strong>'<br>⑦ '父啊，我将我的灵魂交在你手里'<br><br>耶稣气绝。圣殿幔子从上到下裂为两半——隔开至圣所与圣所的幔子，象征'<strong>到神面前的路已开</strong>'。<br><br>第三日清晨，妇女们到坟墓——<strong>坟墓是空的</strong>。天使说：'他不在这里，照他所说的，已经复活了。'之后耶稣多次显现——向抹大拉的马利亚、以马忤斯路上的两人、聚集的门徒、多马、海边的彼得。四十日后他升天，应许差圣灵来。"
      },
      { id: "st-damascus", title: "大马色路上", sub: "逼迫者成了使徒", ref: "使徒行传 9",
        detail: "<strong>扫罗</strong>是耶路撒冷敬虔派系的法利赛人，迦玛列门下。他憎恶'拿撒勒人耶稣'之道，亲自参与司提反殉道（保管打死司提反之人的衣服）。<br><br>他向大祭司请文书，要去大马色搜捕基督徒。<br><br>临近大马色时，<strong>忽然从天上发光，四面照着他</strong>。他仆倒在地，听见声音说：<br><br>'<strong>扫罗，扫罗，你为什么逼迫我？</strong>'<br><br>他说：'主啊，你是谁？'<br><br>'<strong>我就是你所逼迫的耶稣</strong>。'<br><br>扫罗瞎了眼睛，三日不吃不喝。<br><br>主指示一位门徒亚拿尼亚去为他祷告。亚拿尼亚不情愿——这人是大恶人。但主说：'<strong>这人是我所拣选的器皿，要在外邦人和君王并以色列人面前宣扬我的名。</strong>'<br><br>亚拿尼亚去为他按手，扫罗的眼立时复明。受洗。立刻在会堂传讲耶稣是神的儿子。<br><br>这位扫罗后来名叫<strong>保罗</strong>——成为外邦人的使徒，写下新约 13 卷书信。<br><br>对早期教会而言，最大的逼迫者归向基督，本身就是复活信实最有力的证据之一。"
      }
    ]
  }
};

files.content:
/* =========================================================
   主题数据 · themes.js
   8 个贯穿整本圣经的核心主题
   ========================================================= */

const THEMES_DATA = [
  {
    id: "th-covenant",
    name: "约 (Covenant)",
    brief: "贯穿整本圣经的结构骨架——神主动与人立约的奇迹",
    detail: "<strong>'约'（希伯来 berit、希腊 diathēkē）是整本圣经的结构骨架</strong>——'圣经'（Testament）一词本身就是'约'的意思，'旧约/新约'即'旧的盟约/新的盟约'。<br><br>圣经神学传统识别出五大盟约：<br>① <strong>挪亚之约</strong>（创 9）——普世性，以彩虹为记<br>② <strong>亚伯拉罕之约</strong>（创 15, 17）——应许土地、后裔、祝福，以割礼为记<br>③ <strong>西奈/摩西之约</strong>（出 19–24）——条件性的国家盟约，以律法为根本<br>④ <strong>大卫之约</strong>（撒下 7）——王朝永久性的应许<br>⑤ <strong>新约</strong>（耶 31，太 26）——内化的律法，靠基督的血<br><br>约不是合同（contract，对等交换）而是<strong>盟约</strong>（covenant，存在性的相互归属）——婚姻是其最贴近的人间映像。<br><br>这一概念框架的深刻处在于：神是一位<strong>守约的神</strong>——他的可信赖性不是抽象属性，而是历史性的承诺。"
  },
  {
    id: "th-redemption",
    name: "救赎 (Redemption)",
    brief: "圣经的中心动作——从奴役到自由，从死亡到生命",
    detail: "希伯来 ga'al（赎回）原指<strong>近亲赎业者</strong>（kinsman-redeemer）——当一个人因贫穷卖身或卖地，他的近亲有责任以自己的财物赎回。<br><br>这是路得记中波阿斯的角色——他赎回路得和拿俄米的产业。<br><br>这一日常法律概念被神学化：<br>• <strong>出埃及</strong>是'赎回'的原型——'<strong>耶和华用大能的手将你们从为奴之家领出来，脱离埃及王法老的手</strong>'（申 7:8）<br>• <strong>十字架</strong>是更深的赎回——'<strong>你们得赎，脱去你们祖宗所传流虚妄的行为，不是凭着能坏的金银等物，乃是凭着基督的宝血</strong>'（彼前 1:18–19）<br><br>救赎的逻辑：人陷于不能自救的境况；需要外部的代价介入；这代价由有能力且愿意的'近亲'付出。<br><br>'<strong>我们藉这爱子的血得蒙救赎，过犯得以赦免</strong>'（弗 1:7）——救赎与赦免相连，但救赎更强调'代价已付'的客观维度。"
  },
  {
    id: "th-messiah",
    name: "弥赛亚 (Messiah)",
    brief: "受膏者，从大卫的子孙到神的儿子",
    detail: "希伯来 mashiach 意为'<strong>受膏者</strong>'，希腊文译作 Christos——故'基督'即'弥赛亚'。<br><br>旧约中受膏的有三种角色：<strong>祭司</strong>、<strong>君王</strong>、<strong>先知</strong>。耶稣身上汇聚了这三重职分——希伯来书详尽论证他是更大的祭司，福音书呈现他是大卫之子的王，他自己也行先知的角色。<br><br>弥赛亚预言的旧约根源：<br>• <strong>女人的后裔</strong>（创 3:15）——最早预表<br>• <strong>亚伯拉罕的后裔</strong>（创 22:18）<br>• <strong>犹大的杖</strong>（创 49:10）<br>• <strong>大卫的子孙</strong>（撒下 7:12–13）<br>• <strong>童女生子</strong>（赛 7:14）<br>• <strong>受苦的仆人</strong>（赛 53）<br>• <strong>伯利恒生</strong>（弥 5:2）<br>• <strong>骑驴进城</strong>（亚 9:9）<br><br>第二圣殿时期的犹太人对弥赛亚有<strong>多重期待</strong>——政治军事的解放者、祭司性的洁净者、启示性的人子等。耶稣身上的张力部分来自他不符合任何单一期待——他来作'<strong>受苦的仆人</strong>'，这是连门徒都难以接受的。"
  },
  {
    id: "th-kingdom",
    name: "神的国 (Kingdom of God)",
    brief: "耶稣讲道的中心——已然临到却尚未完全",
    detail: "在四福音中，'<strong>神的国</strong>'（或马太常用的'天国'，因犹太人避讳直呼'神'之名）是耶稣讲道的<strong>中心</strong>主题——出现 100 多次。<br><br>耶稣开始事工的宣告：'<strong>日期满了，神的国近了。你们当悔改，信福音</strong>'（可 1:15）。<br><br>这'国'不是地理国家，而是<strong>神的统治</strong>（reign）——他的旨意被遵行的领域。<br><br>新约神学最深的张力之一是<strong>'已然但尚未'</strong>（already but not yet）——<br>• <strong>已然临到</strong>：在耶稣身上、通过他的事工与教会，神的国已经入侵这世界<br>• <strong>尚未完全</strong>：等到基督再来，神的国才完全显明<br><br>主祷文的祷告——'<strong>愿你的国降临，愿你的旨意行在地上，如同行在天上</strong>'——同时是请求和确信。<br><br>登山宝训呈现神国子民的伦理——温柔、虚心、使人和睦的有福了。这不是'进国的条件'，而是'国子民的标志'。"
  },
  {
    id: "th-holiness",
    name: "圣洁 (Holiness)",
    brief: "神的本性与子民的呼召——分别为圣",
    detail: "希伯来 qadosh（圣洁）原意是<strong>'分别出来'</strong>——既指与平凡的分别，也指与不洁、罪恶的分别。<br><br>这是描述神最核心的形容词。在以赛亚的异象中，撒拉弗呼喊：'<strong>圣哉、圣哉、圣哉，万军之耶和华</strong>'（赛 6:3）——希伯来文用三次重复表达至高级。'圣哉'是圣经中唯一被三次重复的属性。<br><br>圣洁不仅是道德高尚，而是一种<strong>本体上的他者性</strong>（otherness）——神是<strong>全然他者</strong>，与受造物根本不同。这是为何亲近神是危险的（乌撒触摸约柜即死，撒下 6 章）。<br><br>神向他的子民发出召唤：'<strong>你们要圣洁，因为我耶和华你们的神是圣洁的</strong>'（利 11:45，被彼前 1:16 引用）。<br><br>圣洁是<strong>存在性的呼召</strong>——不是一系列规条，而是被神塑造、与世界有所区别地活着。利未记的礼仪体系（洁与不洁）是这一存在性差异的具体表达。<br><br>在哲学层面，这与你曾思考的'语言/工具的极限'有遥相呼应——神之圣洁意味着他在某种意义上溢出了人的认知工具。"
  },
  {
    id: "th-faith",
    name: "信心 (Faith)",
    brief: "亚伯拉罕到希伯来书 11 章——以信靠应答应许",
    detail: "希伯来 'emunah 兼具'信仰'和'忠信'两层意思——既是相信，也是被信。希腊 pistis 同此结构。<br><br>圣经的'信心'<strong>不是缺乏证据的盲目接受</strong>，而是在<strong>有限信息下的存在性托付</strong>——以神的话语为基础，作出指向未来的行动。<br><br>典范是亚伯拉罕——他离开本地，'<strong>出去的时候，还不知往哪里去</strong>'（来 11:8）。'<strong>亚伯拉罕信耶和华，耶和华就以此为他的义</strong>'（创 15:6）——这一节是新约'因信称义'的旧约根基。<br><br>希伯来书 11 章的'<strong>信心英雄殿</strong>'回顾——亚伯、以诺、挪亚、亚伯拉罕、撒拉、雅各、约瑟、摩西、喇合等——每一位都'<strong>因信</strong>…作了某事'。这一章给出最经典的信心定义：'<strong>信就是所望之事的实底，是未见之事的确据</strong>'（11:1）。<br><br>新约把因信称义推到极致——'<strong>义人必因信得生</strong>'（哈 2:4，被罗 1:17、加 3:11、来 10:38 三次引用，是宗教改革的核心经文）。<br><br>但'信'与'行'不分割：'<strong>信心若没有行为就是死的</strong>'（雅 2:17）。真正的信心必结出行动的果子——这不是赚取救恩，而是救恩的标志。"
  },
  {
    id: "th-grace",
    name: "恩典 (Grace)",
    brief: "白白的、不配得的爱——基督教神学的中心",
    detail: "希腊 charis（恩典）与 charizomai（白白赐予）同根。希伯来对应词 hen（恩惠）、hesed（盟约性的慈爱）。<br><br>恩典的核心定义：<strong>不配得的恩待</strong>。它不是奖赏给值得的人，而是赐给不值得的人。<br><br>奥古斯丁、马丁·路德、约翰·加尔文都视恩典为基督教神学的<strong>中心</strong>——一切其他教义都从这里展开。<br><br>关键经文：<br>• '<strong>你们得救是本乎恩，也因着信。这并不是出于自己，乃是神所赐的</strong>'（弗 2:8）<br>• '<strong>就如经上所记：'没有义人，连一个也没有…'…如今却蒙神的恩典，因基督耶稣的救赎，就白白地称义</strong>'（罗 3:10, 24）<br>• '<strong>我成了今日的我，是蒙神的恩</strong>'（保罗自陈，林前 15:10）<br><br>恩典的'<strong>白白性</strong>'是其根本——一旦它必须被赚取，它就不是恩典了。但这不意味着对人的回应没有要求——蒙了恩典的人会被改变，活出感恩的生活。<br><br>潘霍华（Bonhoeffer）警告'<strong>廉价的恩典</strong>'——把恩典变成不要求悔改、改变、十字架的轻飘宽容；他主张'<strong>重价的恩典</strong>'——它是免费的，但代价是基督的命。"
  },
  {
    id: "th-creation",
    name: "创造与新创造 (Creation & New Creation)",
    brief: "圣经的弧线——从伊甸到新耶路撒冷",
    detail: "圣经以创造开始（创 1–2），以新创造结束（启 21–22）——这<strong>大弧线</strong>是整本圣经的形而上结构。<br><br>开端的伊甸园：神与人同在，没有死亡、痛苦、哀哭，生命树在园中。<br><br>因人的堕落，受造界进入'<strong>败坏的辖制</strong>'（罗 8:21）——保罗用拟人化的语言说万物'<strong>叹息</strong>'，等候得赎。<br><br>新约多处表达<strong>新创造</strong>已经在基督里开始：<br>• '<strong>若有人在基督里，他就是新造的人——旧事已过，都变成新的了</strong>'（林后 5:17）<br>• '<strong>受造之物切望等候神的众子显出来…脱离败坏的辖制，得享神儿女自由的荣耀</strong>'（罗 8:19, 21）<br><br>启示录 21–22 章的<strong>新天新地</strong>异象——新耶路撒冷从天而降，神的帐幕在人间，神要擦去他们一切的眼泪。生命树重现（'树上的叶子乃为医治万民'），咒诅完全被除。<br><br>这一弧线的形态学意义深远：<strong>救赎不仅是'回到伊甸'，而是更高一级——从'未受试炼的纯真'到'经过赎回的荣耀'</strong>。新耶路撒冷不是花园，而是城市——文化、艺术、各国的尊贵都进入其中。<br><br>这意味着创造本身有目的论方向——它不是循环回归，而是螺旋上升。这与你曾接触的几种历史哲学（黑格尔的辩证、近代进化论）形成对比性的对话。"
  }
];

