/* =========================================================
   主题数据 · themes.js
   8 个贯穿整本圣经的核心主题
   ========================================================= */

const THEMES_DATA = [
  {
    id: "th-covenant",
    name: "约 (Covenant)",
    brief: "贯穿整本圣经的结构骨架——神主动与人立约的奇迹",
    detail: "<strong>'约'（希伯来 berit、希腊 diathēkē）是整本圣经的结构骨架</strong>——'圣经'（Testament）一词本身就是'约'的意思，'旧约/新约'即'旧的盟约/新的盟约'。<br><br>圣经神学传统识别出五大盟约：<br>① <strong>挪亚之约</strong>（创 9）——普世性，以彩虹为记<br>② <strong>亚伯拉罕之约</strong>（创 15, 17）——应许土地、后裔、祝福，以割礼为记<br>③ <strong>西奈/摩西之约</strong>（出 19–24）——条件性的国家盟约，以律法为根本<br>④ <strong>大卫之约</strong>（撒下 7）——王朝永久性的应许<br>⑤ <strong>新约</strong>（耶 31，太 26）——内化的律法，靠基督的血<br><br>约不是合同（contract，对等交换）而是<strong>盟约</strong>（covenant，存在性的相互归属）——婚姻是其最贴近的人间映像。<br><br>这一概念框架的深刻处在于：神是一位<strong>守约的神</strong>——他的可信赖性不是抽象属性，而是历史性的承诺。"
  },
