/* =========================================================
   时间线数据 · timeline.js
   ========================================================= */

const TIMELINE_DATA = [
  {
    era: "Primeval History",
    eraTitle: "原初时期 · 创世记 1–11",
    events: [
      { id: "tl-creation", title: "创造天地", brief: "六日造物，第七日安息；人按神的形像被造", ref: "创世记 1–2",
        detail: "圣经的开篇宣告：'起初，神创造天地。'（创 1:1）<br><br>创造叙事呈现高度的诗性结构——前三日造场所（光与暗、水与气、地与海），后三日造充满者（日月星、鱼鸟、地上动物与人）。第七日神安息——这成为后来安息日命令的根基。<br><br>关键神学：<strong>世界不是必然的</strong>，而是神出于自由意志的创造；<strong>不是邪恶的</strong>（连说七次'神看着是好的'）；<strong>有秩序而非混沌</strong>。这与古代近东其他创造神话（如《埃努玛·埃利什》中众神争斗造世界）形成强烈对比。<br><br>人按神的形像被造（1:26–27）——这一句奠定了所有圣经人观与人权伦理的根基。"
      },
      { id: "tl-fall", title: "人的堕落", brief: "始祖违命；人与神、人与人、人与自然的关系破裂", ref: "创世记 3",
        detail: "蛇引诱，违命，吃禁果——叙述简洁却影响深远。<br><br>堕落不仅是道德犯错，而是<strong>关系的全面破裂</strong>：人与神（躲避神）、人与自我（羞耻、遮蔽）、人与他人（亚当指责夏娃）、人与自然（地受咒诅，劳苦才得粮食）、人与自身存在（必归于尘土）。<br><br>但 3:15 已埋下盼望之线——女人的后裔要伤蛇的头，传统称之为'<strong>原始福音</strong>'（Protoevangelium）。<br><br>奥古斯丁的'原罪'神学、保罗罗马书 5 章的'一人犯罪'论述，都从此章生发。在你曾思考的'人之困境'议题上，这一章是西方思想史上最具结构性的诊断之一。"
