  },
  {
    id: 4,
    label: "演变为 Gamma Squeeze",
    color: "#a855f7",
    icon: "🌪️",
    desc: "股价上涨 → Delta 从0.4升至0.6 → 做市商还需追买200万股 → 股价再涨 → 形成正反馈死亡螺旋（尾巴摇狗）",
    mmShares: 6000000,
    optionVolume: 100000,
    priceLevel: "极高",
  },
];

function generatePriceData(stage) {
  return Array.from({ length: 61 }, (_, i) => {
    const t = i / 60;
    let price, askLiquidity, bidLiquidity, delta;

    if (stage === 0) {
      price = 50 + Math.sin(t * 6) * 1.5;
      askLiquidity = 80 + Math.sin(t * 4) * 5;
      bidLiquidity = 78 + Math.cos(t * 4) * 5;
      delta = 0.35 + Math.sin(t * 3) * 0.02;
    } else if (stage === 1) {
      price = 50 + t * 2;
      askLiquidity = 80 - t * 40;
      bidLiquidity = 78 + t * 5;
      delta = 0.35 + t * 0.05;
    } else if (stage === 2) {
      price = 52 + t * 8;
      askLiquidity = Math.max(5, 40 - t * 60);
      bidLiquidity = 83 + t * 10;
      delta = 0.4 + t * 0.1;
    } else if (stage === 3) {
      const acc = Math.pow(t, 0.7);
      price = 60 + acc * 40;
      askLiquidity = Math.max(2, 10 - t * 15);
      bidLiquidity = 93 + acc * 30;
      delta = 0.5 + acc * 0.3;
    } else {
      const acc = Math.pow(t, 0.6);
      price = 100 + acc * 100;
      askLiquidity = Math.max(1, 5 - t * 8);
      bidLiquidity = 123 + acc * 80;
      delta = Math.min(0.98, 0.8 + acc * 0.18);
    }

    return {
      t: i,
      price: Math.round(price * 10) / 10,
      askLiquidity: Math.max(0, Math.round(askLiquidity)),
      bidLiquidity: Math.round(bidLiquidity),
      delta: Math.round(Math.min(delta, 0.99) * 100) / 100,
    };
  });
}

function generateHedgeData(stage) {
  // Bar chart: required hedge shares over time
  return Array.from({ length: 20 }, (_, i) => {
    const t = i / 19;
    let required, actual;
    if (stage === 0) { required = 50; actual = 50; }
    else if (stage === 1) { required = 50 + t * 350; actual = 50; }
    else if (stage === 2) { required = 400; actual = 50 + t * 350; }
    else if (stage === 3) { required = 400 + t * 50; actual = 400; }
    else { required = 600; actual = 400 + t * 200; }
    return {
      t: Math.round(t * 100),
      required: Math.round(required),
      actual: Math.round(actual),
      gap: Math.max(0, Math.round(required - actual)),
    };
  });
}

