// Shuffle helper
function shuffle(arr) {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

// Generate quiz options from a card
function generateOptions(card, allCards) {
  const sameCategory = allCards.filter(c => c.cat === card.cat && c.q !== card.q);
  const others = shuffle(sameCategory).slice(0, 3).map(c => c.a);
  // Ensure we have 4 unique options
  const allOthers = shuffle(allCards.filter(c => c.q !== card.q));
  while (others.length < 3) {
    const candidate = allOthers.pop();
    if (candidate && !others.includes(candidate.a) && candidate.a !== card.a) {
      others.push(candidate.a);
    }
  }
  const options = shuffle([card.a, ...others.slice(0, 3)]);
  return options;
}

// ==================== COMPONENTS ====================

function ProgressRing({ percent, size = 48, stroke = 4, color }) {
  const r = (size - stroke) / 2;
  const circ = 2 * Math.PI * r;
  const offset = circ - (percent / 100) * circ;
  return (
    <svg width={size} height={size} style={{ transform: "rotate(-90deg)" }}>
      <circle cx={size/2} cy={size/2} r={r} fill="none" stroke="rgba(255,255,255,0.15)" strokeWidth={stroke} />
      <circle cx={size/2} cy={size/2} r={r} fill="none" stroke={color || "#fff"} strokeWidth={stroke}
        strokeDasharray={circ} strokeDashoffset={offset} strokeLinecap="round"
        style={{ transition: "stroke-dashoffset 0.5s ease" }} />
    </svg>
  );
}

