  const [quizOptions, setQuizOptions] = useState([]);
  const [selected, setSelected] = useState(null);
  const [score, setScore] = useState(0);
  const [wrongCards, setWrongCards] = useState([]);
  const [showHint, setShowHint] = useState(false);
  const [streak, setStreak] = useState(0);
  const [bestStreak, setBestStreak] = useState(0);
  const [animateCorrect, setAnimateCorrect] = useState(false);
  const [animateWrong, setAnimateWrong] = useState(false);
  const [totalAnswered, setTotalAnswered] = useState(0);

  const startSession = (cats, sessionMode) => {
    const filtered = cats.length > 0 ? ALL_CARDS.filter(c => cats.includes(c.cat)) : ALL_CARDS;
    const shuffled = shuffle(filtered);
    setCards(shuffled);
    setIdx(0);
    setFlipped(false);
    setSelected(null);
    setScore(0);
    setWrongCards([]);
    setShowHint(false);
    setStreak(0);
    setTotalAnswered(0);
    setMode(sessionMode);
    if (sessionMode === "quiz") {
      setQuizOptions(generateOptions(shuffled[0], ALL_CARDS));
    }
  };

  const nextCard = () => {
    if (idx + 1 >= cards.length) {
      setMode("results");
      return;
    }
    const nextIdx = idx + 1;
    setIdx(nextIdx);
    setFlipped(false);
    setSelected(null);
    setShowHint(false);
    setAnimateCorrect(false);
    setAnimateWrong(false);
    if (mode === "quiz") {
      setQuizOptions(generateOptions(cards[nextIdx], ALL_CARDS));
    }
  };

  const handleQuizSelect = (opt) => {
    if (selected !== null) return;
    setSelected(opt);
    setTotalAnswered(t => t + 1);
    if (opt === cards[idx].a) {
      setScore(s => s + 1);
      setStreak(s => {
        const ns = s + 1;
        if (ns > bestStreak) setBestStreak(ns);
        return ns;
      });
      setAnimateCorrect(true);
    } else {
      setStreak(0);
      setWrongCards(w => [...w, cards[idx]]);
      setAnimateWrong(true);
    }
  };

  const card = cards[idx];
  const progress = cards.length > 0 ? ((idx + 1) / cards.length) * 100 : 0;

  // ==================== STYLES ====================
  const font = "'Noto Sans SC', 'PingFang SC', 'Microsoft YaHei', sans-serif";

  const styles = {
    app: {
      fontFamily: font,
      minHeight: "100vh",
      background: "linear-gradient(160deg, #0f0c29 0%, #302b63 40%, #24243e 100%)",
      color: "#fff",
      position: "relative",
      overflow: "hidden",
    },
    grain: {
      position: "fixed", inset: 0, opacity: 0.03, pointerEvents: "none",
      backgroundImage: `url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noise'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noise)' opacity='1'/%3E%3C/svg%3E")`,
    },
    container: { maxWidth: 520, margin: "0 auto", padding: "20px 16px", position: "relative", zIndex: 1 },
  };

  // ==================== HOME ====================
  if (mode === "home") {
    return (
      <div style={styles.app}>
        <div style={styles.grain} />
        <div style={styles.container}>
          <div style={{ textAlign: "center", padding: "40px 0 24px" }}>
            <div style={{ fontSize: 48, marginBottom: 8 }}>🚗</div>
            <h1 style={{ fontSize: 28, fontWeight: 800, margin: 0, letterSpacing: -0.5,
              background: "linear-gradient(135deg, #fff 0%, #a5b4fc 100%)", WebkitBackgroundClip: "text", WebkitTextFillColor: "transparent" }}>
              科目一刷题助手
            </h1>
            <p style={{ color: "rgba(255,255,255,0.5)", fontSize: 14, margin: "8px 0 0" }}>
              选择分类开始学习，支持翻卡和答题两种模式
            </p>
          </div>

          <div style={{ marginBottom: 24 }}>
            <p style={{ fontSize: 13, color: "rgba(255,255,255,0.4)", marginBottom: 10, fontWeight: 600, textTransform: "uppercase", letterSpacing: 1 }}>选择分类（不选=全部）</p>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
              {CATEGORIES.map(cat => {
                const active = selectedCats.includes(cat.id);
                const count = ALL_CARDS.filter(c => c.cat === cat.id).length;
                return (
                  <button key={cat.id} onClick={() => setSelectedCats(prev => active ? prev.filter(c => c !== cat.id) : [...prev, cat.id])}
                    style={{
                      background: active ? `linear-gradient(135deg, ${cat.color}33, ${cat.color}11)` : "rgba(255,255,255,0.04)",
                      border: `1.5px solid ${active ? cat.color : "rgba(255,255,255,0.08)"}`,
                      borderRadius: 14, padding: "14px 12px", cursor: "pointer", color: "#fff",
                      display: "flex", alignItems: "center", gap: 10, transition: "all 0.2s",
                      transform: active ? "scale(1.02)" : "scale(1)",
                    }}>
                    <span style={{ fontSize: 22 }}>{cat.icon}</span>
                    <div style={{ textAlign: "left" }}>
                      <div style={{ fontSize: 14, fontWeight: 700 }}>{cat.name}</div>
                      <div style={{ fontSize: 11, color: "rgba(255,255,255,0.4)" }}>{count} 题</div>
                    </div>
                    {active && <span style={{ marginLeft: "auto", color: cat.color, fontSize: 18 }}>✓</span>}
                  </button>
                );
              })}
            </div>
          </div>

          <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
            <button onClick={() => startSession(selectedCats, "flashcard")}
              style={{
                background: "linear-gradient(135deg, #667eea, #764ba2)", border: "none", borderRadius: 14,
                padding: "16px", color: "#fff", fontSize: 16, fontWeight: 700, cursor: "pointer",
                boxShadow: "0 4px 20px rgba(102,126,234,0.4)", transition: "transform 0.15s",
              }}
              onMouseDown={e => e.currentTarget.style.transform = "scale(0.97)"}
              onMouseUp={e => e.currentTarget.style.transform = "scale(1)"}>
              📇 翻卡模式 — 看答案记忆
            </button>
            <button onClick={() => startSession(selectedCats, "quiz")}
              style={{
                background: "linear-gradient(135deg, #f093fb, #f5576c)", border: "none", borderRadius: 14,
                padding: "16px", color: "#fff", fontSize: 16, fontWeight: 700, cursor: "pointer",
                boxShadow: "0 4px 20px rgba(245,87,108,0.4)", transition: "transform 0.15s",
              }}
              onMouseDown={e => e.currentTarget.style.transform = "scale(0.97)"}
              onMouseUp={e => e.currentTarget.style.transform = "scale(1)"}>
              🎯 答题模式 — 四选一测试
            </button>
          </div>

          <div style={{ textAlign: "center", marginTop: 20, fontSize: 12, color: "rgba(255,255,255,0.25)" }}>
            共 {selectedCats.length > 0 ? ALL_CARDS.filter(c => selectedCats.includes(c.cat)).length : ALL_CARDS.length} 道题
          </div>
        </div>
      </div>
    );
  }

  // ==================== RESULTS ====================
  if (mode === "results") {
    const total = mode === "quiz" ? totalAnswered : cards.length;
    const pct = total > 0 ? Math.round((score / total) * 100) : 0;
    const passed = pct >= 90;
    return (
      <div style={styles.app}>
        <div style={styles.grain} />
        <div style={styles.container}>
          <div style={{ textAlign: "center", padding: "60px 0 30px" }}>
            <div style={{ fontSize: 64, marginBottom: 16 }}>{passed ? "🎉" : "💪"}</div>
            <h2 style={{ fontSize: 24, fontWeight: 800, margin: "0 0 8px" }}>
              {passed ? "恭喜通过！" : "继续加油！"}
            </h2>
            <p style={{ color: "rgba(255,255,255,0.5)", fontSize: 14 }}>
              {passed ? "你已经掌握了这些知识点" : "科目一需要90分才能过关哦"}
            </p>
          </div>

          <div style={{
            background: "rgba(255,255,255,0.06)", borderRadius: 20, padding: 28,
            border: "1px solid rgba(255,255,255,0.08)", marginBottom: 20
          }}>
            <div style={{ display: "flex", justifyContent: "center", alignItems: "center", gap: 28, marginBottom: 20 }}>
              <div style={{ textAlign: "center" }}>
                <ProgressRing percent={pct} size={80} stroke={6} color={passed ? "#4ade80" : "#fb923c"} />
                <div style={{ fontSize: 28, fontWeight: 800, marginTop: -58, position: "relative" }}>{pct}%</div>
                <div style={{ fontSize: 11, color: "rgba(255,255,255,0.4)", marginTop: 32 }}>正确率</div>
              </div>
            </div>
            <div style={{ display: "flex", justifyContent: "space-around", borderTop: "1px solid rgba(255,255,255,0.08)", paddingTop: 16 }}>
              <div style={{ textAlign: "center" }}>
                <div style={{ fontSize: 22, fontWeight: 800, color: "#4ade80" }}>{score}</div>
                <div style={{ fontSize: 11, color: "rgba(255,255,255,0.4)" }}>正确</div>
              </div>
              <div style={{ textAlign: "center" }}>
                <div style={{ fontSize: 22, fontWeight: 800, color: "#f87171" }}>{wrongCards.length}</div>
                <div style={{ fontSize: 11, color: "rgba(255,255,255,0.4)" }}>错误</div>
              </div>
              <div style={{ textAlign: "center" }}>
                <div style={{ fontSize: 22, fontWeight: 800, color: "#a78bfa" }}>{bestStreak}</div>
                <div style={{ fontSize: 11, color: "rgba(255,255,255,0.4)" }}>最长连对</div>
              </div>
            </div>
          </div>

          {wrongCards.length > 0 && (
            <div style={{ marginBottom: 20 }}>
              <p style={{ fontSize: 13, fontWeight: 700, color: "rgba(255,255,255,0.5)", marginBottom: 10 }}>❌ 错题回顾</p>
              <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
                {wrongCards.map((c, i) => (
                  <div key={i} style={{
                    background: "rgba(248,113,113,0.08)", borderRadius: 12, padding: "12px 14px",
                    border: "1px solid rgba(248,113,113,0.15)", fontSize: 13
                  }}>
                    <div style={{ fontWeight: 600, marginBottom: 4 }}>{c.q}</div>
                    <div style={{ color: "#4ade80" }}>✅ {c.a}</div>
                    <div style={{ color: "rgba(255,255,255,0.35)", fontSize: 11, marginTop: 2 }}>💡 {c.hint}</div>
                  </div>
                ))}
              </div>
            </div>
          )}

          <div style={{ display: "flex", gap: 10 }}>
            {wrongCards.length > 0 && (
              <button onClick={() => {
                setCards(shuffle(wrongCards));
                setIdx(0); setFlipped(false); setSelected(null); setScore(0);
                setWrongCards([]); setShowHint(false); setStreak(0); setTotalAnswered(0);
                setMode("quiz");
                setQuizOptions(generateOptions(wrongCards[0], ALL_CARDS));
              }}
                style={{
                  flex: 1, background: "rgba(248,113,113,0.15)", border: "1px solid rgba(248,113,113,0.3)",
                  borderRadius: 14, padding: 14, color: "#f87171", fontSize: 14, fontWeight: 700, cursor: "pointer"
                }}>
                🔄 只练错题
              </button>
            )}
            <button onClick={() => setMode("home")}
              style={{
                flex: 1, background: "rgba(255,255,255,0.06)", border: "1px solid rgba(255,255,255,0.1)",
                borderRadius: 14, padding: 14, color: "#fff", fontSize: 14, fontWeight: 700, cursor: "pointer"
              }}>
              🏠 返回首页
            </button>
          </div>
        </div>
      </div>
    );
  }

  // ==================== FLASHCARD / QUIZ ====================
  const catInfo = CATEGORIES.find(c => c.id === card?.cat);

  return (
    <div style={styles.app}>
      <div style={styles.grain} />
      <div style={styles.container}>
        {/* Header */}
        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 16 }}>
          <button onClick={() => setMode("home")}
            style={{ background: "rgba(255,255,255,0.06)", border: "none", borderRadius: 10, padding: "8px 14px",
              color: "rgba(255,255,255,0.6)", fontSize: 13, cursor: "pointer", fontWeight: 600 }}>
            ← 返回
          </button>
          <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
            {mode === "quiz" && streak >= 3 && (
              <span style={{ fontSize: 12, color: "#fbbf24", fontWeight: 700 }}>🔥 {streak}连对</span>
            )}
            <span style={{ fontSize: 13, color: "rgba(255,255,255,0.4)", fontWeight: 600 }}>
              {idx + 1} / {cards.length}
            </span>
          </div>
        </div>

        {/* Progress bar */}
        <div style={{ height: 4, background: "rgba(255,255,255,0.06)", borderRadius: 2, marginBottom: 20, overflow: "hidden" }}>
          <div style={{ height: "100%", width: `${progress}%`, background: `linear-gradient(90deg, ${catInfo?.color || "#667eea"}, #a78bfa)`,
            borderRadius: 2, transition: "width 0.4s ease" }} />
        </div>

        {/* Category tag */}
        <div style={{ marginBottom: 12 }}>
          <span style={{
            display: "inline-flex", alignItems: "center", gap: 6,
            background: `${catInfo?.color}22`, border: `1px solid ${catInfo?.color}44`,
            borderRadius: 20, padding: "4px 12px", fontSize: 12, fontWeight: 600, color: catInfo?.color
          }}>
            {catInfo?.icon} {catInfo?.name}
          </span>
        </div>

        {/* Card */}
        <div style={{
          background: animateCorrect ? "rgba(74,222,128,0.08)" : animateWrong ? "rgba(248,113,113,0.08)" : "rgba(255,255,255,0.04)",
          border: `1px solid ${animateCorrect ? "rgba(74,222,128,0.3)" : animateWrong ? "rgba(248,113,113,0.3)" : "rgba(255,255,255,0.08)"}`,
          borderRadius: 20, padding: "28px 22px", marginBottom: 16, minHeight: 160,
          transition: "all 0.3s ease", cursor: mode === "flashcard" ? "pointer" : "default",
        }}
          onClick={() => mode === "flashcard" && setFlipped(!flipped)}>
          <div style={{ fontSize: 16, fontWeight: 700, lineHeight: 1.6, marginBottom: 12 }}>
            {card?.q}
          </div>

          {/* Flashcard answer */}
          {mode === "flashcard" && (
            <div style={{
              overflow: "hidden", maxHeight: flipped ? 400 : 0,
              transition: "max-height 0.4s ease", marginTop: flipped ? 12 : 0,
            }}>
              <div style={{
                borderTop: "1px solid rgba(255,255,255,0.1)", paddingTop: 14,
              }}>
                <div style={{ color: "#4ade80", fontSize: 15, fontWeight: 600, lineHeight: 1.6 }}>
                  ✅ {card?.a}
                </div>
                <div style={{ color: "rgba(255,255,255,0.3)", fontSize: 12, marginTop: 8 }}>
                  💡 记忆口诀：{card?.hint}
                </div>
              </div>
            </div>
          )}

          {/* Flashcard prompt */}
          {mode === "flashcard" && !flipped && (
            <div style={{ color: "rgba(255,255,255,0.25)", fontSize: 13, marginTop: 8 }}>
              👆 点击卡片查看答案
            </div>
          )}
        </div>

        {/* Quiz options */}
        {mode === "quiz" && (
          <div style={{ display: "flex", flexDirection: "column", gap: 8, marginBottom: 16 }}>
            {quizOptions.map((opt, i) => {
              const isCorrect = opt === card?.a;
              const isSelected = selected === opt;
              const revealed = selected !== null;
              let bg = "rgba(255,255,255,0.04)";
              let border = "rgba(255,255,255,0.08)";
              if (revealed && isCorrect) { bg = "rgba(74,222,128,0.12)"; border = "rgba(74,222,128,0.4)"; }
              else if (revealed && isSelected && !isCorrect) { bg = "rgba(248,113,113,0.12)"; border = "rgba(248,113,113,0.4)"; }

              return (
                <button key={i} onClick={() => handleQuizSelect(opt)}
                  style={{
                    background: bg, border: `1.5px solid ${border}`, borderRadius: 14,
                    padding: "14px 16px", color: "#fff", fontSize: 14, fontWeight: 500,
                    cursor: revealed ? "default" : "pointer", textAlign: "left", lineHeight: 1.5,
                    transition: "all 0.2s", opacity: revealed && !isCorrect && !isSelected ? 0.4 : 1,
                  }}>
                  <span style={{ color: "rgba(255,255,255,0.3)", marginRight: 8, fontWeight: 700 }}>
                    {["A", "B", "C", "D"][i]}
                  </span>
                  {opt}
                  {revealed && isCorrect && <span style={{ float: "right" }}>✅</span>}
                  {revealed && isSelected && !isCorrect && <span style={{ float: "right" }}>❌</span>}
                </button>
              );
            })}
          </div>
        )}

        {/* Hint button */}
        {!showHint && selected === null && !flipped && (
          <button onClick={() => setShowHint(true)}
            style={{
              background: "none", border: "1px solid rgba(255,255,255,0.1)", borderRadius: 10,
              padding: "8px 16px", color: "rgba(255,255,255,0.4)", fontSize: 12, cursor: "pointer",
              marginBottom: 12, fontWeight: 600
            }}>
            💡 查看提示
          </button>
        )}
        {showHint && selected === null && (
          <div style={{
            background: "rgba(251,191,36,0.08)", border: "1px solid rgba(251,191,36,0.2)",
            borderRadius: 12, padding: "10px 14px", fontSize: 13, color: "#fbbf24", marginBottom: 12
          }}>
            💡 {card?.hint}
          </div>
        )}

        {/* After answer hint in quiz */}
        {mode === "quiz" && selected !== null && (
          <div style={{
            background: "rgba(167,139,250,0.08)", border: "1px solid rgba(167,139,250,0.2)",
            borderRadius: 12, padding: "10px 14px", fontSize: 13, color: "#a78bfa", marginBottom: 12
          }}>
            💡 记忆口诀：{card?.hint}
          </div>
        )}

        {/* Next button */}
        {(mode === "flashcard" || selected !== null) && (
          <button onClick={nextCard}
            style={{
              width: "100%", background: "linear-gradient(135deg, #667eea, #764ba2)",
              border: "none", borderRadius: 14, padding: 15, color: "#fff", fontSize: 15,
              fontWeight: 700, cursor: "pointer", boxShadow: "0 4px 16px rgba(102,126,234,0.3)",
            }}>
            {idx + 1 >= cards.length ? "📊 查看结果" : "➡️ 下一题"}
          </button>
        )}
      </div>
    </div>
  );
}

