import { useState, useEffect, useCallback, useRef } from "react";

const CATEGORIES = [
  {
    id: "deduction",
    icon: "🔢",
    title: "扣分题",
    color: "#E53935",
    cards: [
      { q: "扣1分的关键词？", a: "普倒掉、会车、灯光、安全带、年检、禁令标志/标线", mnemonic: "口诀：普倒掉 灯带禁" },
      { q: "扣3分的关键词？", a: "普逆、手持电话、前方排队穿插、占道、高速低于最低速度、高速不按规定车道行驶、三不让、故障灯光", mnemonic: "口诀：老三逆子，小三插足" },
      { q: "扣6分的关键词？", a: "应急车道、信号灯、暂扣期间开车、肇事逃逸（轻微伤）、危险爆炸品", mnemonic: "口诀：急信扣逃轻危限，扣666" },
      { q: "扣9分的关键词？", a: "准驾不符、高速违法停车、无校车资格", mnemonic: "口诀：9病床前无孝子" },
      { q: "扣12分的关键词？", a: "饮酒、高速倒车/掉头/逆行、买卖分、肇事逃逸（死亡）", mnemonic: "口诀：高倒逆 酒逃亡" },
      { q: "号牌扣3分？", a: "不按规定安装号牌", mnemonic: "" },
      { q: "号牌扣9分？", a: "未悬挂或故意遮挡、污损号牌", mnemonic: "" },
      { q: "号牌扣12分？", a: "伪造、变造号牌（3+9=12）", mnemonic: "假的扣满12" },
