    cards: [
      { q: "普通车在普通公路超速20%-50%？", a: "记3分", mnemonic: "普普36" },
      { q: "普通车在普通公路超速50%以上？", a: "记6分", mnemonic: "普普36" },
      { q: "普通车在高速/快速路超速20%-50%？", a: "记6分（普通车的2倍）", mnemonic: "普高612" },
      { q: "普通车在高速/快速路超速50%以上？", a: "记12分", mnemonic: "普高612" },
      { q: "7座以上超员20%-50%？", a: "记6分", mnemonic: "7上69" },
      { q: "7座以上超员50%-100%？", a: "记9分", mnemonic: "7上69" },
      { q: "7座以下超员20%-50%？", a: "记3分", mnemonic: "7下36" },
      { q: "7座以下超员50%-100%？", a: "记6分", mnemonic: "7下36" },
      { q: "货车超载30%以下/30%-50%/50%以上？", a: "1分/3分/6分", mnemonic: "货车超载136" },
    ]
  },
  {
    id: "fine",
    icon: "💰",
    title: "罚款题",
    color: "#7B1FA2",
    cards: [
      { q: "罚款20-200元？", a: "实习期单独上高速、用原驾驶证、信息变更未备案、让撤不撤造成堵塞罚200", mnemonic: "刚进新手村的石原里美——200块都不给我！" },
      { q: "罚款200-500元？", a: "逾期审验仍驾驶、隐瞒欺骗补领、身体不适仍驾驶、公客超员未达20%", mnemonic: "于事无补——500元" },
      { q: "罚款200-2000元+吊销？", a: "驾驶拼装报废车、超速50%、把车交给无证人", mnemonic: "拼装报废超50" },
      { q: "罚款200-2000元+拘留15日？", a: "无证/吊销/暂扣期间驾车、肇事逃逸（不构成犯罪）、强迫违法、违反管制、损毁设施、非法拦截", mnemonic: "除吊销外都选拘留" },
      { q: "罚款2000-5000元？", a: "伪造变造证书证件号牌等", mnemonic: "伪造变造罚款选最高" },
      { q: "初次饮酒驾车？", a: "扣12分，暂扣6个月，罚款1000-2000", mnemonic: "" },
      { q: "再次饮酒驾车？", a: "吊销驾照，10日以下拘留，罚款1000-2000", mnemonic: "" },
      { q: "虚假材料申领罚款？", a: "500元以下", mnemonic: "假材料伍佰" },
      { q: "考试贿赂舞弊罚款？", a: "2000元以下", mnemonic: "贿赂2000" },
    ]
  },
  {
    id: "license",
    icon: "🪪",
    title: "驾驶证",
