// Shuffle helper
function shuffle(arr) {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

// Generate quiz questions from cards
function generateQuiz(categories, count = 20) {
  const allCards = [];
  categories.forEach(cat => {
    cat.cards.forEach(card => {
      allCards.push({ ...card, category: cat.title, color: cat.color });
    });
  });
  const selected = shuffle(allCards).slice(0, count);
  return selected.map(card => {
    // Create wrong answers from other cards in same or different categories
    const others = allCards.filter(c => c.a !== card.a);
    const wrongAnswers = shuffle(others).slice(0, 3).map(c => c.a);
    const options = shuffle([card.a, ...wrongAnswers]);
    return { ...card, options, correctIndex: options.indexOf(card.a) };
  });
}

const MODES = { HOME: "home", CARDS: "cards", QUIZ: "quiz", REVIEW: "review" };

