  const [wrongCards, setWrongCards] = useState([]);
  const [showMnemonic, setShowMnemonic] = useState(false);
  const [quizCount, setQuizCount] = useState(20);
  const [selectedAnswer, setSelectedAnswer] = useState(null);
  const [animDir, setAnimDir] = useState(null);

  const startCards = (cat) => {
    setSelectedCat(cat);
    setCardIndex(0);
    setFlipped(false);
    setMode(MODES.CARDS);
  };

  const startQuiz = (count = 20) => {
    setQuizCount(count);
    setQuizQuestions(generateQuiz(CATEGORIES, count));
    setQuizIndex(0);
    setQuizAnswers({});
    setQuizDone(false);
    setSelectedAnswer(null);
    setMode(MODES.QUIZ);
  };

  const startWrongReview = () => {
    if (wrongCards.length === 0) return;
    setSelectedCat({ title: "错题回顾", icon: "📝", color: "#E53935", cards: wrongCards });
    setCardIndex(0);
    setFlipped(false);
    setMode(MODES.CARDS);
  };

  const nextCard = () => {
    if (!selectedCat) return;
    setAnimDir("next");
    setTimeout(() => {
      setFlipped(false);
      setCardIndex(i => (i + 1) % selectedCat.cards.length);
      setShowMnemonic(false);
      setAnimDir(null);
    }, 200);
  };

  const prevCard = () => {
    if (!selectedCat) return;
    setAnimDir("prev");
    setTimeout(() => {
      setFlipped(false);
      setCardIndex(i => (i - 1 + selectedCat.cards.length) % selectedCat.cards.length);
      setShowMnemonic(false);
      setAnimDir(null);
    }, 200);
  };

  const answerQuiz = (idx) => {
    if (selectedAnswer !== null) return;
    setSelectedAnswer(idx);
    const correct = idx === quizQuestions[quizIndex].correctIndex;
    const newAnswers = { ...quizAnswers, [quizIndex]: { selected: idx, correct } };
    setQuizAnswers(newAnswers);
    if (!correct) {
      setWrongCards(prev => {
        const q = quizQuestions[quizIndex];
        if (prev.some(c => c.q === q.q)) return prev;
        return [...prev, { q: q.q, a: q.a, mnemonic: q.mnemonic || "" }];
      });
    }
    setTimeout(() => {
      if (quizIndex < quizQuestions.length - 1) {
        setQuizIndex(quizIndex + 1);
        setSelectedAnswer(null);
      } else {
        setQuizDone(true);
      }
    }, 1200);
  };

  const score = Object.values(quizAnswers).filter(a => a.correct).length;
  const totalCards = CATEGORIES.reduce((s, c) => s + c.cards.length, 0);

  // Styles
  const font = "'Noto Sans SC', 'PingFang SC', 'Microsoft YaHei', sans-serif";

  if (mode === MODES.HOME) {
    return (
      <div style={{ fontFamily: font, minHeight: "100vh", background: "linear-gradient(135deg, #0f0c29, #302b63, #24243e)", padding: "20px", color: "#fff" }}>
        <div style={{ maxWidth: 600, margin: "0 auto" }}>
          {/* Header */}
          <div style={{ textAlign: "center", padding: "30px 0 20px" }}>
            <div style={{ fontSize: 48, marginBottom: 8 }}>🚗</div>
            <h1 style={{ fontSize: 28, fontWeight: 800, margin: 0, background: "linear-gradient(90deg, #FFD54F, #FF8A65)", WebkitBackgroundClip: "text", WebkitTextFillColor: "transparent" }}>科目一备考神器</h1>
            <p style={{ color: "#9e9ec8", fontSize: 14, marginTop: 8 }}>{CATEGORIES.length} 大类 · {totalCards} 张卡片 · 口诀速记</p>
          </div>

          {/* Quiz button */}
          <button onClick={() => startQuiz(20)} style={{
            width: "100%", padding: "18px", borderRadius: 16, border: "none",
            background: "linear-gradient(135deg, #FF6F00, #E53935)", color: "#fff",
            fontSize: 18, fontWeight: 700, cursor: "pointer", marginBottom: 12,
            boxShadow: "0 4px 20px rgba(229,57,53,0.4)", fontFamily: font,
            transition: "transform 0.2s", position: "relative", overflow: "hidden"
          }}
          onMouseDown={e => e.currentTarget.style.transform = "scale(0.97)"}
          onMouseUp={e => e.currentTarget.style.transform = "scale(1)"}
          >
            🎯 模拟考试（20题）
          </button>

          <button onClick={() => startQuiz(10)} style={{
            width: "100%", padding: "14px", borderRadius: 16, border: "1px solid rgba(255,255,255,0.15)",
            background: "rgba(255,255,255,0.06)", color: "#ccc",
            fontSize: 15, fontWeight: 600, cursor: "pointer", marginBottom: 24, fontFamily: font,
          }}>
            ⚡ 快速练习（10题）
          </button>

          {wrongCards.length > 0 && (
            <button onClick={startWrongReview} style={{
              width: "100%", padding: "14px", borderRadius: 16, border: "1px solid rgba(229,57,53,0.4)",
              background: "rgba(229,57,53,0.12)", color: "#FF8A80",
              fontSize: 15, fontWeight: 600, cursor: "pointer", marginBottom: 24, fontFamily: font,
            }}>
              📝 错题回顾（{wrongCards.length}题）
            </button>
          )}

          {/* Category grid */}
          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12 }}>
            {CATEGORIES.map(cat => (
              <button key={cat.id} onClick={() => startCards(cat)} style={{
                padding: "20px 16px", borderRadius: 16, border: "1px solid rgba(255,255,255,0.08)",
                background: "rgba(255,255,255,0.04)", cursor: "pointer", textAlign: "left",
                fontFamily: font, transition: "all 0.2s", position: "relative", overflow: "hidden"
              }}
              onMouseEnter={e => { e.currentTarget.style.background = "rgba(255,255,255,0.1)"; e.currentTarget.style.borderColor = cat.color + "60"; }}
              onMouseLeave={e => { e.currentTarget.style.background = "rgba(255,255,255,0.04)"; e.currentTarget.style.borderColor = "rgba(255,255,255,0.08)"; }}
              >
                <div style={{ fontSize: 28, marginBottom: 8 }}>{cat.icon}</div>
                <div style={{ fontSize: 15, fontWeight: 700, color: "#fff" }}>{cat.title}</div>
                <div style={{ fontSize: 12, color: "#888", marginTop: 4 }}>{cat.cards.length} 张卡片</div>
                <div style={{ position: "absolute", top: 0, right: 0, width: 60, height: 60, borderRadius: "0 16px 0 60px", background: cat.color + "15" }} />
              </button>
            ))}
          </div>
        </div>
      </div>
    );
  }

  // FLASHCARD MODE
  if (mode === MODES.CARDS && selectedCat) {
    const card = selectedCat.cards[cardIndex];
    return (
      <div style={{ fontFamily: font, minHeight: "100vh", background: "linear-gradient(135deg, #0f0c29, #302b63, #24243e)", padding: "20px", color: "#fff" }}>
        <div style={{ maxWidth: 600, margin: "0 auto" }}>
          {/* Top bar */}
          <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 20 }}>
            <button onClick={() => setMode(MODES.HOME)} style={{ background: "rgba(255,255,255,0.1)", border: "none", color: "#fff", padding: "8px 16px", borderRadius: 12, fontSize: 14, cursor: "pointer", fontFamily: font }}>← 返回</button>
            <span style={{ fontSize: 14, color: "#9e9ec8" }}>{cardIndex + 1} / {selectedCat.cards.length}</span>
          </div>

          {/* Category label */}
          <div style={{ textAlign: "center", marginBottom: 16 }}>
            <span style={{ fontSize: 13, color: selectedCat.color, fontWeight: 600 }}>{selectedCat.icon} {selectedCat.title}</span>
          </div>

          {/* Progress bar */}
          <div style={{ height: 4, background: "rgba(255,255,255,0.1)", borderRadius: 2, marginBottom: 24 }}>
            <div style={{ height: 4, borderRadius: 2, background: selectedCat.color, width: `${((cardIndex + 1) / selectedCat.cards.length) * 100}%`, transition: "width 0.3s" }} />
          </div>

          {/* Card */}
          <div
            onClick={() => setFlipped(!flipped)}
            style={{
              minHeight: 280, borderRadius: 24, padding: "32px 24px",
              background: flipped
                ? `linear-gradient(135deg, ${selectedCat.color}22, ${selectedCat.color}08)`
                : "rgba(255,255,255,0.06)",
              border: `1px solid ${flipped ? selectedCat.color + "40" : "rgba(255,255,255,0.1)"}`,
              cursor: "pointer", transition: "all 0.4s",
              display: "flex", flexDirection: "column", justifyContent: "center", alignItems: "center",
              textAlign: "center",
              opacity: animDir ? 0.3 : 1,
              transform: animDir === "next" ? "translateX(-30px)" : animDir === "prev" ? "translateX(30px)" : "none",
            }}
          >
            {!flipped ? (
              <>
                <div style={{ fontSize: 13, color: "#888", marginBottom: 16, letterSpacing: 2 }}>问 题</div>
                <div style={{ fontSize: 20, fontWeight: 700, lineHeight: 1.6 }}>{card.q}</div>
                <div style={{ fontSize: 12, color: "#666", marginTop: 24 }}>点击翻转查看答案 👆</div>
              </>
            ) : (
              <>
                <div style={{ fontSize: 13, color: selectedCat.color, marginBottom: 16, letterSpacing: 2 }}>答 案</div>
                <div style={{ fontSize: 18, fontWeight: 600, lineHeight: 1.8, color: "#e0e0e0" }}>{card.a}</div>
                {card.mnemonic && (
                  <div style={{
                    marginTop: 20, padding: "12px 16px", borderRadius: 12,
                    background: "rgba(255,215,0,0.1)", border: "1px solid rgba(255,215,0,0.2)"
                  }}>
                    <div style={{ fontSize: 11, color: "#FFD54F", marginBottom: 4 }}>💡 记忆口诀</div>
                    <div style={{ fontSize: 15, color: "#FFD54F", fontWeight: 600 }}>{card.mnemonic}</div>
                  </div>
                )}
              </>
            )}
          </div>

          {/* Navigation */}
          <div style={{ display: "flex", gap: 12, marginTop: 24, justifyContent: "center" }}>
            <button onClick={prevCard} style={{
              flex: 1, maxWidth: 160, padding: "14px", borderRadius: 14, border: "1px solid rgba(255,255,255,0.15)",
              background: "rgba(255,255,255,0.06)", color: "#ccc", fontSize: 15, cursor: "pointer", fontFamily: font, fontWeight: 600
            }}>← 上一题</button>
            <button onClick={nextCard} style={{
              flex: 1, maxWidth: 160, padding: "14px", borderRadius: 14, border: "none",
              background: selectedCat.color, color: "#fff", fontSize: 15, cursor: "pointer", fontFamily: font, fontWeight: 600
            }}>下一题 →</button>
          </div>
        </div>
      </div>
    );
  }

  // QUIZ MODE
  if (mode === MODES.QUIZ) {
    if (quizDone) {
      const passed = score >= quizQuestions.length * 0.9;
      return (
        <div style={{ fontFamily: font, minHeight: "100vh", background: "linear-gradient(135deg, #0f0c29, #302b63, #24243e)", padding: "20px", color: "#fff" }}>
          <div style={{ maxWidth: 600, margin: "0 auto", textAlign: "center", paddingTop: 60 }}>
            <div style={{ fontSize: 72, marginBottom: 16 }}>{passed ? "🎉" : "😤"}</div>
            <h2 style={{ fontSize: 28, fontWeight: 800, margin: "0 0 8px" }}>{passed ? "恭喜通过！" : "继续加油！"}</h2>
            <p style={{ color: "#9e9ec8", fontSize: 14, marginBottom: 32 }}>
              {passed ? "你已经掌握了大部分知识点" : "多复习几遍口诀就能通过"}
            </p>
            <div style={{
              fontSize: 64, fontWeight: 900, marginBottom: 8,
              background: passed ? "linear-gradient(90deg, #4CAF50, #81C784)" : "linear-gradient(90deg, #FF6F00, #E53935)",
              WebkitBackgroundClip: "text", WebkitTextFillColor: "transparent"
            }}>{score}/{quizQuestions.length}</div>
            <p style={{ color: "#888", fontSize: 14, marginBottom: 40 }}>
              正确率 {Math.round(score / quizQuestions.length * 100)}%　（90%及格）
            </p>

            {/* Wrong answers review */}
            {Object.entries(quizAnswers).filter(([, v]) => !v.correct).length > 0 && (
              <div style={{ textAlign: "left", marginBottom: 32 }}>
                <h3 style={{ fontSize: 16, fontWeight: 700, marginBottom: 12, color: "#FF8A80" }}>❌ 答错的题目：</h3>
                {Object.entries(quizAnswers).filter(([, v]) => !v.correct).map(([idx]) => {
                  const q = quizQuestions[idx];
                  return (
                    <div key={idx} style={{
                      padding: "16px", borderRadius: 14, marginBottom: 10,
                      background: "rgba(229,57,53,0.08)", border: "1px solid rgba(229,57,53,0.2)"
                    }}>
                      <div style={{ fontSize: 14, fontWeight: 600, marginBottom: 8 }}>{q.q}</div>
                      <div style={{ fontSize: 13, color: "#4CAF50" }}>✅ {q.a}</div>
                      {q.mnemonic && <div style={{ fontSize: 12, color: "#FFD54F", marginTop: 6 }}>💡 {q.mnemonic}</div>}
                    </div>
                  );
                })}
              </div>
            )}

            <div style={{ display: "flex", gap: 12 }}>
              <button onClick={() => setMode(MODES.HOME)} style={{
                flex: 1, padding: "14px", borderRadius: 14, border: "1px solid rgba(255,255,255,0.15)",
                background: "rgba(255,255,255,0.06)", color: "#ccc", fontSize: 15, cursor: "pointer", fontFamily: font, fontWeight: 600
              }}>返回首页</button>
              <button onClick={() => startQuiz(quizCount)} style={{
                flex: 1, padding: "14px", borderRadius: 14, border: "none",
                background: "linear-gradient(135deg, #FF6F00, #E53935)", color: "#fff", fontSize: 15, cursor: "pointer", fontFamily: font, fontWeight: 600
              }}>再来一次</button>
            </div>
          </div>
        </div>
      );
    }

    const q = quizQuestions[quizIndex];
    return (
      <div style={{ fontFamily: font, minHeight: "100vh", background: "linear-gradient(135deg, #0f0c29, #302b63, #24243e)", padding: "20px", color: "#fff" }}>
        <div style={{ maxWidth: 600, margin: "0 auto" }}>
          {/* Top */}
          <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 16 }}>
            <button onClick={() => setMode(MODES.HOME)} style={{ background: "rgba(255,255,255,0.1)", border: "none", color: "#fff", padding: "8px 16px", borderRadius: 12, fontSize: 14, cursor: "pointer", fontFamily: font }}>← 退出</button>
            <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
              <span style={{ fontSize: 13, color: "#4CAF50" }}>✓{Object.values(quizAnswers).filter(a => a.correct).length}</span>
              <span style={{ fontSize: 13, color: "#888" }}>·</span>
              <span style={{ fontSize: 13, color: "#FF5252" }}>✗{Object.values(quizAnswers).filter(a => !a.correct).length}</span>
            </div>
            <span style={{ fontSize: 14, color: "#9e9ec8" }}>{quizIndex + 1}/{quizQuestions.length}</span>
          </div>

          {/* Progress */}
          <div style={{ height: 4, background: "rgba(255,255,255,0.1)", borderRadius: 2, marginBottom: 28 }}>
            <div style={{ height: 4, borderRadius: 2, background: "linear-gradient(90deg, #FF6F00, #E53935)", width: `${((quizIndex + 1) / quizQuestions.length) * 100}%`, transition: "width 0.3s" }} />
          </div>

          {/* Category tag */}
          <div style={{ marginBottom: 12 }}>
            <span style={{ fontSize: 12, padding: "4px 10px", borderRadius: 8, background: q.color + "20", color: q.color }}>{q.category}</span>
          </div>

          {/* Question */}
          <div style={{ fontSize: 20, fontWeight: 700, lineHeight: 1.6, marginBottom: 28, minHeight: 60 }}>{q.q}</div>

          {/* Options */}
          <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
            {q.options.map((opt, idx) => {
              const isSelected = selectedAnswer === idx;
              const isCorrect = idx === q.correctIndex;
              const answered = selectedAnswer !== null;
              let bg = "rgba(255,255,255,0.06)";
              let border = "rgba(255,255,255,0.1)";
              let textColor = "#e0e0e0";

              if (answered) {
                if (isCorrect) {
                  bg = "rgba(76,175,80,0.15)";
                  border = "#4CAF50";
                  textColor = "#81C784";
                } else if (isSelected && !isCorrect) {
                  bg = "rgba(229,57,53,0.15)";
                  border = "#E53935";
                  textColor = "#FF8A80";
                }
              }

              return (
                <button key={idx} onClick={() => answerQuiz(idx)} style={{
                  padding: "16px 18px", borderRadius: 14, textAlign: "left",
                  border: `1px solid ${border}`, background: bg, color: textColor,
                  fontSize: 15, lineHeight: 1.6, cursor: answered ? "default" : "pointer",
                  fontFamily: font, transition: "all 0.3s", fontWeight: isSelected || (answered && isCorrect) ? 600 : 400,
                }}>
                  <span style={{ marginRight: 10, opacity: 0.5 }}>{String.fromCharCode(65 + idx)}</span>
                  {opt}
                </button>
              );
            })}
          </div>

          {/* Show mnemonic after answer */}
          {selectedAnswer !== null && q.mnemonic && (
            <div style={{
              marginTop: 16, padding: "12px 16px", borderRadius: 12,
              background: "rgba(255,215,0,0.08)", border: "1px solid rgba(255,215,0,0.15)",
              animation: "fadeIn 0.3s"
            }}>
              <span style={{ fontSize: 13, color: "#FFD54F" }}>💡 {q.mnemonic}</span>
            </div>
          )}
        </div>
      </div>
    );
  }

  return null;
}
